/**
 * Client-side checks that only a real browser can answer: whether a renderer is
 * actually obtained, whether the viewport really reaches the bottom, and
 * whether the history viewer pages as you scroll.
 *
 * Run with `npm run test:browser` (needs Google Chrome).
 *
 * Two headless limitations are worked around explicitly rather than hidden:
 * headless Chrome dispatches no native `scroll` events, so scrolling is driven
 * with synthetic ones; and with no compositor the DOM renderer never paints
 * glyphs, so content is asserted against the terminal buffer — the source of
 * truth for what gets displayed — not against DOM text.
 */

import * as React from 'react';
import { createRoot } from 'react-dom/client';

import { ChatController } from '../../src/client/chat/controller';
import { forgetTerminals } from '../../src/client/chat/chat-terminal';
import { ChatView } from '../../src/client/shell/chat/ChatView';
import { TerminalSplit } from '../../src/client/shell/chat/TerminalSplit';
import { TurnStrip } from '../../src/client/shell/chat/TurnStrip';
import { DEFAULT_CHAT_VIEW } from '../../src/client/chat/view-settings';
import { createTerminalController, LIVE_SCROLLBACK_LINES } from '../../src/client/terminal/controller';
import { HistoryView } from '../../src/client/terminal/history-view';
import { Dialog } from '../../src/client/ui/relay/Dialog';
import { PhoneContext } from '../../src/client/ui/touch';
import { FloatingMenu, type FloatingMenuAction } from '../../src/client/shell/FloatingMenu';
import { BottomNav } from '../../src/client/shell/BottomNav';
import { MoreSheet } from '../../src/client/shell/MoreSheet';
import { ChatSettingsDialog } from '../../src/client/shell/dialogs/ChatSettingsDialog';
import { SettingsDialog } from '../../src/client/shell/dialogs/SettingsDialog';
import { DEFAULT_NOTIFICATIONS } from '../../src/client/ui/settings';
import { EnvironmentDialog } from '../../src/client/shell/dialogs/EnvironmentDialog';
import { SessionsDialog } from '../../src/client/shell/dialogs/SessionsDialog';
import { ConversationsDialog } from '../../src/client/shell/dialogs/ConversationsDialog';
import { UsageDashboardDialog } from '../../src/client/shell/dialogs/UsageDashboardDialog';
import { TabSwitcherSheet } from '../../src/client/shell/TabSwitcherSheet';
import { TabBar } from '../../src/client/ui/relay/TabBar';
import { MonacoEditor } from '../../src/client/shell/chat/MonacoEditor';
import { WorkflowPopup } from '../../src/client/shell/chat/WorkflowPopup';
import { GitHubItemDialog } from '../../src/client/shell/chat/GitHubItemDialog';
import { GitHubPanel } from '../../src/client/shell/chat/GitHubPanel';
import { FileEditorDialog } from '../../src/client/shell/chat/FileEditorDialog';
import { MessageBubble } from '../../src/client/shell/chat/MessageBubble';
import { monacoStylesApplied } from '../../src/client/chat/monaco';
import { Toasts } from '../../src/client/shell/Toasts';
import { shellStore } from '../../src/client/shell/store';
import { FileTreePanel } from '../../src/client/shell/chat/FileTreePanel';
import { TerminalSplit } from '../../src/client/shell/chat/TerminalSplit';
import { disablePullToRefresh } from '../../src/client/ui/mobile';
import { visualViewportKeyboardInset } from '../../src/client/ui/keyboard-viewport';

/**
 * A real workflow run, as the adapter emitted it.
 *
 * Generated by test/browser/run.js from test/fixtures/chat/claude-workflow
 * .jsonl on every run — see the note there for why it is not written by hand.
 */
import RECORDED_WORKFLOW from './workflow-events.json';

/**
 * A real workflow run that failed, likewise.
 *
 * Generated from test/fixtures/chat/claude-workflow-failed.jsonl by the same
 * replay in test/browser/run.js. Its counterpart above is the control: that run
 * finished, with one of its five agents dead, and must go on reading as done.
 */
import RECORDED_FAILED_WORKFLOW from './workflow-failed-events.json';

/**
 * A real Oh My Pi conversation, at the level the browser receives it.
 *
 * Generated from test/fixtures/chat/omp-empty-rows.jsonl by test/browser/run.js.
 * Five steps whose whole reply was a space, and the one that finally spoke —
 * the recording the empty rows in #132 were reported from.
 */
import RECORDED_EMPTY_ROWS from './empty-rows-events.json';

/**
 * One turn of a real Oh My Pi conversation, likewise.
 *
 * Generated from test/fixtures/chat/acp-omp.jsonl by test/browser/run.js,
 * including a real `send()` — which is where the duplicate prompt came from
 * (#129).
 */
import RECORDED_OMP_TURN from './omp-turn-events.json';

/**
 * The same successful run with everything it said about itself left out.
 *
 * What a runtime going quiet looks like: the call is opened and never mentioned
 * again, and the turn ends anyway (#139). Generated by test/browser/run.js
 * rather than filtered here, because the reducer writes into a `block_start`'s
 * block object and the shared import above has already been written into by the
 * checks that run before this one.
 */
import RECORDED_QUIET_WORKFLOW from './workflow-quiet-events.json';

const results: string[] = [];
const check = (name: string, ok: boolean, detail = ''): void => {
  results.push(`${ok ? 'PASS' : 'FAIL'} :: ${name}${detail ? ` :: ${detail}` : ''}`);
};
const wait = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));
const scroll = (el: HTMLElement, top: number): void => {
  el.scrollTop = top;
  el.dispatchEvent(new Event('scroll'));
};

async function run(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:800px;height:400px;position:absolute;top:0;left:0';
  document.body.appendChild(host);

  const controller = createTerminalController({ fontSize: 14 });
  controller.open(host);
  await wait(200);

  check(
    'terminal opens with a usable geometry',
    controller.terminal.cols > 10 && controller.terminal.rows > 5,
    `${controller.terminal.cols}x${controller.terminal.rows}`,
  );
  check(
    'an accelerated renderer is obtained (or cleanly falls back)',
    ['webgl', 'dom'].includes(controller.rendererKind()),
    controller.rendererKind(),
  );

  // Issue #19 (copy from the terminal), asserted at the real layer: the
  // controller must intercept a right-click when there is a selection to copy,
  // and leave the native menu alone when there is not. select() makes a
  // deterministic selection without depending on rendered glyphs or the
  // Clipboard API (unavailable in a headless file:// context).
  controller.terminal.select(0, 0, 5);
  const menuWithSelection = new MouseEvent('contextmenu', { bubbles: true, cancelable: true });
  host.dispatchEvent(menuWithSelection);
  check('right-click with a selection is intercepted for copy', menuWithSelection.defaultPrevented);

  controller.terminal.clearSelection();
  const menuNoSelection = new MouseEvent('contextmenu', { bubbles: true, cancelable: true });
  host.dispatchEvent(menuNoSelection);
  check('right-click with no selection leaves the native menu', !menuNoSelection.defaultPrevented);

  let text = '';
  for (let i = 0; i < 3000; i++) {
    text += `riga ${i}\r\n`;
  }
  controller.write(text);
  await wait(600);

  const buffer = controller.terminal.buffer.active;
  check('output written through the batching path arrives', buffer.baseY > 0, `baseY=${buffer.baseY}`);
  check('the viewport stays pinned to the newest output', controller.isAtBottom());

  // The live buffer must be *bounded*, because everything older is the server's
  // job to page back in. Asserting that against the real 20k limit would need
  // 20k lines of output to say anything, so it is asserted against a small
  // explicit limit on a throwaway terminal — the limit is a parameter, and what
  // is under test is that the parameter is honoured — plus one assertion that
  // the default is the constant the rest of the app reasons about.
  const boundedHost = document.createElement('div');
  boundedHost.style.cssText = 'width:800px;height:400px;position:absolute;top:0;left:0';
  document.body.appendChild(boundedHost);
  const bounded = createTerminalController({ fontSize: 14, scrollback: 500 });
  bounded.open(boundedHost);
  let overflow = '';
  for (let i = 0; i < 1500; i++) {
    overflow += `riga ${i}\r\n`;
  }
  bounded.write(overflow);
  await wait(400);
  const boundedBuffer = bounded.terminal.buffer.active;
  check(
    'the live scrollback stays bounded',
    boundedBuffer.baseY === 500,
    `baseY=${boundedBuffer.baseY} after 1500 lines into a 500-line buffer`,
  );
  check(
    'and the default bound is the one the app pages against',
    LIVE_SCROLLBACK_LINES === 20000,
    `LIVE_SCROLLBACK_LINES=${LIVE_SCROLLBACK_LINES}`,
  );
  bounded.dispose();
  boundedHost.remove();

  let reachedTop = 0;
  controller.onReachedTop(() => {
    reachedTop += 1;
  });

  controller.terminal.scrollToTop();
  await wait(80);
  check('scrolling up leaves the bottom', !controller.isAtBottom());
  check('reaching the top signals the hand-off to history', reachedTop > 0, `fired ${reachedTop}x`);

  // Already parked at the top: there is no scroll left to emit an event, so
  // the wheel gesture itself has to keep working.
  const atTop = reachedTop;
  host.dispatchEvent(new WheelEvent('wheel', { deltaY: -120, bubbles: true }));
  await wait(80);
  check(
    'scrolling up again while already at the top still signals',
    reachedTop > atTop,
    `fired ${reachedTop}x total`,
  );

  controller.terminal.scrollToBottom();
  await wait(60);
  const after = controller.terminal.buffer.active;
  check(
    'scrolling back down reaches the very bottom',
    controller.isAtBottom() && after.viewportY === after.baseY,
    `viewportY=${after.viewportY} baseY=${after.baseY}`,
  );

  // --- history viewer ---
  const historyHost = document.createElement('div');
  historyHost.style.cssText = 'width:800px;height:400px;position:relative';
  document.body.appendChild(historyHost);

  const requested: Array<{ from: number; count: number }> = [];
  let exited = 0;
  const view = new HistoryView({
    container: historyHost,
    fontSize: 14,
    fontFamily: 'monospace',
    theme: { background: '#0d1117', foreground: '#f0f6fc' },
    fetchPage: async (from, count) => {
      requested.push({ from, count });
      return Array.from({ length: count }, (_, index) => `storia ${from + index}`);
    },
    onExit: () => {
      exited += 1;
    },
  });

  const TOTAL = 100_000;
  view.setRange({ firstLine: 0, totalLines: TOTAL });
  view.open(50_000);
  await wait(300);

  check('history view opens', view.isOpen);
  check(
    'it asks for a page at the anchor',
    requested.length > 0 && requested[0].from < 50_000 && requested[0].from > 49_000,
    JSON.stringify(requested[0]),
  );
  check(
    'it asks for one screenful, not the whole session',
    requested[0].count > 0 && requested[0].count < 100,
    `count=${requested[0].count}`,
  );

  const historyBuffer = (view as unknown as { terminal: { buffer: { active: any } } }).terminal.buffer
    .active;
  const firstRow = historyBuffer.getLine(0)?.translateToString(true);
  check('the fetched page lands in the terminal', firstRow === `storia ${requested[0].from}`, String(firstRow));

  const status = historyHost.querySelector('.history-view__status') as HTMLElement;
  const statusText = status.textContent || '';
  check(
    'the status line reports the real position',
    // The whole session, not the page: a viewer that says "1–19 of 19" tells
    // the user they have reached the end of a 100k-line history.
    statusText.includes(`of ${TOTAL}`) && statusText.includes(String(requested[0].from + 1)),
    JSON.stringify(statusText),
  );

  const spacer = historyHost.querySelector('.history-view__spacer') as HTMLElement;
  const scroller = historyHost.querySelector('.history-view__scroller') as HTMLElement;
  check('the scrollbar spans the whole session', spacer.clientHeight > 100_000, `${spacer.clientHeight}px`);

  const before = requested.length;
  scroll(scroller, Math.max(0, scroller.scrollTop - 200_000));
  await wait(300);
  const newer = requested.slice(before);
  check(
    'scrolling up pages further back',
    newer.length > 0 && newer[newer.length - 1].from < requested[0].from,
    JSON.stringify(newer[newer.length - 1] ?? null),
  );

  // The top of the range must be reachable, not just approachable.
  scroll(scroller, 0);
  await wait(300);
  check(
    'the oldest line is reachable',
    requested[requested.length - 1].from === 0,
    JSON.stringify(requested[requested.length - 1]),
  );

  // And so must the bottom: this is where the viewer hands back to the live
  // terminal, and a coordinate mismatch here strands the user in history.
  scroll(scroller, spacer.clientHeight);
  await wait(200);
  check('scrolling past the newest line returns to live', exited > 0 && !view.isOpen, `exited=${exited}`);

  await checkModeQueriesDoNotKillTheTerminal();
  await checkAWorkflowPopupBehavesLikeTheFilePopup();
  await checkARunningWorkflowSaysWhatItIsDoing();
  await checkAWorkflowShowsItsPhasesAndItsAgents();
  await checkAFailedWorkflowReadsAsFailedEverywhere();
  await checkAWorkflowNothingWillReportOnStopsSpinning();
  await checkOnePromptDrawsOneUserBubble();
  await checkALaunchedWorkflowReadsAsRunningUntilItEnds();
  await checkAnAgentPopupShowsWhatTheAgentIsDoing();
  await checkATallDialogStaysOnScreen();
  await checkTheComposerShrinksWithTheWorkspaceRail();
  await checkAMessageThatCouldNotBeSentSaysSoAndCanBeRetried();
  await checkTheFixedBarsNeverWrap();
  await checkALiveAnswerAppearsAsItStreams();
  await checkSilentStepsLeaveNoRowButKeepTheirTrace();
  await checkNoRowIsDrawnWithNothingToRead();
  await checkAQuestionIsAnsweredByClicking();
  await checkANoToolFallbackQuestionSurvivesReload();
  await checkACardTheAgentGaveUpOnStopsOfferingAnAnswer();
  await checkAQuestionCanBeAnsweredInYourOwnWords();
  await checkTypedWordsThatDidNotLandAreNotShownAsAnswered();
  await checkThePlanControlCanBeReviewedAndActedOn();
  await checkThePhoneLayoutIsUsable();
  await checkThePhoneReadsTheMessageFirst();
  await checkThePhoneShellSurfacesAreUsable();
  await checkTheConversationsTerminalCanBeDrivenFromAPhone();
  await checkALongTabNameStaysInsideTheStrip();
  await checkAnOverflowingTabStripCanBeNavigated();
  await checkAnUnreportedFigureIsNeverDrawnAsZero();
  await checkTheUsageChartsAreInteractive();
  await checkAServerOlderThanThePageSaysSo();
  await checkUnattributedWorkCanBeAttributedByHand();
  await checkTheHistoryListsConversationsRatherThanRequests();
  await checkTheCommandMenuIsFullBeforeTheFirstMessage();
  await checkANewConversationCanBeStartedFromTheComposer();
  await checkTheFileEditorShowsTheFile();
  await checkAReadOnlyFileStaysReadOnly();
  await checkAChatFileLinkOpensAtItsSourceLine();
  await checkARetriedGuidedIssueKeepsItsWorkflow();
  await checkTheGitHubPanelSaysWhoIsOnItAndWhatItLinksTo();
  // After the editor checks on purpose: this one opens a FileEditorDialog,
  // and Monaco is a module-level singleton that does not survive being mounted
  // and torn down before they get to it.
  await checkALongPopupTitleStaysInsideItsWindow();
  await checkATurnsBadgeSaysHowItEnded();
  await checkATurnsFiguresAreNeverCutShort();
  await checkAWaitingMessageCanBeSentNow();
  await checkALongQueueCollapsesToOneRow();
  await checkFoldedHistoryIsNotBuiltUntilItIsOpened();
  await checkATurnCanBeBranchedFromItsHeader();
  await checkAConversationTellsOneStoryAboutItsTokens();
  await checkTheModelShownIsTheModelThatRan();
  await checkTheModelPickerSaysWhereTheDefaultCameFrom();
  await checkTheEffortChipSaysAndSetsHowHardTheAgentThinks();
  await checkARememberedLevelSeedsOnlyFreshWorkAndSurvivesAReload();
  await checkTheContextReadingIsHonestAboutItsCeiling();
  await checkTheAccountReadingIsOnlyEverWhatAProviderSaid();
  await checkTheTurnIndexListsTheWholeConversation();
  await checkClearingResetsTheFiguresAboveTheChat();
  await checkASilentRuntimeSaysSoRatherThanGoingBlank();
  await checkTheSilenceFitsThePhonesCollapsedHeader();
  await checkTheUsageWindowReachesBeforeThisYear();
  await checkTheEffortHistogramsAreReadableWithoutAMouse();
  await checkTheFileTreeAndTheShellAreSizedForAThumb();
  await checkAnExpandedReasoningRowIsNeverEmpty();
  await checkAWaitingConversationIsVisibleWithoutOpeningIt();
  await checkEveryConversationCanBeFoundAndReopened();
  await checkAConversationSaysWhichApprovalModeItIsIn();
  await checkTheEnvironmentSizePickerIsUsable();

  const pre = document.createElement('pre');
  pre.id = 'results';
  pre.textContent = results.join('\n');
  document.body.appendChild(pre);
}

/**
 * A card whose question can no longer be delivered says so, and stops asking.
 *
 * Here rather than in a unit test because the defect was entirely a rendered
 * one (#174). On omp the runtime abandoned the `tools/call` after 30 seconds
 * while the card stayed on screen with live buttons for another ten minutes —
 * every one of which would have sent an answer into a request the agent had
 * already dropped — and the sentence it eventually showed, "Skipped without
 * answering", blamed the user for a question they were never able to answer.
 * Both halves of that are about what is on the glass, so both are checked
 * there: the buttons are gone, and the sentence is the true one.
 */
async function checkACardTheAgentGaveUpOnStopsOfferingAnAnswer(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => {
      sent.push(message);
    },
  } as never);

  const ask = {
    question: 'How should I proceed?',
    header: 'Next move',
    multiSelect: false,
    options: [
      { label: 'PR #167, then continue #168', description: 'Verify the suite, then open its PR' },
      { label: 'Continue #168 only', description: 'Leave #167 un-PRd for now' },
    ],
  };

  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'omp',
      state: 'awaiting_answer',
      capabilities: { streaming: true, toolCalls: true, questions: true },
      messages: [
        {
          id: 'm1', seq: 1, turnId: 't1', role: 'assistant', ts: 1,
          blocks: [{
            kind: 'tool',
            toolId: 'write_20|fc_tmp_duo3u3bkp7',
            name: 'mcp__ccweb_ask_user_question',
            toolKind: 'other',
            status: 'running',
            input: ask,
          }],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [{
        requestId: 'q-1',
        toolId: 'write_20|fc_tmp_duo3u3bkp7',
        question: ask.question,
        header: ask.header,
        multiSelect: false,
        ts: 2,
        options: [
          { optionId: 'opt-0', label: ask.options[0].label, description: ask.options[0].description },
          { optionId: 'opt-1', label: ask.options[1].label, description: ask.options[1].description },
        ],
      }],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 2,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'omp',
      runtimeLabel: 'Oh My Pi',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const liveCard = host.querySelector('[data-question-card="live"]') as HTMLElement | null;
  check('the question starts out as a live card', !!liveCard);
  if (!liveCard) {
    root.unmount();
    host.remove();
    return;
  }

  /**
   * Buttons a person could actually press.
   *
   * Counted rather than trusting `data-question-card`, and by visibility and
   * reachability rather than by presence: a control left in the tree at
   * `opacity:0` or `pointer-events:none` still answers `querySelector`, and a
   * geometry sweep drops it silently instead of failing.
   */
  const pressable = (card: HTMLElement): HTMLElement[] =>
    Array.from(card.querySelectorAll<HTMLElement>('button')).filter((node) => {
      const style = getComputedStyle(node);
      const box = node.getBoundingClientRect();
      return style.visibility !== 'hidden'
        && style.display !== 'none'
        && style.pointerEvents !== 'none'
        && Number(style.opacity || '1') > 0.05
        && box.width > 0
        && box.height > 0
        && node.tabIndex >= 0
        && !(node as HTMLButtonElement).disabled;
    });

  check(
    'a live card offers something to press',
    pressable(liveCard).length >= 2,
    `${pressable(liveCard).length} pressable`,
  );

  // What the runtime giving up looks like from the browser's side: the call
  // that asked reports failed, and the session resolves the question against
  // the same tool id — carrying `abandoned`, which is the whole difference
  // between this and a skip.
  controller.transcript.apply({
    t: 'tool',
    seq: 10,
    ts: Date.now(),
    toolId: 'write_20|fc_tmp_duo3u3bkp7',
    patch: { status: 'failed', error: 'MCP error: Request timeout after 30000ms' },
  } as never);
  controller.transcript.apply({
    t: 'question_resolved',
    seq: 11,
    ts: Date.now(),
    requestId: 'q-1',
    toolId: 'write_20|fc_tmp_duo3u3bkp7',
    optionIds: [],
    abandoned: true,
  } as never);
  await wait(250);
  settle(document);

  const card = host.querySelector('[data-question-card]') as HTMLElement | null;
  check('the card is still in the conversation, as the record of what was asked', !!card);
  if (!card) {
    root.unmount();
    host.remove();
    return;
  }

  check(
    'it no longer offers an answer nobody would receive',
    pressable(card).length === 0,
    `${pressable(card).length} still pressable`,
  );
  const text = card.textContent || '';
  check(
    'and it says the agent stopped waiting',
    text.includes('stopped waiting'),
    text.slice(-90),
  );
  check(
    'rather than blaming the person who was never asked',
    !text.includes('Skipped without answering'),
    text.slice(-90),
  );
  check(
    'the outcome is recorded as its own thing, not as a skip',
    card.querySelector('[data-question-answer="abandoned"]') !== null,
    card.querySelector('[data-question-answer]')?.getAttribute('data-question-answer') || 'none',
  );
  check(
    'and nothing was sent on the way there',
    sent.filter((message) => message.type === 'chat_question_answer').length === 0,
  );

  root.unmount();
  host.remove();
}

/**
 * A question the model asked is answered by clicking, and stays as a record.
 *
 * Here rather than in a unit test because every claim is about the rendered
 * conversation: that the card appears *inside* the transcript at the call that
 * asked (not in a tray under it), that a multi-select needs a confirm and a
 * single-select does not, and that the card survives the answer instead of
 * vanishing. A jsdom assertion on props would pass for a card rendered into
 * nowhere.
 */
async function checkAQuestionIsAnsweredByClicking(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => {
      sent.push(message);
    },
  } as never);

  const askBlock = (toolId: string, input: unknown): Record<string, unknown> => ({
    kind: 'tool',
    toolId,
    name: 'mcp__ccweb__ask_user_question',
    toolKind: 'other',
    status: 'running',
    input,
  });

  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'awaiting_answer',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        questions: true, interrupt: true, resume: true, fork: false, attachments: true,
        usage: true, cost: true, plan: false,
      },
      messages: [
        {
          id: 'm1', seq: 1, turnId: 't1', role: 'user', ts: 1,
          blocks: [{ kind: 'text', text: 'Fix the parser.' }],
        },
        {
          id: 'm2', seq: 2, turnId: 't1', role: 'assistant', ts: 2,
          blocks: [
            askBlock('tool-single', {
              question: 'Which approach should I take?',
              header: 'Approach',
              multiSelect: false,
              options: [
                { label: 'Rewrite it', description: 'Slower but cleaner' },
                { label: 'Patch it', description: 'Faster, more debt' },
              ],
            }),
          ],
        },
        {
          id: 'm3', seq: 3, turnId: 't1', role: 'assistant', ts: 3,
          blocks: [
            askBlock('tool-multi', {
              question: 'Which rules should I apply?',
              multiSelect: true,
              options: [{ label: 'semicolons' }, { label: 'trailing commas' }, { label: 'single quotes' }],
            }),
          ],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [
        {
          requestId: 'q-single', toolId: 'tool-single', question: 'Which approach should I take?',
          header: 'Approach', multiSelect: false, ts: 2,
          options: [
            { optionId: 'opt-0', label: 'Rewrite it', description: 'Slower but cleaner' },
            { optionId: 'opt-1', label: 'Patch it', description: 'Faster, more debt' },
          ],
        },
        {
          requestId: 'q-multi', toolId: 'tool-multi', question: 'Which rules should I apply?',
          multiSelect: true, ts: 3,
          options: [
            { optionId: 'opt-0', label: 'semicolons' },
            { optionId: 'opt-1', label: 'trailing commas' },
            { optionId: 'opt-2', label: 'single quotes' },
          ],
        },
      ],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 3,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const cards = Array.from(host.querySelectorAll('[data-question-card]')) as HTMLElement[];
  check('both questions render as cards', cards.length === 2, `found ${cards.length}`);
  if (cards.length !== 2) return;

  const [single, multi] = cards;

  // Inside the conversation, at the call that asked — the thing that makes the
  // exchange still read as a conversation when scrolled back to. A card in a
  // pinned tray would be outside this element entirely.
  const inTranscript = single.closest('[data-message-id="m2"]');
  check('the card sits in the message that asked', !!inTranscript);

  const optionText = (card: HTMLElement): string => card.textContent || '';
  check(
    'the single-choice card offers every option',
    optionText(single).includes('Rewrite it') && optionText(single).includes('Patch it'),
  );
  check('option descriptions are shown', optionText(single).includes('Slower but cleaner'));

  // A single-choice question answers on the click itself; a multi-select must
  // not, or the first tick would send the answer and the rest would go nowhere.
  const singleButtons = Array.from(single.querySelectorAll('button')) as HTMLButtonElement[];
  const patch = singleButtons.find((b) => (b.textContent || '').includes('Patch it'));
  check('each option is its own control', !!patch);

  const boxes = Array.from(multi.querySelectorAll('input[type="checkbox"]')) as HTMLInputElement[];
  check('the multi-select card offers checkboxes', boxes.length === 3, `found ${boxes.length}`);
  const confirm = (Array.from(multi.querySelectorAll('button')) as HTMLButtonElement[])
    .find((b) => (b.textContent || '').trim() === 'Confirm');
  check('the multi-select card has a confirm', !!confirm);
  check('confirm is disabled before anything is picked', !!confirm && confirm.disabled);

  if (boxes.length === 3 && confirm) {
    boxes[0].click();
    boxes[2].click();
    await wait(150);
    check('confirm becomes available once something is picked', !confirm.disabled);
    // Answers only. Opening a conversation also asks for its turn index (#86),
    // which is not an answer to anything and must not read as one.
    const answersSoFar = sent.filter((m) => m.type === 'chat_question_answer');
    check(
      'picking a checkbox does not answer on its own',
      answersSoFar.length === 0,
      `${answersSoFar.length} sent`,
    );
    confirm.click();
    await wait(150);
  }

  if (patch) {
    patch.click();
    await wait(200);
  }

  const answers = sent.filter((m) => m.type === 'chat_question_answer');
  check('both answers reach the server', answers.length === 2, `${answers.length} sent`);
  const multiAnswer = answers.find((m) => m.requestId === 'q-multi');
  const singleAnswer = answers.find((m) => m.requestId === 'q-single');
  check(
    'the multi-select answer carries every pick',
    !!multiAnswer && JSON.stringify(multiAnswer.optionIds) === JSON.stringify(['opt-0', 'opt-2']),
    JSON.stringify(multiAnswer?.optionIds),
  );
  check(
    'the single-choice answer carries the one pick',
    !!singleAnswer && JSON.stringify(singleAnswer.optionIds) === JSON.stringify(['opt-1']),
    JSON.stringify(singleAnswer?.optionIds),
  );

  // The card remains interactive only until this correlated acknowledgement.
  // A durable resolution later remains the source of record for every screen.
  for (const answer of answers) {
    controller.handle({
      type: 'chat_question_answer_ack',
      sessionId: 'browser-check',
      submissionId: answer.submissionId,
      accepted: true,
    } as never);
  }
  await wait(100);

  await wait(200);
  const after = Array.from(host.querySelectorAll('[data-question-card]')) as HTMLElement[];
  // The card must not vanish on being answered: scrolling back past a decision
  // should show the decision, which is the acceptance criterion a tray-based
  // card fails.
  check('the cards stay in the conversation after answering', after.length === 2, `${after.length} left`);
  check(
    'an answered card stops offering buttons',
    after.every((card) => card.getAttribute('data-question-card') === 'answered'),
    after.map((c) => c.getAttribute('data-question-card')).join(','),
  );
  check('the answered card still shows what was asked', (after[0].textContent || '').includes('Which approach'));
  check('the answered card shows what was chosen', (after[0].textContent || '').includes('Patch it'));

  /**
   * Which options a card has marked, by label.
   *
   * Found by the mark itself — the screen-reader word every chosen option
   * carries — rather than by anything the fix introduced, so this reads the
   * same on the code before it. The label is the option row's text with that
   * word taken back off; matched by substring below, because an option's
   * description runs straight into its label in `textContent`.
   */
  const markedIn = (card: HTMLElement): string[] =>
    Array.from(card.querySelectorAll<HTMLElement>('span'))
      .filter((node) => node.textContent === 'chosen')
      .map((node) => (node.parentElement?.textContent || '').replace('chosen', '').trim());
  const marks = (card: HTMLElement | undefined, labels: string[]): boolean => {
    if (!card) return false;
    const found = markedIn(card);
    return found.length === labels.length && labels.every((label, at) => found[at].includes(label));
  };

  const singleCard = after.find((card) => (card.textContent || '').includes('Which approach'));
  const multiCard = after.find((card) => (card.textContent || '').includes('Which rules'));
  check(
    'the marks are on the options themselves, not only in a sentence underneath',
    marks(multiCard, ['semicolons', 'single quotes']) && marks(singleCard, ['Patch it']),
    `${JSON.stringify(multiCard ? markedIn(multiCard) : null)} / ${JSON.stringify(singleCard ? markedIn(singleCard) : null)}`,
  );

  // Issue #113: leaving the conversation and coming back.
  //
  // A tab switch takes the whole surface down and builds it again from the
  // snapshot the server sends on rejoin — which is why the marks went. They
  // were never in the record the card was drawn from; they were in the card's
  // own memory of the click, and that memory does not survive being unmounted.
  //
  // So this tears the surface down and stands a *fresh* controller up on the
  // snapshot, which is the only fixture that reproduces it. Answering in place
  // and re-hydrating the same tree passes on the broken code.
  // What the server sends back when an answer lands, which nothing in this
  // fixture had been doing: the conversation's own record of the decision.
  // Without it the marks on screen are only the card's memory of the click,
  // which is exactly the state the issue is about.
  for (const answer of answers) {
    controller.transcript.apply({
      t: 'question_resolved',
      seq: 900 + answers.indexOf(answer),
      ts: Date.now(),
      requestId: answer.requestId,
      toolId: answer.requestId === 'q-multi' ? 'tool-multi' : 'tool-single',
      optionIds: answer.optionIds,
      skipped: false,
    } as never);
  }
  await wait(150);

  const rejoinSnapshot = {
    sessionId: 'browser-check',
    runtime: 'claude',
    state: 'idle',
    capabilities: { questions: true, streaming: true },
    messages: JSON.parse(JSON.stringify(controller.transcript.messages)),
    pendingPermissions: [],
    queued: [],
    firstSeq: 1,
    replayFrom: 1,
    cursor: 99,
    live: true,
    bypassPermissions: false,
    // What the server now carries, and the whole point of the fix. Taken from
    // the transcript this browser built rather than typed out, so it is the
    // same answer the reducer folded out of the events above.
    answeredQuestions: {
      'tool-multi': controller.transcript.answerFor('tool-multi'),
      'tool-single': controller.transcript.answerFor('tool-single'),
    },
  };
  root.unmount();
  await wait(50);

  const rejoined = new ChatController('browser-check', { send: () => {} } as never);
  rejoined.handle({ type: 'chat_snapshot', sessionId: 'browser-check', snapshot: rejoinSnapshot } as never);
  const backRoot = createRoot(host);
  backRoot.render(
    React.createElement(ChatView, {
      controller: rejoined,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(300);
  settle(document);

  const back = Array.from(host.querySelectorAll('[data-question-card]')) as HTMLElement[];
  const backMulti = back.find((card) => (card.textContent || '').includes('Which rules'));
  const backSingle = back.find((card) => (card.textContent || '').includes('Which approach'));
  check(
    'an answered question comes back marked after leaving the conversation',
    marks(backSingle, ['Patch it']),
    backSingle ? JSON.stringify(markedIn(backSingle)) : 'the card is gone',
  );
  check(
    'and a pick-several answer comes back with every option that was picked',
    marks(backMulti, ['semicolons', 'single quotes']),
    backMulti ? JSON.stringify(markedIn(backMulti)) : 'the card is gone',
  );
  check(
    'and never reads as a question nobody answered',
    back.every((card) => !(card.textContent || '').includes('Skipped without answering')),
    back.map((card) => (card.textContent || '').slice(-40)).join(' | ') || 'no cards',
  );

  backRoot.unmount();
  host.remove();
}

/**
 * A structured-response fallback has no tool bubble to own its question card.
 *
 * That is the path used when a runtime cannot call the questionnaire MCP: the
 * server still records a real `QuestionRequest`, but its `toolId` is absent and
 * the reducer gives it a durable question block in the assistant message that
 * asked it. This drives that card through a combined picked-and-typed answer, then
 * destroys both the view and controller and rebuilds them from the snapshot a
 * reload receives. A card backed only by component state passes before the
 * teardown and disappears, or comes back blank, afterwards.
 */
async function checkANoToolFallbackQuestionSurvivesReload(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const request = {
    requestId: 'fallback-browser-question',
    question: 'Which rollout safeguards should the fallback path use?',
    header: 'Fallback rollout',
    multiSelect: true,
    ts: 1,
    options: [
      { optionId: 'opt-0', label: 'Canary tenants', description: 'Start with the internal cohort.' },
      { optionId: 'opt-1', label: 'Feature flag', description: 'Keep an immediate off switch.' },
    ],
  };
  const ownWords = 'Pause automatically if the questionnaire delivery rate drops.';
  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('fallback-browser', {
    send: (message: Record<string, unknown>) => sent.push(message),
  } as never);

  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'fallback-browser',
    snapshot: {
      sessionId: 'fallback-browser',
      runtime: 'grok',
      state: 'awaiting_answer',
      capabilities: { streaming: true, questions: true, plan: true },
      messages: [
        {
          id: 'fallback-assistant',
          seq: 1,
          turnId: 'fallback-turn',
          role: 'assistant',
          ts: 1,
          blocks: [
            { kind: 'text', text: 'I need one rollout detail before continuing.' },
            { kind: 'question', request },
          ],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [request],
      questionHistory: [request],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
      planMode: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'grok',
      runtimeLabel: 'Grok CLI',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);
  settle(document);

  const live = host.querySelector('[data-question-card="live"]') as HTMLElement | null;
  check(
    'a no-tool fallback question is a live card in the default-mode conversation',
    Boolean(live)
      && Boolean(live?.closest('[role="log"]'))
      && Boolean(live?.closest('[data-message-id="fallback-assistant"]'))
      && !live?.closest('[aria-label="Questions from the assistant"]'),
    live ? (live.textContent || '').replace(/\s+/g, ' ').slice(0, 180) : 'no live fallback card',
  );

  const first = live?.querySelector<HTMLInputElement>('input[type="checkbox"]');
  first?.click();
  (live?.querySelector('[data-question-own-words="closed"]') as HTMLElement | null)?.click();
  await wait(150);
  const area = live?.querySelector('textarea') as HTMLTextAreaElement | null;
  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
  if (area) {
    setter?.call(area, ownWords);
    area.dispatchEvent(new Event('input', { bubbles: true }));
  }
  await wait(150);
  const confirm = (Array.from(live?.querySelectorAll('button') ?? []) as HTMLButtonElement[])
    .find((button) => (button.textContent || '').trim() === 'Confirm');
  confirm?.click();
  await wait(200);

  const answer = sent.find((message) => message.type === 'chat_question_answer');
  check(
    'the no-tool fallback card sends its selected and typed answer by request id',
    Boolean(answer)
      && answer?.requestId === request.requestId
      && JSON.stringify(answer?.optionIds) === '["opt-0"]'
      && answer?.text === ownWords
      && answer?.skipped === false,
    JSON.stringify(answer ?? null),
  );

  // The durable answer the session writes after delivering the response. This
  // supersedes the card's optimistic click state and is what every other
  // browser — including this one after a reload — is meant to read.
  controller.transcript.apply({
    t: 'question_resolved',
    seq: 2,
    ts: 2,
    requestId: request.requestId,
    optionIds: ['opt-0'],
    text: ownWords,
    skipped: false,
  } as never);
  await wait(200);
  settle(document);

  const settled = host.querySelector('[data-question-card="answered"]') as HTMLElement | null;
  const settledText = (settled?.textContent || '').replace(/\s+/g, ' ');
  check(
    'the resolved no-tool fallback remains a readable answered card',
    Boolean(settled)
      && Boolean(settled?.closest('[role="log"]'))
      && !settled?.closest('[aria-label="Questions from the assistant"]')
      && settledText.includes(request.question)
      && settledText.includes('Canary tenants')
      && settledText.includes(ownWords)
      && settled?.querySelectorAll('[data-question-option="chosen"]').length === 2,
    settledText.slice(0, 260) || 'no answered fallback card',
  );

  root.unmount();
  await wait(50);

  const reloaded = new ChatController('fallback-browser', { send: () => {} } as never);
  reloaded.handle({
    type: 'chat_snapshot',
    sessionId: 'fallback-browser',
    snapshot: {
      sessionId: 'fallback-browser',
      runtime: 'grok',
      state: 'idle',
      capabilities: { streaming: true, questions: true, plan: true },
      messages: [
        {
          id: 'fallback-assistant',
          seq: 1,
          turnId: 'fallback-turn',
          role: 'assistant',
          ts: 1,
          blocks: [
            { kind: 'text', text: 'I need one rollout detail before continuing.' },
            {
              kind: 'question',
              request,
              answer: {
                optionIds: ['opt-0'],
                text: ownWords,
                skipped: false,
              },
            },
          ],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [],
      questionHistory: [request],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 2,
      live: true,
      bypassPermissions: false,
      planMode: false,
    },
  } as never);

  const reloadedRoot = createRoot(host);
  reloadedRoot.render(
    React.createElement(ChatView, {
      controller: reloaded,
      runtime: 'grok',
      runtimeLabel: 'Grok CLI',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(350);
  settle(document);

  const cards = Array.from(host.querySelectorAll<HTMLElement>('[data-question-card]'));
  const afterReload = cards[0] ?? null;
  const afterReloadText = (afterReload?.textContent || '').replace(/\s+/g, ' ');
  check(
    'a fresh controller rebuilds the fallback question and answer from its durable message block',
    cards.length === 1
      && afterReload?.getAttribute('data-question-card') === 'answered'
      && Boolean(afterReload.closest('[role="log"]'))
      && !afterReload.closest('[aria-label="Questions from the assistant"]')
      && afterReloadText.includes(request.question)
      && afterReloadText.includes('Canary tenants')
      && afterReloadText.includes(ownWords)
      && afterReload?.querySelectorAll('[data-question-option="chosen"]').length === 2
      && afterReload.querySelectorAll('button').length === 0,
    `${cards.length} cards :: ${afterReloadText.slice(0, 260) || 'no fallback card'}`,
  );

  reloadedRoot.unmount();
  host.remove();
}

/**
 * An option list the model wrote is not the only answer a question can have.
 *
 * Two defects, both only visible with a layout engine running and both from the
 * same real conversation. The options a model writes are sentences — its own
 * gloss on what picking one would mean — and `Button` sets `white-space:
 * nowrap`, so every description ran off the right-hand edge of the card and
 * kept going past the edge of the conversation. And the last option a model
 * writes is routinely "Let me explain in my own words", which was a button like
 * any other: clicking it answered the question with the string "Let me explain
 * in my own words" and bought a wasted round trip.
 *
 * So: nothing inside the card may reach past its own border, and that row is a
 * textarea whose contents are the answer. Asserted against the rendered card
 * because both claims are about geometry and events, not about props.
 */
async function checkAQuestionCanBeAnsweredInYourOwnWords(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => {
      sent.push(message);
    },
  } as never);

  // The question from the conversation this was reported from, verbatim —
  // including the option the model wrote for itself at the end.
  const OPTIONS = [
    {
      label: 'Persistent storage, attached to each container',
      description:
        "The user's workspace lives outside the container and is attached to it, the way per-user " +
        'environments already keep a home directory. Closing a session leaves the work where it was.',
    },
    {
      label: 'Fresh checkout each time',
      description:
        'A session starts by pulling the project into a clean container. Anything not pushed is ' +
        'gone when the session closes — explicit and cheap, but unforgiving.',
    },
    {
      label: 'Let me explain in my own words',
      description: 'None of these is quite right.',
    },
  ];
  const ask = {
    question: "When a session's container is destroyed, what happens to the work inside it?",
    header: 'WHERE WORK LIVES',
    multiSelect: false,
    options: OPTIONS,
  };

  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'awaiting_answer',
      capabilities: { streaming: true, questions: true },
      messages: [
        {
          id: 'a1', seq: 1, turnId: 't1', role: 'assistant', ts: 1,
          blocks: [
            {
              kind: 'tool', toolId: 'tool-own', name: 'mcp__ccweb__ask_user_question',
              toolKind: 'other', status: 'running', input: ask,
            },
          ],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [
        {
          requestId: 'q-own', toolId: 'tool-own', ts: 1,
          question: ask.question, header: ask.header, multiSelect: false,
          options: OPTIONS.map((option, at) => ({ optionId: `opt-${at}`, ...option })),
        },
      ],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const card = host.querySelector('[data-question-card="live"]') as HTMLElement | null;
  check('the live question renders as a card', !!card);
  if (!card) {
    root.unmount();
    host.remove();
    return;
  }

  // ------------------------------------------------------------------ wrapping
  const cardBox = card.getBoundingClientRect();
  const spilled = Array.from(card.querySelectorAll<HTMLElement>('*')).filter(
    (node) => node.getBoundingClientRect().right > cardBox.right + 1,
  );
  check(
    'no part of a question reaches past the edge of its own card',
    spilled.length === 0,
    spilled.length
      ? spilled
          .slice(0, 2)
          .map((node) => `${(node.textContent || '').trim().slice(0, 28)} → ${Math.round(node.getBoundingClientRect().right)} of ${Math.round(cardBox.right)}`)
          .join(' | ')
      : `${Math.round(cardBox.width)}px wide`,
  );

  const optionButtons = Array.from(card.querySelectorAll('button')) as HTMLButtonElement[];
  const persistent = optionButtons.find((button) =>
    (button.textContent || '').includes('Persistent storage'),
  );
  check('the first option is its own control', !!persistent);
  // `scrollWidth > clientWidth` is the layout engine saying "this did not fit".
  // The bug was one line of text laid out at whatever width it wanted inside a
  // box the width of the card, so this is the measurement that names it.
  check(
    'a long option lays itself out inside the width it was given',
    !!persistent && persistent.scrollWidth <= persistent.clientWidth + 1,
    persistent ? `${persistent.scrollWidth}px of content in ${persistent.clientWidth}px` : 'no option',
  );
  // And wrapped rather than merely clipped or pushed onto its own long line.
  // Measured against the description's own type size, so this says "this
  // paragraph occupies more than one line" rather than trusting a pixel count
  // that a theme could move.
  const description = Array.from(card.querySelectorAll<HTMLElement>('span')).find((span) =>
    (span.textContent || '').startsWith("The user's workspace lives outside"),
  );
  const lineOf = (node: HTMLElement): number => parseFloat(getComputedStyle(node).fontSize) || 13;
  check(
    'and its description wraps onto as many lines as it needs',
    !!description && description.getBoundingClientRect().height > lineOf(description) * 2.4,
    description
      ? `${Math.round(description.getBoundingClientRect().height)}px at ${lineOf(description)}px type`
      : 'no description',
  );

  // ------------------------------------------------------- the free-text row
  const ownRow = card.querySelector('[data-question-own-words]') as HTMLElement | null;
  check('the card offers to take an answer in the user’s own words', !!ownRow);
  check(
    'and does not offer the model’s own version of it as well',
    card.querySelectorAll('[data-question-own-words]').length === 1
      && optionButtons.filter((button) => (button.textContent || '').includes('Let me explain')).length === 1,
    `${card.querySelectorAll('[data-question-own-words]').length} rows`,
  );
  check(
    'and keeps the wording the model chose for it',
    (ownRow?.textContent || '').includes('Let me explain in my own words'),
    (ownRow?.textContent || '').trim().slice(0, 48),
  );

  const explain = optionButtons.find((button) => (button.textContent || '').includes('Let me explain'));
  if (explain) {
    explain.click();
    await wait(200);
  }

  // The defect, stated as the thing that must not happen: clicking that row
  // used to answer the question with its own label and unblock the agent.
  check(
    'opening it does not answer the question with the label on it',
    sent.filter((message) => message.type === 'chat_question_answer').length === 0,
    `${sent.filter((message) => message.type === 'chat_question_answer').length} answers sent`,
  );

  const area = card.querySelector('textarea') as HTMLTextAreaElement | null;
  check('opening it puts a textarea on the card', !!area);
  check(
    'which is big enough to write an explanation in',
    !!area && isPainted(area) && area.getBoundingClientRect().height >= 40,
    area ? `${Math.round(area.getBoundingClientRect().width)}x${Math.round(area.getBoundingClientRect().height)}` : 'no textarea',
  );
  if (!area) {
    root.unmount();
    host.remove();
    return;
  }

  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
  setter?.call(area, 'A container per project, not per session.');
  area.dispatchEvent(new Event('input', { bubbles: true }));
  await wait(150);

  const send = (Array.from(card.querySelectorAll('button')) as HTMLButtonElement[]).find(
    (button) => (button.textContent || '').trim() === 'Send',
  );
  check('typed words can be sent', !!send && !send.disabled);
  send?.click();
  await wait(200);

  const answer = sent.find((message) => message.type === 'chat_question_answer');
  check('the answer reaches the server', !!answer);
  check(
    'and carries the words rather than an option id',
    !!answer
      && answer.text === 'A container per project, not per session.'
      && JSON.stringify(answer.optionIds) === '[]',
    `${JSON.stringify(answer?.text)} / ${JSON.stringify(answer?.optionIds)}`,
  );
  // The half that decides whether the agent hears anything at all: a typed
  // answer travelling as a skip would reach the model as "they declined".
  check('and is not sent as a skip', !!answer && answer.skipped === false, String(answer?.skipped));

  // What the server writes back, and what a second browser would see.
  controller.transcript.apply({
    t: 'question_resolved',
    seq: 900,
    ts: 1,
    requestId: 'q-own',
    toolId: 'tool-own',
    optionIds: [],
    text: 'A container per project, not per session.',
    skipped: false,
  } as never);
  await wait(200);

  const settled = host.querySelector('[data-question-card="answered"]') as HTMLElement | null;
  check('the card settles as answered', !!settled);
  const settledText = (settled?.textContent || '').replace(/\s+/g, ' ');
  check(
    'and the answered card shows what was typed',
    settledText.includes('A container per project, not per session.'),
    settledText.slice(-80),
  );
  check(
    'and never reads as a question nobody answered',
    !settledText.includes('Skipped without answering'),
    settledText.slice(-60),
  );
  check(
    'and still lists the options the model offered',
    settledText.includes('Persistent storage') && settledText.includes('Fresh checkout'),
  );

  root.unmount();
  await wait(50);

  // ------------------------------------------------- and on a pick-several
  //
  // Its own mount rather than a second card in the fixture above: a
  // multi-select answers from the Confirm button under the whole card, so the
  // claim is that one press carries the ticks *and* the sentence. A card that
  // sent only one of them would look identical up to the click.
  const multiSent: Array<Record<string, unknown>> = [];
  const multi = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => {
      multiSent.push(message);
    },
  } as never);
  const multiAsk = {
    question: 'Which rules should I apply?',
    multiSelect: true,
    options: [{ label: 'semicolons' }, { label: 'trailing commas' }],
  };
  multi.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check', runtime: 'claude', state: 'awaiting_answer',
      capabilities: { streaming: true, questions: true },
      messages: [
        {
          id: 'a1', seq: 1, turnId: 't1', role: 'assistant', ts: 1,
          blocks: [
            {
              kind: 'tool', toolId: 'tool-multi', name: 'mcp__ccweb__ask_user_question',
              toolKind: 'other', status: 'running', input: multiAsk,
            },
          ],
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [
        {
          requestId: 'q-multi', toolId: 'tool-multi', ts: 1,
          question: multiAsk.question, multiSelect: true,
          options: [
            { optionId: 'opt-0', label: 'semicolons' },
            { optionId: 'opt-1', label: 'trailing commas' },
          ],
        },
      ],
      firstSeq: 1, replayFrom: 1, cursor: 1, live: true, bypassPermissions: false,
    },
  } as never);

  const multiRoot = createRoot(host);
  multiRoot.render(
    React.createElement(ChatView, {
      controller: multi,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const multiCard = host.querySelector('[data-question-card="live"]') as HTMLElement | null;
  const boxes = multiCard
    ? (Array.from(multiCard.querySelectorAll('input[type="checkbox"]')) as HTMLInputElement[])
    : [];
  check(
    'a pick-several question still ticks by option, and offers the words as well',
    boxes.length === 2 && !!multiCard?.querySelector('[data-question-own-words]'),
    `${boxes.length} boxes`,
  );

  const openWords = multiCard
    ? (Array.from(multiCard.querySelectorAll('button')) as HTMLButtonElement[]).find((button) =>
        (button.textContent || '').includes('own words'),
      )
    : undefined;
  const multiConfirm = (): HTMLButtonElement | undefined =>
    multiCard
      ? (Array.from(multiCard.querySelectorAll('button')) as HTMLButtonElement[]).find(
          (button) => (button.textContent || '').trim() === 'Confirm',
        )
      : undefined;

  check('confirm is refused while nothing is ticked and nothing is typed', multiConfirm()?.disabled === true);

  boxes[0]?.click();
  openWords?.click();
  await wait(200);
  const multiArea = multiCard?.querySelector('textarea') as HTMLTextAreaElement | null;
  if (multiArea) {
    setter?.call(multiArea, '…but never in generated files.');
    multiArea.dispatchEvent(new Event('input', { bubbles: true }));
    await wait(150);
  }
  multiConfirm()?.click();
  await wait(200);

  const multiAnswer = multiSent.find((message) => message.type === 'chat_question_answer');
  check(
    'one confirm carries both the ticks and the words',
    !!multiAnswer
      && JSON.stringify(multiAnswer.optionIds) === '["opt-0"]'
      && multiAnswer.text === '…but never in generated files.',
    `${JSON.stringify(multiAnswer?.optionIds)} / ${JSON.stringify(multiAnswer?.text)}`,
  );

  multiRoot.unmount();
  host.remove();
}

/**
 * The card settles on the click, and must give that up the moment the session
 * says something else.
 *
 * Reported from a real conversation: a sentence was typed into the card, the
 * card drew it in green under "Answered in their own words", and the agent's
 * very next line was "taking the skipped one" — it had been told the question
 * was skipped. The words never reached it. The cause that day was a server
 * older than the page it was serving, which dropped a field it had never heard
 * of, but the shape is general: a second browser answering first, or a session
 * that no longer holds the question, both end with a record that does not say
 * what this browser sent. Optimistic state is right up to that point and a lie
 * afterwards, so `question_resolved` — the same event the model's tool result
 * was built from — wins outright over it.
 *
 * Asserted through the rendered card because the claim is about what a person
 * reads off the screen, and the bug was invisible at every layer below it: the
 * frame was correct, the reducer was correct, and the card still said the
 * question had been answered in words nobody was given.
 */
async function checkTypedWordsThatDidNotLandAreNotShownAsAnswered(): Promise<void> {
  const WORDS = 'We need gitlab, gitea and oidc as well, handled by those platforms.';
  const OPTIONS = [
    { label: 'A token per forge, kept in the user’s storage' },
    { label: 'Install the tool, leave signing in to the user' },
  ];
  const ask = {
    question: 'How should non-GitHub forges be authenticated?',
    header: 'NON-GITHUB FORGES',
    multiSelect: false,
    options: OPTIONS,
  };

  // One mount per resolution, because the disagreement has to be the *first*
  // thing the card hears after the click — a card that had already been told
  // the truth once would pass this without the fix.
  const answerThenResolveWith = async (
    resolution: Record<string, unknown>,
  ): Promise<{
    text: string;
    card: HTMLElement | null;
    outcome: string | null | undefined;
    teardown: () => void;
  }> => {
    const host = document.createElement('div');
    host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
    document.body.appendChild(host);

    // `false` is the real connection contract for a frame attempted while the
    // WebSocket is closed. The card must stay pending until a durable event
    // proves that some answer landed.
    const controller = new ChatController('browser-check', { send: () => false } as never);
    controller.handle({
      type: 'chat_snapshot',
      sessionId: 'browser-check',
      snapshot: {
        sessionId: 'browser-check',
        runtime: 'claude',
        state: 'awaiting_answer',
        capabilities: { streaming: true, questions: true },
        messages: [
          {
            id: 'a1', seq: 1, turnId: 't1', role: 'assistant', ts: 1,
            blocks: [
              {
                kind: 'tool', toolId: 'tool-lost', name: 'mcp__ccweb__ask_user_question',
                toolKind: 'other', status: 'running', input: ask,
              },
            ],
          },
        ],
        pendingPermissions: [],
        pendingQuestions: [
          {
            requestId: 'q-lost', toolId: 'tool-lost', ts: 1,
            question: ask.question, header: ask.header, multiSelect: false,
            options: OPTIONS.map((option, at) => ({ optionId: `opt-${at}`, ...option })),
          },
        ],
        firstSeq: 1,
        replayFrom: 1,
        cursor: 1,
        live: true,
        bypassPermissions: false,
      },
    } as never);

    const root = createRoot(host);
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/tmp/project',
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
    await wait(400);

    const live = host.querySelector('[data-question-card="live"]') as HTMLElement | null;
    const open = live?.querySelector('[data-question-own-words="closed"]') as HTMLElement | null;
    open?.click();
    await wait(150);
    const area = live?.querySelector('textarea') as HTMLTextAreaElement | null;
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
    if (area) {
      setter?.call(area, WORDS);
      area.dispatchEvent(new Event('input', { bubbles: true }));
      await wait(150);
    }
    (Array.from(live?.querySelectorAll('button') ?? []) as HTMLButtonElement[])
      .find((button) => (button.textContent || '').trim() === 'Send')
      ?.click();
    await wait(200);

    check(
      'an answer attempted while disconnected leaves the original card answerable',
      !!host.querySelector('[data-question-card="live"]')
        && !host.querySelector('[data-question-answer-sending="true"]'),
    );

    controller.transcript.apply({
      t: 'question_resolved', seq: 900, ts: 1,
      requestId: 'q-lost', toolId: 'tool-lost',
      ...resolution,
    } as never);
    await wait(250);

    const card = host.querySelector('[data-question-card="answered"]') as HTMLElement | null;
    return {
      text: (card?.textContent || '').replace(/\s+/g, ' '),
      card,
      outcome: card?.querySelector('[data-question-answer]')?.getAttribute('data-question-answer'),
      teardown: () => { root.unmount(); host.remove(); },
    };
  };

  // ---------------------------------------------- the record says it was skipped
  const skipped = await answerThenResolveWith({ optionIds: [], skipped: true });
  check('a question answered in words still settles as a card', !!skipped.card);
  check(
    'a card whose words the session never took does not show them as the answer',
    !skipped.text.includes(WORDS),
    skipped.text.slice(0, 200) || 'no answered card',
  );
  check(
    'and says so rather than letting the sentence vanish',
    !!skipped.card?.querySelector('[data-question-answer-dropped]'),
    skipped.text.slice(-160),
  );
  check(
    'and reads as the skip the agent was actually told about',
    skipped.outcome === 'skipped',
    String(skipped.outcome),
  );
  skipped.teardown();
  await wait(50);

  // -------------------------------- the record says someone else picked an option
  const overtaken = await answerThenResolveWith({ optionIds: ['opt-1'], skipped: false });
  const chosenRows = Array.from(
    overtaken.card?.querySelectorAll('[data-question-option="chosen"]') ?? [],
  ).map((row) => (row.textContent || '').replace(/\s+/g, ' '));
  check(
    'a question answered elsewhere first shows that answer, not this browser’s',
    chosenRows.length === 1 && chosenRows[0].includes('Install the tool'),
    chosenRows.join(' | ').slice(0, 200) || 'nothing is marked as chosen',
  );
  check(
    'and does not leave the words this browser sent standing beside it',
    !overtaken.text.includes(WORDS)
      && !!overtaken.card?.querySelector('[data-question-answer-dropped]'),
    overtaken.text.slice(0, 200),
  );
  check(
    'and still marks it as answered rather than skipped',
    overtaken.outcome === 'chosen',
    String(overtaken.outcome),
  );
  overtaken.teardown();
}

/**
 * A program that asks the terminal what it supports must not be able to stop it
 * rendering.
 *
 * DECRQM (`CSI ? <mode> $p`) is how a modern TUI probes for synchronized
 * output, in-band resize and friends before it draws anything. xterm answers it
 * from a handler that runs inside the write loop, so an exception there does
 * not just drop the reply: it tears down the loop, and every later write — from
 * this program or any other sharing the terminal — is silently discarded. The
 * screen simply stops at whatever was on it, which for a program that probes
 * before its first frame is nothing at all.
 *
 * That is not hypothetical; it is what shipped. The build settings turned
 * xterm's reply-code enum into an assignment to an undeclared name, which
 * throws in a strict-mode bundle. This check is written against the behaviour
 * rather than the sequence so it keeps its meaning if the cause ever changes.
 */
async function checkModeQueriesDoNotKillTheTerminal(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:800px;height:400px;position:absolute;top:0;left:600px';
  document.body.appendChild(host);

  const controller = createTerminalController({ fontSize: 14 });
  controller.open(host);
  await wait(200);

  const replies: string[] = [];
  controller.terminal.onData((data) => replies.push(data));

  const errors: string[] = [];
  const onError = (event: ErrorEvent): void => { errors.push(event.message); };
  window.addEventListener('error', onError);

  // The five modes a real agent CLI probes at startup, each followed by the
  // primary-device-attributes query it uses to detect "no answer".
  const queries = [2026, 2048, 2031, 1010, 1011]
    .map((mode) => `\x1b[?${mode}$p\x1b[c`)
    .join('');
  controller.terminal.write(queries);
  await wait(200);

  check(
    'a mode query is answered',
    replies.some((reply) => reply.includes('$y')),
    JSON.stringify(replies.slice(0, 6)),
  );
  check('a mode query throws nothing', errors.length === 0, errors.join(' | '));

  // The real damage was here: everything written afterwards vanished.
  const marker = 'still-alive-after-mode-query';
  controller.terminal.write(`\r\n${marker}\r\n`);
  await wait(200);

  const buffer = controller.terminal.buffer.active;
  let rendered = false;
  for (let row = 0; row < buffer.length; row++) {
    if (buffer.getLine(row)?.translateToString(true).includes(marker)) {
      rendered = true;
      break;
    }
  }
  check('the terminal still renders after a mode query', rendered);

  window.removeEventListener('error', onError);
  controller.dispose();
  host.remove();
}

/**
 * Issue #45: a running workflow opens in a popup that behaves like the file
 * editor's — movable and expandable — and keeps showing its log live and
 * after the run ends.
 *
 * Driven through the whole `ChatView`, not a bare `AgentsPanel`. Two of the
 * things asked for here only exist in the composition: that a `tool` patch
 * (which never reaches the panel's own `subscribe` tier) still reaches the
 * popup — true only if the popup really is on `subscribeContent` — and that
 * selecting another rail tab does not take the popup down with the panel that
 * opened it. Rendering the panel alone passed both while the second was false.
 */
async function checkAWorkflowPopupBehavesLikeTheFilePopup(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('workflow-check', { send: () => {} });
  const transcript = controller.transcript;
  transcript.apply({ t: 'msg_start', seq: 1, ts: 1, id: 'm1', role: 'assistant', turnId: 't1' });
  transcript.apply({
    t: 'block_start',
    seq: 2,
    ts: 2,
    msgId: 'm1',
    index: 0,
    block: {
      kind: 'tool',
      toolId: 'wf1',
      name: 'Workflow',
      toolKind: 'task',
      status: 'running',
      input: { name: 'review-changes' },
      output: '▸ Review\nchecking file a',
    },
  });

  const root = createRoot(host);
  const paint = (panelTab: string): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/tmp/project',
        view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab, panelWidth: 420 },
        onViewChange: () => {},
      } as never),
    );
  };

  paint('agents');
  await wait(200);

  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  const row = rail?.querySelector('[role="button"]') as HTMLElement | null;
  check('a workflow row is clickable', !!row);
  row?.click();
  await wait(50);

  const panel = host.querySelector('[role="dialog"]') as HTMLElement | null;
  check('clicking the workflow row opens a popup', !!panel);
  if (!panel) {
    root.unmount();
    host.remove();
    return;
  }

  check('the popup names the workflow', !!panel.textContent?.includes('review-changes'));
  check('the popup shows the running stage so far', !!panel.textContent?.includes('checking file a'));

  // Movable, like the file popup: a resize grip is present and dragging it
  // changes the panel's own size rather than the content scrolling instead.
  const grip = panel.querySelector('[title="Drag to resize"]') as HTMLElement | null;
  check('the popup has a resize grip', !!grip);
  const before = panel.getBoundingClientRect();
  if (grip) {
    grip.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, clientX: before.right, clientY: before.bottom }));
    window.dispatchEvent(new PointerEvent('pointermove', { clientX: before.right + 120, clientY: before.bottom + 120 }));
    window.dispatchEvent(new PointerEvent('pointerup', {}));
    await wait(50);
  }
  const afterResize = panel.getBoundingClientRect();
  check(
    'dragging the grip resizes the popup',
    afterResize.width > before.width && afterResize.height > before.height,
    `${Math.round(before.width)}x${Math.round(before.height)} -> ${Math.round(afterResize.width)}x${Math.round(afterResize.height)}`,
  );

  const maximise = panel.querySelector('[aria-label="Fill the window"]') as HTMLElement | null;
  check('the popup can be expanded to fill the screen', !!maximise);
  maximise?.click();
  await wait(50);
  const maximised = panel.getBoundingClientRect();
  check(
    'expanding it fills most of the viewport',
    maximised.width > window.innerWidth - 40,
    `${Math.round(maximised.width)}px vs viewport ${window.innerWidth}px`,
  );

  // Live: a `tool` patch is the wire event a running workflow actually gets
  // patched with (see chat-reducer.ts), and it must reach this popup even
  // though it never reaches the panel's own `subscribe` tier.
  transcript.apply({
    t: 'block_delta',
    seq: 3,
    ts: 3,
    msgId: 'm1',
    index: 0,
    text: '\n▸ Verify\nall clear',
  });
  await wait(50);
  check(
    'new output streamed into the workflow appears live',
    !!panel.textContent?.includes('all clear'),
  );

  // And it survives completion, for review afterward.
  transcript.apply({ t: 'tool', seq: 4, ts: 4, toolId: 'wf1', patch: { status: 'completed' } });
  await wait(50);
  check('the popup still shows the log once the workflow finishes', !!panel.textContent?.includes('all clear'));
  check('the popup reflects the finished status', !!panel.textContent?.toLowerCase().includes('done'));

  // The file popup is mounted by the rail, not by the tab that opened it, so
  // it outlives a tab change. The workflow popup has to do the same, or a
  // workflow you opened to watch disappears the moment you look at anything
  // else — and "still there for review afterward" only holds if you never
  // touched the rail in between.
  paint('links');
  await wait(200);
  const afterSwitch = host.querySelector('[role="dialog"]') as HTMLElement | null;
  check(
    'the popup survives selecting another rail tab',
    !!afterSwitch && !!afterSwitch.textContent?.includes('all clear'),
    afterSwitch ? 'still open' : 'unmounted with the agents tab',
  );

  root.unmount();
  host.remove();
}

/**
 * Issue #45, the second half: a workflow that is still running says what it is
 * doing, and goes on saying it as the run moves.
 *
 * The popup above it opens on a call that already has output. This one opens on
 * the state a real Claude workflow is in for most of its life — a tool call with
 * `{scriptPath}`, no output, and minutes to go — and asks whether anything at
 * all changes on screen while the runtime reports. Every event replayed here is
 * one the adapter emits from `task_started`/`task_progress` (see handleTask in
 * adapters/claude.ts); the unit test proves the same states render, this proves
 * they arrive without a remount and that nothing keeps pulsing after the end.
 */
async function checkARunningWorkflowSaysWhatItIsDoing(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('workflow-live-check', { send: () => {} });
  const transcript = controller.transcript;
  transcript.apply({ t: 'msg_start', seq: 1, ts: 1, id: 'm1', role: 'assistant', turnId: 't1' });
  transcript.apply({
    t: 'block_start',
    seq: 2,
    ts: 2,
    msgId: 'm1',
    index: 0,
    block: {
      kind: 'tool',
      toolId: 'wf2',
      name: 'Workflow',
      toolKind: 'task',
      status: 'running',
      // What Claude actually sends for this tool, and all it sends.
      input: { scriptPath: '/home/dev/.claude/workflows/review-changes.md' },
    },
  });

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
      onViewChange: () => {},
    } as never),
  );
  await wait(200);

  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  (rail?.querySelector('[role="button"]') as HTMLElement | null)?.click();
  await wait(50);

  const panel = host.querySelector('[role="dialog"]') as HTMLElement | null;
  check('a workflow with no output yet still opens', !!panel);
  if (!panel) {
    root.unmount();
    host.remove();
    return;
  }

  check(
    'the title says which workflow this is, not just "Workflow"',
    !!panel.textContent?.includes('review-changes'),
  );
  check(
    'a workflow that has reported nothing yet says so',
    !!panel.textContent?.includes('Waiting for the first stage'),
  );

  transcript.apply({
    t: 'agent_progress',
    seq: 3,
    ts: 3,
    parentToolId: 'wf2',
    patch: { activity: 'Stage 1 of 5: review', status: 'running', prompt: undefined },
  });
  await wait(50);
  check(
    'the stage the workflow is on appears while it runs',
    !!panel.textContent?.includes('Stage 1 of 5: review'),
  );
  check(
    'the waiting line goes once the workflow is reporting',
    !panel.textContent?.includes('Waiting for the first stage'),
  );

  transcript.apply({
    t: 'agent_step',
    seq: 4,
    ts: 4,
    parentToolId: 'wf2',
    step: {
      id: 'p1',
      name: 'Bash',
      toolKind: 'execute',
      status: 'running',
      input: { command: 'npm test' },
      ts: 4,
    },
  });
  transcript.apply({
    t: 'agent_progress',
    seq: 5,
    ts: 5,
    parentToolId: 'wf2',
    patch: { activity: 'Stage 2 of 5: implement', toolUses: 1, totalTokens: 18400 },
  });
  await wait(50);
  check(
    'a phase and the stage after it both land without a refresh',
    !!panel.textContent?.includes('npm test') && !!panel.textContent?.includes('Stage 2 of 5'),
  );

  // The one glyph that says "still going": the loader-circle arc, matched by
  // its own path because the icons carry nothing else to recognise them by.
  const spinner = (): Element | null => panel.querySelector('.ricon path[d^="M21 12a9 9 0 1 1-6.219"]');
  check('the running stage is marked as running', !!spinner());

  // The tool_result at last. The log it carries is the record of the run, and
  // the live view above it must stop behaving like something still in motion.
  transcript.apply({
    t: 'tool',
    seq: 6,
    ts: 6,
    toolId: 'wf2',
    patch: { status: 'completed', output: '▸ Review\nchecking file a\n▸ Verify\nall clear' },
  });
  await wait(50);
  check('the finished log arrives in the popup that watched the run', !!panel.textContent?.includes('all clear'));
  check('the phases the run went through are still listed after it', !!panel.textContent?.includes('npm test'));
  check('nothing still says "running" over a workflow that has finished', !spinner());

  root.unmount();
  host.remove();
}

/**
 * Issue #117: a workflow opens on the whole shape of the run — its phases, the
 * agents inside them, and what each of them is doing — and it all moves.
 *
 * Every event replayed here comes out of a real recorded run: test/browser/
 * run.js replays test/fixtures/chat/claude-workflow.jsonl through the claude
 * adapter and writes what it emits, so this is driven by what a browser would
 * actually have received rather than by a shape someone imagined. The unit
 * tests prove the same states render; this proves they arrive without a reopen,
 * that a phase can be folded and an agent opened, and that the counts on the
 * agents list say what the workflow holds.
 */
async function checkAWorkflowShowsItsPhasesAndItsAgents(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('workflow-structure-check', { send: () => {} });
  const transcript = controller.transcript;

  // Split at the run's own reports so the popup can be opened part-way through
  // and then fed the rest, which is the only way to ask whether it updates.
  const reports = RECORDED_WORKFLOW.filter((event) => event.t === 'workflow_progress');
  const half = reports[1];
  const cut = RECORDED_WORKFLOW.indexOf(half) + 1;
  let seq = 1;
  const play = (events: Array<Record<string, unknown>>): void => {
    for (const event of events) transcript.apply({ ts: seq, ...event, seq: seq++ } as never);
  };
  play(RECORDED_WORKFLOW.slice(0, cut));

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
      onViewChange: () => {},
    } as never),
  );
  await wait(200);

  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  const railText = rail?.textContent ?? '';
  check(
    'the agents list says how many agents the workflow holds',
    /\d+ agents/.test(railText),
    railText.slice(0, 120),
  );

  (rail?.querySelector('[role="button"]') as HTMLElement | null)?.click();
  await wait(50);

  const panel = host.querySelector('[role="dialog"]') as HTMLElement | null;
  check('a workflow with a structure to show opens', !!panel);
  if (!panel) {
    root.unmount();
    host.remove();
    return;
  }

  check(
    'the run\'s phases are listed by name',
    !!panel.textContent?.includes('Collect') && !!panel.textContent?.includes('Check'),
    panel.textContent?.slice(0, 160),
  );
  check(
    'the agents inside a phase are listed, several at once',
    ['collect:1', 'collect:2', 'collect:3'].every((label) => !!panel.textContent?.includes(label)),
  );

  // The rest of the run, with the popup already open and untouched.
  play(RECORDED_WORKFLOW.slice(cut));
  await wait(80);

  check(
    'agents that started later appear without the popup being reopened',
    !!panel.textContent?.includes('check:ok') && !!panel.textContent?.includes('check:bad'),
  );
  check(
    'a failed agent is identifiable without opening it',
    !!panel.textContent?.includes('failed') && !!panel.textContent?.includes('no-such-model-at-all'),
  );

  // A phase folds shut and stays shut, which is the affordance a run with
  // dozens of agents needs and a run with five must not force on anyone.
  const phaseHeader = [...panel.querySelectorAll('[role="button"][aria-expanded]')].find((el) =>
    el.textContent?.includes('Collect'),
  ) as HTMLElement | undefined;
  check('a phase heading can be folded', !!phaseHeader);
  phaseHeader?.click();
  await wait(50);
  check(
    'folding a phase hides the agents inside it',
    !panel.textContent?.includes('collect:1') && !!panel.textContent?.includes('Collect'),
  );
  phaseHeader?.click();
  await wait(50);
  check('unfolding a phase brings them back', !!panel.textContent?.includes('collect:1'));

  // The drill-in: an agent's own task, spend and outcome, one click away.
  const agentRow = [...panel.querySelectorAll('[role="button"][aria-expanded]')].find((el) =>
    el.textContent?.includes('check:bad'),
  ) as HTMLElement | undefined;
  check('an agent row can be opened', !!agentRow);
  const beforeOpen = panel.textContent ?? '';
  agentRow?.click();
  await wait(50);
  const opened = panel.textContent ?? '';
  check(
    'opening an agent shows what it was asked to do',
    opened.includes('CHECK-BAD') && !beforeOpen.includes('CHECK-BAD'),
  );
  check(
    'opening an agent shows what it spent and how it ended',
    /Failed with/.test(opened) && /model no-such-model-at-all/.test(opened),
    opened.slice(opened.indexOf('check:bad'), opened.indexOf('check:bad') + 220),
  );

  const done = [...panel.querySelectorAll('[role="button"][aria-expanded]')].find((el) =>
    el.textContent?.includes('collect:1'),
  ) as HTMLElement | undefined;
  done?.click();
  await wait(50);
  check(
    'an agent that finished says what it reported back',
    /Reported back/.test(panel.textContent ?? '') && !!panel.textContent?.includes('tokens'),
  );

  root.unmount();
  host.remove();

  // At a phone's width, where none of this can be reached by a media query:
  // the popup is inline-styled throughout, so a phase heading carrying a title,
  // two badges and a count has to hold itself together on 390px or spill.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const narrow = new ChatController('workflow-phone-check', { send: () => {} });
  let phoneSeq = 1;
  for (const event of RECORDED_WORKFLOW) {
    narrow.transcript.apply({ ts: phoneSeq, ...event, seq: phoneSeq++ } as never);
  }
  const call = narrow.transcript.messages
    .flatMap((message) => message.blocks)
    .find((entry) => entry.kind === 'tool' && entry.name === 'Workflow') as { toolId: string };

  const phoneRoot = createRoot(doc.body);
  phoneRoot.render(
    React.createElement(
      PhoneContext.Provider,
      { value: true },
      React.createElement(WorkflowPopup, {
        open: true,
        transcript: narrow.transcript,
        toolId: call.toolId,
        onClose: () => {},
        isMobile: true,
      } as never),
    ),
  );
  await wait(300);
  settle(doc);

  const dialog = doc.querySelector('[role="dialog"]') as HTMLElement | null;
  check('the workflow popup opens at a phone’s width', !!dialog);
  if (dialog) {
    const rows = [...dialog.querySelectorAll('*')].filter(isPainted);
    const spilled = rows.filter((el) => el.getBoundingClientRect().right > 391);
    check(
      'and its phases and agents fit inside it',
      rows.length > 10 && spilled.length === 0,
      spilled.length
        ? spilled.slice(0, 3).map((el) => `${(el.textContent ?? '').slice(0, 30)} → ${Math.round(el.getBoundingClientRect().right)}px`).join(' | ')
        : `${rows.length} painted elements measured`,
    );
    // Badges excepted: their 10px is a decision Badge takes for every surface
    // in the app, not one this view is free to make, and holding this popup to
    // a rule the rest of the chrome does not keep would be theatre.
    const words = paintedText(dialog).filter((entry) => !entry.node.closest('[data-badge]'));
    const small = words.filter((entry) => entry.size < PHONE_MIN_TEXT - 0.01);
    check(
      'and nothing it writes is below the phone’s floor',
      words.length > 8 && small.length === 0,
      small.length
        ? small.slice(0, 3).map((entry) => `${entry.text.slice(0, 24)} @ ${entry.size}px`).join(' | ')
        : `${words.length} lines measured`,
    );
  }

  phoneRoot.unmount();
  frame.remove();
}

/**
 * Issue #140: a workflow that failed looks failed everywhere it appears, and
 * the conversation says so without anybody opening anything.
 *
 * Both recordings are replayed, because the whole bug lives in the difference
 * between them and a check driven by one alone would pass on code that painted
 * every workflow red. They end with the same launching tool result — "Workflow
 * launched in background", no error — and differ only in what the run said
 * about itself afterwards.
 *
 * The colours are read off the layout engine rather than assumed from the
 * label: "failed" written in `var(--success)` would satisfy a textContent check
 * and still be a green badge on a broken run.
 */
/**
 * Nothing reads as running once nothing can report on it (#139).
 *
 * After a turn finished and the agent had answered, a delegation started during
 * that turn could still spin: a running badge on its row, a non-zero count on
 * the panel, a turning dot on the trace, and a popup saying it was waiting for
 * a stage to report in — with no waits and no activity anywhere in the trace,
 * because the runtime had gone quiet minutes earlier and nothing in this app
 * ever closed a call on a turn-level event.
 *
 * Every one of those four is a rendering question, which is why they are asked
 * here. Driven off the real recording with the run's own reports dropped, which
 * is what a runtime going quiet looks like.
 */
async function checkAWorkflowNothingWillReportOnStopsSpinning(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('stale-workflow-check', { send: () => {} });
  let seq = 1;
  // Everything the runtime said about the run itself, taken out: the call is
  // opened and then never mentioned again, and the turn ends anyway.
  const quiet = RECORDED_QUIET_WORKFLOW;
  for (const event of quiet) {
    controller.transcript.apply({ ts: seq, ...(event as Record<string, unknown>), seq: seq++ } as never);
  }

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
      onViewChange: () => {},
    } as never),
  );
  await wait(300);
  settle(document);

  const rail = (): HTMLElement | null => host.querySelector('aside[aria-label="Workspace"]');
  const railText = (): string => (rail()?.textContent || '').replace(/\s+/g, ' ');

  /** The status word on the delegation's own row, which is the badge. */
  const rowStatus = (): string => {
    const row = rail()?.querySelector<HTMLElement>('[role="button"]');
    const words = (row?.textContent || '').match(
      /queued|running|done|failed|denied|canceled|no longer reporting/gi,
    );
    return words ? words[0].toLowerCase() : '';
  };

  check(
    'a delegation nobody will report on again does not keep a running badge',
    rowStatus() !== 'running',
    `its row says "${rowStatus()}" — ${railText().slice(0, 90)}`,
  );
  check(
    'and the panel says so in words rather than going quiet about it',
    rowStatus() === 'no longer reporting',
    `its row says "${rowStatus()}" — ${railText().slice(0, 90)}`,
  );
  // The running-count badge on the panel header, which is the figure the issue
  // names. It is drawn only when something is in flight, so its absence is the
  // assertion: "Agents 1 total" with nothing after it.
  check(
    'and the running count does not claim something is in flight',
    !/total\s*[1-9]/.test(railText()),
    railText().slice(0, 90),
  );

  (rail()?.querySelector('[role="button"]') as HTMLElement | null)?.click();
  await wait(300);
  settle(document);
  const popup = document.querySelector('[role="dialog"]') as HTMLElement | null;
  check(
    'its popup opens',
    Boolean(popup),
    popup ? 'open' : `rail is ${railText().slice(0, 60)}`,
  );
  if (popup) {
    check(
      'and does not claim it is waiting for a stage that will never report',
      !/Waiting for the first stage/i.test(popup.textContent || ''),
      (popup.textContent || '').replace(/\s+/g, ' ').slice(-90),
    );
    (popup.querySelector('[aria-label="Close"]') as HTMLElement | null)?.click();
    await wait(150);
  }

  root.unmount();
  host.remove();
}

/**
 * A background workflow reads as running until the run itself ends (#116).
 *
 * Starting one is a quick, separate step: the request comes back in seconds
 * with "Workflow launched in background", and the run keeps going for minutes.
 * The app took that acknowledgement for the end of the work — a green **done**
 * badge on the row and in the popup title, no spinner, below the Finished
 * divider, and missing from the panel's running count — while the run
 * underneath it counted up through hundreds of tool calls for another nine
 * minutes.
 *
 * Cut at the receipt, on the real recording: that is the middle of the run, and
 * it is where every one of those surfaces used to be wrong at once. Then the
 * rest is played in with the view already on screen, so the settle is measured
 * on the live path too.
 */
async function checkALaunchedWorkflowReadsAsRunningUntilItEnds(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const receiptAt = RECORDED_WORKFLOW.findIndex((event) => {
    const patch = (event as { t?: string; patch?: { output?: unknown } }).patch;
    return (event as { t?: string }).t === 'tool'
      && typeof patch?.output === 'string'
      && /launched in background/i.test(patch.output as string);
  });

  const controller = new ChatController('workflow-running-check', { send: () => {} });
  let seq = 1;
  const play = (batch: unknown[]): void => {
    for (const event of batch) {
      controller.transcript.apply({ ts: seq, ...(event as Record<string, unknown>), seq: seq++ } as never);
    }
  };
  play(RECORDED_WORKFLOW.slice(0, receiptAt + 1));

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
      onViewChange: () => {},
    } as never),
  );
  await wait(300);
  settle(document);

  /**
   * The status word on the workflow's own row in the Agents panel.
   *
   * Read off the row rather than off the surface: the words "done" and
   * "running" appear all over a conversation, and a check that greps the whole
   * screen for them agrees with itself whatever the badge says.
   */
  const rowStatus = (): string => {
    const rail = host.querySelector('aside[aria-label="Workspace"]');
    const row = Array.from(rail?.querySelectorAll<HTMLElement>('[role="button"]') ?? []).find((node) =>
      /review-changes|probe-workflow/i.test(node.textContent || ''),
    );
    // The first of them: the status badge sits immediately after the name, and
    // the counts of the agents inside the run ("5 done", "1 failed") follow it.
    const words = (row?.textContent || '').match(/queued|running|done|failed|denied|canceled/gi);
    return words ? words[0].toLowerCase() : '';
  };
  const railText = (): string =>
    (host.querySelector('aside[aria-label="Workspace"]')?.textContent || '').replace(/\s+/g, ' ');

  check(
    'a workflow that has only been launched does not read as done',
    rowStatus() !== 'done',
    `its row says "${rowStatus()}" — ${railText().slice(0, 90)}`,
  );
  check(
    'it reads as running instead',
    rowStatus() === 'running',
    `its row says "${rowStatus()}" — ${railText().slice(0, 90)}`,
  );

  // The popup, where the acknowledgement was captioned as the run's result.
  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  (rail?.querySelector('[role="button"]') as HTMLElement | null)?.click();
  await wait(300);
  settle(document);

  const popup = document.querySelector('[role="dialog"]') as HTMLElement | null;
  check(
    'its popup opens on the run',
    Boolean(popup),
    popup ? (popup.textContent || '').slice(0, 40) : `no dialog; rail is ${(rail?.textContent || '').slice(0, 60)}`,
  );
  if (popup) {
    const popupTitle = (popup.querySelector('h2')?.textContent || '').toLowerCase();
    check(
      'and its title says running, not done',
      popupTitle.includes('running') && !popupTitle.includes('done'),
      popupTitle.slice(0, 60) || 'the popup has no title',
    );
    check(
      'and never offers the launch acknowledgement as the run’s final output',
      !/Final output/i.test(popup.textContent || ''),
      /Final output/i.test(popup.textContent || '') ? 'captioned as a result' : 'not captioned as a result',
    );
    (popup.querySelector('[aria-label="Close"]') as HTMLElement | null)?.click();
    await wait(150);
  }

  // And it settles, on the run's own word, with the view already on screen.
  play(RECORDED_WORKFLOW.slice(receiptAt + 1));
  await wait(300);
  settle(document);
  check(
    'and it settles as done once the run itself says so',
    rowStatus() === 'done',
    `its row says "${rowStatus()}" — ${railText().slice(0, 90)}`,
  );

  root.unmount();
  host.remove();
}

/**
 * One prompt draws one bubble (#129).
 *
 * Sending a single message put two identical user turns on the screen, side by
 * side, on Oh My Pi and every other ACP runtime and both codex modes. Both were
 * written by the server — `ChatSession.deliver` writes the user's message, and
 * the adapter used to write it again from inside its own `send` under a turn id
 * of its own — and the reducer folds anything arriving inside an open turn into
 * that turn, so the two landed together.
 *
 * Here rather than only in a unit test because the claim the issue makes is
 * about what is on the screen: a transcript holding two messages is one thing,
 * two bordered bubbles carrying the same sentence is the thing that was
 * reported. Driven by a real recording replayed through the real adapter,
 * including the `send()` that used to produce the second copy.
 */
async function checkOnePromptDrawsOneUserBubble(): Promise<void> {
  const PROMPT = 'What is the magic word?';
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('omp-1', { send: () => {} });
  let seq = 1;
  // The user's own message, as the session writes it. Its id shape is not
  // decoration: it is what tells the reducer this app minted the message, and
  // therefore what tells it that anything else claiming to be the user in the
  // same turn is a runtime handing the prompt back.
  const asked = 'user-aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';
  for (const event of [
    { t: 'msg_start', id: asked, role: 'user', turnId: 'turn-11111111-2222-3333-4444-555555555555' },
    { t: 'block_start', msgId: asked, index: 0, block: { kind: 'text', text: PROMPT } },
    { t: 'msg_end', msgId: asked },
    ...RECORDED_OMP_TURN,
  ]) {
    controller.transcript.apply({ ts: seq, ...(event as Record<string, unknown>), seq: seq++ } as never);
  }

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'omp',
      runtimeLabel: 'Oh My Pi',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(250);
  settle(document);

  // Counted as bubbles, not as strings: the prompt appears in more than one
  // place on this surface (the turn strip's label, a search field's value), and
  // what was reported is two rows in the conversation carrying it.
  const bubbles = Array.from(host.querySelectorAll<HTMLElement>('article')).filter(
    (node) => isPainted(node) && (node.textContent || '').includes(PROMPT),
  );
  check(
    'one prompt draws one user bubble',
    bubbles.length === 1,
    `${bubbles.length} rows carry the prompt: ${bubbles.map((node) => describe(node)).join(' | ') || 'none'}`,
  );
  check(
    'and the conversation holds one user message, not two',
    controller.transcript.messages.filter((message) => message.role === 'user').length === 1,
    controller.transcript.messages
      .filter((message) => message.role === 'user')
      .map((message) => message.id)
      .join(', ') || 'none',
  );
  // The answer is still there. A fix that dropped the wrong message would
  // satisfy both counts above and leave the conversation with no reply in it.
  // `abacus` is what this recording's agent actually replied.
  check(
    'and the agent’s answer is still on the screen',
    Array.from(host.querySelectorAll<HTMLElement>('article')).some(
      (node) => isPainted(node) && /abacus/i.test(node.textContent || ''),
    ),
    Array.from(host.querySelectorAll<HTMLElement>('article'))
      .map((node) => (node.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 40))
      .join(' | ') || 'no rows at all',
  );

  root.unmount();
  host.remove();
}

async function checkAFailedWorkflowReadsAsFailedEverywhere(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const mount = (
    id: string,
    events: Array<Record<string, unknown>>,
  ): { root: ReturnType<typeof createRoot>; play: (rest: Array<Record<string, unknown>>) => void } => {
    const controller = new ChatController(id, { send: () => {} });
    let seq = 1;
    const play = (batch: Array<Record<string, unknown>>): void => {
      for (const event of batch) {
        controller.transcript.apply({ ts: seq, ...event, seq: seq++ } as never);
      }
    };
    play(events);
    const root = createRoot(host);
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/tmp/project',
        view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
        onViewChange: () => {},
      } as never),
    );
    return { root, play };
  };

  // Cut where the run reported that it had failed, and mount there: that is the
  // moment somebody watching the conversation is being told, and the turn it
  // lands in is the one still open. Everything after it is played in below,
  // with the view already on screen.
  const failedAt = RECORDED_FAILED_WORKFLOW.findIndex(
    (event) => (event as { t?: string }).t === 'workflow_failed',
  );
  check('the recording still holds a run that failed', failedAt >= 0);
  // Mounted *before* the agents inside it start dying, so what follows is
  // judged on a panel that had to redraw rather than one built from the
  // finished article. The counts arrive on `workflow_progress`, which the
  // reducer marks neither structural nor meta — a panel on the coarse
  // subscription tier renders the right thing here and then never moves.
  const firstReport = RECORDED_FAILED_WORKFLOW.findIndex(
    (event) => (event as { t?: string }).t === 'workflow_progress',
  );
  const { root, play } = mount(
    'workflow-failed-check',
    RECORDED_FAILED_WORKFLOW.slice(0, firstReport + 1),
  );
  await wait(220);
  settle(document);

  const early = host.querySelector('aside[aria-label="Workspace"]')?.textContent ?? '';
  check(
    'the agents list shows the run before anything has failed',
    /agents/.test(early) && !/failed/.test(early),
    early.replace(/\s+/g, ' ').slice(0, 120),
  );

  // The rest of the reports, and the failure, into a panel already on screen.
  play(RECORDED_FAILED_WORKFLOW.slice(firstReport + 1, failedAt + 1));
  await wait(160);
  settle(document);

  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  const railText = rail?.textContent ?? '';
  check(
    'the agents list says the failed workflow failed',
    /failed/.test(railText) && !/\bdone\b/.test(railText),
    railText.slice(0, 160),
  );
  check(
    'the row says how many of its agents died',
    /2 failed/.test(railText),
    railText.slice(0, 160),
  );

  // The badge's colour, from the engine. `--destructive` and `--success` are
  // different variables and this is the one thing a label cannot prove.
  const badge = [...(rail?.querySelectorAll('span') ?? [])].find(
    (el) => el.textContent?.trim() === 'failed' && isPainted(el),
  ) as HTMLElement | undefined;
  check('the failed badge is painted', !!badge);
  const badgeColour = badge ? getComputedStyle(badge).color : '';
  // Resolved by the engine rather than read off the custom property: the token
  // is authored in oklch and computes to rgb, so comparing the two as strings
  // would fail against a badge that is exactly right.
  const swatch = (token: string): string => {
    const probe = document.createElement('span');
    probe.style.color = `var(${token})`;
    document.body.appendChild(probe);
    const resolved = getComputedStyle(probe).color;
    probe.remove();
    return resolved;
  };
  const destructive = swatch('--destructive');
  const success = swatch('--success');
  check(
    'the failed badge is drawn in the destructive colour, not the success one',
    !!badgeColour && badgeColour === destructive && badgeColour !== success,
    `${badgeColour} — destructive ${destructive}, success ${success}`,
  );

  // The chat itself, which is the half of #140 that had no surface at all.
  const transcriptText = host.querySelector('[role="log"]')?.textContent ?? '';
  check(
    'the conversation says the workflow failed, without opening anything',
    /Workflow "probe-workflow-failure" failed/.test(transcriptText),
    transcriptText.replace(/\s+/g, ' ').slice(0, 220),
  );
  check(
    'the conversation says why it failed',
    /forced workflow failure/.test(transcriptText),
  );

  // The rest of the run, so what follows is judged on a settled conversation
  // rather than on one caught mid-report.
  play(RECORDED_FAILED_WORKFLOW.slice(failedAt + 1));
  await wait(120);
  settle(document);

  // And the popup's title, which read "done" over a run that had died.
  (rail?.querySelector('[role="button"]') as HTMLElement | null)?.click();
  await wait(80);
  const panel = document.querySelector('[role="dialog"]') as HTMLElement | null;
  check('the failed workflow still opens', !!panel);
  const title = panel?.querySelector('h2, [role="heading"]') ?? panel;
  check(
    'the popup title badge reads failed',
    /failed/.test(title?.textContent ?? '') && !/\bdone\b/.test(title?.textContent ?? ''),
    (title?.textContent ?? '').slice(0, 120),
  );
  check(
    'a phase whose every agent died does not read as finished',
    !/finished/.test(panel?.textContent ?? ''),
    (panel?.textContent ?? '').slice(0, 160),
  );

  root.unmount();
  host.innerHTML = '';

  // The control: a run that finished, with one of its five agents dead. It must
  // still read as done, or the fix has traded a missed failure for an invented
  // one — agents inside a workflow fail by design.
  //
  // Mounted before that agent dies, and the rest played in afterwards, because
  // this is the case that has nothing else to lean on: a run that fails raises
  // an event the whole panel redraws for, and a run that merely loses an agent
  // reports it only as `workflow_progress` — which reaches the live
  // subscription tier and no other. Built from the finished recording this
  // passed on a panel that could never have redrawn.
  // Cut at the last report before the agent dies, whichever that is: the run
  // reports its whole roster each time, and the first report of all already
  // carries several agents.
  const deathAt = RECORDED_WORKFLOW.findIndex(
    (event) =>
      (event as { t?: string }).t === 'workflow_progress'
      && ((event as { agents?: Array<{ state?: string }> }).agents ?? []).some(
        (agent) => agent.state === 'failed',
      ),
  );
  const controlFirst = deathAt - 1;
  const control = mount('workflow-done-check', RECORDED_WORKFLOW.slice(0, controlFirst + 1));
  await wait(220);
  settle(document);
  const beforeDeath = host.querySelector('aside[aria-label="Workspace"]')?.textContent ?? '';
  check(
    'the finished run’s panel starts with nothing failed',
    /agents/.test(beforeDeath) && !/failed/.test(beforeDeath),
    beforeDeath.replace(/\s+/g, ' ').slice(0, 120),
  );

  // Only the run's own reports, which is the window this is about. Between two
  // structural events a run can report a dozen times, and on the coarse
  // subscription tier the panel shows none of it until something unrelated
  // happens to fire — so a check that replayed the whole tail would be proved
  // right by the next `msg_start` rather than by the panel.
  control.play(
    RECORDED_WORKFLOW.slice(controlFirst + 1).filter((event) => {
      const type = (event as { t?: string }).t;
      // `tool` as well as `workflow_progress`, because since #116 that is how
      // the run reports its own ending: the launching call is left running when
      // the launch is acknowledged and settled when the run says it is over, so
      // a replay that dropped those would be asserting "reads as done" against
      // a run that has not finished.
      return type === 'workflow_progress' || type === 'tool';
    }),
  );
  await wait(200);
  settle(document);
  const controlRail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  const controlText = controlRail?.textContent ?? '';
  check(
    'a workflow that finished still reads as done',
    /done/.test(controlText),
    controlText.slice(0, 160),
  );
  check(
    'and says, without being remounted, that one agent died inside it',
    /1 failed/.test(controlText),
    controlText.replace(/\s+/g, ' ').slice(0, 160),
  );
  const controlTranscript = host.querySelector('[role="log"]')?.textContent ?? '';
  check(
    'a workflow that finished raises no failure in the chat',
    !/Workflow ".*" failed/.test(controlTranscript),
  );

  control.root.unmount();
  host.remove();

  // At a phone's width, where none of this can be reached by a media query.
  // The failure the conversation now carries is a runtime error verbatim —
  // three lines of stack trace in the recording — inside an inline-styled
  // callout, on the narrowest column this app has.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  // The bubble on its own, at the width it would have, rather than the whole
  // ChatView: the shell needs a tab strip and a session around it to lay itself
  // out, and dropped into a bare frame it collapses the transcript column to a
  // third of the screen — where every measurement below would pass by being too
  // small to spill rather than by fitting.
  const phoneHost = doc.createElement('div');
  phoneHost.style.cssText = 'width:390px;display:flex;flex-direction:column';
  doc.body.appendChild(phoneHost);

  const narrow = new ChatController('workflow-failed-phone-check', { send: () => {} });
  let phoneSeq = 1;
  for (const event of RECORDED_FAILED_WORKFLOW.slice(0, failedAt + 1)) {
    narrow.transcript.apply({ ts: phoneSeq, ...event, seq: phoneSeq++ } as never);
  }
  const failure = narrow.transcript.messages.find(
    (message) => message.role === 'system' && message.blocks.some((block) => block.kind === 'error'),
  );
  check('the failure is a message in the transcript', !!failure);
  const phoneRoot = createRoot(phoneHost);
  phoneRoot.render(
    React.createElement(
      PhoneContext.Provider,
      { value: true },
      React.createElement(MessageBubble, {
        message: failure,
        transcript: narrow.transcript,
      } as never),
    ),
  );
  await wait(200);
  settle(doc);

  // The innermost match, not the first: every ancestor up to the app root also
  // contains the text, and measuring one of those would be measuring the
  // column rather than the callout drawn inside it.
  const matches = [...doc.querySelectorAll('div')].filter(
    (el) => /Workflow "probe-workflow-failure" failed/.test(el.textContent ?? '') && isPainted(el),
  );
  const callout = matches.find(
    (el) => !matches.some((other) => other !== el && el.contains(other)),
  ) as HTMLElement | undefined;
  check('the failure reaches the phone’s transcript too', !!callout);

  // Drawn as a line across the conversation, not as a turn. The identical
  // callout renders either way, so every text assertion above passes on a
  // failure wrapped in the assistant's chrome — an avatar, a copy button and
  // an "Assistant message" label around something the assistant never said.
  check(
    'and is not dressed up as something the agent said',
    !doc.querySelector('article'),
    doc.querySelector('article')?.getAttribute('aria-label') ?? 'no article',
  );
  check(
    'and carries no message controls',
    doc.querySelectorAll('button').length === 0,
    `${doc.querySelectorAll('button').length} buttons`,
  );
  check(
    'and says when it happened, unlike every other rule',
    /\d{1,2}:\d{2}/.test(doc.body.textContent ?? ''),
    (doc.body.textContent ?? '').replace(/\s+/g, ' ').slice(-40),
  );
  if (callout) {
    const spilled = [...callout.querySelectorAll('*')].filter(
      (el) => isPainted(el) && el.getBoundingClientRect().right > 391,
    );
    check(
      'and a stack trace inside it does not run off the screen',
      spilled.length === 0 && callout.getBoundingClientRect().right <= 391,
      spilled.length
        ? spilled.slice(0, 2).map((el) => `${(el.textContent ?? '').slice(0, 24)} → ${Math.round(el.getBoundingClientRect().right)}px`).join(' | ')
        : `${Math.round(callout.getBoundingClientRect().width)}x${Math.round(callout.getBoundingClientRect().height)} inside ${Math.round(phoneHost.getBoundingClientRect().width)}px`,
    );
    const small = paintedText(callout).filter((entry) => entry.size < PHONE_MIN_TEXT - 0.01);
    check(
      'and it is written above the phone’s type floor',
      small.length === 0,
      small.length
        ? small.slice(0, 2).map((entry) => `${entry.text.slice(0, 24)} @ ${entry.size}px`).join(' | ')
        : 'measured',
    );
  }

  phoneRoot.unmount();
  frame.remove();
}

/**
 * Issue #44: opening a delegated agent shows its own steps — live while it
 * works, still there once it is done, and with a failure inside its work
 * spelled out rather than reduced to a badge.
 *
 * The events replayed here are the ones the claude adapter emits for real
 * sub-agent traffic (see test/chat-claude.test.js, which replays a captured
 * run through the adapter to prove that shape). This check starts where that
 * one stops: given those events, what does someone actually see?
 */
async function checkAnAgentPopupShowsWhatTheAgentIsDoing(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('agent-check', { send: () => {} });
  const transcript = controller.transcript;
  transcript.apply({ t: 'msg_start', seq: 1, ts: 1, id: 'm1', role: 'assistant', turnId: 't1' });
  transcript.apply({
    t: 'block_start',
    seq: 2,
    ts: 2,
    msgId: 'm1',
    index: 0,
    block: {
      kind: 'tool',
      toolId: 'ag1',
      name: 'Agent',
      toolKind: 'task',
      status: 'running',
      input: { subagent_type: 'general-purpose', description: 'Find the magic word' },
    },
  });

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'agents', panelWidth: 420 },
      onViewChange: () => {},
    } as never),
  );
  await wait(200);

  const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
  const row = rail?.querySelector('[role="button"]') as HTMLElement | null;
  check('a sub-agent row is clickable, not just a workflow', !!row);
  row?.click();
  await wait(50);

  const panel = host.querySelector('[role="dialog"]') as HTMLElement | null;
  check('clicking a sub-agent row opens its detail view', !!panel);
  if (!panel) {
    root.unmount();
    host.remove();
    return;
  }

  // Nothing reported yet: the view has to say so rather than look broken.
  check(
    'an agent with nothing reported yet says it is waiting',
    !!panel.textContent?.toLowerCase().includes('waiting'),
  );

  // Progress within its own work — the thing a status badge cannot say.
  transcript.apply({
    t: 'agent_progress',
    seq: 3,
    ts: 3,
    parentToolId: 'ag1',
    patch: { activity: 'Reading hello.txt', lastTool: 'Read', toolUses: 1, totalTokens: 21853 },
  });
  await wait(50);
  check(
    'the detail view shows what the agent is doing right now',
    !!panel.textContent?.includes('Reading hello.txt'),
  );

  // A step it took, live, with no refresh.
  transcript.apply({
    t: 'agent_step',
    seq: 4,
    ts: 4,
    parentToolId: 'ag1',
    step: {
      id: 's1',
      name: 'Read',
      toolKind: 'read',
      status: 'running',
      input: { file_path: '/tmp/project/hello.txt' },
      ts: 4,
    },
  });
  await wait(50);
  check(
    "a step appears in the running agent's view without a refresh",
    !!panel.textContent?.includes('Read') && !!panel.textContent?.includes('hello.txt'),
  );

  // The closing half must not overwrite the tool's name with a placeholder —
  // the reducer merges only what a patch actually carries.
  transcript.apply({
    t: 'agent_step',
    seq: 5,
    ts: 5,
    parentToolId: 'ag1',
    step: { id: 's1', status: 'completed', output: 'The magic word is BANANAPHONE.' },
  });
  await wait(50);
  check(
    'completing a step keeps the tool name it was opened with',
    !!panel.textContent?.includes('Read'),
  );

  // A failure *inside* the agent's work, which the row's badge cannot show.
  transcript.apply({
    t: 'agent_step',
    seq: 6,
    ts: 6,
    parentToolId: 'ag1',
    step: {
      id: 's2',
      name: 'Bash',
      toolKind: 'execute',
      status: 'failed',
      error: 'grep: missing.txt: No such file or directory',
      ts: 6,
    },
  });
  await wait(50);
  check(
    'a failure inside the agent shows its actual message',
    !!panel.textContent?.includes('No such file or directory'),
  );

  // And the whole sequence survives the run finishing, for review.
  transcript.apply({
    t: 'agent_progress',
    seq: 7,
    ts: 7,
    parentToolId: 'ag1',
    // Shaped the way the adapter really emits it: the keys it has nothing to
    // say about are present and undefined, not absent. A merge that assigns
    // blindly erases them, which a patch with the keys simply omitted would
    // never have caught.
    patch: { status: 'completed', durationMs: 3921, activity: undefined, lastTool: undefined },
  });
  transcript.apply({
    t: 'tool',
    seq: 8,
    ts: 8,
    toolId: 'ag1',
    patch: { status: 'completed', output: 'The magic word is BANANAPHONE.' },
  });
  await wait(50);
  const text = panel.textContent || '';
  check(
    'the finished agent still lists every step it took',
    text.includes('Read') && text.includes('Bash') && text.includes('No such file or directory'),
  );
  check('the finished agent shows what it reported back', text.includes('BANANAPHONE'));
  // That last progress report named only a status and a duration. A merge that
  // wrote absent keys back as undefined would have blanked the activity line
  // the report before it established.
  check(
    'a later progress report does not erase what an earlier one said',
    text.includes('Reading hello.txt'),
  );

  root.unmount();
  host.remove();
}

/**
 * A dialog with more content than fits must scroll, not overflow the window.
 *
 * The overlay centres the panel, so an uncapped panel that outgrows the
 * viewport hangs off *both* edges — the title row ends up above the top of the
 * window, and since the overlay is `position: fixed` there is nothing to scroll
 * to reach it. The runtime-profiles dialog hit this as soon as it had more than
 * a couple of profiles in it.
 *
 * Only a real layout engine can answer this, which is why it lives here rather
 * than in the jsdom suite: it is entirely about measured geometry.
 */
async function checkATallDialogStaysOnScreen(): Promise<void> {
  const host = document.createElement('div');
  document.body.appendChild(host);

  const rows = Array.from({ length: 60 }, (_, index) =>
    React.createElement('p', { key: index, style: { height: 48, margin: 0 } }, `row ${index}`),
  );
  createRoot(host).render(
    React.createElement(
      Dialog,
      {
        open: true,
        title: 'Tall dialog',
        description: 'More content than the window can hold',
        footer: React.createElement('button', { type: 'button' }, 'Save'),
        onClose: () => {},
        width: 720,
      },
      React.createElement('div', null, ...rows),
    ),
  );
  await wait(250);

  const panel = document.querySelector('[role="dialog"]') as HTMLElement | null;
  if (!panel) {
    check('a tall dialog renders', false);
    return;
  }

  const box = panel.getBoundingClientRect();
  check(
    'a tall dialog fits inside the window',
    box.height <= window.innerHeight,
    `panel ${Math.round(box.height)}px vs viewport ${window.innerHeight}px`,
  );
  // The failure that actually bites: content centred past the top edge is
  // unreachable, so the title and the close button are simply gone.
  check('its title stays reachable', box.top >= 0, `top=${Math.round(box.top)}px`);
  check(
    'its footer stays reachable',
    box.bottom <= window.innerHeight,
    `bottom=${Math.round(box.bottom)}px of ${window.innerHeight}px`,
  );

  // Header, body, footer — the body is the middle one and the only scroller.
  const body = panel.children[1] as HTMLElement | undefined;
  check(
    'the overflow moves into the body',
    !!body && body.scrollHeight > body.clientHeight,
    body ? `scrollHeight=${body.scrollHeight} clientHeight=${body.clientHeight}` : 'no body',
  );

  // Header and footer must keep their own height rather than being squeezed
  // away to make room — that is what flex would do to them by default.
  const header = panel.children[0] as HTMLElement | undefined;
  const footer = panel.children[2] as HTMLElement | undefined;
  check(
    'the header and footer are not squeezed',
    !!header && header.clientHeight > 20 && !!footer && footer.clientHeight > 20,
    `header=${header?.clientHeight} footer=${footer?.clientHeight}`,
  );

  // And scrolling the body actually moves it.
  if (body) {
    body.scrollTop = body.scrollHeight;
    await wait(50);
    check('the body scrolls to the end', body.scrollTop > 0, `scrollTop=${body.scrollTop}`);
  }

  host.remove();
}


/**
 * A popup title is cut to fit, and the window's controls keep their place (#114).
 *
 * Only a layout engine can answer this one. The title row is a flex line, and
 * the failure is entirely about what a flex item's automatic minimum size does
 * to it: the title had no permission to shrink, so a title carrying a `nowrap`
 * span made the line wider than the panel and pushed the `flex-shrink: 0`
 * controls block out of it — 341px past the right edge of a phone screen in the
 * measurement that opened the issue, which is not "hard to aim at" but gone. A
 * plain-string title failed the other way and wrapped, tripling the height of
 * the bar. Static markup renders both as fine.
 *
 * Four shapes of title, because the two failures need different ones: a plain
 * string, the issue reader's icon + number + sentence, the workflow popup's
 * name + status badge, and the file editor's icon + name + badges. Each is
 * measured at a desktop width, then narrowed, then maximised, then again inside
 * a real 390px phone frame — the AC asks for all four states.
 */
async function checkALongPopupTitleStaysInsideItsWindow(): Promise<void> {
  const LONG = 'Answered questions come back blank after switching tabs — the choices must stay marked exactly as they were sent';
  const LONG_PATH = `src/client/shell/chat/${LONG.replace(/[^a-z]+/gi, '-')}.tsx`;

  // The two panels that read something have to have read it: an issue reader
  // showing its "Issue" placeholder and a file editor with no file are the two
  // shortest titles in the app, and would check nothing.
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url);
    if (url.includes('/github/issue/')) {
      return new Response(
        JSON.stringify({ kind: 'issue', item: { number: 114, title: LONG, url: 'https://github.com/dnviti/code-agents-webcli/issues/114', state: 'open', author: { login: 'dnviti' }, body: 'A long title must be truncated, never overflow.', comments: [] } }),
        { status: 200, headers: { 'content-type': 'application/json' } },
      );
    }
    if (url.includes('/workspace/') && url.includes('/file?')) {
      return new Response(
        JSON.stringify({
          path: `/home/dev/projects/webcli/${LONG_PATH}`,
          name: LONG_PATH.split('/').pop(),
          relativePath: LONG_PATH,
          size: 12, mtimeMs: 0, language: 'typescript',
          content: 'const a = 1;\n', binary: false, tooLarge: false, writable: true,
        }),
        { status: 200, headers: { 'content-type': 'application/json' } },
      );
    }
    return realFetch(input as RequestInfo);
  }) as typeof window.fetch;

  /**
   * Every assertion the AC makes about one open panel.
   *
   * Named per case so a failure says which shape of title broke, and asserted
   * rather than swept: `isPainted` DROPS a node it cannot see, so a control
   * pushed off the screen would quietly leave a sweep with nothing to report.
   */
  const measure = (doc: Document, label: string, expectTitle?: string, expectText = expectTitle): boolean => {
    const view = doc.defaultView as Window;
    const panel = doc.querySelector('[role="dialog"]') as HTMLElement | null;
    if (!panel) {
      check(`${label}: the popup is on screen`, false);
      return false;
    }
    const h2 = panel.querySelector('h2[id$="-title"]') as HTMLElement | null;
    const row = h2?.parentElement as HTMLElement | null;
    const header = panel.children[0] as HTMLElement;
    if (!h2 || !row) {
      check(`${label}: the popup has a title`, false);
      return false;
    }

    // The reported failure, stated exactly: the title reaches the strip the
    // window's own controls occupy. Not "the row overflows" — on a phone the
    // 44px touch targets deliberately bleed into the header's padding, which is
    // inside the panel and is not this defect.
    const controlsBox = (row.lastElementChild as HTMLElement).getBoundingClientRect();
    const h2Box = h2.getBoundingClientRect();
    check(
      `${label}: the title stops before the window controls`,
      h2Box.right <= controlsBox.left + 1,
      `title ends ${Math.round(h2Box.right)}, controls start ${Math.round(controlsBox.left)}`,
    );
    // One line: `white-space: nowrap` cannot wrap, so this is really asking
    // whether the clamp is in effect at all. Measured against the title's own
    // line box rather than the header, which is legitimately two rows tall when
    // a dialog passes a description and 76px tall on a phone, where the close
    // control is a 44px touch target.
    const lineHeight = parseFloat(view.getComputedStyle(h2).lineHeight)
      || parseFloat(view.getComputedStyle(h2).fontSize) * 1.5;
    check(
      `${label}: the title stays on one line`,
      h2Box.height <= lineHeight * 1.6,
      `${Math.round(h2Box.height)}px against a ${Math.round(lineHeight)}px line`,
    );

    // The cut has to be an ellipsis, not a clip: an inline-level wrapper inside
    // the title is laid out at max-content and chopped with nothing to say so.
    const spilled = Array.from(h2.querySelectorAll<HTMLElement>('*')).filter(
      (node) => node.getBoundingClientRect().right > h2Box.right + 1,
    );
    check(
      `${label}: nothing inside the title is chopped without an ellipsis`,
      spilled.length === 0,
      spilled.map((node) => `${(node.textContent || '').slice(0, 12)}@${Math.round(node.getBoundingClientRect().right)}`).join(', ')
        || `h2 right=${Math.round(h2Box.right)}`,
    );

    // A title with more text than room is cut *with an ellipsis*, not merely
    // clipped. Conditional on there being something to cut: maximised, this
    // title fits, and demanding truncation there would be demanding a defect.
    const inTitle = [h2, ...Array.from(h2.querySelectorAll<HTMLElement>('*'))];
    const overflowing = inTitle.filter((node) => node.scrollWidth > node.clientWidth + 1);
    const clippers = overflowing.filter((node) => {
      const styles = view.getComputedStyle(node);
      return styles.textOverflow === 'ellipsis' && styles.whiteSpace === 'nowrap';
    });
    check(
      `${label}: a title too long for the bar is cut with an ellipsis`,
      overflowing.length === 0 || clippers.length > 0,
      overflowing.length
        ? `${clippers.length}/${overflowing.length} truncating, ${overflowing[0].scrollWidth} into ${overflowing[0].clientWidth}`
        : 'it fits as it is',
    );

    // Every control in the bar: inside the panel, full size, and hit-testable.
    const panelBox = panel.getBoundingClientRect();
    const controls = Array.from(header.querySelectorAll<HTMLElement>('button, a[href]'));
    check(`${label}: the title bar still has its controls`, controls.length > 0, `${controls.length}`);
    for (const control of controls) {
      const box = control.getBoundingClientRect();
      const name = control.getAttribute('aria-label') || control.getAttribute('title') || control.tagName;
      check(
        `${label}: “${name}” is inside the panel`,
        box.right <= panelBox.right + 1 && box.left >= panelBox.left - 1
          && box.top >= panelBox.top - 1 && box.bottom <= panelBox.bottom + 1,
        `control=[${Math.round(box.left)},${Math.round(box.right)}] panel=[${Math.round(panelBox.left)},${Math.round(panelBox.right)}]`,
      );
      const size = laidOutSize(control);
      check(
        `${label}: “${name}” keeps its full size`,
        size.width > 8 && size.height > 8,
        `${size.width}x${size.height}`,
      );
      const hit = doc.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2);
      check(
        `${label}: “${name}” can actually be clicked`,
        !!hit && (hit === control || control.contains(hit)),
        hit ? `${hit.tagName}${hit === control ? '' : ' (not the control)'}` : 'nothing at that point',
      );
    }

    if (expectTitle !== undefined) {
      check(
        `${label}: the whole title is on hover`,
        h2.getAttribute('title') === expectTitle,
        JSON.stringify(h2.getAttribute('title')),
      );
    }
    if (expectText !== undefined) {
      check(
        `${label}: and nothing was actually taken away`,
        (h2.textContent || '').includes(expectText),
        (h2.textContent || '').slice(0, 40),
      );
    }
    return clippers.length > 0;
  };

  // A workflow whose run name is far longer than any title bar, hydrated the
  // real way so the popup draws its status badge beside it.
  const workflowController = (): ChatController => {
    const controller = new ChatController('browser-check', { send: () => {} });
    controller.transcript.apply({ t: 'msg_start', seq: 1, ts: 1, id: 'm1', role: 'assistant', turnId: 't1' } as never);
    controller.transcript.apply({
      t: 'block_start', seq: 2, ts: 2, msgId: 'm1', index: 0,
      block: { kind: 'tool', toolId: 'wf1', name: 'Workflow', toolKind: 'task', status: 'running', input: { name: LONG } },
    } as never);
    return controller;
  };

  const cases: Array<{ label: string; node: () => React.ReactElement; hover?: string; text?: string }> = [
    {
      label: 'a plain title',
      hover: LONG,
      node: () => React.createElement(
        Dialog,
        { open: true, movable: true, title: LONG, onClose: () => {}, width: 420 },
        React.createElement('p', null, 'body'),
      ),
    },
    {
      label: 'an issue reader',
      hover: LONG,
      node: () => React.createElement(GitHubItemDialog, { sessionId: 's1', kind: 'issue', number: 114, onClose: () => {} } as never),
    },
    {
      label: 'a workflow popup',
      hover: LONG,
      node: () => React.createElement(WorkflowPopup, { open: true, transcript: workflowController().transcript, toolId: 'wf1', onClose: () => {} } as never),
    },
    {
      label: 'a file editor',
      hover: LONG_PATH,
      // The bar shows the file's name; the path it came from is the hover.
      text: LONG_PATH.split('/').pop(),
      node: () => React.createElement(FileEditorDialog, {
        open: true,
        sessionId: 's1',
        filePath: `/home/dev/projects/webcli/${LONG_PATH}`,
        onClose: () => {},
      } as never),
    },
  ];

  for (const one of cases) {
    const host = document.createElement('div');
    document.body.appendChild(host);
    const root = createRoot(host);
    root.render(one.node());
    await wait(250);
    settle(document);
    measure(document, one.label, one.hover, one.text ?? one.hover);

    // Narrower re-cuts it immediately. The grip is only on the movable panels;
    // the ones without it are measured in the phone frame below instead.
    const panel = document.querySelector('[role="dialog"]') as HTMLElement | null;
    const grip = panel?.querySelector('[title="Drag to resize"]') as HTMLElement | null;
    if (panel && grip) {
      const box = panel.getBoundingClientRect();
      grip.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, clientX: box.right, clientY: box.bottom }));
      window.dispatchEvent(new PointerEvent('pointermove', { clientX: box.right - 300, clientY: box.bottom }));
      window.dispatchEvent(new PointerEvent('pointerup', {}));
      await wait(80);
      settle(document);
      measure(document, `${one.label}, dragged 300px narrower`, one.hover, one.text ?? one.hover);
    }

    const maximise = panel?.querySelector('[aria-label="Fill the window"]') as HTMLElement | null;
    if (maximise) {
      maximise.click();
      await wait(120);
      settle(document);
      measure(document, `${one.label}, filling the window`, one.hover, one.text ?? one.hover);
    }

    root.unmount();
    host.remove();
    await wait(30);
  }

  // And the width that started the issue. A real frame, with the real
  // stylesheets: without them every var(--text-*) resolves to nothing and the
  // header measures at the browser's own 16px default.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  for (const one of cases) {
    const mount = doc.createElement('div');
    doc.body.appendChild(mount);
    const root = createRoot(mount);
    root.render(React.createElement(PhoneContext.Provider, { value: true }, one.node()));
    await wait(300);
    settle(doc);
    const truncated = measure(doc, `${one.label} on a phone`, one.hover, one.text ?? one.hover);
    // The width the issue was reported at. Every one of these titles is far
    // wider than 390px, so if nothing is truncating here the mechanism is not
    // engaged at all and every assertion above passed on a title that fitted.
    check(`${one.label} on a phone: the title is actually being cut`, truncated);
    root.unmount();
    mount.remove();
    await wait(30);
  }

  frame.remove();
  window.fetch = realFetch;
}

/**
 * The composer belongs to the conversation column, and must shrink with it.
 *
 * Two defects in one check, both of which static markup renders as passing:
 *
 *   1. The composer used to be a sibling of the row holding the workspace rail,
 *      so it ran the full width of the surface and the rail was simply drawn on
 *      top of its left end.
 *   2. Moving it into the column was not enough. The region holding it is a CSS
 *      grid, and a grid item has `min-width: auto` exactly the way a flex item
 *      does — so the implicit track refused to go below the composer's
 *      min-content width and a wide rail pushed it off the right edge instead.
 *      Only a layout engine can tell those apart from a correct layout, which
 *      is why this check lives here.
 */
/**
 * A queued message that could not be delivered, as the person who typed it sees it.
 *
 * The failure this belongs to (#89) is silent by nature: the message left the
 * queue, appeared in the conversation and was never answered, and the whole
 * point of queueing is that nobody is watching while it happens. So the row
 * that says otherwise has to be real — visible text giving the reason, the
 * message itself still there to be recovered, and a button that actually asks
 * the server to try again. Every part of that is a rendering question, which
 * is why it is checked here rather than in a unit test.
 */
async function checkAMessageThatCouldNotBeSentSaysSoAndCanBeRetried(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:420px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', { send: (message) => sent.push(message) });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [],
      },
      messages: [],
      pendingPermissions: [],
      queued: [
        {
          id: 'q-failed',
          text: 'the one that did not go',
          ts: 1,
          error: 'the pi process was still busy 15s after the last turn ended',
          attempts: 1,
        },
        { id: 'q-waiting', text: 'the one still waiting', ts: 2 },
      ],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(250);

  const rows = Array.from(
    host.querySelectorAll('[aria-label="Messages waiting to be sent"] [role="listitem"]'),
  ) as HTMLElement[];
  check('both queued messages are on screen', rows.length === 2, `${rows.length} rows`);

  const failedRow = rows[0];
  const waitingRow = rows[1];
  const failedText = failedRow?.textContent ?? '';

  check(
    'the message that could not be sent is still there to be recovered, not retyped',
    failedText.includes('the one that did not go'),
    failedText.slice(0, 160),
  );
  check(
    'and it says, in words, that it was not sent and why',
    failedText.includes('Not sent') && failedText.includes('still busy'),
    failedText.slice(0, 160),
  );

  // Announced rather than merely coloured: nobody is looking at the composer
  // while a queue works through, which is the whole reason the queue exists.
  check(
    'the reason is announced, not only drawn',
    Boolean(failedRow?.querySelector('[role="alert"]')),
  );

  const retry = Array.from(failedRow?.querySelectorAll('button') ?? []).find((button) =>
    (button.textContent ?? '').includes('Try again'),
  ) as HTMLButtonElement | undefined;
  check('the row offers a way to try it again', Boolean(retry));
  check(
    'and it is a real button, so it can be reached from the keyboard',
    retry?.tagName === 'BUTTON' && !retry.disabled,
  );

  const before = sent.length;
  retry?.click();
  await wait(150);
  const asked = sent.slice(before).find((message) => message.type === 'chat_queue_retry');
  check(
    'pressing it asks the server to send that exact message again',
    Boolean(asked) && asked?.queuedId === 'q-failed',
    JSON.stringify(sent.slice(before)),
  );

  // The offer belongs to the failure, not to the queue: a message that is
  // simply waiting its turn has nothing to retry.
  const waitingText = waitingRow?.textContent ?? '';
  check(
    'a message that is merely waiting is not dressed up as a failure',
    !waitingText.includes('Not sent') && !waitingText.includes('Try again'),
    waitingText.slice(0, 160),
  );

  root.unmount();
  host.remove();
}

async function checkTheComposerShrinksWithTheWorkspaceRail(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:360px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('browser-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'thinking',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [{ name: 'clear' }],
      },
      messages: [],
      pendingPermissions: [],
      queued: [{ id: 'q1', text: 'a message waiting its turn', ts: 1 }],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  const paint = (panelWidth: number): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/tmp/project',
        view: { ...DEFAULT_CHAT_VIEW, panelOpen: true, panelTab: 'files', panelWidth },
        onViewChange: () => {},
      } as never),
    );
  };

  // Wide enough that the rail takes most of the surface, which is the case that
  // broke: at the default 320 the column had room to spare and both defects
  // looked fine.
  for (const panelWidth of [320, 560]) {
    paint(panelWidth);
    await wait(250);

    const rail = host.querySelector('aside[aria-label="Workspace"]') as HTMLElement | null;
    const textarea = host.querySelector('textarea') as HTMLElement | null;
    if (!rail || !textarea) {
      check(`the composer renders beside a ${panelWidth}px rail`, false);
      continue;
    }

    const railBox = rail.getBoundingClientRect();
    const inputBox = textarea.getBoundingClientRect();
    const hostBox = host.getBoundingClientRect();

    // The rail sits to the *right* of the conversation since the redesign, so
    // the test of "neither is drawn over the other" runs the other way: the
    // composer has to end before the rail begins.
    check(
      `a ${panelWidth}px rail starts after the composer ends`,
      inputBox.right <= railBox.left + 1,
      `composer ends ${Math.round(inputBox.right)}, rail starts ${Math.round(railBox.left)}`,
    );
    check(
      `a ${panelWidth}px rail leaves the composer inside the surface`,
      inputBox.right <= hostBox.right + 1,
      `composer ends ${Math.round(inputBox.right)}, surface ends ${Math.round(hostBox.right)}`,
    );
  }

  root.unmount();
  host.remove();
}

/**
 * The fixed-height bars must never wrap, at any width the app is used at.
 *
 * Acceptance criterion §7.5 of the design spec, and the one defect class this
 * layout is most exposed to: the header, the turn strips and the terminal tab
 * bar are all a fixed height with a money figure or a token count on the right.
 * One item that refuses to shrink pushes the row to two lines — which changes
 * the height of everything below it — or clips the number, which is worse than
 * not showing it. Static markup renders both as passing; only a layout engine
 * knows.
 *
 * The rule the components implement, asserted here rather than described: the
 * low-value items shrink (`min-width: 0` + ellipsis) and the numbers do not.
 */
async function checkTheFixedBarsNeverWrap(): Promise<void> {
  const host = document.createElement('div');
  document.body.appendChild(host);

  const controller = new ChatController('bar-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'bar-check',
    snapshot: {
      sessionId: 'bar-check',
      runtime: 'claude',
      state: 'running',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [{ name: 'clear' }],
      },
      // Deliberately the widest realistic values: six-figure token counts, a
      // four-decimal cost, a long branch name and a deep working directory.
      usage: { totalTokens: 987654, costUsd: 1234.5678, contextWindow: 200000, contextUsed: 190000 },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'please refactor the authentication middleware so that it validates the bearer token against the new issuer, then update every call site that still assumes the old claim shape, and make sure the integration tests cover the expired-token path as well as the malformed-header path' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [
            { kind: 'text', text: 'an answer' },
            { kind: 'thinking', text: 'working' },
            {
              kind: 'tool', toolId: 'x1', name: 'bash', toolKind: 'execute',
              status: 'completed', input: { command: 'npm test' }, durationMs: 754321,
            },
          ],
          usage: { inputTokens: 123456, outputTokens: 98765, costUsd: 1234.5678 },
        },
        {
          id: 'u2', seq: 3, turnId: 't2', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'and now a second turn, so the first one folds' }],
        },
        {
          id: 'a2', seq: 4, turnId: 't2', role: 'assistant', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'done' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: true,
    },
  } as never);

  // A fresh mount per width rather than one root re-rendered three times: the
  // surface measures itself with a ResizeObserver to decide which zones fit,
  // and re-rendering a live tree into a resized box is not the same thing as
  // opening it at that size — which is what a user actually does.
  for (const width of [924, 1280, 1600]) {
    host.style.cssText = `width:${width}px;height:760px;position:absolute;top:0;left:0;display:flex`;
    const root = createRoot(host);
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/home/dev/projects/a-rather-deeply-nested-working-directory',
        branch: 'feature/a-long-enough-branch-name-to-crowd-the-bar',
        view: { ...DEFAULT_CHAT_VIEW, terminalOpen: true },
        onViewChange: () => {},
      } as never),
    );
    await wait(400);

    const bars: Array<[string, HTMLElement | null]> = [
      ['session header', host.querySelector('header')],
      ['turn strip', host.querySelector('[data-turn-id]')],
      ['turn index header', host.querySelector('nav[aria-label="Turns"] div')],
      ['activity filter row', host.querySelector('[aria-label="Activity"] [role="tablist"]')],
      ['terminal tab bar', host.querySelector('[role="tablist"][aria-label="Terminals"]')],
    ];

    for (const [name, bar] of bars) {
      if (!bar) {
        // The turn index is a rail only above 1024px; below that it is a sheet
        // and its header legitimately is not on screen.
        if (name === 'turn index header' && width < 1024) continue;
        check(
          `${name} renders at ${width}px`,
          false,
          `not found; navs=${host.querySelectorAll('nav').length} tablists=${host.querySelectorAll('[role="tablist"]').length}`,
        );
        continue;
      }
      // One line, not two: a wrapped bar is taller than the box it was given.
      check(
        `the ${name} does not wrap at ${width}px`,
        bar.scrollHeight <= bar.clientHeight + 1,
        `scrollHeight=${bar.scrollHeight} clientHeight=${bar.clientHeight}`,
      );
    }

    // And the figures people came to read are inside their bar, not clipped
    // off its right edge.
    const header = host.querySelector('header') as HTMLElement | null;
    if (header) {
      const headerBox = header.getBoundingClientRect();
      const overflowing = Array.from(header.querySelectorAll('*')).filter((node) => {
        const box = (node as HTMLElement).getBoundingClientRect();
        return box.width > 0 && box.right > headerBox.right + 1;
      });
      check(
        `nothing in the header is clipped at ${width}px`,
        overflowing.length === 0,
        overflowing.length
          ? overflowing
              .map((n) => `${n.tagName.toLowerCase()}:${(n.textContent || '').trim().slice(0, 18) || (n as HTMLElement).getAttribute('aria-label') || '?'}`)
              .join(' | ')
          : '0 overflowing',
      );
    }

    root.unmount();
  }

  host.remove();
}

/**
 * The chat has to show the answer while it is being written.
 *
 * Every layer under this was already covered — the reducer applies the events,
 * the transcript bumps its version, the strips re-render — and the chat still
 * went blank in 5.1.2, because the list looked its messages up in a map that
 * was built once and never rebuilt. Nothing short of mounting the real view
 * and streaming into it catches that, so this asserts the only thing that
 * actually matters: the words reach the screen.
 */
async function checkALiveAnswerAppearsAsItStreams(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:760px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('live-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'live-check',
    snapshot: {
      sessionId: 'live-check', runtime: 'claude', state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [],
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'the question already in the transcript' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 1,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/home/dev/project',
      branch: 'main',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  // Exactly what arrives from the socket while an answer is being written:
  // a new turn opens, then text lands in it a delta at a time.
  const event = (payload: unknown): void =>
    controller.handle({ type: 'chat_event', sessionId: 'live-check', event: payload } as never);

  // Read from the rendered messages only. The turn strip repeats the opening
  // question as its label, so asserting against the whole subtree would pass
  // on the strip alone while the body it names is empty — which is the exact
  // bug being guarded against.
  const bodyText = (): string =>
    Array.from(host.querySelectorAll('[data-message-id]'))
      .map((node) => node.textContent || '')
      .join(' ');

  event({ t: 'msg_start', id: 'u2', seq: 2, turnId: 't2', role: 'user', ts: Date.now() });
  event({ t: 'block_start', msgId: 'u2', index: 0, block: { kind: 'text', text: '' } });
  event({ t: 'block_delta', msgId: 'u2', index: 0, text: 'a question typed while the app is open' });
  event({ t: 'msg_end', msgId: 'u2' });
  await wait(250);

  check(
    'a message sent while the app is open shows up',
    bodyText().includes('a question typed while the app is open'),
    'the user\'s own turn never rendered',
  );

  event({ t: 'msg_start', id: 'a2', seq: 3, turnId: 't2', role: 'assistant', ts: Date.now() });
  event({ t: 'block_start', msgId: 'a2', index: 0, block: { kind: 'text', text: '' } });
  await wait(120);
  event({ t: 'block_delta', msgId: 'a2', index: 0, text: 'the answer as it ' });
  await wait(120);
  event({ t: 'block_delta', msgId: 'a2', index: 0, text: 'is being written' });
  await wait(250);

  const text = bodyText();
  check(
    'the answer is on screen before it has finished',
    text.includes('the answer as it is being written'),
    text.includes('the answer as it')
      ? 'the first delta rendered but later ones did not'
      : 'the streaming turn body stayed empty',
  );

  // And the transcript really did receive it — so a failure above is the view
  // not rendering, not the events being wrong.
  check(
    'the transcript itself holds the streamed message',
    controller.transcript.messages.some((m: { id: string }) => m.id === 'a2'),
    `ids=${controller.transcript.messages.map((m: { id: string }) => m.id).join(',')}`,
  );

  root.unmount();
  host.remove();
}

/**
 * Issue #46 — a step that only ran commands leaves no row, and the next reply
 * speaks for it.
 *
 * A static render can count rows but cannot click, and the half of this that
 * matters is the click: the pill on the reply has to open the trace *at the
 * start* of the stretch it counts, not at its own first call. That is a real
 * event handler feeding real state into the rail, so it needs a real browser.
 */
/**
 * No row is drawn with nothing to read in it (#132).
 *
 * The check above proves the #46 rule on a conversation built for it. This one
 * proves it on a real recorded one — the maintainer's own Oh My Pi session, the
 * one in which the agent filed issue #129 — where the rule failed. Oh My Pi
 * sends a reply that is a single space alongside the tool activity on almost
 * every step, so almost every step counted as having spoken and got the row
 * #46 exists to remove: a bordered strip with a model name, a clock and a work
 * counter, and no sentence in it. 22 of that conversation's 29 rows.
 *
 * The last stretch is played in after the view is on screen, so the live path
 * is covered as well as the replayed one — a fold that only happens on rehydrate
 * would leave the strips appearing while the agent works and vanishing when the
 * conversation is reopened.
 */
async function checkNoRowIsDrawnWithNothingToRead(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:760px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('empty-rows', { send: () => {} });
  let seq = 1;
  const play = (batch: unknown[]): void => {
    for (const event of batch) {
      controller.transcript.apply({ ts: seq, ...(event as Record<string, unknown>), seq: seq++ } as never);
    }
  };
  // Everything but the last message, so the reply that finally speaks arrives
  // live, into a conversation already on screen.
  const lastStart = RECORDED_EMPTY_ROWS.map((event) => (event as { t?: string }).t)
    .lastIndexOf('msg_start');
  play(RECORDED_EMPTY_ROWS.slice(0, lastStart));

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'omp',
      runtimeLabel: 'Oh My Pi',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(300);
  settle(document);

  /** Every row in the conversation, and what a reader would find in it. */
  const rows = (): HTMLElement[] =>
    Array.from(host.querySelectorAll<HTMLElement>('[aria-label="Assistant message"]')).filter(isPainted);
  /**
   * The readable part of a row: what the agent actually said.
   *
   * Everything else in the row is accounting — the model and token line in the
   * `<footer>`, the clock, the work counter — so `textContent` says every row
   * has something in it, which is precisely the complaint. Measured off the
   * prose container with the footer taken out, since the footer lives inside it.
   */
  const readable = (row: HTMLElement): string =>
    Array.from(row.querySelectorAll<HTMLElement>('.chat-prose'))
      .map((node) => {
        const copy = node.cloneNode(true) as HTMLElement;
        copy.querySelectorAll('footer').forEach((each) => each.remove());
        return (copy.textContent || '').trim();
      })
      .join(' ')
      .trim();

  const blankWhileRunning = rows().filter((row) => !readable(row));
  check(
    'while the agent works, no row is drawn with nothing to read in it',
    blankWhileRunning.length === 0,
    `${rows().length} rows, ${blankWhileRunning.length} of them blank`,
  );

  play(RECORDED_EMPTY_ROWS.slice(lastStart));
  await wait(300);
  settle(document);

  const blank = rows().filter((row) => !readable(row));
  check(
    'and none once the reply that finally speaks has landed',
    blank.length === 0,
    `${rows().length} rows, ${blank.length} of them blank`,
  );
  check(
    'the conversation is the one reply that said something',
    rows().length === 1 && readable(rows()[0]).includes('Aperta la issue'),
    rows().map((row) => readable(row).slice(0, 40) || '(nothing to read)').join(' | ') || 'no rows',
  );

  // And the folded stretch went to that reply, not to an empty strip.
  const counter = rows()[0]?.querySelector<HTMLElement>('button[aria-label^="Show work"]');
  check(
    'and it carries the work of every step folded into it',
    Boolean(counter) && /\d+ commands?/.test(counter?.getAttribute('aria-label') || ''),
    counter?.getAttribute('aria-label') || 'no work counter on the reply',
  );
  check(
    'while the trace still holds every one of them',
    (host.textContent || '').includes('handleChatSend'),
    'looked for a folded step’s own command on the rail',
  );

  root.unmount();
  host.remove();
}

async function checkSilentStepsLeaveNoRowButKeepTheirTrace(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:760px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const tool = (id: string, command: string, output: string): unknown => ({
    kind: 'tool', toolId: id, name: 'bash', toolKind: 'execute',
    status: 'completed', input: { command }, output, durationMs: 1200,
  });

  const controller = new ChatController('silent-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'silent-check',
    snapshot: {
      sessionId: 'silent-check', runtime: 'claude', state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [],
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'run the tests' }],
        },
        // Two steps that said nothing at all — the rows #46 removes.
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [tool('x1', 'npm run lint', 'THE-FIRST-SILENT-STEP')],
        },
        {
          id: 'a2', seq: 3, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [tool('x2', 'npm run typecheck', 'THE-SECOND-SILENT-STEP')],
        },
        // …and the reply that finally arrives, which has to speak for them.
        {
          id: 'a3', seq: 4, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [
            { kind: 'text', text: 'all green' },
            tool('x3', 'npm test', 'ITS-OWN-STEP'),
          ],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 4,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/home/dev/project',
      branch: 'main',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const rows = (): HTMLElement[] =>
    Array.from(host.querySelectorAll<HTMLElement>('[aria-label="Assistant message"]'));

  check(
    'a step that only ran commands gets no row of its own',
    rows().length === 1,
    `${rows().length} assistant rows: ${rows().map((r) => (r.textContent || '').slice(0, 24)).join(' | ')}`,
  );

  const reply = rows()[0];
  const replyText = reply ? reply.textContent || '' : '';
  const counter = reply
    ? reply.querySelector<HTMLElement>('button[aria-label^="Show work"]')
    : null;
  check(
    'the reply that follows them counts the whole stretch',
    replyText.includes('all green')
      && Boolean(counter)
      && (counter?.getAttribute('aria-label') || '').includes('3 commands'),
    `${replyText.slice(0, 80)} — ${counter?.getAttribute('aria-label') || 'no work counter'}`,
  );

  // Issue #118: the counter is one of the message actions now, sized like them
  // and on the same line, not a banner of its own under the prose.
  const actions = reply
    ? Array.from(reply.querySelectorAll<HTMLElement>('button[aria-label]'))
    : [];
  const labels = actions.map((node) => node.getAttribute('aria-label') || '');
  check(
    'the counter sits in the action row, right after retry',
    labels.findIndex((each) => each.startsWith('Show work')) === labels.indexOf('Retry this turn') + 1
      && labels.indexOf('Retry this turn') >= 0,
    labels.join(' | ') || 'no labelled actions on the reply',
  );
  const rowTop = (node: HTMLElement): number => Math.round(node.getBoundingClientRect().top);
  const retryButton = actions.find((node) => node.getAttribute('aria-label') === 'Retry this turn');
  check(
    'and on the same line as them',
    Boolean(counter && retryButton && rowTop(counter) === rowTop(retryButton)),
    counter && retryButton
      ? `counter at ${rowTop(counter)}, retry at ${rowTop(retryButton)}`
      : 'one of the two controls is missing',
  );
  // It draws numbers, not the sentence the wide button spelled out.
  check(
    'it says it in glyphs and numbers rather than words',
    (counter?.textContent || '').trim() === '3' && !/show work/i.test(replyText),
    `visible text: ${JSON.stringify((counter?.textContent || '').trim())}`,
  );

  // The trace never lost any of it — the rail is the record, and it is open.
  const railText = (): string => host.textContent || '';
  check(
    'every silent step is still on the trace',
    railText().includes('npm run lint') && railText().includes('npm run typecheck'),
    'looked for both suppressed commands on the rail',
  );

  check(
    'the reply carries a way into the trace',
    Boolean(counter),
    counter ? 'work counter found' : 'no work counter on the reply',
  );
  counter?.click();
  await wait(300);

  // Focusing a row expands it, so the first silent step's output is the proof
  // that the counter landed at the start of the stretch rather than on its own
  // call.
  check(
    'it opens the trace at the first silent step, not at the reply’s own call',
    railText().includes('THE-FIRST-SILENT-STEP'),
    railText().includes('THE-FIRST-SILENT-STEP')
      ? 'the first silent step is expanded'
      : railText().includes('ITS-OWN-STEP')
        ? 'the counter focused the reply’s own call'
        : 'nothing was expanded',
  );

  // And live: a silent step arriving mid-stream must not add a row either.
  const event = (payload: unknown): void =>
    controller.handle({ type: 'chat_event', sessionId: 'silent-check', event: payload } as never);
  event({ t: 'msg_start', id: 'u2', seq: 5, turnId: 't2', role: 'user', ts: Date.now() });
  event({ t: 'block_start', msgId: 'u2', index: 0, block: { kind: 'text', text: 'and again' } });
  event({ t: 'msg_end', msgId: 'u2' });
  event({ t: 'msg_start', id: 'a4', seq: 6, turnId: 't2', role: 'assistant', ts: Date.now() });
  event({
    t: 'block_start',
    msgId: 'a4',
    index: 0,
    block: tool('x4', 'npm run build', 'A-LIVE-SILENT-STEP'),
  });
  await wait(300);

  check(
    'a silent step arriving live adds no row while it runs',
    rows().length === 1,
    `${rows().length} assistant row(s) while the second turn is only tools`,
  );

  event({ t: 'msg_end', msgId: 'a4' });
  event({ t: 'msg_start', id: 'a5', seq: 7, turnId: 't2', role: 'assistant', ts: Date.now() });
  event({ t: 'block_start', msgId: 'a5', index: 0, block: { kind: 'text', text: 'built' } });
  await wait(300);

  const live = rows()[1];
  const liveText = live ? live.textContent || '' : '';
  const liveCounter = live
    ? live.querySelector<HTMLElement>('button[aria-label^="Show work"]')
    : null;
  check(
    'the reply appears with the live step already counted on it',
    liveText.includes('built')
      && (liveCounter?.getAttribute('aria-label') || '').includes('1 command'),
    `${liveText.slice(0, 80) || 'the streamed reply never rendered'} — ${
      liveCounter?.getAttribute('aria-label') || 'no work counter'
    }`,
  );

  root.unmount();
  host.remove();
}

/* -------------------------------------------------------------------------
 * The phone (issue #51)
 *
 * Every check above runs at a desktop width, which is how the phone layout
 * shipped for four minor versions as a shrunken desktop: nothing that ran had
 * a viewport small enough to see it. These thresholds are written out here
 * rather than imported from `src/client/ui/touch.ts` on purpose — a check that
 * imports the app's own constants proves the app agrees with itself, not that
 * a finger can hit the button or that an eye can read the label.
 * ------------------------------------------------------------------------- */

/** The floor for anything rendered as text on a phone. */
const PHONE_MIN_TEXT = 12;
/** Live session information is never set below the body text. */
const PHONE_LIVE_TEXT = 15;
/** Hit area, not ink: a 20px glyph in a 44px button passes. */
const PHONE_TARGET = 44;
/** Clear space between two neighbouring targets. */
const PHONE_GAP = 8;
/**
 * Above this size on the axis they touch, two neighbours need no gap.
 *
 * The gap exists so the seam between two targets is findable. That is a real
 * problem at the floor — two 44px buttons touching present one 88px strip with
 * an invisible join — and not one above it: a bottom bar's segments are 78px
 * wide with a label in the middle of each, which is how every phone in the
 * world draws a tab bar, and inserting gaps into one would make it read as five
 * loose buttons rather than one bar.
 */
const PHONE_GAP_EXEMPT_AT = PHONE_TARGET * 1.5;
/**
 * The most vertical room the chrome may take from the conversation, at rest.
 *
 * The point of the floating menu and the collapsing header and composer is that
 * the transcript gets the screen. Nothing else here would notice a redesign
 * that quietly gave the chrome its room back — every other rule is about the
 * chrome being *big enough*, which pushes the other way.
 *
 * A pixel budget rather than a share of the screen: the chrome is a fixed
 * number of pixels, so its share grows as the screen shortens, and a share
 * would fail in landscape for a layout that had given up nothing at all.
 *
 * The budget covers the header strip, the live ribbon, the collapsed composer
 * and the bottom bar together — about 160px of surface plus the bar's 57. It
 * does not cover the floating menu, which floats.
 *
 * The bar is not counted out for the keyboard-open viewport even though the app
 * hides it there: that hiding is driven by `visualViewport`, which a fixture in
 * a sized div cannot move. So this measures the harder case in that one.
 */
const PHONE_CHAT_CHROME = 220;

/** Visible, non-decorative, and not a screen-reader-only clone. */
/** The view a node actually lives in — this page's, or an iframe's. */
function viewOf(node: Element): Window {
  return node.ownerDocument?.defaultView ?? window;
}

/**
 * Jump every entrance animation to its end state.
 *
 * Headless Chrome does not advance animation frames here, so a sheet that
 * arrives from `opacity: 0` stays at 0 for as long as the fixture lives. It
 * still lays out, which is why the geometry rules read it happily while the
 * panel was, by the browser's own account, not on screen. Finishing the
 * animations makes the measured frame the settled one instead of the first.
 * An infinite animation (the spinner, the composer sweep) cannot finish and
 * throws — those have no end state to wait for, so leaving them running is
 * the right answer.
 */
function settle(doc: Document): void {
  for (const animation of doc.getAnimations()) {
    try {
      animation.finish();
    } catch {
      /* infinite: no end to jump to */
    }
  }
}

function isPainted(node: Element): boolean {
  const box = node.getBoundingClientRect();
  if (box.width <= 2 || box.height <= 2) return false;
  if (node.closest('[aria-hidden="true"]')) return false;
  const view = viewOf(node);
  const styles = view.getComputedStyle(node);
  if (styles.visibility === 'hidden' || styles.display === 'none') return false;
  // opacity does not inherit, so a faded-out ancestor still computes to 1 here.
  // A sheet mid-transition would otherwise be measured as if it were on screen.
  for (let el: Element | null = node; el; el = el.parentElement) {
    if (view.getComputedStyle(el).opacity === '0') return false;
  }
  return true;
}

/**
 * The controls, and only the controls.
 *
 * A control nested inside another control is dropped: the outer one is what a
 * finger aims at, and counting both reports a 0px gap between a chip and its
 * own icon every time.
 *
 * `treeitem` is here because the file tree is built out of divs: its rows take
 * a tap and open a file, and by tag alone none of them is a control — so the
 * whole of the Files destination shipped at 26px rows and every rule below
 * reported the surface clean (issue #51).
 */
function paintedControls(root: HTMLElement): HTMLElement[] {
  const rootBox = root.getBoundingClientRect();
  const all = Array.from(
    root.querySelectorAll<HTMLElement>(
      'button, input, select, textarea, [role="tab"], [role="option"], [role="treeitem"], a[href]',
    ),
  ).filter(isPainted).filter((node) => {
    // A sheet's scrim is a control by markup and a gesture by intent: it is the
    // empty half of the screen you tap to dismiss, so it abuts the sheet on
    // purpose and has no size of its own to meet. Recognised by what it is —
    // an empty element covering most of the surface — rather than by a name.
    const box = node.getBoundingClientRect();
    const empty = !(node.textContent || '').trim() && node.childElementCount === 0;
    return !(empty && box.width * box.height > rootBox.width * rootBox.height * 0.2);
  });
  return all.filter((node) => !all.some((other) => other !== node && other.contains(node)));
}

/**
 * A control's laid-out size, ignoring transforms.
 *
 * `getBoundingClientRect()` reports the painted box, which a dialog's entrance
 * animation scales — so a 44px button measures 43.12px for as long as the
 * animation is mid-flight, and headless Chrome does not always finish one. How
 * big a control *is* is a layout question; where it is on screen is the one the
 * rect answers, and that is what the spacing and overflow checks use.
 */
function laidOutSize(node: HTMLElement): { width: number; height: number } {
  return { width: node.offsetWidth, height: node.offsetHeight };
}

/**
 * Which of the named live figures has been seen on screen at all.
 *
 * A collapsed layout is allowed to hide a figure; it is not allowed to make it
 * unreachable. Filled as the states are walked, asserted once at the end.
 */
const seenLive = new Set<string>();

/** Whether any ancestor up to the host deliberately scrolls this node sideways. */
function scrollsSideways(node: Element): boolean {
  for (let at: Element | null = node.parentElement; at; at = at.parentElement) {
    const overflowX = viewOf(at).getComputedStyle(at).overflowX;
    if (overflowX === 'auto' || overflowX === 'scroll') return true;
  }
  return false;
}

/**
 * The nearest ancestor that scrolls this node, if any.
 *
 * Two controls in different scroll containers have no fixed distance from each
 * other — one of them moves when its container is scrolled, and either can be
 * clipped to a sliver at the boundary. Measuring the space between them says
 * nothing about whether they can be mistapped for each other.
 */
function scrollBoxOf(node: Element): Element | null {
  for (let at: Element | null = node.parentElement; at; at = at.parentElement) {
    const styles = viewOf(at).getComputedStyle(at);
    if (/(auto|scroll)/.test(styles.overflowY) || /(auto|scroll)/.test(styles.overflowX)) return at;
  }
  return null;
}

/** Elements that render a word of their own, with the size that word is set at. */
function paintedText(root: HTMLElement): Array<{ node: HTMLElement; size: number; text: string }> {
  const out: Array<{ node: HTMLElement; size: number; text: string }> = [];
  for (const node of Array.from(root.querySelectorAll<HTMLElement>('*'))) {
    const own = Array.from(node.childNodes)
      .filter((child) => child.nodeType === Node.TEXT_NODE)
      .map((child) => (child.textContent || '').trim())
      .join(' ')
      .trim();
    if (!own || !isPainted(node)) continue;
    out.push({ node, size: parseFloat(viewOf(node).getComputedStyle(node).fontSize) || 0, text: own });
  }
  return out;
}

/**
 * The box the user types their message into.
 *
 * Not simply the first `textarea`: xterm keeps a hidden one of its own for IME
 * and clipboard, it comes first in the DOM once the shell is open, and it is
 * 0x0 at `left: -9999em` — so with the terminal on screen the composer rules
 * below were measuring the terminal's plumbing and reporting the composer as
 * having no height.
 */
function composerField(host: HTMLElement): HTMLElement | null {
  return Array.from(host.querySelectorAll<HTMLElement>('textarea')).find(isPainted) ?? null;
}

function describe(node: HTMLElement, text?: string): string {
  const label = (text || node.getAttribute('aria-label') || node.textContent || '')
    .replace(/\s+/g, ' ')
    .trim();
  return `${node.tagName.toLowerCase()}${label ? `:${label.slice(0, 24)}` : ''}`;
}

/**
 * The chat surface as a phone actually composes it.
 *
 * The menu is inside `ChatView` on a phone — it has to be, because it is
 * anchored above the composer and the shell does not know where that ends — so
 * this only has to supply what the shell would contribute to it.
 */
function PhoneSurface({ controller }: { controller: ChatController }): React.ReactElement {
  // Real view state, not a frozen object with a no-op setter.
  //
  // `DEFAULT_CHAT_VIEW.panelOpen` is true — a desktop preference — and on a
  // phone the rail *replaces* the transcript, so a fixture that cannot write
  // the setting back renders a surface with no conversation in it at all and
  // every measurement below is of the panel. The app clears it on mount; a
  // fixture that swallows the write never sees that happen.
  // Seeded shut, which is what the shell hands a phone: `panelOpen` is a
  // desktop preference and on a phone the rail replaces the conversation, so
  // AppShell keeps its own session-scoped answer and starts it false. A fixture
  // that passes the stored default straight through renders the panel and
  // measures that instead of the conversation.
  const [view, setView] = React.useState({ ...DEFAULT_CHAT_VIEW, panelOpen: false });
  const onViewChange = React.useCallback((next: typeof DEFAULT_CHAT_VIEW) => setView(next), []);
  const go = React.useCallback(
    (next: Partial<typeof DEFAULT_CHAT_VIEW>) => setView((current) => ({ ...current, ...next })),
    [],
  );

  // Both bands: the budget below is about what the chrome costs the
  // conversation, and the bar is chrome.
  return React.createElement(
    'div',
    { style: { flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column' } },
    // The surface in a box that can shrink, exactly as AppShell holds it. Given
    // the column directly, `height: 100%` on the surface takes the bar's 56px
    // as well and the transcript is squeezed to nothing.
    React.createElement(
      'div',
      { style: { flex: 1, minHeight: 0, display: 'flex' } },
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/home/dev/projects/a-rather-deeply-nested-working-directory',
        isMobile: true,
        view,
        onViewChange,
        // The phone's route to the conversation list. On a phone the header
        // carries no controls at all, so the actions sheet is where "beside the
        // transcript search" is — and a fixture that leaves this out is a
        // fixture in which the route does not exist to be found (#127).
        onOpenConversations: () => {},
        // What the shell contributes. The surface adds its own inside.
        menuActions: [
          { id: 'new', label: 'New session', icon: 'plus', onPress: () => {} },
          { id: 'more', label: 'More…', icon: 'ellipsis', expands: true, onPress: () => {} },
        ],
      } as never),
    ),
    React.createElement(BottomNav, {
      destinations: [
        {
          id: 'chat', label: 'Chat', icon: 'message-square',
          current: !view.panelOpen && !view.terminalOpen,
          onGo: () => go({ panelOpen: false, terminalOpen: false }),
        },
        {
          id: 'trace', label: 'Trace', icon: 'list-todo',
          current: view.panelOpen && view.panelTab === 'trace',
          onGo: () => go({ panelOpen: true, panelTab: 'trace', terminalOpen: false }),
        },
        {
          id: 'files', label: 'Files', icon: 'hard-drive',
          current: view.panelOpen && view.panelTab !== 'trace',
          onGo: () => go({ panelOpen: true, panelTab: 'files', terminalOpen: false }),
        },
        {
          id: 'terminal', label: 'Shell', icon: 'terminal',
          current: view.terminalOpen,
          onGo: () => go({ panelOpen: false, terminalOpen: true }),
        },
        { id: 'sessions', label: 'Sessions', icon: 'layout-list', onGo: () => {} },
      ],
    } as never),
  );
}

/**
 * A phone is not a narrow desktop.
 *
 * Three viewports, because the failures differ: portrait is the ordinary case,
 * the short one stands in for the on-screen keyboard eating half the screen
 * (headless Chrome has no `visualViewport` to resize, and the layout question —
 * does the composer survive losing the height — is the same either way), and
 * landscape is where a row that only wrapped by luck stops wrapping.
 */
/**
 * Every phone rule, against whatever is currently on screen.
 *
 * Separate from the mount so it can be run again with a sheet open — see the
 * loop in the caller. `where` names the state, so a failure says which one.
 */
function assertPhoneSurface(host: HTMLElement, where: string, atRest = false): void {
  const hostBox = host.getBoundingClientRect();

  // 1. Every control a finger is meant to hit.
  //
  //    A key on the on-screen key strip is judged on height alone. Nine keys
  //    cannot each be 44px wide on a 390px screen — 460px of keys before any
  //    gaps — and no platform's own keyboard tries: a keyboard row is aimed at
  //    vertically, along a band the width of the screen. The exemption is by
  //    name and only for width, so the row still has to be a full target tall
  //    and everything that is not a key still has to be square.
  const controls = paintedControls(host);
  const isKey = (node: HTMLElement): boolean => Boolean(node.closest('[aria-label="Terminal keys"]'));
  const small = controls.filter((node) => {
    const box = laidOutSize(node);
    if (isKey(node)) return box.height < PHONE_TARGET;
    return box.width < PHONE_TARGET || box.height < PHONE_TARGET;
  });
  check(
    `every control is at least ${PHONE_TARGET}px in ${where}`,
    small.length === 0,
    small.length
      ? small
          .slice(0, 8)
          .map((n) => {
            const b = laidOutSize(n);
            return `${describe(n)}=${b.width}x${b.height}`;
          })
          .join(' | ')
      : `${controls.length} controls`,
  );

  // 2. And far enough from the one next to it. Only pairs that actually sit
  //    side by side on the same line can be mistapped for each other.
  const byLeft = [...controls].sort(
    (a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left,
  );
  const crowded: string[] = [];
  for (let i = 0; i < byLeft.length; i++) {
    const a = byLeft[i].getBoundingClientRect();
    for (let j = i + 1; j < byLeft.length; j++) {
      const b = byLeft[j].getBoundingClientRect();
      const sameLine = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top) > Math.min(a.height, b.height) / 2;
      if (!sameLine) continue;
      // Only controls that share a scroll container have a fixed distance from
      // each other — see scrollBoxOf.
      if (scrollBoxOf(byLeft[i]) !== scrollBoxOf(byLeft[j])) continue;
      // Both comfortably over the floor on the axis they meet on — see
      // PHONE_GAP_EXEMPT_AT.
      if (a.width >= PHONE_GAP_EXEMPT_AT && b.width >= PHONE_GAP_EXEMPT_AT) continue;
      // Two keys of the same key strip, for the reason above: a keyboard row is
      // a row, and the space between its keys is what makes it one.
      if (isKey(byLeft[i]) && isKey(byLeft[j])) continue;
      const gap = b.left - a.right;
      // Only the nearest neighbour to the right matters; anything further is
      // separated by that one.
      if (gap < -0.5) continue;
      if (gap < PHONE_GAP - 0.5) {
        crowded.push(`${describe(byLeft[i])}↔${describe(byLeft[j])}=${Math.round(gap)}px`);
      }
      break;
    }
  }
  check(
    `neighbouring controls are at least ${PHONE_GAP}px apart in ${where}`,
    crowded.length === 0,
    crowded.length ? crowded.slice(0, 8).join(' | ') : 'no crowded pairs',
  );

  // 3. Nothing is set in text too small to read.
  const texts = paintedText(host);
  const tiny = texts.filter((t) => t.size < PHONE_MIN_TEXT - 0.01);
  check(
    `no text is smaller than ${PHONE_MIN_TEXT}px in ${where}`,
    tiny.length === 0,
    tiny.length
      ? tiny.slice(0, 8).map((t) => `${describe(t.node, t.text)}@${t.size}px`).join(' | ')
      : `${texts.length} text nodes`,
  );

  // 4. The live session figures — whichever of them this state is showing.
  //
  //    Not "all of them, always": the header and the composer collapse now, so
  //    most of these sit behind a disclosure. What has to hold is that when one
  //    is on screen it is legible, and that every one of them is reachable in
  //    *some* state — asserted once at the end, against `seenLive`.
  const live: Array<[string, HTMLElement | null]> = [
    ['the state', host.querySelector('header [role="status"]')],
    ['the cost and tokens', host.querySelector('[aria-label="Session usage"]')],
    ['the approvals state', host.querySelector('[aria-label="Approvals bypassed"]')],
    ['the model', host.querySelector('[aria-label="Change model"]')],
  ];
  for (const [label, node] of live) {
    if (!node) continue;
    seenLive.add(label);
    const size = parseFloat(viewOf(node).getComputedStyle(node).fontSize) || 0;
    check(
      `${label} is at least ${PHONE_LIVE_TEXT}px in ${where}`,
      size >= PHONE_LIVE_TEXT - 0.01,
      `${size}px`,
    );
  }

  // And the model control shows the model, not the word "model".
  //
  // Asserted because the size check above cannot tell the difference: the chip
  // falls back to a placeholder when nothing reported a model, and a fixture
  // that fails to deliver one measures the placeholder and passes.
  const modelChip = host.querySelector('[aria-label="Change model"]') as HTMLElement | null;
  if (modelChip) {
    check(
      `the model control names the model in ${where}`,
      (modelChip.textContent || '').includes('claude-opus-4-6'),
      (modelChip.textContent || '').trim() || 'empty',
    );
  }

  // 5. And each of them says which control it is.
  //
  //    The issue's wording is "identified without pressing" — on a touch screen
  //    there is no hover, so `title` reveals nothing and `aria-label` is only
  //    read aloud to somebody who has turned a screen reader on. A drawn word
  //    is the only thing that answers the question for everybody.
  const header = host.querySelector('header') as HTMLElement | null;
  const composer = (composerField(host)?.parentElement ?? null) as HTMLElement | null;
  for (const [region, box] of [['the header', header], ['the composer row', composer]] as Array<
    [string, HTMLElement | null]
  >) {
    if (!box) continue;
    const mute = paintedControls(box).filter((node) => {
      if (node.tagName === 'TEXTAREA') return false;
      // A field's placeholder is drawn text saying what the field is for, which
      // is the same answer a button's label gives.
      if (node.tagName === 'INPUT' && (node as HTMLInputElement).placeholder.trim()) return false;
      return !(node.textContent || '').trim();
    });
    check(
      `every control in ${region} is identifiable without pressing it in ${where}`,
      mute.length === 0,
      mute.length ? mute.slice(0, 8).map((n) => describe(n)).join(' | ') : 'all labelled',
    );
  }

  // 6. Nothing is pushed off the side. Vertical overflow inside the
  //    conversation is scrolling and expected; horizontal overflow is a row
  //    that refused to wrap, which is the defect.
  const offscreen = Array.from(host.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node)) return false;
    // Popovers and sheets are allowed to be positioned relative to the
    // viewport rather than this host.
    if (viewOf(node).getComputedStyle(node).position === 'fixed') return false;
    // Nor is a row that deliberately scrolls sideways off-screen: the workspace
    // tab strip is a scroller with a way back to what it is hiding. What this
    // is looking for is content pushed out of a box that does not scroll.
    if (scrollsSideways(node)) return false;
    // Nor xterm's own rendering surface. Its canvas is as wide as the terminal
    // has columns, and the columns come from a fit against the real pane at
    // runtime; a fixture that mounts a terminal without one is measuring the
    // default eighty columns, which says nothing about this layout. The pane
    // around it is not exempt — only what xterm paints inside it.
    if (node.closest('.xterm')) return false;
    const box = node.getBoundingClientRect();
    return box.right > hostBox.right + 1 || box.left < hostBox.left - 1;
  });
  check(
    `nothing is pushed off the side in ${where}`,
    offscreen.length === 0,
    offscreen.length ? offscreen.slice(0, 8).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  // 7. And the conversation has most of the screen.
  //
  //    Only in the resting state: opening the details or the composer's other
  //    controls is the user asking for that room, and taking it back the moment
  //    they do would make the disclosure useless.
  if (atRest) {
    const scroller = host.querySelector('[data-message-id]')?.closest('[style*="overflow"]') as HTMLElement | null;
    const surface = host.getBoundingClientRect();
    if (scroller && surface.height > 0) {
      const chrome = surface.height - scroller.getBoundingClientRect().height;
      check(
        `the chrome takes no more than ${PHONE_CHAT_CHROME}px from the conversation in ${where}`,
        chrome <= PHONE_CHAT_CHROME,
        `${Math.round(chrome)}px of ${Math.round(surface.height)}px`
          + ` (${Math.round((1 - chrome / surface.height) * 100)}% left to the conversation)`,
      );
    }
  }

  // 8. The regions do not overlap.
  //
  //    Every rule above is satisfiable by a layout whose bands sit on top of
  //    each other: a control can be the right size, in the right type, inside
  //    the surface, and still be underneath the ribbon.
  //
  //    Asserted between the *regions*, not their contents. The conversation is
  //    a scroller, so it clips its own children — a turn scrolled half out of
  //    view has a box that extends above the scroller and is painted nowhere
  //    near there, and comparing that box to the header reports an overlap that
  //    does not exist on screen.
  const conversation = host.querySelector('[data-message-id]')?.closest('[style*="overflow"]') as HTMLElement | null;
  const bands: Array<[string, HTMLElement | null]> = [
    ['the header', host.querySelector('header')],
    ['the status ribbon', host.querySelector('[role="status"][aria-live="polite"]:not(header *)')],
  ];
  for (const [label, band] of bands) {
    if (!band || !conversation || band.contains(conversation) || conversation.contains(band)) continue;
    const bandBox = band.getBoundingClientRect();
    const box = conversation.getBoundingClientRect();
    check(
      `the conversation and ${label} do not overlap in ${where}`,
      box.top >= bandBox.bottom - 1 || box.bottom <= bandBox.top + 1,
      `conversation ${Math.round(box.top)}-${Math.round(box.bottom)}, ${label} ${Math.round(bandBox.top)}-${Math.round(bandBox.bottom)}`,
    );
  }

  // 9. The composer is the one thing that must survive every viewport: a
  //    phone with no way to type is not a degraded layout, it is a dead app.
  const textarea = composerField(host);
  if (!textarea) {
    check(`the composer is reachable in ${where}`, false, 'no textarea');
  } else {
    const box = textarea.getBoundingClientRect();
    check(
      `the composer is fully on screen in ${where}`,
      box.top >= hostBox.top - 1 && box.bottom <= hostBox.bottom + 1 && box.height > 0,
      `composer ${Math.round(box.top)}–${Math.round(box.bottom)}, surface ${Math.round(hostBox.top)}–${Math.round(hostBox.bottom)}`,
    );
  }

}

/**
 * On a phone the message is the loudest thing in the conversation (#92).
 *
 * It was the quietest. Every piece of chrome around it — the turn header, the
 * tool and reasoning summary, the model and token line, the timestamps — had
 * been made phone-aware and raised to 15px to satisfy an earlier issue about
 * illegible captions, and the prose itself never was: it stayed at 13px,
 * sans-serif, while the accounting around it sat at 15 in a wide monospace
 * face and in capitals, which reads larger still. A screenful gave more space
 * to the figures between two sentences than to the sentences.
 *
 * So this measures the order rather than a floor. Every rule the app has about
 * phone type until now has been "nothing smaller than N", and a floor cannot
 * catch an inversion — that is exactly how this shipped.
 */
async function checkThePhoneReadsTheMessageFirst(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
  document.body.appendChild(host);

  const controller = new ChatController('phone-type-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'phone-type-check',
    snapshot: {
      sessionId: 'phone-type-check', runtime: 'claude', state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: false,
        interrupt: true, resume: true, fork: false, attachments: false, usage: true,
        cost: true, plan: false, commands: [],
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'why did the release script tag the wrong commit' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          model: 'claude-opus-4-6',
          usage: { inputTokens: 18422, outputTokens: 1203, costUsd: 0.1286 },
          blocks: [
            {
              kind: 'tool', toolId: 'x1', name: 'bash', toolKind: 'execute', status: 'completed',
              input: { command: 'git log --oneline -20' }, output: 'a1b2c3d chore: release', durationMs: 1200,
            },
            { kind: 'text', text: 'Because it reads the version before the bump commit lands, so it tags the parent.' },
          ],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(React.createElement(PhoneSurface, { controller }));
  await wait(400);
  settle(document);

  const log = host.querySelector('[role="log"]') as HTMLElement | null;
  if (!log) {
    check('the phone draws a conversation to measure', false);
    root.unmount();
    host.remove();
    return;
  }

  const painted = paintedText(log);
  const find = (needle: string): { size: number; text: string; node: HTMLElement } | undefined =>
    painted.find((entry) => entry.text.includes(needle));

  const prose = find('Because it reads the version');
  check(
    'the message is drawn at all',
    Boolean(prose),
    painted.map((entry) => `${entry.text.slice(0, 18)}@${entry.size}`).slice(0, 10).join(' | '),
  );
  if (!prose) {
    root.unmount();
    host.remove();
    return;
  }

  // Everything else in the conversation is supporting detail, and every piece
  // of it has to be below the message. Named individually so a failure says
  // which one inverted, rather than "something did".
  const detail: Array<[string, string]> = [
    ['the turn header', 'turn 1'],
    ['the model and token line', 'claude-opus-4-6'],
    ['the token count', 'in'],
    ['the tool and reasoning summary', 'tool'],
    ['the timestamp', ':'],
  ];
  for (const [what, needle] of detail) {
    const found = painted.find((entry) => entry.text.toLowerCase().includes(needle.toLowerCase()));
    // Asserted rather than skipped: a needle that stops matching would take
    // its own assertion off the sweep and leave this reporting all clear.
    check(`${what} is on the screen to be measured`, Boolean(found), needle);
    if (!found) continue;
    check(
      `${what} is smaller than the message`,
      found.size < prose.size - 0.01,
      `${found.size}px against the message's ${prose.size}px`,
    );
    check(
      `${what} is still large enough to read at arm's length`,
      found.size >= PHONE_MIN_TEXT - 0.01,
      `${found.size}px, floor ${PHONE_MIN_TEXT}px`,
    );
  }

  // And the sweep, because naming four is not the same as covering the row: no
  // text in the conversation may reach the message's size except the message.
  const louder = painted.filter(
    (entry) => entry.size > prose.size + 0.01 && !entry.text.includes('Because it reads the version'),
  );
  check(
    'nothing in the conversation is drawn larger than the message',
    louder.length === 0,
    louder.map((entry) => `${entry.text.slice(0, 20)}@${entry.size}`).join(' | ') || 'the message wins',
  );

  check(
    'and the message is comfortably above the floor for reading at arm’s length',
    prose.size >= 16,
    `${prose.size}px`,
  );

  // The composer, which must not make the page zoom when it takes focus.
  const field = composerField(host);
  const fieldSize = field ? parseFloat(getComputedStyle(field).fontSize) : 0;
  check(
    'focusing the composer cannot make the page zoom',
    fieldSize >= 16 - 0.01,
    `${fieldSize}px, iOS zooms below 16px`,
  );

  root.unmount();
  host.remove();
}

/**
 * Plan mode is a conversation control, not a hidden slash command.
 *
 * This is deliberately a rendered check. The regression that prompted the
 * feature was the button disappearing from the Web UI, and the two most
 * important follow-on guarantees are geometric: the revision can be read and
 * acted on without leaving the conversation, and the same route remains
 * reachable once a phone has folded the composer's secondary controls away.
 */
async function checkThePlanControlCanBeReviewedAndActedOn(): Promise<void> {
  const markdown = [
    '# Deployment plan',
    '',
    '1. Preserve the current conversation state.',
    '2. Verify the browser and server paths together.',
    '3. Ship only after the checks pass.',
  ].join('\n');
  const plan = { markdown, revision: 4, ts: Date.now() };
  const capabilities = {
    streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
    questions: true, planMode: true, interrupt: true, resume: true, fork: false,
    attachments: true, usage: true, cost: true, plan: false,
    models: [{ name: 'claude-opus-4-6', value: 'claude-opus-4-6' }],
  };
  const snapshot = (
    sessionId: string,
    state: 'idle' | 'running',
    document = plan,
  ): Record<string, unknown> => ({
    type: 'chat_snapshot',
    sessionId,
    planMode: true,
    planDocument: document,
    snapshot: {
      sessionId,
      runtime: 'claude',
      state,
      capabilities,
      messages: [],
      pendingPermissions: [],
      pendingQuestions: [],
      queued: [],
      firstSeq: 0,
      replayFrom: 0,
      cursor: 0,
      live: true,
      bypassPermissions: false,
      planMode: true,
      planDocument: document,
    },
  });

  const host = document.createElement('div');
  host.style.cssText = 'width:960px;height:720px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  let redraw = (): void => {};
  const controller = new ChatController('plan-browser-check', {
    send: (message: unknown) => sent.push(message as Record<string, unknown>),
    onChange: () => redraw(),
  } as never);
  controller.handle(snapshot('plan-browser-check', 'running') as never);

  const root = createRoot(host);
  const paint = (): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude',
        workingDir: '/tmp/project',
        view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
        onViewChange: () => {},
      } as never),
    );
  };
  paint();
  redraw = paint;
  await wait(300);
  settle(document);

  const planToggle = host.querySelector<HTMLButtonElement>('button[aria-label^="Plan mode"]');
  const modelToggle = host.querySelector<HTMLElement>('[aria-label="Change model"]');
  const planBox = planToggle?.getBoundingClientRect();
  const modelBox = modelToggle?.getBoundingClientRect();
  check(
    'the desktop composer exposes a readable Plan control',
    Boolean(planToggle)
      && isPainted(planToggle!)
      && (planToggle!.textContent || '').trim() === 'Plan on'
      && (planBox?.width || 0) >= 54
      && (planBox?.height || 0) >= 24,
    planToggle && planBox
      ? `${(planToggle.textContent || '').trim()} at ${Math.round(planBox.width)}x${Math.round(planBox.height)}`
      : 'no Plan control',
  );
  check(
    'the Plan control sits with the model controls',
    Boolean(planBox)
      && Boolean(modelBox)
      && modelBox!.right <= planBox!.left + 1
      && Math.abs((modelBox!.top + modelBox!.bottom) / 2 - (planBox!.top + planBox!.bottom) / 2) <= 3,
    planBox && modelBox
      ? `model ends ${Math.round(modelBox.right)}, Plan starts ${Math.round(planBox.left)}`
      : 'one of the controls is missing',
  );
  check(
    'an active planning turn disables the mode switch and explains why',
    planToggle?.disabled === true
      && (planToggle.title || '').includes('available when that turn ends'),
    planToggle ? planToggle.title : 'no Plan control',
  );

  const review = host.querySelector<HTMLButtonElement>('[aria-label="Read the submitted plan"]');
  check(
    'the latest submitted plan has a review control',
    Boolean(review) && isPainted(review!),
    review ? (review.textContent || '').trim() : 'no review control',
  );
  review?.click();
  await wait(200);
  settle(document);

  let dialog = host.querySelector<HTMLElement>('[role="dialog"]');
  const dialogText = (dialog?.innerText || '').replace(/\s+/g, ' ');
  check(
    'the review dialog names the revision and renders the whole plan',
    Boolean(dialog)
      && /revision 4/i.test(dialogText)
      && dialogText.includes('Deployment plan')
      && dialogText.includes('Preserve the current conversation state')
      && dialogText.includes('Ship only after the checks pass'),
    dialogText.slice(0, 240) || 'no dialog',
  );

  const actionButton = (label: string): HTMLButtonElement | null =>
    Array.from(dialog?.querySelectorAll<HTMLButtonElement>('button') || [])
      .find((button) => (button.textContent || '').trim() === label) ?? null;
  const rejectWhileBusy = actionButton('Reject plan');
  const acceptWhileBusy = actionButton('Accept plan');
  check(
    'accepting and rejecting are disabled while the planning turn is active',
    rejectWhileBusy?.disabled === true && acceptWhileBusy?.disabled === true,
    `reject=${String(rejectWhileBusy?.disabled)} accept=${String(acceptWhileBusy?.disabled)}`,
  );
  check(
    'the disabled plan actions say what must finish first',
    dialogText.includes('Wait for the active turn to finish before accepting or rejecting this plan.'),
    dialogText.slice(0, 240),
  );

  const sentBeforeClose = sent.length;
  (dialog?.querySelector('[aria-label="Close"]') as HTMLElement | null)?.click();
  await wait(120);
  check(
    'closing the plan review is inert',
    host.querySelector('[role="dialog"]') === null
      && sent.length === sentBeforeClose
      && controller.planModeValue
      && controller.planDocumentValue?.revision === 4,
    `${sent.length - sentBeforeClose} messages, mode=${String(controller.planModeValue)}, revision=${String(controller.planDocumentValue?.revision)}`,
  );

  // The turn ends. The same revision can now be rejected, which keeps Plan
  // mode on and returns the caret to the ordinary composer for feedback.
  controller.handle({
    type: 'chat_event',
    sessionId: 'plan-browser-check',
    event: { t: 'state', seq: 1, ts: Date.now(), state: 'idle' },
  } as never);
  await wait(120);
  (host.querySelector('[aria-label="Read the submitted plan"]') as HTMLElement | null)?.click();
  await wait(120);
  dialog = host.querySelector<HTMLElement>('[role="dialog"]');
  const reject = Array.from(dialog?.querySelectorAll<HTMLButtonElement>('button') || [])
    .find((button) => (button.textContent || '').trim() === 'Reject plan');
  reject?.click();
  await wait(50);
  const rejectMessage = sent[sent.length - 1];
  check(
    'Reject sends the revision being reviewed',
    rejectMessage?.type === 'chat_reject_plan' && rejectMessage.revision === 4,
    JSON.stringify(rejectMessage || null),
  );
  controller.handle({
    type: 'chat_plan_action',
    sessionId: 'plan-browser-check',
    action: 'reject',
    revision: 4,
    accepted: true,
    planMode: true,
    plan,
    message: 'Plan rejected. Add feedback in the composer.',
  } as never);
  await wait(180);
  const field = host.querySelector<HTMLTextAreaElement>('textarea[aria-label="Message"]');
  check(
    'a confirmed rejection closes review, keeps Plan mode, and focuses feedback',
    host.querySelector('[role="dialog"]') === null
      && controller.planModeValue
      && document.activeElement === field,
    `dialog=${String(Boolean(host.querySelector('[role="dialog"]')))} mode=${String(controller.planModeValue)} focus=${(document.activeElement as HTMLElement | null)?.getAttribute('aria-label') || 'none'}`,
  );

  // Acceptance is a distinct callback and names the same latest revision. The
  // server response is authoritative for leaving Plan mode; the dialog only
  // closes after that response arrives.
  (host.querySelector('[aria-label="Read the submitted plan"]') as HTMLElement | null)?.click();
  await wait(120);
  dialog = host.querySelector<HTMLElement>('[role="dialog"]');
  const accept = Array.from(dialog?.querySelectorAll<HTMLButtonElement>('button') || [])
    .find((button) => (button.textContent || '').trim() === 'Accept plan');
  accept?.click();
  await wait(50);
  const acceptMessage = sent[sent.length - 1];
  check(
    'Accept sends the revision being reviewed',
    acceptMessage?.type === 'chat_accept_plan' && acceptMessage.revision === 4,
    JSON.stringify(acceptMessage || null),
  );
  controller.handle({
    type: 'chat_plan_action',
    sessionId: 'plan-browser-check',
    action: 'accept',
    revision: 4,
    accepted: true,
    planMode: false,
    plan,
    message: 'Plan accepted. Implementation started.',
  } as never);
  await wait(150);
  check(
    'a confirmed acceptance closes review and leaves Plan mode',
    host.querySelector('[role="dialog"]') === null
      && !controller.planModeValue
      && controller.planDocumentValue?.revision === 4,
    `dialog=${String(Boolean(host.querySelector('[role="dialog"]')))} mode=${String(controller.planModeValue)}`,
  );

  root.unmount();
  host.remove();

  // A real phone viewport, not a 390px div in the desktop page. The review is
  // fixed to the viewport, so only an iframe can prove its sheet stays inside a
  // phone rather than silently measuring the desktop around the fixture.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html style="height:100%"><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0;height:100%;display:flex;overflow:hidden"></body></html>',
  );
  doc.close();
  await wait(150);

  const phonePlan = { ...plan, revision: 9 };
  let phoneRedraw = (): void => {};
  const phoneController = new ChatController('plan-phone-check', {
    send: () => {},
    onChange: () => phoneRedraw(),
  } as never);
  phoneController.handle(snapshot('plan-phone-check', 'idle', phonePlan) as never);
  const phoneRoot = createRoot(doc.body);
  const paintPhone = (): void => phoneRoot.render(React.createElement(PhoneSurface, { controller: phoneController }));
  paintPhone();
  phoneRedraw = paintPhone;
  await wait(400);
  settle(doc);

  const more = doc.querySelector<HTMLButtonElement>('[aria-label="Show the other controls"]');
  check('the phone can reveal its secondary composer controls', Boolean(more) && isPainted(more!));
  more?.click();
  await wait(180);
  settle(doc);

  const phoneToggle = doc.querySelector<HTMLButtonElement>('button[aria-label^="Plan mode"]');
  const phoneReview = doc.querySelector<HTMLButtonElement>('[aria-label="Read the submitted plan"]');
  const viewportWidth = frame.contentWindow?.innerWidth || 390;
  const viewportHeight = frame.contentWindow?.innerHeight || 740;
  const inViewport = (node: Element): boolean => {
    const box = node.getBoundingClientRect();
    return box.left >= -1
      && box.top >= -1
      && box.right <= viewportWidth + 1
      && box.bottom <= viewportHeight + 1;
  };
  check(
    'the phone exposes Plan after expanding the other controls',
    Boolean(phoneToggle)
      && isPainted(phoneToggle!)
      && inViewport(phoneToggle!)
      && laidOutSize(phoneToggle!).width >= PHONE_TARGET
      && laidOutSize(phoneToggle!).height >= PHONE_TARGET,
    phoneToggle
      ? `${Math.round(phoneToggle.getBoundingClientRect().left)}..${Math.round(phoneToggle.getBoundingClientRect().right)}, ${laidOutSize(phoneToggle).width}x${laidOutSize(phoneToggle).height}`
      : 'no Plan control',
  );
  check(
    'the phone can reach the submitted revision from the same expanded row',
    Boolean(phoneReview)
      && isPainted(phoneReview!)
      && inViewport(phoneReview!)
      && laidOutSize(phoneReview!).width >= PHONE_TARGET
      && laidOutSize(phoneReview!).height >= PHONE_TARGET,
    phoneReview
      ? `${Math.round(phoneReview.getBoundingClientRect().left)}..${Math.round(phoneReview.getBoundingClientRect().right)}, ${laidOutSize(phoneReview).width}x${laidOutSize(phoneReview).height}`
      : 'no review control',
  );

  phoneReview?.click();
  await wait(180);
  settle(doc);
  const sheet = doc.querySelector<HTMLElement>('[role="dialog"]');
  const sheetBox = sheet?.getBoundingClientRect();
  const sheetText = (sheet?.innerText || '').replace(/\s+/g, ' ');
  check(
    'the phone review opens as a revisioned sheet inside the viewport',
    Boolean(sheet)
      && Boolean(sheetBox)
      && sheetBox!.left >= -1
      && sheetBox!.right <= viewportWidth + 1
      && sheetBox!.top >= -1
      && sheetBox!.bottom <= viewportHeight + 1
      && /revision 9/i.test(sheetText),
    sheetBox
      ? `${Math.round(sheetBox.left)},${Math.round(sheetBox.top)} ${Math.round(sheetBox.width)}x${Math.round(sheetBox.height)} in ${viewportWidth}x${viewportHeight}`
      : 'no sheet',
  );
  check(
    'the phone plan sheet keeps its content and actions within its width',
    Boolean(sheet)
      && sheet!.scrollWidth <= sheet!.clientWidth + 1
      && sheetText.includes('Deployment plan')
      && sheetText.includes('Ship only after the checks pass'),
    sheet ? `content ${sheet.scrollWidth}px in ${sheet.clientWidth}px` : 'no sheet',
  );
  const sheetActions = Array.from(sheet?.querySelectorAll<HTMLButtonElement>('button') || [])
    .filter((button) => /^(Accept|Reject) plan$/.test((button.textContent || '').trim()));
  const unreachable = sheetActions.filter(
    (button) => !isPainted(button)
      || !inViewport(button)
      || laidOutSize(button).width < PHONE_TARGET
      || laidOutSize(button).height < PHONE_TARGET,
  );
  check(
    'both plan decisions remain reachable on the phone sheet',
    sheetActions.length === 2 && unreachable.length === 0,
    sheetActions.length
      ? sheetActions.map((button) => `${(button.textContent || '').trim()}=${laidOutSize(button).width}x${laidOutSize(button).height}`).join(' | ')
      : 'no decision buttons',
  );

  phoneRoot.unmount();
  frame.remove();
}

async function checkThePhoneLayoutIsUsable(): Promise<void> {
  const host = document.createElement('div');
  document.body.appendChild(host);

  const controller = new ChatController('phone-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'phone-check',
    snapshot: {
      sessionId: 'phone-check',
      runtime: 'claude',
      state: 'running',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [{ name: 'clear' }],
        models: [{ name: 'claude-opus-4-6', value: 'claude-opus-4-6' }],
      },
      usage: { totalTokens: 987654, costUsd: 12.3456, contextWindow: 200000, contextUsed: 150000 },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'rework the mobile layout so the controls are reachable' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [
            { kind: 'text', text: 'here is what I changed' },
            // Both kinds of hidden work, so the reply's work counter is drawn in
            // its widest form — two glyphs and two numbers — where every rule
            // below can measure it (issue #118).
            { kind: 'thinking', text: 'which of these actually needs changing' },
            {
              kind: 'tool', toolId: 'x1', name: 'bash', toolKind: 'execute',
              status: 'completed', input: { command: 'npm test' }, durationMs: 4321,
            },
          ],
          usage: { inputTokens: 12345, outputTokens: 6789, costUsd: 0.4321 },
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: true,
    },
  } as never);

  // The model reaches the composer through a `session` event, not through the
  // snapshot and not through a prop — a `model` field on either is quietly
  // ignored, which is how a fixture ends up asserting the size of the word
  // "model" instead of the size of a model name.
  controller.handle({
    type: 'chat_event',
    sessionId: 'phone-check',
    event: {
      // seq 3, not 0: the reducer drops anything at or below the cursor the
      // snapshot left behind, so a seq-0 session event is silently a no-op.
      t: 'session', seq: 3, ts: Date.now(), model: 'claude-opus-4-6',
      // Repeated in full: a `session` event replaces the capabilities rather
      // than merging into them, so a short one here would quietly take the
      // model list and the interrupt away from everything below.
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [{ name: 'clear' }],
        models: [{ name: 'claude-opus-4-6', value: 'claude-opus-4-6' }],
      },
    },
  } as never);

  const viewports: Array<[string, number, number]> = [
    ['portrait', 390, 740],
    ['with the keyboard open', 390, 380],
    ['landscape', 740, 390],
  ];

  /**
   * The base surface, and the same surface with each of the phone's own
   * overlays open.
   *
   * A check only ever covers what its fixture reaches. The trace rail, the turn
   * index and the model list are all sheets on a phone, and asserting the
   * closed state alone is how a layout ends up correct in the chrome and
   * untouched everywhere behind it.
   */
  const states: Array<[string, string[], boolean?]> = [
    ['', []],
    // Scrolled back, because a control only exists in that state: the
    // "Jump to latest" pill floats over the transcript when it is not pinned.
    // It shipped at 34px — a hardcoded height overriding the touch floor its
    // own primitive applies — and every run that happened to leave the
    // transcript pinned reported the phone clean.
    ['scrolled back through the conversation', [], true],
    // Each is now reached through the floating menu: open it, then press the
    // row. Driving it the way a thumb does is the only way to know the route
    // still exists — the controls left the header when the menu arrived.
    ['with the session details open', ['[aria-label="Show the session details"]']],
    ['with the other composer controls open', ['[aria-label="Show the other controls"]']],
    ['with the menu open', ['[aria-label="Open the menu"]']],
  ];

  for (const [name, width, height] of viewports) {
    for (const [state, opens, scrollBack] of states) {
      // A fresh mount per state, not a toggle: closing a sheet is its own
      // control, and a second click on the opener left the previous sheet up
      // and reported its offences against every state after it.
      host.style.cssText = `width:${width}px;height:${height}px;position:absolute;top:0;left:0;display:flex;overflow:hidden`;
      const root = createRoot(host);
      root.render(React.createElement(PhoneSurface, { controller }));
      await wait(400);

      const where = state ? `${name} ${state}` : name;

      if (scrollBack) {
        const scroller = host.querySelector('[data-message-id]')?.closest('[style*="overflow"]') as HTMLElement | null;
        if (scroller) {
          scroller.scrollTop = 0;
          scroller.dispatchEvent(new Event('scroll'));
          await wait(250);
        }
      }

      let reached = true;
      for (const selector of opens) {
        const opener = host.querySelector(selector) as HTMLElement | null;
        if (!opener) {
          check(`the phone surface can open ${state} in ${name}`, false, `no ${selector}`);
          reached = false;
          break;
        }
        opener.click();
        await wait(250);
        settle(host.ownerDocument);
      }
      if (!reached) {
        root.unmount();
        continue;
      }

      // The menu has to be *legible*, not merely present. It was animating in
      // from `opacity: 0` and headless Chrome never advanced the frame, so
      // every rule below skipped the panel as invisible and reported the state
      // as clean — a check that covered the menu by name and nothing by fact.
      if (state.includes('menu')) {
        const panel = host.querySelector('[role="menu"]') as HTMLElement | null;
        const styles = panel ? viewOf(panel).getComputedStyle(panel) : null;
        check(
          `the menu is actually on screen in ${name}`,
          Boolean(panel) && styles!.opacity === '1' && !/rgba\(.*,\s*0\)/.test(styles!.backgroundColor),
          panel ? `opacity=${styles!.opacity} background=${styles!.backgroundColor}` : 'no panel',
        );

        // The route to every conversation, in the sheet the phone keeps the
        // transcript search in. Asserted beside it rather than merely present:
        // the two are one pairing, and a row that drifted to the bottom of a
        // list of session verbs is a route nobody finds.
        const rows = Array.from(host.querySelectorAll<HTMLElement>('[role="menu"] [role="menuitem"], [role="menu"] button'))
          .filter(isPainted)
          .map((node) => (node.getAttribute('aria-label') || node.textContent || '').trim());
        const atSearch = rows.findIndex((label) => label.includes('Search this conversation'));
        const atList = rows.findIndex((label) => label.includes('All conversations'));
        check(
          `the phone's menu offers every conversation in ${name}`,
          atList >= 0,
          rows.slice(0, 8).join(' | ') || 'no rows',
        );
        check(
          `and offers it beside the transcript search in ${name}`,
          atSearch >= 0 && Math.abs(atList - atSearch) === 1,
          `search at ${atSearch}, list at ${atList}`,
        );

        // And the button that dismisses it is still the thing under the finger.
        // Its scrim and it were on the same layer, so which one a tap reached
        // was decided by document order.
        const button = host.querySelector('[aria-label="Close the menu"][aria-haspopup="menu"]') as HTMLElement | null;
        const box = button?.getBoundingClientRect();
        const hit = box
          ? host.ownerDocument.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2)
          : null;
        check(
          `the menu button is not covered by its own scrim in ${name}`,
          Boolean(button) && Boolean(hit) && button!.contains(hit as Node),
          hit ? `${(hit as HTMLElement).tagName.toLowerCase()}:${(hit as HTMLElement).getAttribute('aria-label') || '?'}` : 'nothing there',
        );
      }
      // Issue #118 — the work counter is one of the message actions now, so
      // the sweep below covers it only for as long as this fixture keeps
      // producing hidden work. Named here so that stops being silent: a
      // transcript with nothing to count would leave every rule above passing
      // over a control that is no longer on screen.
      if (!state) {
        const counter = host.querySelector<HTMLElement>('button[aria-label^="Show work"]');
        const box = counter ? laidOutSize(counter) : { width: 0, height: 0 };
        const label = counter?.getAttribute('aria-label') || '';
        check(
          `the reply’s work counter is hittable and says what it counts in ${name}`,
          box.width >= PHONE_TARGET
            && box.height >= PHONE_TARGET
            && label.includes('1 command')
            && label.includes('1 reasoning step'),
          counter ? `${box.width}x${box.height} — ${label}` : 'no work counter on screen',
        );

        // …and *drawn*, which the rules above cannot see: `laidOutSize` reads
        // offsetWidth, and `isPainted` drops a faded node from the sweep rather
        // than failing it — so a counter at `opacity: 0` measures 78x44 and
        // vanishes from every other check at once. Its two glyphs are asserted
        // by count for the same reason: the label would still read "1 command,
        // 1 reasoning step" over a control drawing two bare numbers.
        const glyphs = counter ? counter.querySelectorAll('svg').length : 0;
        const opacity = counter
          ? Number(viewOf(counter).getComputedStyle(counter).opacity)
          : 0;
        check(
          `and it is actually painted, with both its glyphs, in ${name}`,
          Boolean(counter) && isPainted(counter as Element) && opacity >= 0.9 && glyphs === 2,
          counter ? `opacity=${opacity} glyphs=${glyphs}` : 'no work counter on screen',
        );

        // Reachable by keyboard "on the same terms as the other message
        // actions" (issue #118). Both halves are needed: `.focus()` succeeds on
        // a `tabIndex={-1}` element — programmatic focus is not tab order — so
        // the index is what says a Tab key can ever arrive here, and the focus
        // call is what says the element accepts it once it does.
        counter?.focus();
        const focused = Boolean(counter) && host.ownerDocument.activeElement === counter;
        check(
          `and it is in the tab order and takes focus in ${name}`,
          focused && (counter?.tabIndex ?? -1) >= 0,
          counter
            ? `tabIndex=${counter.tabIndex} focused=${focused}`
            : 'no work counter on screen',
        );
        (host.ownerDocument.activeElement as HTMLElement | null)?.blur();
      }
      assertPhoneSurface(host, where, opens.length === 0);
      root.unmount();
    }
  }

  // The bar is a set of destinations, and pressing one has to go there.
  //
  // Asserted by driving it, because the parts that could be wrong are all on
  // the far side of a press: which item paints as current, and whether the
  // surface actually changed. Static markup shows a bar that looks right and
  // navigates nowhere.
  //
  // And every rule the resting surface is held to is re-run *at* each
  // destination. Arriving somewhere and finding desktop density is the same
  // defect as never arriving, and this block used to prove only the arrival:
  // the Files rail shipped 26px rows and the shell 22px tabs while the phone
  // checks reported the layout clean (issue #51).
  {
    // The workspace route, answered — otherwise Files arrives at an error note
    // and the tree this is here to measure is never on screen. Everything else
    // still goes to the real server, including the terminal's own create,
    // which 404s and leaves the pane in its error phase: the tab strip is
    // drawn either way, and the strip is what is being measured.
    const realFetch = window.fetch;
    window.fetch = ((input: RequestInfo | URL, init?: RequestInit) => {
      const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
      // `.call(window)`, because a bare `fetch` off a saved reference throws
      // "Illegal invocation" — it needs its window as the receiver.
      if (!url.includes('/api/workspace/')) return realFetch.call(window, input as RequestInfo, init);
      return Promise.resolve(
        new Response(
          JSON.stringify({
            root: '/home/dev/projects/webcli',
            path: '',
            truncated: false,
            entries: [
              { name: 'src', path: '/home/dev/projects/webcli/src', isDirectory: true },
              { name: 'test', path: '/home/dev/projects/webcli/test', isDirectory: true },
              { name: 'package.json', path: '/home/dev/projects/webcli/package.json', isDirectory: false, size: 4312 },
              { name: 'README.md', path: '/home/dev/projects/webcli/README.md', isDirectory: false, size: 918 },
            ],
          }),
          { status: 200, headers: { 'content-type': 'application/json' } },
        ),
      );
    }) as typeof window.fetch;

    host.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
    const root = createRoot(host);
    root.render(React.createElement(PhoneSurface, { controller }));
    await wait(400);

    const bar = host.querySelector('nav[aria-label="Go to"]') as HTMLElement | null;
    const current = (): string =>
      (bar?.querySelector('[aria-current="page"]')?.textContent || '').trim();

    check('the bar starts on the conversation', current() === 'Chat', current() || 'nothing current');

    for (const [label, expect] of [
      ['Trace', 'a rail'],
      ['Files', 'a rail'],
      ['Shell', 'a terminal'],
      ['Chat', 'the transcript'],
    ] as Array<[string, string]>) {
      const item = Array.from(bar?.querySelectorAll('button') ?? []).find(
        (node) => (node.textContent || '').trim() === label,
      ) as HTMLElement | undefined;
      if (!item) {
        check(`the bar offers ${label}`, false, 'not found');
        continue;
      }
      item.click();
      await wait(300);

      check(`pressing ${label} marks it as where you are`, current() === label, current() || 'nothing current');

      const showsRail = Boolean(host.querySelector('aside[aria-label="Workspace"]'));
      const showsShell = Boolean(host.querySelector('[role="tablist"][aria-label="Terminals"]'));
      const showsTranscript = Boolean(host.querySelector('[data-message-id]'));
      check(
        `pressing ${label} actually shows ${expect}`,
        expect === 'a rail'
          ? showsRail
          : expect === 'a terminal'
            ? showsShell
            : showsTranscript && !showsRail,
        `rail=${showsRail} shell=${showsShell} transcript=${showsTranscript}`,
      );

      // The Files rail is fetched, so wait for the tree rather than measuring
      // the "Loading files…" note that stands in for it.
      if (label === 'Files') await wait(300);
      settle(host.ownerDocument);
      assertPhoneSurface(host, `the ${label} destination`);
    }

    root.unmount();
    window.fetch = realFetch;
  }

  // Reachable, not merely legible wherever it happened to be drawn. Collapsing
  // the header and the composer is what this asserts the price of: every figure
  // the issue names by hand still has a state that shows it.
  for (const label of ['the state', 'the cost and tokens', 'the approvals state', 'the model']) {
    check(
      `${label} is reachable somewhere on a phone`,
      seenLive.has(label),
      seenLive.has(label) ? 'shown' : 'never on screen in any state',
    );
  }

  host.remove();
}

/**
 * The index beside a conversation lists all of it, not the part that is loaded.
 *
 * The defect this covers is invisible to a unit test of the merge: a browser
 * holding the last two turns of a hundred-turn conversation used to draw an
 * index of two, numbered 1 and 2, in the one case where an index is the only
 * way to navigate (#86). So this asserts what is actually on screen — the count,
 * the numbering, and that each row is titled with what the *user* asked.
 */
async function checkTheTurnIndexListsTheWholeConversation(): Promise<void> {
  const frame = document.createElement('div');
  frame.style.cssText = 'width:1400px;height:800px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(frame);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => sent.push(message),
  } as never);

  // What a browser actually holds after opening a long conversation: the tail.
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: { streaming: true, questions: false },
      // The replay landed *inside* the last turn, which is what a reload of a
      // long conversation actually gives you: the ask that opened it is not in
      // the window, only the answer to it.
      messages: [
        {
          id: 'a40', seq: 80, turnId: 't40', role: 'assistant', ts: 80,
          blocks: [{ kind: 'text', text: 'the discovery that simplified it' }],
          // Still flagged mid-stream, with the session idle. That combination
          // is ordinary: the flag is only ever cleared by an event, and the
          // window that carried this message was cut before the one that would
          // have. The turn is finished — the session says so — and the row must
          // not sit there spinning on it.
          streaming: true,
        },
      ],
      pendingPermissions: [],
      pendingQuestions: [],
      firstSeq: 1,
      replayFrom: 79,
      cursor: 80,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  check(
    'opening a conversation asks for its whole turn index',
    sent.some((message) => message.type === 'chat_turn_index_request'),
    sent.map((message) => String(message.type)).join(' | ') || 'nothing was asked for',
  );

  // What the server answers with: every turn, from the first.
  const recorded = Array.from({ length: 40 }, (_, i) => ({
    id: `u${i + 1}`,
    turnId: `t${i + 1}`,
    index: i + 1,
    label:
      i === 0 ? 'set up the parser' : i === 39 ? 'and now the changelog' : `ask ${i + 1}`,
    startedAt: (i + 1) * 1000,
    outcome: 'done',
    // What each turn cost, as the accounting filed it. The first is under a
    // cent, which must not round away to "$0.00" beside real work.
    usage: i === 0 ? { costUsd: 0.0031 } : { costUsd: 0.42 + i },
  }));
  // One with no user prompt behind it, which must say so rather than quote the
  // model — the tail of a resumed conversation is the ordinary case.
  recorded[1] = { ...recorded[1], label: null } as never;

  controller.handle({
    type: 'chat_turn_index',
    sessionId: 'browser-check',
    turns: recorded,
    firstSeq: 1,
    complete: true,
  } as never);
  await wait(50);

  const root = createRoot(frame);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  // The number on the strip over the conversation, which is what a reload
  // actually shows you: holding the last turn of forty, it must say 40. It said
  // "TURN 1" until the whole history had been paged in, because the number came
  // from the position in the loaded window rather than from the conversation.
  // Read off the strip itself rather than the page text: the index panel also
  // shows a count, and a check that matched anywhere would pass on that.
  const strip = frame.querySelector('[data-turn-id]');
  const stripText = (strip?.textContent || '').replace(/\s+/g, ' ');
  const foldLabel = strip
    ?.querySelector('[aria-label^="Collapse turn"], [aria-label^="Expand turn"]')
    ?.getAttribute('aria-label');
  check(
    'the turn on screen is numbered by the conversation, not by the window',
    foldLabel === 'Collapse turn 40' || foldLabel === 'Expand turn 40',
    foldLabel || 'no turn strip on screen',
  );
  check(
    'the conversation is on screen under that number',
    stripText.length > 0,
    stripText.slice(0, 80) || 'the strip is empty',
  );

  const list = frame.querySelector('[aria-label="Conversation turns"]');
  const rows = list ? Array.from(list.querySelectorAll('[role="option"]')) : [];
  check(
    'the index lists every turn, not only the ones loaded',
    rows.length === 40,
    `${rows.length} rows for a 40-turn conversation holding 1`,
  );
  // Newest first: the turn you are looking at is the top row, and the first
  // turn of the conversation is the last one.
  check(
    'the newest turn is the first row',
    (rows[0]?.textContent || '').includes('and now the changelog'),
    (rows[0]?.textContent || '').slice(0, 80) || 'no first row',
  );
  check(
    'and it reaches back to the first turn at the bottom',
    (rows[39]?.textContent || '').includes('set up the parser'),
    (rows[39]?.textContent || '').slice(0, 80) || 'no last row',
  );
  check(
    'a turn with no prompt behind it says so instead of quoting the model',
    (rows[38]?.textContent || '').includes('no prompt'),
    (rows[38]?.textContent || '').slice(0, 80) || 'no second-from-last row',
  );
  // The turn on screen, whose opening ask is not in the window. It reads "no
  // prompt" if the label is taken from the loaded messages — which is what the
  // index showed for the turn the user was looking at (#86). It is the top row,
  // and its number is still the conversation's.
  check(
    'a half-loaded turn is titled from the recording, not "no prompt"',
    !(rows[0]?.textContent || '').includes('no prompt'),
    (rows[0]?.textContent || '').slice(0, 80) || 'no first row',
  );
  // The reported defect, read off the icon rather than off the state that
  // decides it: the chat had finished and the row was still turning.
  const spinning = rows.filter((row) =>
    Array.from(row.querySelectorAll('*')).some((node) =>
      ((node as HTMLElement).style?.animation || '').includes('relay-spin'),
    ),
  );
  check(
    'no row spins once the session says it is idle',
    spinning.length === 0,
    spinning.length
      ? `${spinning.length} spinning: ${(spinning[0].textContent || '').slice(0, 40)}`
      : 'none',
  );
  check(
    'the newest row still carries the number the conversation gave it',
    (rows[0]?.textContent || '').trim().startsWith('40'),
    (rows[0]?.textContent || '').slice(0, 40) || 'no first row',
  );

  // What each turn cost, beside the turn — the whole point of asking. Read off
  // the rendered row rather than off the data behind it.
  const newestRow = (rows[0]?.textContent || '').replace(/\s+/g, ' ');
  check(
    'each turn carries what it cost',
    newestRow.includes('$39.42'),
    newestRow.slice(0, 60) || 'no first row',
  );
  const oldestRow = (rows[39]?.textContent || '').replace(/\s+/g, ' ');
  check(
    'a turn under a cent is not rounded away to nothing',
    oldestRow.includes('$0.0031'),
    oldestRow.slice(0, 60) || 'no last row',
  );

  // And it arrives as a turn ends, without reopening the conversation: the
  // session says what it filed the moment it files it.
  controller.handle({
    type: 'chat_turn_spend',
    sessionId: 'browser-check',
    turnId: 't40',
    usage: { costUsd: 1.25 },
  } as never);
  await wait(120);
  const afterSpend = (
    frame.querySelector('[aria-label="Conversation turns"]')?.querySelectorAll('[role="option"]')[0]
      ?.textContent || ''
  ).replace(/\s+/g, ' ');
  check(
    'a turn ending updates its cost in place',
    afterSpend.includes('$1.25'),
    afterSpend.slice(0, 60) || 'no first row',
  );

  // A transcript this short is already scrolled to its top, so the list asks
  // for a page on its own. Settle that one first, or the click below would be
  // measured against a request it did not make.
  controller.handle({
    type: 'chat_page',
    sessionId: 'browser-check',
    events: [],
    firstSeq: 1,
    from: 40,
    cursor: 80,
  } as never);
  await wait(200);

  // Choosing one from before what is loaded has to take the user there, which
  // means fetching it first. Asserted on the outcome rather than on the request
  // — a transcript this short is at its own top and asks for pages unprompted,
  // so counting requests would measure the scroll position, not the click.
  const oldest = rows[39] as HTMLElement | undefined;
  oldest?.click();
  await wait(200);
  check(
    'and the entry stays selected while it is being fetched',
    oldest?.getAttribute('aria-selected') === 'true',
    String(oldest?.getAttribute('aria-selected')),
  );

  controller.handle({
    type: 'chat_page',
    sessionId: 'browser-check',
    events: [
      { t: 'msg_start', seq: 1, ts: 1, id: 'u1', role: 'user', turnId: 't1' },
      { t: 'block_start', seq: 2, ts: 1, msgId: 'u1', index: 0, block: { kind: 'text', text: 'set up the parser' } },
      { t: 'msg_end', seq: 3, ts: 1, msgId: 'u1' },
      { t: 'turn_end', seq: 4, ts: 1, turnId: 't1', stopReason: 'end_turn' },
    ],
    firstSeq: 1,
    from: 1,
    cursor: 80,
  } as never);
  await wait(400);

  const transcriptText = frame.textContent || '';
  check(
    'selecting an older entry brings that turn into the conversation',
    transcriptText.includes('set up the parser'),
    transcriptText.includes('set up the parser') ? 'the turn is here' : 'the turn never arrived',
  );

  root.unmount();
  frame.remove();
}

run().catch((error: unknown) => {
  const pre = document.createElement('pre');
  pre.id = 'results';
  pre.textContent = `FAIL :: threw :: ${error instanceof Error ? error.stack : String(error)}`;
  document.body.appendChild(pre);
});

/**
 * The chat surface is not the whole phone (issue #51).
 *
 * The bottom bar, its more sheet and the tab switcher live in the app shell,
 * above and beside every conversation — none of them is reachable from a
 * ChatView fixture, so they need their own mount or they go the way the phone
 * layout went: untested and therefore unchanged.
 *
 * The floating menu is mounted *open*, because shut it is one button and the
 * question is whether the list behind it can be read and hit.
 *
 * The terminal's key strip is deliberately not here. It is the terminal's own
 * on-screen controls, which issue #51 lists as a non-goal — they were sized
 * for a thumb when they were added, under their own issue.
 */
async function checkThePhoneShellSurfacesAreUsable(): Promise<void> {
  const noop = (): void => {};
  const surfaces: Array<[string, () => React.ReactElement]> = [
    ['the floating menu', () =>
      React.createElement(OpenFloatingMenu, {
        actions: [
          { id: 'search', label: 'Search this conversation', icon: 'search', onPress: noop, expands: true, group: 'surface' },
          { id: 'trace', label: 'Trace rail', icon: 'panel-right', onPress: noop, toggle: true, active: true, group: 'surface' },
          { id: 'sessions', label: 'Sessions', icon: 'layout-list', onPress: noop, expands: true, group: 'session' },
          { id: 'new', label: 'New', icon: 'plus', onPress: noop, group: 'session' },
          { id: 'more', label: 'More', icon: 'ellipsis', onPress: noop, expands: true, group: 'session' },
        ],
      } as never)],
    ['the more sheet', () =>
      React.createElement(MoreSheet, {
        open: true, theme: 'dark', logoutUrl: '/logout', canCloseSession: true,
        install: { supported: true, reason: null } as never,
        onInstall: noop, onClose: noop, onReconnect: noop, onClearTerminal: noop,
        onSwitchMode: noop, onCloseSession: noop, onOpenSettings: noop,
        onToggleTheme: noop, onRename: noop,
      } as never)],
    ['the chat settings dialog', () =>
      React.createElement(ChatSettingsDialog, {
        open: true, settings: DEFAULT_CHAT_VIEW, onChange: noop, onClose: noop,
      } as never)],
    // The app's own settings dialog, which was never in this list: it is the
    // longest dialog in the product and the only place several behaviours can
    // be changed at all — including which conversations may interrupt you.
    ['the settings dialog', () =>
      React.createElement(SettingsDialog, {
        open: true,
        settings: {
          fontSize: 14,
          theme: 'github-dark',
          terminalFontFamily: 'jetbrains-mono',
          chatBypassPermissions: false,
          notifications: DEFAULT_NOTIFICATIONS,
        },
        onPreview: noop, onSave: noop, onClose: noop,
        install: 'available', onInstall: noop, onOpenRuntimeProfiles: noop,
      } as never)],
    ['the sessions dialog', () =>
      React.createElement(SessionsDialog, {
        open: true,
        sessions: [
          { id: 's1', title: 'a session with a fairly long name', runtime: 'claude', workingDir: '/tmp/a' },
          { id: 's2', title: 'another one', runtime: 'codex', workingDir: '/tmp/b' },
        ],
        activeId: 's1', onJoin: noop, onLeave: noop, onDelete: noop, onNew: noop, onClose: noop,
      } as never)],
    // The conversation list, which on a phone is the surface the whole feature
    // is reached through: several projects, several conversations each, and the
    // badges that carry the live facts — so the sweeps below measure the row at
    // its widest rather than an empty list.
    ['the conversations dialog', () =>
      React.createElement(ConversationsDialog, {
        open: true,
        load: async () => ({
          projects: [
            {
              dir: '/home/dev/projects/a-rather-deeply-nested-working-directory',
              name: 'a-rather-deeply-nested-working-directory',
              lastActivity: '2026-07-25T21:35:00.000Z',
              conversations: [
                {
                  id: 'p1', name: 'Session 25/07/2026, 21:35',
                  firstMessage: 'rework the mobile layout so every control is reachable with a thumb',
                  runtime: 'claude', runtimeLabel: 'Claude',
                  lastActivity: '2026-07-25T21:35:00.000Z',
                  workingDir: '/home/dev/projects/a-rather-deeply-nested-working-directory',
                  events: 40, canResume: true, running: true, bypassPermissions: true,
                },
                {
                  id: 'p2', name: 'Session 24/07/2026, 09:12',
                  firstMessage: 'why is the terminal blank after a reload?',
                  runtime: 'codex', runtimeLabel: 'Codex',
                  lastActivity: '2026-07-24T09:12:00.000Z',
                  workingDir: '/home/dev/projects/a-rather-deeply-nested-working-directory',
                  events: 12, canResume: false, running: false, bypassPermissions: false,
                },
              ],
            },
            {
              dir: '/srv/infra',
              name: 'infra',
              lastActivity: '2026-07-20T10:00:00.000Z',
              conversations: [
                {
                  id: 'p3', name: 'Session 20/07/2026, 10:00',
                  firstMessage: 'roll the certificates',
                  runtime: 'claude', runtimeLabel: 'Claude',
                  lastActivity: '2026-07-20T10:00:00.000Z',
                  workingDir: '/srv/infra',
                  events: 90, canResume: true, running: false, bypassPermissions: false,
                },
              ],
            },
          ],
          total: 3,
          truncated: false,
        }),
        openIds: ['p1'],
        activeId: 'p1',
        onOpen: noop,
        onDelete: async () => false,
        onClose: noop,
      } as never)],
    ['the tab switcher', () =>
      React.createElement(TabSwitcherSheet, {
        open: true,
        tabs: [
          { id: 't1', title: 'a session with a fairly long name', kind: 'terminal' },
          { id: 't2', title: 'another one', kind: 'chat' },
        ],
        activeId: 't1',
        onSelect: noop, onCloseTab: noop, onNew: noop, onAllSessions: noop, onClose: noop,
      } as never)],
  ];

  for (const [name, render] of surfaces) {
    // An iframe, not a sized div.
    //
    // Two of these four surfaces are `Dialog`s, and a Dialog portals to
    // `document.body` and positions itself against the *viewport*. Measured
    // inside this page it would be 800px wide whatever the host div says — so
    // the one thing being asked ("does it fit a phone?") would be answered
    // about a desktop. An iframe has a viewport of its own.
    const frame = document.createElement('iframe');
    frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
    document.body.appendChild(frame);
    const doc = frame.contentDocument as Document;
    doc.open();
    doc.write(
      '<!doctype html><html><head>'
      + '<link rel="stylesheet" href="/css/relay/relay.css">'
      + '<link rel="stylesheet" href="/css/main.css">'
      + '</head><body style="margin:0"></body></html>',
    );
    doc.close();
    await wait(150);

    const host = doc.body;
    const root = createRoot(host);
    // Inside a provider, because two of these are the app's ordinary dialogs
    // rather than phone-only surfaces: they take their sizing from the shell's
    // `isMobile`, the same way every other component below AppShell does, and
    // outside one they would correctly render at desktop sizes.
    root.render(React.createElement(PhoneContext.Provider, { value: true }, render()));
    await wait(300);
    settle(doc);

    const target = host;
    const controls = paintedControls(target);
    if (controls.length === 0) {
      check(`${name} renders on a phone`, false, 'no controls found');
      root.unmount();
      frame.remove();
      continue;
    }

    const small = controls.filter((node) => {
      const box = laidOutSize(node);
      return box.width < PHONE_TARGET || box.height < PHONE_TARGET;
    });
    check(
      `every control in ${name} is at least ${PHONE_TARGET}px`,
      small.length === 0,
      small.length
        ? small.slice(0, 8).map((n) => {
            const b = laidOutSize(n);
            return `${describe(n)}=${b.width}x${b.height}`;
          }).join(' | ')
        : `${controls.length} controls`,
    );

    const tiny = paintedText(target).filter((t) => t.size < PHONE_MIN_TEXT - 0.01);
    check(
      `no text in ${name} is smaller than ${PHONE_MIN_TEXT}px`,
      tiny.length === 0,
      tiny.length
        ? tiny.slice(0, 8).map((t) => `${describe(t.node, t.text)}@${t.size}px`).join(' | ')
        : 'all legible',
    );

    const offscreen = Array.from(target.querySelectorAll<HTMLElement>('*')).filter((node) => {
      if (!isPainted(node) || scrollsSideways(node)) return false;
      const box = node.getBoundingClientRect();
      return box.right > 391 || box.left < -1;
    });
    check(
      `nothing in ${name} is pushed off the side`,
      offscreen.length === 0,
      offscreen.length ? offscreen.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
    );

    root.unmount();
    frame.remove();
  }
}

/**
 * A name the user chose can be any length (issue #54).
 *
 * Names used to live only in the page that typed them, so nothing longer than
 * a session id ever survived to be looked at twice. Now a name is stored and
 * comes back on every page load, on every device — including the 300-character
 * one somebody pasted in — so the strip has to keep it inside its own row
 * instead of stretching until the tabs beside it are unreachable.
 */
async function checkALongTabNameStaysInsideTheStrip(): Promise<void> {
  const LONG = 'a session name that somebody pasted in from a commit message and never shortened, '
    + 'complete with a path /home/dev/projects/deeply/nested/thing and a ticket reference #54';

  const host = document.createElement('div');
  host.style.cssText = 'width:900px;position:absolute;top:0;left:0';
  document.body.appendChild(host);

  const root = createRoot(host);
  root.render(
    React.createElement(TabBar, {
      tabs: [
        { id: 't1', title: LONG, status: 'running' },
        { id: 't2', title: 'short', status: 'idle' },
        { id: 't3', title: 'also short', status: 'idle' },
      ],
      activeId: 't1',
      onSelect: () => {},
      onClose: () => {},
      onNew: () => {},
      ariaLabel: 'Sessions',
    } as never),
  );
  await wait(200);

  const strip = host.querySelector('[role="tablist"][aria-label="Sessions"]') as HTMLElement;
  const tabs = Array.from(strip.querySelectorAll<HTMLElement>('[role="tab"]'));
  const stripBox = strip.getBoundingClientRect();

  check(
    'a very long tab name does not widen its tab past the strip’s limit',
    tabs[0].getBoundingClientRect().width <= 209,
    `${Math.round(tabs[0].getBoundingClientRect().width)}px`,
  );
  check(
    'the tabs beside it are still on screen',
    tabs.length === 3 && tabs[2].getBoundingClientRect().right <= stripBox.right + 1,
    `${tabs.length} tabs, last right=${Math.round(tabs[2]?.getBoundingClientRect().right ?? -1)} strip right=${Math.round(stripBox.right)}`,
  );
  check(
    'the strip is still one row tall',
    host.getBoundingClientRect().height <= 37,
    `${Math.round(host.getBoundingClientRect().height)}px`,
  );

  root.unmount();
  host.remove();

  // And the same name in the phone's tab switcher, where the row is the whole
  // width of the screen and there is nowhere for an overflow to hide.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const sheetRoot = createRoot(doc.body);
  sheetRoot.render(
    React.createElement(
      PhoneContext.Provider,
      { value: true },
      React.createElement(TabSwitcherSheet, {
        open: true,
        tabs: [
          { id: 't1', title: LONG, kind: 'chat' },
          { id: 't2', title: 'short', kind: 'terminal' },
        ],
        activeId: 't1',
        onSelect: () => {}, onCloseTab: () => {}, onNew: () => {},
        onAllSessions: () => {}, onClose: () => {},
      } as never),
    ),
  );
  await wait(300);
  settle(doc);

  const spilling = Array.from(doc.body.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node) || scrollsSideways(node)) return false;
    const box = node.getBoundingClientRect();
    return box.right > 391 || box.left < -1;
  });
  check(
    'a very long tab name does not push the phone tab switcher off the side',
    spilling.length === 0,
    spilling.length ? spilling.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  sheetRoot.unmount();
  frame.remove();
}

/**
 * A hidden scrollbar still needs two discoverable ways to reach what it hides:
 * the wheel already under the pointer, and an explicit list for precise jumps.
 * This needs a layout engine because the button is intentionally conditional on
 * measured overflow rather than on an arbitrary tab count.
 */
async function checkAnOverflowingTabStripCanBeNavigated(): Promise<void> {
  const tabs = [
    { id: 'one', title: 'gateway', status: 'running' },
    { id: 'two', title: 'deploy', status: 'idle', attention: 'approval' },
    { id: 'three', title: 'documentation', status: 'idle', unread: true },
    { id: 'four', title: 'tests', status: 'idle' },
    { id: 'five', title: 'release', status: 'idle' },
    { id: 'six', title: 'metrics', status: 'idle' },
    { id: 'seven', title: 'cleanup', status: 'idle' },
  ];
  const host = document.createElement('div');
  host.style.cssText = 'width:1200px;position:absolute;top:0;left:0';
  document.body.appendChild(host);

  const root = createRoot(host);
  let selected = '';
  const render = (shown: typeof tabs): void => root.render(
    React.createElement(TabBar, {
      tabs: shown,
      activeId: 'one',
      onSelect: (id: string) => { selected = id; },
      ariaLabel: 'Overflow sessions',
    } as never),
  );

  render(tabs);
  await wait(150);
  check(
    'the all-tabs control stays out of a tab strip that fits',
    !host.querySelector('[aria-label="All open tabs"]'),
    'wide strip',
  );

  host.style.width = '420px';
  // Headless Chrome's virtual-time mode does not deliver ResizeObserver
  // notifications for this synthetic host resize. A real viewport resize also
  // emits this event, and the component keeps it as a fallback to the observer.
  window.dispatchEvent(new Event('resize'));
  await wait(150);
  const strip = host.querySelector('[role="tablist"][aria-label="Overflow sessions"]') as HTMLElement;
  const trigger = host.querySelector('[aria-label="All open tabs"]') as HTMLButtonElement | null;
  check(
    'an overflowing tab strip offers a list of every open tab',
    Boolean(trigger),
    trigger ? 'control shown' : `content ${strip?.scrollWidth}px in ${strip?.clientWidth}px`,
  );

  const stripStyles = window.getComputedStyle(strip);
  // Chromium canonicalises `pan-x pan-y pinch-zoom` to its equivalent keyword,
  // `manipulation`; other engines may preserve the three explicit tokens.
  const allowsPanAndZoom = (touchAction: string): boolean => {
    const values = touchAction.split(/\s+/);
    return touchAction === 'manipulation'
      || (values.includes('pan-x') && values.includes('pan-y') && values.includes('pinch-zoom'));
  };
  const bodyTouchAction = window.getComputedStyle(document.body).touchAction;
  check(
    'an overflowing tab strip accepts native horizontal touch swipes',
    stripStyles.overflowX === 'auto'
      && allowsPanAndZoom(stripStyles.touchAction)
      && allowsPanAndZoom(bodyTouchAction)
      && stripStyles.overscrollBehaviorX === 'contain',
    `overflow=${stripStyles.overflowX} touch=${stripStyles.touchAction} body-touch=${bodyTouchAction} overscroll=${stripStyles.overscrollBehaviorX}`,
  );

  // A component can advertise native panning correctly and still have an
  // ancestor cancel the gesture. The app-wide pull-to-refresh guard used to do
  // exactly that whenever a mostly-horizontal finger drifted slightly down.
  const touchEventAt = (
    type: 'touchstart' | 'touchmove',
    ...points: Array<[number, number]>
  ): TouchEvent => {
    const event = new Event(type, { bubbles: true, cancelable: true }) as TouchEvent;
    Object.defineProperty(event, 'touches', {
      value: points.map(([clientX, clientY], identifier) => ({ clientX, clientY, identifier })),
    });
    return event;
  };
  const removePullGuard = disablePullToRefresh();
  strip.dispatchEvent(touchEventAt('touchstart', [300, 30]));
  const jitter = touchEventAt('touchmove', [299, 32]);
  strip.dispatchEvent(jitter);
  const swipe = touchEventAt('touchmove', [180, 34]);
  strip.dispatchEvent(swipe);
  check(
    'the pull-to-refresh guard leaves a horizontal tab swipe native after finger jitter',
    !jitter.defaultPrevented && !swipe.defaultPrevented,
    `jitter=${jitter.defaultPrevented} swipe=${swipe.defaultPrevented}`,
  );

  strip.dispatchEvent(touchEventAt('touchstart', [260, 40], [160, 40]));
  const pinch = touchEventAt('touchmove', [280, 48], [140, 32]);
  strip.dispatchEvent(pinch);
  check(
    'the pull-to-refresh guard leaves pinch zoom native over the tab strip',
    !pinch.defaultPrevented,
    `prevented=${pinch.defaultPrevented}`,
  );

  strip.dispatchEvent(touchEventAt('touchstart', [200, 30]));
  strip.dispatchEvent(touchEventAt('touchmove', [201, 33]));
  const downwardPull = touchEventAt('touchmove', [202, 52]);
  strip.dispatchEvent(downwardPull);
  check(
    'the gesture guard still blocks a deliberate downward pull at the page top',
    downwardPull.defaultPrevented,
    `prevented=${downwardPull.defaultPrevented}`,
  );
  removePullGuard();

  const textEntry = document.createElement('textarea');
  document.body.appendChild(textEntry);
  textEntry.focus();
  const layoutHeight = window.innerHeight;
  const pinchInset = visualViewportKeyboardInset(
    { height: layoutHeight / 2, scale: 2 },
    layoutHeight,
    textEntry,
  );
  const keyboardInset = visualViewportKeyboardInset(
    { height: layoutHeight - 300, scale: 1 },
    layoutHeight,
    textEntry,
  );
  check(
    'pinch zoom is not mistaken for a software keyboard by mobile chrome or chat',
    pinchInset === 0 && keyboardInset === 300,
    `pinch=${pinchInset}px keyboard=${keyboardInset}px`,
  );
  textEntry.remove();

  strip.scrollLeft = 0;
  const vertical = new WheelEvent('wheel', { deltaY: 120, cancelable: true, bubbles: true });
  strip.dispatchEvent(vertical);
  check(
    'a vertical mouse wheel moves an overflowing tab strip sideways',
    strip.scrollLeft > 0 && vertical.defaultPrevented,
    `left=${strip.scrollLeft} prevented=${vertical.defaultPrevented}`,
  );

  const horizontal = new WheelEvent('wheel', {
    deltaX: 40,
    deltaY: 2,
    cancelable: true,
    bubbles: true,
  });
  strip.dispatchEvent(horizontal);
  check(
    'horizontal trackpad input keeps its native scrolling path',
    !horizontal.defaultPrevented,
    `prevented=${horizontal.defaultPrevented}`,
  );

  trigger?.click();
  await wait(80);
  const menu = host.querySelector('[role="menu"][aria-label="Open tabs"]') as HTMLElement | null;
  const rows = Array.from(menu?.querySelectorAll<HTMLButtonElement>('[role="menuitemradio"]') || []);
  check(
    'the overflow chooser lists every open tab in strip order',
    rows.length === tabs.length && rows.map((row) => row.textContent?.trim()).join('|').includes('gateway|deploy'),
    `${rows.length} rows`,
  );
  check(
    'the overflow chooser carries waiting and completed cues',
    Boolean(menu?.querySelector('[aria-label="Waiting for approval"]'))
      && Boolean(menu?.querySelector('[aria-label="Completed"]')),
    menu?.textContent || 'no menu',
  );

  rows[4]?.click();
  await wait(40);
  check(
    'choosing from the all-tabs list selects that tab and closes the list',
    selected === 'five' && !host.querySelector('[role="menu"][aria-label="Open tabs"]'),
    `selected=${selected}`,
  );

  (host.querySelector('[aria-label="All open tabs"]') as HTMLButtonElement | null)?.click();
  await wait(80);
  const reopenedTrigger = host.querySelector('[aria-label="All open tabs"]') as HTMLButtonElement | null;
  const activeRow = host.querySelector('[role="menuitemradio"][aria-checked="true"]');
  check(
    'the all-tabs menu puts keyboard focus on the current tab',
    document.activeElement === activeRow,
    document.activeElement ? describe(document.activeElement) : 'no focus',
  );
  window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true, cancelable: true }));
  await wait(40);
  check(
    'Escape closes the all-tabs menu and returns focus to its button',
    !host.querySelector('[role="menu"][aria-label="Open tabs"]') && document.activeElement === reopenedTrigger,
    document.activeElement ? describe(document.activeElement) : 'no focus',
  );

  reopenedTrigger?.click();
  await wait(40);
  document.body.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  await wait(40);
  check(
    'a click outside closes the all-tabs menu',
    !host.querySelector('[role="menu"][aria-label="Open tabs"]'),
    'outside click',
  );

  render(tabs.slice(0, 2));
  await wait(150);
  check(
    'the all-tabs control disappears as soon as the remaining tabs fit',
    !host.querySelector('[aria-label="All open tabs"]'),
    'two tabs remain',
  );

  root.unmount();
  host.remove();
}

/** The floating menu with its own button already pressed. */
function OpenFloatingMenu({ actions }: { actions: FloatingMenuAction[] }): React.ReactElement {
  const ref = React.useRef<HTMLDivElement | null>(null);
  React.useEffect(() => {
    (ref.current?.querySelector('[aria-label="Open the menu"]') as HTMLElement | null)?.click();
  }, []);
  return React.createElement(
    'div',
    { ref, style: { position: 'relative', width: '100%', height: '100%' } },
    React.createElement(FloatingMenu, { actions } as never),
  );
}

/**
 * The one acceptance criterion of issue #56 that only a browser can answer.
 *
 * "An agent that reports no usage or no cost is shown as not reported and never
 * as zero" is a claim about pixels, not about types: every layer underneath
 * keeps the null intact, and it would take exactly one `?? 0` or one
 * `.toFixed(2)` in a cell to turn the whole distinction into a confident
 * $0.00 that nobody would ever question. So this renders the real dialog
 * against a real response and reads what came out.
 */
async function checkAnUnreportedFigureIsNeverDrawnAsZero(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });

  // codex reports tokens and never reports cost; claude reports both. A
  // dashboard that renders these two the same way is the bug.
  const dashboard = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    bucket: 'hour', filters: {},
    totals: totals({ turns: 4, modelTurns: 9, toolCalls: 12, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 4, costReportedTurns: 2 }),
    // Two buckets, not one: the second reported nothing at all, and half of
    // what these checks are for is that it does not come out looking like an
    // hour that cost zero.
    series: [
      { key: '2026-07-27T09:00', totals: totals({ turns: 4, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 4, costReportedTurns: 2 }) },
      { key: '2026-07-27T10:00', totals: totals({ turns: 2, totalTokens: 900, tokensReportedTurns: 2, costReportedTurns: 0 }) },
    ],
    byProject: [
      { key: 'billing-api', totals: totals({ turns: 3, totalTokens: 4000, costUsd: 1.25, tokensReportedTurns: 3, costReportedTurns: 2 }) },
      // The sentinel the server sends for work recorded before projects
      // existed. Spelled out here rather than imported, because the point of
      // the check is that the browser renders whatever the wire actually says —
      // which is exactly how a mismatch between this literal and the constant
      // caught the sentinel being an unprintable control character.
      { key: '//unattributed', totals: totals({ turns: 1, totalTokens: 1000, tokensReportedTurns: 1, costReportedTurns: 0 }) },
    ],
    byAgent: [
      { key: 'claude', totals: totals({ turns: 2, totalTokens: 3000, costUsd: 1.25, tokensReportedTurns: 2, costReportedTurns: 2 }) },
      { key: 'codex', totals: totals({ turns: 2, totalTokens: 2000, tokensReportedTurns: 2, costReportedTurns: 0 }) },
    ],
    // A job whose runtime never named a model groups under the empty key —
    // the breakdown must label that, not leave the cell blank.
    byModel: [
      { key: 'claude-opus-5', totals: totals({ turns: 2, totalTokens: 3000, costUsd: 1.25, tokensReportedTurns: 2, costReportedTurns: 2 }) },
      { key: '', totals: totals({ turns: 2, totalTokens: 2000, tokensReportedTurns: 2, costReportedTurns: 0 }) },
    ],
    effortByAgent: [], effortByModel: [], topTools: [], topToolsByAgent: [],
  };

  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    const body = url.includes('/api/usage/dashboard') ? dashboard : { jobs: [], total: 0 };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:800px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  const text = (doc.body.textContent || '').replace(/\s+/g, ' ');

  check(
    'the usage dashboard renders its figures at all',
    text.includes('1.25') && /5[.,]0k|5,?000/.test(text),
    text.slice(0, 200) || 'nothing rendered',
  );

  check(
    'a cost no agent reported is not drawn as zero',
    !/\$0\.00/.test(text),
    /\$0\.00/.test(text) ? `found $0.00 in: ${text.slice(0, 300)}` : 'no confident zero on screen',
  );

  check(
    'a cost no agent reported says so in words',
    /not reported|cannot report|n\/a/i.test(text),
    text.includes('not reported') ? 'says not reported' : text.slice(0, 300),
  );

  check(
    'a bucket label on the trend line is a date, not Invalid Date',
    !/Invalid Date/.test(text),
    /Invalid Date/.test(text) ? text.slice(0, 300) : 'every label parsed',
  );

  // A dollar figure on a subscription plan is a list price, not a bill, and
  // nothing in the data says which plan an account is on — so the caveat has
  // to be on screen, not on hover, where a tooltip check would pass while a
  // viewer read the totals as money they had spent.
  check(
    'the dashboard says on screen that cost is a list price, not a bill',
    /subscription/i.test(text) && /would have cost|not as what you were charged/i.test(text),
    /subscription/i.test(text) ? 'caveat is visible' : text.slice(0, 400),
  );

  const blankLabels = Array.from(doc.querySelectorAll('tbody tr')).filter(
    (row) => !(row.querySelector('td')?.textContent || '').trim(),
  );
  check(
    'a breakdown row for an unnamed model is labelled, not blank',
    blankLabels.length === 0,
    blankLabels.length === 0
      ? 'every breakdown row has a label'
      : `${blankLabels.length} row(s) with an empty first cell`,
  );

  check(
    'a partly-reported total says how much of it was measured',
    /2 of 4|of 4 jobs/i.test(text),
    /2 of 4/.test(text) ? 'qualified' : text.slice(0, 300),
  );

  const spilling = Array.from(doc.body.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node) || scrollsSideways(node)) return false;
    const box = node.getBoundingClientRect();
    return box.right > 1101 || box.left < -1;
  });
  check(
    'the usage dashboard stays inside the window',
    spilling.length === 0,
    spilling.length ? spilling.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * Issue #66's acceptance criteria, which are all claims about pixels and
 * events rather than about types.
 *
 * "The charts are interactive" survives a typecheck no matter how it is built:
 * an SVG `<title>` compiles, renders, and is unreachable by a finger, by the
 * keyboard and by a screen reader. So this drives the real dialog against a
 * real response and checks the things a viewer actually does — focus a bar,
 * press it, press a breakdown row — and, crucially, checks what went back to
 * the *server* as a result. A selection that highlights a bar without
 * re-asking the question is a chart that only looks interactive.
 */
async function checkTheUsageChartsAreInteractive(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });

  const dashboard = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    bucket: 'hour', filters: {},
    totals: totals({ turns: 6, modelTurns: 11, toolCalls: 14, totalTokens: 5900, costUsd: 1.25, tokensReportedTurns: 6, costReportedTurns: 2 }),
    series: [
      { key: '2026-07-27T09:00', totals: totals({ turns: 4, modelTurns: 8, toolCalls: 10, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 4, costReportedTurns: 2 }) },
      // Reported nothing on cost. Must not be drawn as a bar of height zero.
      { key: '2026-07-27T10:00', totals: totals({ turns: 2, modelTurns: 3, toolCalls: 4, totalTokens: 900, tokensReportedTurns: 2, costReportedTurns: 0 }) },
    ],
    byProject: [
      { key: 'billing-api', totals: totals({ turns: 3, totalTokens: 4000, costUsd: 1.25, tokensReportedTurns: 3, costReportedTurns: 2 }) },
      { key: 'web', totals: totals({ turns: 3, totalTokens: 1900, tokensReportedTurns: 3, costReportedTurns: 0 }) },
    ],
    byAgent: [
      { key: 'claude', totals: totals({ turns: 4, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 4, costReportedTurns: 2 }) },
      { key: 'codex', totals: totals({ turns: 2, totalTokens: 900, tokensReportedTurns: 2, costReportedTurns: 0 }) },
    ],
    byModel: [{ key: 'claude-opus-5', totals: totals({ turns: 6, totalTokens: 5900, costUsd: 1.25, tokensReportedTurns: 6, costReportedTurns: 2 }) }],
    // Real distributions, because an empty one renders no histogram at all —
    // which is how the effort panel went on being unreachable by keyboard
    // through every check written to prove the charts were not (#66).
    effortByAgent: [{
      key: 'claude',
      turns: 6,
      modelTurnsReportedTurns: 6,
      modelTurnsAvg: 2.8,
      modelTurnsMax: 9,
      toolCallsAvg: 2.3,
      toolCallsMax: 7,
      modelTurnsHistogram: [2, 2, 1, 1, 0],
      toolCallsHistogram: [1, 2, 2, 1, 0],
    }],
    effortByModel: [], topTools: [], topToolsByAgent: [],
  };

  const asked: string[] = [];
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    asked.push(url);
    const body = url.includes('/api/usage/dashboard') ? dashboard : { jobs: [], total: 0 };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  // The trend's own group, named. Every chart on this dashboard is a group of
  // buttons now, so an unqualified `[role="group"] button` collects the effort
  // histograms' buckets and the period arrows along with the trend's bars.
  const bars = (): HTMLButtonElement[] =>
    Array.from(doc.querySelectorAll<HTMLButtonElement>('[role="group"][aria-label$="over time"] button'));

  check(
    'every point on the trend is a real control, not a decoration',
    bars().length === 2 && bars().every((b) => b.tagName === 'BUTTON'),
    `${bars().length} control(s) on the trend`,
  );

  check(
    'a point announces its own figures to a screen reader',
    bars().some((b) => /1\.25/.test(b.getAttribute('aria-label') || '')),
    bars().map((b) => b.getAttribute('aria-label')).join(' | ').slice(0, 200),
  );

  // No pointer, no hover: just reaching the control, the way a keyboard tab
  // stop or a tap on a touch screen does.
  bars()[1].focus();
  await wait(120);
  // Scoped to the trend's own subtree. Unqualified, this took the first polite
  // region in the dialog, which is now the window control's name — so a check
  // about the trend's readout was reading a date and reporting on a chart it
  // had never looked at.
  const trendRow = doc.querySelector('[role="group"][aria-label$="over time"]');
  const live = (trendRow?.parentElement ?? doc).querySelector(
    '[aria-live="polite"]',
  ) as HTMLElement | null;
  check(
    'reaching a point reveals its figures without a mouse',
    Boolean(live && /not reported/i.test(live.textContent || '')),
    live ? (live.textContent || '').slice(0, 160) : 'no readout region',
  );

  // The two facts this dashboard exists to keep apart, one pixel from each
  // other on a chart: an hour that reported no cost, and an hour that cost
  // nothing. If both bars paint the same, the chart is lying about one.
  const fills = bars().map((b) => {
    const span = b.querySelector('span') as HTMLElement;
    const style = (frame.contentWindow as Window).getComputedStyle(span);
    return `${style.backgroundColor}/${style.borderTopStyle}`;
  });
  check(
    'a bucket nothing reported is drawn differently from one that cost zero',
    fills[0] !== fills[1],
    fills.join(' vs '),
  );

  const measureTab = Array.from(doc.querySelectorAll<HTMLElement>('button, [role="tab"]')).find(
    (el) => (el.textContent || '').trim() === 'Tokens',
  );
  check('the trend offers a measure other than cost', Boolean(measureTab), measureTab ? 'found' : 'no Tokens control');
  measureTab?.click();
  await wait(200);
  check(
    'switching the measure redraws the chart against it',
    bars().some((b) => /Tokens/i.test(b.getAttribute('aria-label') || '')),
    bars().map((b) => b.getAttribute('aria-label')).join(' | ').slice(0, 200),
  );

  // Selecting a breakdown row must reach the server, not merely tint a row.
  const before = asked.length;
  const projectButton = Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
    (b) => (b.textContent || '').trim() === 'billing-api',
  );
  check('a breakdown row can be selected', Boolean(projectButton), projectButton ? 'found' : 'no billing-api row');
  projectButton?.click();
  await wait(400);
  const sinceRow = asked.slice(before);
  check(
    'selecting a project re-asks the whole dashboard for that project',
    sinceRow.some((u) => u.includes('/api/usage/dashboard') && u.includes('project=billing-api')),
    sinceRow.join(' | ').slice(0, 300) || 'nothing was re-requested',
  );
  check(
    // The list underneath is the conversations one (#88); the claim is
    // unchanged — a narrowing reaches it, rather than leaving it answering a
    // different question from the charts above.
    'and narrows the list underneath it by the same thing',
    sinceRow.some((u) => u.includes('/api/usage/conversations') && u.includes('project=billing-api')),
    sinceRow.filter((u) => u.includes('/conversations')).join(' | ').slice(0, 300)
      || 'the conversation list was not re-requested',
  );

  const chipText = (doc.querySelector('[aria-label="Active filters"]') as HTMLElement | null)?.textContent || '';
  check(
    'the narrowing says on screen what it is',
    /billing-api/.test(chipText),
    chipText.slice(0, 160) || 'no filter chips',
  );

  // Pressing a bar narrows to that hour — the drill-down from the chart.
  const beforeBar = asked.length;
  bars()[0].click();
  await wait(400);
  const sinceBar = asked.slice(beforeBar);
  check(
    'selecting a point on the trend narrows the range to it',
    sinceBar.some((u) => u.includes('/api/usage/dashboard') && u.includes('from=') && u.includes('to=')),
    sinceBar.join(' | ').slice(0, 300) || 'nothing was re-requested',
  );

  // And it must be undoable in one action, from the chip rather than by
  // finding precisely the same bar again.
  const beforeClear = asked.length;
  const clearAll = Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
    (b) => (b.textContent || '').trim() === 'Clear all',
  );
  check('there is one control that clears everything', Boolean(clearAll), clearAll ? 'found' : 'no Clear all');
  clearAll?.click();
  await wait(400);
  check(
    'clearing puts the unnarrowed question back',
    asked.slice(beforeClear).some((u) => u.includes('/api/usage/dashboard') && !u.includes('project=')),
    asked.slice(beforeClear).join(' | ').slice(0, 300) || 'nothing was re-requested',
  );

  const sortButton = Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
    // "Jobs" until #86, when the unit got the name it always was: a turn.
    (b) => (b.getAttribute('aria-label') || '') === 'Sort by Turns',
  );
  check('a breakdown can be re-sorted by another measure', Boolean(sortButton), sortButton ? 'found' : 'no sort control');

  // Phone width: the whole point of dropping the fixed-width SVG.
  frame.style.width = '390px';
  await wait(300);
  const spilling = Array.from(doc.body.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node) || scrollsSideways(node)) return false;
    const box = node.getBoundingClientRect();
    return box.right > 391 || box.left < -1;
  });
  check(
    'the charts stay inside a phone-width window',
    spilling.length === 0,
    spilling.length ? spilling.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * The page served out of `dist/public` by a server process that started before
 * the build that produced it.
 *
 * A real crash, and an easy one to hit: rebuilding refreshes the bundle a
 * running server hands out without refreshing the routes it answers with, so
 * the browser gets a response one version behind the code reading it. The
 * breakdown it expects is simply absent, and spreading `undefined` took the
 * whole dialog down — including any chance of saying why. Guarding the table
 * alone would have been worse: an absent breakdown would then draw as a
 * project list with nothing in it, which is a different and more believable
 * lie.
 */
/**
 * The history reads as conversations, and one of them opens onto its requests.
 *
 * The claim #88 makes is about what is on screen, and a typecheck cannot see
 * any of it: a dashboard that asked for conversations and then drew the flat
 * job list compiles perfectly. So this renders the real dialog against real
 * responses and asks four things a person would ask — is the list the tabs
 * rather than the requests, does an entry carry enough to recognise it, does a
 * conversation that used two agents say so instead of naming one, and is the
 * detail still reachable underneath.
 */
async function checkTheHistoryListsConversationsRatherThanRequests(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });

  const dashboard = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    bucket: 'hour', filters: {},
    totals: totals({ turns: 41, totalTokens: 90_000, costUsd: 7.5, tokensReportedTurns: 41, costReportedTurns: 41 }),
    series: [], byProject: [], byAgent: [], byModel: [],
    effortByAgent: [], effortByModel: [], topTools: [], topToolsByAgent: [],
  };

  // Two tabs, forty-one requests between them. The first is the case the issue
  // is about: a morning's work in one tab, which used to be forty rows.
  const conversations = {
    total: 2,
    conversations: [
      {
        sessionId: 'tab-morning',
        name: 'Refactoring the parser',
        agents: ['claude', 'codex'],
        models: ['claude-opus-5', 'gpt-5'],
        projects: ['billing-api'],
        startedAt: '2026-07-27T09:00:00.000Z',
        lastActiveAt: '2026-07-27T12:30:00.000Z',
        totals: totals({ turns: 40, totalTokens: 88_000, costUsd: 7.25, tokensReportedTurns: 40, costReportedTurns: 40 }),
      },
      {
        // No name: this tab has been closed, and the entry survives it.
        sessionId: 'aa11bb22-cc33-dd44',
        name: null,
        agents: ['claude'],
        models: [],
        projects: [],
        startedAt: '2026-07-27T08:00:00.000Z',
        lastActiveAt: '2026-07-27T08:05:00.000Z',
        totals: totals({ turns: 1, totalTokens: 2000, costUsd: 0.25, tokensReportedTurns: 1, costReportedTurns: 1 }),
      },
    ],
  };

  const job = (id: string, turnId: string) => ({
    id, sessionId: 'tab-morning', nativeSessionId: null, turnId,
    userId: 1, userLogin: 'octocat', agent: 'claude', model: 'claude-opus-5',
    project: 'billing-api', projectSource: 'observed',
    startedAt: '2026-07-27T09:00:00.000Z', endedAt: '2026-07-27T09:01:00.000Z',
    durationMs: 60_000, outcome: 'completed', modelTurns: 2, toolCalls: 3,
    inputTokens: 100, outputTokens: 50, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 150, costUsd: 0.2,
    reportsUsage: true, reportsCost: true,
  });

  const asked: string[] = [];
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    asked.push(url);
    const body = url.includes('/api/usage/dashboard')
      ? dashboard
      : url.includes('/api/usage/conversations')
        ? conversations
        : url.includes('/api/usage/jobs')
          ? { total: 2, jobs: [job('tab-morning:t1', 't1'), job('tab-morning:t2', 't2')] }
          : { agents: [], models: [], projects: [] };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="../../dist/public/css/relay/relay.css">'
    + '<link rel="stylesheet" href="../../dist/public/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(700);

  const text = (): string => (doc.body.textContent || '').replace(/\s+/g, ' ');

  check(
    'the history asks the server for conversations, not for every request',
    asked.some((url) => url.includes('/api/usage/conversations')),
    asked.join(' | ').slice(0, 300) || 'nothing was requested',
  );

  check(
    // Otherwise the headline covers a day and the list covers all time, and
    // the entries visibly fail to add up to the figure above them.
    'over the same range the figures above it were computed for',
    asked.some(
      (url) =>
        url.includes('/api/usage/conversations')
        && url.includes(`from=${encodeURIComponent(dashboard.from)}`)
        && url.includes(`to=${encodeURIComponent(dashboard.to)}`),
    ),
    asked.filter((u) => u.includes('/conversations')).join(' | ').slice(0, 300),
  );

  // Read the row, not the page: every figure on this screen is a run of digits
  // next to another one, and a regexp over the whole document would find "40"
  // inside the headline totals whether or not the row rendered at all.
  const entryRow = (): HTMLElement | undefined =>
    (Array.from(doc.querySelectorAll('tbody tr')) as HTMLElement[]).find((row) =>
      (row.textContent || '').includes('Refactoring the parser'),
    );
  const cells = (row: HTMLElement | undefined): string[] =>
    Array.from(row?.querySelectorAll('td') ?? []).map((cell) => (cell.textContent || '').trim());

  check(
    'a tab used forty times is one entry carrying all forty',
    cells(entryRow()).includes('40'),
    cells(entryRow()).join(' | ') || 'the conversation row did not render',
  );

  check(
    'and the entry says enough to recognise it — project, agent, when it ran',
    /billing-api/.test(text()) && /claude/.test(text()) && /2026|27\/0?7|0?7\/27/.test(text()),
    text().slice(0, 400),
  );

  check(
    'a conversation that used two agents is not shown as having used one',
    /claude\s*\+1/.test(text()),
    text().slice(0, 400),
  );

  check(
    'a conversation whose tab is gone still appears, named by what is left',
    /Conversation aa11bb22/.test(text()),
    text().slice(0, 400),
  );

  // The detail below the entry: open the first conversation and the requests
  // inside it must be what is asked for, narrowed to that conversation.
  const entry = entryRow();
  check('the conversation entry is a row that can be opened', Boolean(entry), 'no such row');
  entry?.click();
  await wait(400);

  check(
    'opening it asks for that conversation\'s own requests',
    asked.some((url) => url.includes('/api/usage/jobs') && url.includes('sessionId=tab-morning')),
    asked.filter((u) => u.includes('/jobs')).join(' | ').slice(0, 300) || 'no job request was made',
  );

  const backButton = Array.from(doc.querySelectorAll('button')).find(
    (b) => /all conversations/i.test(b.textContent || ''),
  );
  check(
    'and there is a way back to the list',
    Boolean(backButton),
    Array.from(doc.querySelectorAll('button')).map((b) => b.textContent).join(' | ').slice(0, 200),
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

async function checkAServerOlderThanThePageSaysSo(): Promise<void> {
  const totals = {
    turns: 1, modelTurns: 1, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 100, costUsd: 0.5,
    tokensReportedTurns: 1, costReportedTurns: 1,
  };
  // Exactly what 5.3.0 answered with: no `byProject`, no `bucket`, no `filters`.
  const oldShape = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    totals,
    series: [{ key: '2026-07-27T09:00', totals }],
    byAgent: [{ key: 'claude', totals }],
    byModel: [{ key: 'claude-opus-5', totals }],
    effortByAgent: [], effortByModel: [], topTools: [], topToolsByAgent: [],
  };

  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    const body = url.includes('/api/usage/dashboard') ? oldShape : { jobs: [], total: 0 };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  let crashed: string | null = null;
  (frame.contentWindow as Window).addEventListener('error', (event) => {
    crashed = String((event as ErrorEvent).message || 'error');
  });

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  const text = (doc.body.textContent || '').replace(/\s+/g, ' ');
  check(
    'a response from an older server does not take the dialog down',
    crashed === null && text.length > 0,
    crashed ?? (text ? 'still rendering' : 'nothing on screen'),
  );
  check(
    'and says the server is behind the page, rather than showing empty figures',
    /older than this page/i.test(text) && /restart the server/i.test(text),
    text.slice(0, 240) || 'nothing on screen',
  );
  check(
    'and does not draw the missing breakdown as a project list with nothing in it',
    !/Nothing here yet/.test(text),
    text.slice(0, 240),
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * Attributing work to a project by hand, from the job it belongs to.
 *
 * The claim is not "a form exists" — it is that pressing Save sends the right
 * assertion for the right job, and that the interface never offers to edit a
 * project that was actually observed. Both are invisible to a typecheck: an
 * edit control rendered for an observed job compiles perfectly and produces a
 * button whose only possible outcome is the server refusing it.
 */
async function checkUnattributedWorkCanBeAttributedByHand(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });
  const one = totals({ turns: 1, totalTokens: 100, costUsd: 0.5, tokensReportedTurns: 1, costReportedTurns: 1 });

  const dashboard = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    bucket: 'hour', filters: {},
    totals: one,
    series: [{ key: '2026-07-27T09:00', totals: one }],
    byProject: [
      { key: 'billing-api', totals: one },
      { key: '//unattributed', totals: one },
    ],
    byAgent: [{ key: 'claude', totals: one }],
    byModel: [{ key: 'claude-opus-5', totals: one }],
    effortByAgent: [], effortByModel: [], topTools: [], topToolsByAgent: [],
  };

  const jobFields = {
    sessionId: 'sess-1', nativeSessionId: null, turnId: 't1', userId: 7, userLogin: 'dnviti',
    agent: 'claude', model: 'claude-opus-5',
    startedAt: '2026-07-27T09:14:02.000Z', endedAt: '2026-07-27T09:14:41.000Z',
    durationMs: 39000, outcome: 'completed', modelTurns: 3, toolCalls: 5,
    inputTokens: 10, outputTokens: 10, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: null, totalTokens: 100, costUsd: 0.5,
    reportsUsage: true, reportsCost: true,
  };
  const unattributed = { ...jobFields, id: 'sess-1:t1', project: null, projectSource: null };
  const observed = { ...jobFields, id: 'sess-2:t9', sessionId: 'sess-2', project: 'billing-api', projectSource: 'observed' };

  const posted: Array<{ url: string; body: unknown }> = [];
  let openId = 'sess-1:t1';
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    if ((init?.method || 'GET').toUpperCase() === 'POST') {
      posted.push({ url, body: JSON.parse(String(init?.body ?? '{}')) });
      return new Response(JSON.stringify({ updated: 2, project: 'billing-api' }), {
        status: 200, headers: { 'content-type': 'application/json' },
      });
    }
    if (url.includes('/api/usage/dashboard')) {
      return new Response(JSON.stringify(dashboard), { status: 200, headers: { 'content-type': 'application/json' } });
    }
    if (/\/api\/usage\/jobs\/[^?]/.test(url)) {
      const body = url.includes('sess-2') ? observed : unattributed;
      // The second job ran on two models, the way a delegating turn does. The
      // first carries no `models` key at all — which is also what a server
      // older than this page answers, and must not blank the dialog. (#75)
      const models = url.includes('sess-2')
        ? [
            { model: 'claude-opus-5', calls: 3, inputTokens: 800, outputTokens: 150, cacheReadTokens: null, cacheWriteTokens: null, costUsd: 0.75 },
            { model: 'claude-haiku-4-5', calls: 1, inputTokens: 200, outputTokens: 50, cacheReadTokens: null, cacheWriteTokens: null, costUsd: 0.25 },
          ]
        : undefined;
      return new Response(
        JSON.stringify({ ...body, tools: [], ...(models ? { models } : {}) }),
        { status: 200, headers: { 'content-type': 'application/json' } },
      );
    }
    return new Response(JSON.stringify({ jobs: [openId === 'sess-2:t9' ? observed : unattributed], total: 1 }), {
      status: 200, headers: { 'content-type': 'application/json' },
    });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  const text = () => (doc.body.textContent || '').replace(/\s+/g, ' ');
  const byLabel = (label: string) =>
    Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
      (b) => (b.textContent || '').trim() === label,
    );

  check(
    'the dashboard says where unattributed work can be fixed',
    /attribute it/i.test(text()),
    text().slice(0, 2000),
  );

  // The history opens on conversations now (#88), and a single job is a level
  // below that. Attribution is a per-request question, so this check takes the
  // Requests view — which is exactly the reason that view still exists.
  const requestsTab = Array.from(doc.querySelectorAll<HTMLElement>('[role="tab"], button')).find(
    (el) => (el.textContent || '').trim() === 'Requests',
  );
  check('the history offers the requests behind the conversations', Boolean(requestsTab), 'no Requests control');
  requestsTab?.click();
  await wait(400);

  // Open the unattributed job from the history — the last table on the page.
  // Not `tbody tr`, which is the first breakdown row four panels above it.
  const historyRow = (): HTMLElement | null => {
    const tables = Array.from(doc.querySelectorAll('table'));
    return (tables[tables.length - 1]?.querySelector('tbody tr') as HTMLElement | null) ?? null;
  };
  historyRow()?.click();
  await wait(400);
  check('a job opens from the history', /Job detail/i.test(text()), text().slice(0, 160));

  const attributeButton = byLabel('Attribute…');
  check(
    'an unattributed job offers to be attributed',
    Boolean(attributeButton),
    attributeButton ? 'found' : 'no attribute control',
  );
  attributeButton?.click();
  await wait(200);

  const field = doc.querySelector('input[aria-label="Project name"]') as HTMLInputElement | null;
  check('the form asks for a project name', Boolean(field), field ? 'found' : 'no input');

  const suggestions = Array.from(doc.querySelectorAll('datalist option')).map((o) => (o as HTMLOptionElement).value);
  check(
    'and suggests the projects already in use, so a name is not retyped by guess',
    suggestions.includes('billing-api') && !suggestions.some((v) => v.includes('unattributed')),
    suggestions.join(', ') || 'no suggestions',
  );

  const sessionBox = doc.querySelector('input[type="checkbox"]') as HTMLInputElement | null;
  check(
    'the whole conversation is the default, since that is the unit people fix',
    Boolean(sessionBox && sessionBox.checked),
    sessionBox ? `checked=${sessionBox.checked}` : 'no checkbox',
  );

  if (field) {
    const setter = Object.getOwnPropertyDescriptor(
      (frame.contentWindow as Window & typeof globalThis).HTMLInputElement.prototype,
      'value',
    )?.set;
    setter?.call(field, 'billing-api');
    field.dispatchEvent(new (frame.contentWindow as Window & typeof globalThis).Event('input', { bubbles: true }));
  }
  await wait(150);
  byLabel('Save')?.click();
  await wait(400);

  check(
    'saving sends the attribution for that job',
    posted.length === 1 && posted[0].url.includes('sess-1%3At1/project'),
    posted.map((p) => p.url).join(' | ') || 'nothing was sent',
  );
  check(
    'and sends the name and the whole-conversation choice with it',
    posted.length === 1
      && (posted[0].body as { project: string }).project === 'billing-api'
      && (posted[0].body as { applyToSession: boolean }).applyToSession === true,
    JSON.stringify(posted[0]?.body ?? null),
  );
  check(
    'and reports how much work it actually changed',
    /2 job\(s\) attributed/.test(text()),
    text().slice(0, 240),
  );

  // Now the other half of the claim: an observed project offers no edit at all.
  // A fresh mount rather than a re-render — re-rendering the same tree keeps
  // the open-job state, so the "second" job never actually opened and the
  // check passed by looking at the first one.
  root.unmount();
  await wait(100);
  openId = 'sess-2:t9';
  const second = createRoot(doc.body);
  second.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);
  // A fresh mount is back on the conversation list, so the requests view has to
  // be taken again — the state that was reset is exactly why this is a remount.
  Array.from(doc.querySelectorAll<HTMLElement>('[role="tab"], button'))
    .find((el) => (el.textContent || '').trim() === 'Requests')
    ?.click();
  await wait(400);
  historyRow()?.click();
  await wait(400);

  check(
    'the second job opened',
    /Job detail/i.test(text()) && /billing-api/.test(text()),
    text().slice(0, 200),
  );

  check(
    'a job that ran on two models shows both, with each one own spend (#75)',
    /claude-haiku-4-5/.test(text()) && /\$0\.7500/.test(text()) && /\$0\.2500/.test(text()),
    text().slice(0, 400),
  );

  check(
    'a project that was observed offers no way to overwrite it',
    !byLabel('Attribute…') && !byLabel('Change'),
    byLabel('Change') || byLabel('Attribute…')
      ? 'an edit control was offered for a measured value'
      : 'no edit offered',
  );

  second.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * Issue #71 — the `/` menu is complete before a word has been typed.
 *
 * A layout engine is needed for this and a props assertion is not: the claim is
 * that a person opening a brand-new conversation can *see* their skills, both
 * by typing a slash and by pressing the control that says it offers commands
 * and skills. Every part of that — that the popup renders at all with no
 * messages behind it, that it carries the descriptions, that the button opens
 * the same list — is a rendered fact.
 */
async function checkTheCommandMenuIsFullBeforeTheFirstMessage(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('browser-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false,
        commands: [
          { name: 'clear', description: 'Start a new conversation, forgetting everything above' },
          { name: 'complex-work', description: 'Orchestrate a complex, multi-phase engineering task' },
          { name: 'figma:figma-use', description: 'Write a design into Figma' },
          { name: 'undocumented-skill' },
        ],
      },
      // The whole point: nothing has been sent yet.
      messages: [],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(250);

  const menu = (): HTMLElement | null =>
    host.querySelector('[role="listbox"][aria-label="Slash commands"]');

  const textarea = host.querySelector('textarea') as HTMLTextAreaElement | null;
  check('the composer is on screen in a conversation with no messages', Boolean(textarea));
  if (!textarea) {
    root.unmount();
    host.remove();
    return;
  }

  const type = (value: string): void => {
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value')?.set;
    setter?.call(textarea, value);
    textarea.dispatchEvent(new Event('input', { bubbles: true }));
  };

  textarea.focus();
  type('/');
  await wait(200);

  const typed = menu();
  const typedText = typed?.textContent ?? '';
  check('typing a slash opens the menu before any message has been sent', Boolean(typed));
  check(
    'and it lists the skills installed for this session, not just the built-ins',
    typedText.includes('complex-work') && typedText.includes('figma:figma-use'),
    typedText.slice(0, 200) || 'nothing listed',
  );
  check(
    'each entry carries the description its author wrote',
    typedText.includes('Orchestrate a complex, multi-phase engineering task'),
    typedText.slice(0, 240),
  );
  check(
    'and an entry with no description is shown plainly, with no invented one',
    typedText.includes('undocumented-skill') && !/no description/i.test(typedText),
    typedText.slice(0, 240),
  );

  // Narrowing has to reach the skills too — a menu that filters only the
  // built-ins would look right until the first keystroke after the slash.
  type('/comp');
  await wait(200);
  const narrowedText = menu()?.textContent ?? '';
  check(
    'typing narrows to the matching skill',
    narrowedText.includes('complex-work') && !narrowedText.includes('figma:figma-use'),
    narrowedText.slice(0, 200) || 'nothing listed',
  );

  type('');
  await wait(150);
  check('clearing the line closes the menu', !menu());

  const button = host.querySelector('[aria-label="Slash commands and skills"]') as HTMLElement | null;
  check('the composer offers a control for commands and skills', Boolean(button));
  button?.click();
  await wait(200);
  const openedText = menu()?.textContent ?? '';
  check(
    'and pressing it shows the same list, with no message sent first',
    openedText.includes('complex-work') && openedText.includes('clear'),
    openedText.slice(0, 200) || 'nothing listed',
  );

  // Picking an entry has to put the command in the line, which is what makes
  // it behave exactly as typing its name does.
  const rows = Array.from(host.querySelectorAll('[role="listbox"][aria-label="Slash commands"] [role="option"]'));
  const pick = rows.find((row) => (row.textContent ?? '').includes('complex-work')) as HTMLElement | undefined;
  pick?.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  await wait(200);
  check(
    'choosing an entry puts that command in the line, ready to run',
    textarea.value.trim().startsWith('/complex-work'),
    JSON.stringify(textarea.value),
  );

  root.unmount();
  host.remove();
}

/**
 * Issue #77: the file editor, read the way a person reads it.
 *
 * Every check this app had around this editor confirmed that its *parts* were
 * built — that the host element exists, that the fallback textarea carries the
 * right label, that a read-only file arrives read-only. All of them passed
 * while the editor on screen drew files in an order they are not in, with a
 * bare textarea over the first line, because none of them ever looked at a
 * rendered editor. They could not: the checks used to run from a `file://`
 * page, where the chunk this fetches by absolute path can never arrive.
 *
 * So this one loads the real chunk over HTTP, opens a real file in it, and
 * compares what is on the screen against the file.
 */
async function checkTheFileEditorShowsTheFile(): Promise<void> {
  const lines = Array.from({ length: 200 }, (_, i) => `line-${i + 1} const value${i + 1} = ${i + 1};`);
  const text = lines.join('\n');
  const initialLine = 150;

  const host = document.createElement('div');
  // Stacked above whatever earlier checks left on the page — the terminal from
  // the first check is still mounted at the same corner, and "is anything drawn
  // over the first line" is a question about *this* editor.
  host.style.cssText = 'width:900px;height:500px;position:absolute;top:0;left:0;z-index:9999';
  document.body.appendChild(host);

  const root = createRoot(host);
  root.render(
    React.createElement(MonacoEditor, {
      value: text,
      path: '/tmp/browser-check/sample.ts',
      language: 'ts',
      ariaLabel: 'Contents of sample.ts',
      initialLine,
    } as never),
  );

  // The chunk is several megabytes and is fetched, parsed and started here, so
  // this waits for the editor rather than for a fixed delay.
  let ready = false;
  for (let i = 0; i < 120 && !ready; i++) {
    await wait(100);
    ready = host.querySelector('[data-monaco-host="ready"]') !== null;
  }
  check('the real code editor loads and attaches', ready, host.innerHTML.slice(0, 120));
  if (!ready) {
    root.unmount();
    host.remove();
    return;
  }

  /** The rendered lines, top to bottom — which is the order a reader gets. */
  const onScreen = (): { text: string; top: number }[] =>
    Array.from(host.querySelectorAll('.view-line'))
      .map((node) => ({
        text: (node.textContent ?? '').replace(/ /g, ' ').trimEnd(),
        top: node.getBoundingClientRect().top,
      }))
      .sort((a, b) => a.top - b.top);

  const rendered = onScreen();
  check('it renders the file, not an empty frame', rendered.length > 5, `${rendered.length} lines`);
  check(
    'a requested source line is revealed when Monaco opens',
    rendered.some((line) => line.text === lines[initialLine - 1]),
    rendered.slice(0, 4).map((line) => line.text.split(' ')[0]).join(','),
  );

  const activeLine = host.querySelector('.line-numbers.active-line-number') as HTMLElement | null;
  check(
    'and the cursor is placed on that source line',
    activeLine?.textContent?.trim() === String(initialLine),
    activeLine?.textContent?.trim() || 'no active line number',
  );

  // The heart of the report. Every rendered line must be the line the file has
  // at that position — so a window that is complete but shuffled fails here.
  const firstShown = lines.indexOf(rendered[0]?.text ?? '');
  const inFileOrder =
    firstShown !== -1 && rendered.every((line, i) => line.text === lines[firstShown + i]);
  check(
    'the file is shown in the file’s own order',
    inFileOrder,
    inFileOrder ? `from line ${firstShown + 1}` : rendered.slice(0, 8).map((l) => l.text.split(' ')[0]).join(','),
  );

  const numbers = Array.from(host.querySelectorAll('.line-numbers'))
    .map((node) => ({ text: (node.textContent ?? '').trim(), top: node.getBoundingClientRect().top }))
    .sort((a, b) => a.top - b.top)
    .map((entry) => entry.text);
  check(
    'the line numbers say what the lines beside them are',
    numbers.length > 0 && numbers.every((n, i) => Number(n) === firstShown + i + 1),
    numbers.slice(0, 6).join(','),
  );

  // The stylesheet, asked of the layout engine rather than of the network: this
  // one rule is what positions every line, and losing it is what produced both
  // halves of the report at once.
  const firstLine = host.querySelector('.view-line') as HTMLElement | null;
  check(
    'the editor’s own stylesheet is in effect',
    firstLine !== null && getComputedStyle(firstLine).position === 'absolute',
    firstLine ? getComputedStyle(firstLine).position : 'no line',
  );

  // The stray box: Monaco's hidden input area, drawn as an ordinary resizable
  // textarea whenever those rules are missing.
  const boxes = Array.from(host.querySelectorAll('textarea')).filter(
    (node) => getComputedStyle(node).resize !== 'none',
  );
  check('nothing in the editor is a resizable box', boxes.length === 0, `${boxes.length} found`);

  const lineBox = firstLine?.getBoundingClientRect();
  const covering = lineBox
    ? (document.elementFromPoint(lineBox.left + 4, lineBox.top + lineBox.height / 2) as HTMLElement | null)
    : null;
  check(
    'nothing is drawn over the first line',
    covering !== null && host.contains(covering) && covering.closest('.view-lines') !== null,
    covering ? `${covering.tagName}.${String(covering.className).slice(0, 40)}` : 'nothing at that point',
  );

  // Scrolled, because that is where the fault showed itself worst: Monaco
  // reuses its line elements, so with the positioning rules missing the order
  // on screen becomes the order they happen to sit in — which looks fine at
  // first paint and comes apart the moment you move.
  // Scrolled, because that is where the fault showed itself worst: Monaco
  // reuses its line elements, so with the positioning rules missing the order
  // on screen becomes the order they happen to sit in — which looks right at
  // first paint and comes apart the moment the view moves.
  //
  // What is asserted is the invariant, not the movement: this page runs on
  // virtual time with no compositor, so whether a synthetic wheel actually
  // carries the viewport anywhere is up to the engine and not worth a flaky
  // check. Whatever is on screen must be a contiguous run of the file in the
  // file's order, at rest and after the view is pushed around — which is
  // exactly what the report showed it was not.
  const scrollable = host.querySelector('.monaco-scrollable-element') as HTMLElement | null;
  const wheel = (delta: number): void => {
    scrollable?.dispatchEvent(
      new WheelEvent('wheel', { deltaY: delta, deltaMode: 0, bubbles: true, cancelable: true }),
    );
  };
  const stillInOrder = (label: string): void => {
    const shown = onScreen();
    const from = lines.indexOf(shown[0]?.text ?? '');
    check(
      label,
      from !== -1 && shown.every((line, i) => line.text === lines[from + i]),
      `from line ${from + 1}: ${shown.slice(0, 6).map((l) => l.text.split(' ')[0]).join(',')}`,
    );
  };

  for (let i = 0; i < 8; i++) wheel(240);
  await wait(600);
  stillInOrder('what is on screen after scrolling down is the file, in order');

  for (let i = 0; i < 12; i++) wheel(-240);
  await wait(600);
  stillInOrder('and after scrolling back it is still the file, in order');

  // The light theme, since the fault was reported as visible in one theme: the
  // editor is rebuilt from the live palette on a theme change, and a rendering
  // that only survives in the dark is not a fix.
  document.documentElement.classList.add('light');
  await wait(400);
  const light = onScreen();
  const lightFirst = lines.indexOf(light[0]?.text ?? '');
  check(
    'and it is still the file, in order, in the light theme',
    lightFirst !== -1 && light.every((line, i) => line.text === lines[lightFirst + i]),
    light.slice(0, 4).map((l) => l.text.split(' ')[0]).join(','),
  );
  document.documentElement.classList.remove('light');
  await wait(200);

  // The guard that keeps this from coming back silently. Removing the
  // stylesheet is exactly the state a failed fetch leaves the page in, and the
  // loader has to be able to tell — otherwise it hands over an editor that
  // renders a file in an order it is not in, which is the failure that made
  // this a bug report rather than a nuisance.
  const sheet = document.querySelector('link[href="/monaco.bundle.css"]');
  check('the editor’s stylesheet is loaded by its own loader', sheet !== null);
  if (sheet) {
    check('and while it is there, the loader says the rules are in effect', monacoStylesApplied());
    document.head.removeChild(sheet);
    await wait(100);
    check(
      'with it gone, the loader notices instead of rendering anyway',
      !monacoStylesApplied(),
      'this is what a failed stylesheet fetch leaves behind',
    );
    document.head.appendChild(sheet);
    await wait(100);
  }

  root.unmount();
  host.remove();
}

/**
 * A file opened read-only cannot be typed into — asked of the editor that is
 * actually on screen, not of the fallback.
 */
async function checkAReadOnlyFileStaysReadOnly(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:700px;height:300px;position:absolute;top:0;left:0';
  document.body.appendChild(host);

  let changes = 0;
  const root = createRoot(host);
  root.render(
    React.createElement(MonacoEditor, {
      value: 'const readOnly = true;\nconst second = 2;\n',
      path: '/tmp/browser-check/locked.ts',
      language: 'ts',
      readOnly: true,
      onChange: () => { changes += 1; },
      ariaLabel: 'Contents of locked.ts',
    } as never),
  );

  let ready = false;
  for (let i = 0; i < 120 && !ready; i++) {
    await wait(100);
    ready = host.querySelector('[data-monaco-host="ready"]') !== null;
  }
  check('the read-only file opens in the real editor too', ready);
  if (!ready) {
    root.unmount();
    host.remove();
    return;
  }

  // The host reports ready as soon as the editor is created; the first lines
  // land a frame or two later — and by this point in the suite the page is
  // frugal with frames, so the editor is nudged into laying itself out rather
  // than waited on indefinitely. `automaticLayout` watches the host's size.
  //
  // A frame is awaited as well as a timer, and that is the part that matters:
  // Monaco draws its lines from `requestAnimationFrame`, and under the headless
  // harness's virtual clock a timer can come back without one ever having run —
  // which made this check pass or fail on the timing of the suite ahead of it
  // rather than on anything about the editor.
  for (let i = 0; i < 40 && host.querySelector('.view-line') === null; i++) {
    host.style.width = `${700 + (i % 2)}px`;
    window.dispatchEvent(new Event('resize'));
    await new Promise((resolve) => requestAnimationFrame(() => resolve(null)));
    await wait(100);
  }

  const input = host.querySelector('textarea') as HTMLTextAreaElement | null;
  check('a read-only file cannot be typed into', input !== null && input.readOnly, String(input?.readOnly));
  check('and nothing reported a change', changes === 0, `${changes} changes`);

  const shown = Array.from(host.querySelectorAll('.view-line'))
    .map((node) => (node.textContent ?? '').replace(/ /g, ' ').trimEnd());
  check(
    'the read-only view shows the file as it is',
    shown[0] === 'const readOnly = true;' && shown[1] === 'const second = 2;',
    shown.length ? shown.join(' / ') : `no lines; editor=${Boolean(host.querySelector('.monaco-editor'))} html=${host.innerHTML.slice(0, 200)}`,
  );

  root.unmount();
  host.remove();
}

/**
 * An absolute source link in an agent reply stays inside the application.
 *
 * This is deliberately end-to-end through ChatView: the regression was a real
 * anchor asking Express for `/home/.../registry.ts:228`, so unit-testing the
 * parser or the editor alone cannot prove the browser navigation was stopped,
 * the line suffix was removed from the file request, and Monaco received it.
 */
async function checkAChatFileLinkOpensAtItsSourceLine(): Promise<void> {
  const workingDir = '/home/dev/projects/webcli';
  const filePath = `${workingDir}/src/server/chat/registry.ts`;
  const plainFilePath = `${workingDir}/README.md`;
  const initialLine = 150;
  const lines = Array.from({ length: 220 }, (_, i) => `registry-line-${i + 1} const entry${i + 1} = ${i + 1};`);
  const content = lines.join('\n');

  const controller = new ChatController('file-link-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'file-link-check',
    snapshot: {
      sessionId: 'file-link-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true,
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: 1,
          blocks: [{ kind: 'text', text: 'Where is the registry entry?' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: 2,
          blocks: [{
            kind: 'text',
            text: `Open [registry.ts:${initialLine}](${filePath}:${initialLine}) or [README](${plainFilePath}). Keep [the website](https://example.com) external.`,
          }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: false,
    },
  } as never);

  const requested: string[] = [];
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const raw = String(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url);
    const url = new URL(raw, window.location.href);
    if (url.pathname.includes('/api/workspace/') && url.pathname.endsWith('/file')) {
      const requestedPath = url.searchParams.get('path') || '';
      requested.push(requestedPath);
      const markdown = requestedPath === plainFilePath;
      const body = markdown ? '# Project\n\nOpened in the normal preview.' : content;
      return new Response(
        JSON.stringify({
          path: requestedPath,
          name: markdown ? 'README.md' : 'registry.ts',
          relativePath: markdown ? 'README.md' : 'src/server/chat/registry.ts',
          size: body.length,
          mtimeMs: 1,
          language: markdown ? 'markdown' : 'typescript',
          content: body,
          binary: false,
          tooLarge: false,
          writable: false,
        }),
        { status: 200, headers: { 'content-type': 'application/json' } },
      );
    }
    return realFetch.call(window, input as RequestInfo, init);
  }) as typeof window.fetch;

  const host = document.createElement('div');
  host.style.cssText = 'width:1100px;height:720px;position:absolute;top:0;left:0;display:flex;z-index:9999';
  document.body.appendChild(host);
  const root = createRoot(host);

  try {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir,
        view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
        onViewChange: () => {},
      } as never),
    );
    await wait(300);

    const link = Array.from(host.querySelectorAll('a')).find(
      (anchor) =>
        anchor.dataset.workspaceFilePath === filePath
        && anchor.dataset.workspaceFileLine === String(initialLine),
    ) as HTMLAnchorElement | undefined;
    check('an absolute source reference is rendered as a chat link', Boolean(link));
    if (!link) return;

    check(
      'workspace links advertise a dialog instead of a new browser tab',
      link.getAttribute('aria-haspopup') === 'dialog'
        && link.getAttribute('target') === null
        && link.getAttribute('href')?.startsWith('#workspace-file='),
      link.outerHTML,
    );
    const external = Array.from(host.querySelectorAll('a')).find(
      (anchor) => anchor.getAttribute('href') === 'https://example.com',
    );
    check(
      'ordinary web links retain their external-link semantics',
      external?.getAttribute('target') === '_blank'
        && external.getAttribute('aria-haspopup') === null,
      external?.outerHTML || 'no external link',
    );

    const middleClick = new MouseEvent('auxclick', {
      bubbles: true,
      cancelable: true,
      button: 1,
    });
    link.dispatchEvent(middleClick);
    check('middle-click cannot bypass workspace routing', middleClick.defaultPrevented);

    const click = new MouseEvent('click', { bubbles: true, cancelable: true, button: 0 });
    link.dispatchEvent(click);
    check('clicking the source reference stops browser navigation', click.defaultPrevented);

    let ready = false;
    for (let i = 0; i < 120 && !ready; i++) {
      await wait(100);
      ready = host.querySelector('[role="dialog"] [data-monaco-host="ready"]') !== null;
    }

    check(
      'the file request removes the source-line suffix',
      requested.length === 1 && requested[0] === filePath,
      JSON.stringify(requested),
    );
    const dialog = host.querySelector('[role="dialog"]') as HTMLElement | null;
    check(
      'the existing file popup opens the referenced file while the workspace rail is closed',
      Boolean(dialog) && (dialog?.textContent || '').includes('registry.ts'),
      dialog ? (dialog.textContent || '').slice(0, 120) : 'no dialog',
    );
    check('that popup reaches the real Monaco editor', ready);

    // Give Monaco a frame after creation to paint the model window around the
    // cursor. The host's ready marker is set synchronously with editor.create.
    await new Promise((resolve) => requestAnimationFrame(() => resolve(null)));
    await wait(200);
    const shown = Array.from(dialog?.querySelectorAll('.view-line') || [])
      .map((node) => (node.textContent || '').replace(/ /g, ' ').trimEnd());
    const active = dialog?.querySelector('.line-numbers.active-line-number') as HTMLElement | null;
    check(
      'the linked source line is visible in Monaco',
      shown.includes(lines[initialLine - 1]),
      shown.slice(0, 5).map((line) => line.split(' ')[0]).join(','),
    );
    check(
      'and Monaco puts its cursor on that exact line',
      active?.textContent?.trim() === String(initialLine),
      active?.textContent?.trim() || 'no active line',
    );

    const close = Array.from(dialog?.querySelectorAll('button') || [])
      .find((button) => button.textContent?.trim() === 'Close') as HTMLButtonElement | undefined;
    close?.click();
    await wait(150);

    const plainLink = Array.from(host.querySelectorAll('a')).find(
      (anchor) => anchor.dataset.workspaceFilePath === plainFilePath,
    ) as HTMLAnchorElement | undefined;
    plainLink?.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, button: 0 }));
    for (let i = 0; i < 30 && requested.length < 2; i++) await wait(50);
    const plainDialog = host.querySelector('[role="dialog"]') as HTMLElement | null;
    check(
      'a file link with no line opens through the same popup',
      requested[1] === plainFilePath && Boolean(plainDialog),
      JSON.stringify(requested),
    );
    check(
      'and keeps the file editor’s normal preview behaviour',
      (plainDialog?.textContent || '').includes('Opened in the normal preview.')
        && plainDialog?.querySelector('[data-monaco-host]') === null,
      (plainDialog?.textContent || '').slice(0, 120),
    );
  } finally {
    root.unmount();
    host.remove();
    window.fetch = realFetch;
  }
}

/**
 * Starting a new conversation is a control, not a piece of folklore (#69).
 *
 * The check is about the healthy case on purpose. There has always been a
 * "Start a new chat" button, but only inside the recovery notice — so the one
 * state it could not be pressed in was the ordinary one, and the only way to
 * ask while things were working was to know that `/clear` existed and type it.
 * Rendered rather than asserted on props: what matters is that it is on screen
 * over a live conversation and that pressing it sends the same command.
 */
/**
 * A conversation says which approval mode it is in, where the user is looking —
 * and says nothing at all until the user has spoken.
 *
 * Here rather than in a unit test because the whole complaint in #134 is that
 * the mode was decided invisibly. "The component was passed the right value" is
 * not the claim — the claim is that a person sitting in front of the pane can
 * read it, so this measures the rendered chip and the two recovery buttons: on
 * screen, not transparent, and set in type big enough to be read.
 *
 * It also measures where the mode may *not* be said. A rule written across the
 * transcript as the conversation opened was the only thing in a chat nobody had
 * spoken in yet: a line, a turn strip numbering a turn that never happened, and
 * no empty state, so the first question the user asked opened turn 2. The mode
 * is a standing fact and the standing indicators carry it; the transcript starts
 * empty and the first prompt starts turn 1.
 *
 * The two buttons are the heart of it. They sat side by side doing opposite
 * things about approvals with nothing on screen saying which was which, so the
 * check asserts they say different things and that each says the right one.
 */
async function checkAConversationSaysWhichApprovalModeItIsIn(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('browser-check', { send: () => {} } as never);
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false,
      },
      messages: [],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 0,
      live: true,
      bypassPermissions: true,
    },
  } as never);

  // The marker the server sends as a conversation begins, in the words
  // ChatSession emits — see approvalNoticeDetail. It carries the mode and draws
  // nothing: what it used to draw was a rule and a turn strip in a conversation
  // nobody had spoken in yet.
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: {
      t: 'marker',
      kind: 'approvals',
      seq: 1,
      ts: 1,
      detail: 'bypassed — tools run without asking',
      bypassing: true,
    },
  } as never);

  const root = createRoot(host);
  const paint = (preference: boolean): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/tmp/project',
        approvalPreference: preference,
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
  };
  paint(false);
  await wait(250);

  // Nothing in the transcript, because nothing has been said in it. Measured
  // three ways because each one is a different way the old behaviour showed
  // itself: a rule with the mode written across it, a turn strip numbering a
  // turn that had not happened, and the empty state suppressed by the single
  // message behind both of them.
  const noticed = Array.from(host.querySelectorAll<HTMLElement>('[role="separator"]')).find((node) =>
    /approvals/i.test(node.textContent || ''),
  );
  check(
    'a conversation nobody has spoken in yet draws no line about approvals',
    !noticed,
    (noticed?.textContent || '').trim(),
  );
  const strips = Array.from(host.querySelectorAll<HTMLElement>('[data-turn-id]'));
  check(
    'and no turn strip, because the first prompt has not opened a turn yet',
    strips.length === 0,
    strips.map((node) => (node.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 60)).join(' | '),
  );
  const empty = Array.from(host.querySelectorAll<HTMLElement>('p')).find((node) =>
    /Nothing here yet/.test(node.textContent || ''),
  );
  check(
    'and the empty conversation says so, which the marker used to suppress',
    Boolean(empty) && isPainted(empty as HTMLElement),
    empty ? 'painted' : 'no empty state',
  );

  const chipNamed = (label: string): HTMLElement | null =>
    host.querySelector<HTMLElement>(`[aria-label="${label}"]`);

  // Where the mode is stated instead: permanently, beside the input box and in
  // the header, rather than once at a top the reader scrolls away from.
  const chip = chipNamed('Approvals bypassed');
  check(
    'the mode is stated on the chip beside the input box',
    Boolean(chip) && !chipNamed('Approvals asked for'),
  );
  if (chip) {
    check(
      'and the chip is on screen rather than merely present',
      isPainted(chip),
      `${Math.round(chip.getBoundingClientRect().width)}x${Math.round(chip.getBoundingClientRect().height)}`,
    );
    const size = parseFloat(window.getComputedStyle(chip).fontSize) || 0;
    check('and it is set in type that can be read', size >= 10 - 0.01, `${size}px`);
  }

  // And the first thing the user says is turn 1 — which it was not while the
  // marker held a turn of its own above it.
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'msg_start', id: 'u1', seq: 6, ts: 6, turnId: 'first-turn', role: 'user' },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'block_start', msgId: 'u1', index: 0, block: { kind: 'text', text: '' } },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'block_delta', msgId: 'u1', index: 0, text: 'the first thing anyone asked' },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'msg_end', msgId: 'u1' },
  } as never);
  paint(false);
  await wait(250);

  // Off the fold button's label rather than the strip's text, which runs the
  // number straight into the clock beside it — "turn 101:00:00".
  const numbered = Array.from(host.querySelectorAll<HTMLElement>('[data-turn-id] button'))
    .map((node) => node.getAttribute('aria-label') || '')
    .filter((label) => /turn \d+$/.test(label));
  check(
    'the user’s first prompt is turn 1, and the only turn',
    numbered.length === 1 && /turn 1$/.test(numbered[0]),
    numbered.join(' | ') || 'no turn strip at all',
  );

  // And now a `/clear`, which starts the conversation over in whatever mode the
  // account's preference names — here, back to asking.
  //
  // This is the interval the whole feature turns on. A restart from inside a
  // conversation never goes through the launch path, so no `chat_started` and
  // no snapshot arrive: the opening line of the replacement conversation is the
  // only thing that reaches the browser with the new mode. Measured on the
  // persistent indicators rather than on that line, because a one-off sentence
  // scrolling up the transcript while the chip beside the input box still reads
  // "Approvals asked for" over an agent running unattended — or the reverse —
  // is exactly the standing false claim #134 exists to remove.
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'marker', kind: 'cleared', seq: 7, ts: 7, detail: 'started a new conversation' },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: {
      t: 'marker',
      kind: 'approvals',
      seq: 8,
      ts: 8,
      detail: 'on — you are asked before each tool call',
      bypassing: false,
    },
  } as never);
  paint(false);
  await wait(250);

  check(
    'a clear that changes the mode moves the chip with it',
    Boolean(chipNamed('Approvals asked for')) && !chipNamed('Approvals bypassed'),
    chipNamed('Approvals bypassed') ? 'still claiming bypassed' : 'asks first',
  );

  // Back the other way, so the chip is following the marker rather than simply
  // decaying to the safe answer once anything at all arrives.
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: { t: 'marker', kind: 'cleared', seq: 9, ts: 9, detail: 'started a new conversation' },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'browser-check',
    event: {
      t: 'marker',
      kind: 'approvals',
      seq: 10,
      ts: 10,
      detail: 'bypassed — tools run without asking',
      bypassing: true,
    },
  } as never);
  paint(false);
  await wait(250);

  check(
    'and a clear that turns the bypass back on moves it back',
    Boolean(chipNamed('Approvals bypassed')) && !chipNamed('Approvals asked for'),
    chipNamed('Approvals asked for') ? 'still claiming it asks' : 'bypassed',
  );

  // Now the conversation's process goes away, which is the recovery notice the
  // issue was reported against.
  controller.handle({
    type: 'chat_unavailable',
    sessionId: 'browser-check',
    runtime: 'claude',
    runtimeLabel: 'Claude Code',
    canResume: true,
    message: 'this chat session is not running',
  } as never);
  paint(false);
  await wait(250);

  const buttonNamed = (needle: RegExp): HTMLButtonElement | undefined =>
    Array.from(host.querySelectorAll<HTMLButtonElement>('button')).find((node) =>
      needle.test(node.textContent || ''),
    );

  const resume = buttonNamed(/Resume this conversation/);
  const fresh = buttonNamed(/Start a new chat/);
  check('both ways back are offered', Boolean(resume) && Boolean(fresh));
  if (resume && fresh) {
    check(
      'resuming says it brings the conversation back bypassing',
      /approvals bypassed/.test(resume.textContent || ''),
      (resume.textContent || '').trim(),
    );
    check(
      'starting over says it will ask, which is the other answer',
      /asks first/.test(fresh.textContent || ''),
      (fresh.textContent || '').trim(),
    );
    for (const [label, node] of [['resume', resume], ['start over', fresh]] as const) {
      check(
        `the ${label} button is on screen and pressable`,
        isPainted(node) && !node.disabled && node.tabIndex >= 0,
        `${Math.round(node.getBoundingClientRect().width)}x${Math.round(node.getBoundingClientRect().height)} disabled=${node.disabled} tabIndex=${node.tabIndex}`,
      );
      const size = parseFloat(window.getComputedStyle(node).fontSize) || 0;
      check(`the ${label} button’s label is legible`, size >= 12 - 0.01, `${size}px`);
    }
  }

  // And with the preference the other way round, the two swap over — which is
  // what proves the labels are the rule and not two hard-coded strings.
  paint(true);
  await wait(200);
  const resumeAgain = buttonNamed(/Resume this conversation/);
  const freshAgain = buttonNamed(/Start a new chat/);
  check(
    'the preference decides what starting over says, not the conversation',
    /approvals bypassed/.test(freshAgain?.textContent || ''),
    (freshAgain?.textContent || '').trim(),
  );
  check(
    'while resuming still reports the conversation’s own mode',
    /approvals bypassed/.test(resumeAgain?.textContent || ''),
    (resumeAgain?.textContent || '').trim(),
  );

  // The one screen where starting over is the *only* route back, and the reason
  // the sentence under the notice exists at all: with no Resume beside it there
  // is nothing to compare the button's label against. Nothing recorded which
  // conversation the agent was having, so `canResume` is false.
  //
  // Measured at a phone's width rather than the 900px above, because a sentence
  // appended to a paragraph in a narrow column is exactly the thing that clips
  // or overflows, and a string match on the markup would pass over either.
  host.style.width = '390px';
  controller.handle({
    type: 'chat_unavailable',
    sessionId: 'browser-check',
    runtime: 'claude',
    runtimeLabel: 'Claude Code',
    canResume: false,
    message: 'this chat session is not running',
  } as never);
  paint(true);
  await wait(250);

  const only = buttonNamed(/Start a new chat/);
  check(
    'starting over is the only button when the conversation cannot be resumed',
    Boolean(only) && !buttonNamed(/Resume this conversation/),
  );
  const said = Array.from(host.querySelectorAll<HTMLElement>('p')).find((node) =>
    /A new conversation runs with/.test(node.textContent || ''),
  );
  check('states the mode even when starting over is the only button', Boolean(said));
  if (said) {
    const box = said.getBoundingClientRect();
    check(
      'and the sentence is painted rather than merely present',
      isPainted(said),
      `${Math.round(box.width)}x${Math.round(box.height)}`,
    );
    const size = parseFloat(window.getComputedStyle(said).fontSize) || 0;
    check('and it is set in type that can be read on a phone', size >= 12 - 0.01, `${size}px`);
    // Not clipped and not off to one side: `overflow: hidden` on an ancestor
    // and a paragraph wider than the column both read as "present" to a string
    // match, and both mean the user never sees the mode they are about to get.
    const column = host.getBoundingClientRect();
    check(
      'and it fits the column it is in rather than running off the side',
      box.left >= column.left - 0.5 && box.right <= column.right + 0.5,
      `notice ${Math.round(box.left)}–${Math.round(box.right)} in ${Math.round(column.left)}–${Math.round(column.right)}`,
    );
    check(
      'and it names the mode the preference will give it',
      /approvals bypassed/.test(said.textContent || ''),
      (said.textContent || '').replace(/\s+/g, ' ').trim().slice(-80),
    );
  }

  root.unmount();
  host.remove();
}

async function checkANewConversationCanBeStartedFromTheComposer(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  const controller = new ChatController('browser-check', {
    send: (message: Record<string, unknown>) => {
      sent.push(message);
    },
  } as never);

  const snapshot = (state: string): Record<string, unknown> => ({
    type: 'chat_snapshot',
    sessionId: 'browser-check',
    snapshot: {
      sessionId: 'browser-check',
      runtime: 'claude',
      state,
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false, commands: [{ name: 'clear' }],
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: 1,
          blocks: [{ kind: 'text', text: 'that is the parser sorted, thanks' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: 2,
          blocks: [{ kind: 'text', text: 'glad it helped.' }],
        },
      ],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 2,
      live: true,
      bypassPermissions: false,
    },
  });

  controller.handle(snapshot('idle') as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(250);

  const find = (): HTMLButtonElement | null =>
    host.querySelector('button[aria-label^="Start a new conversation"]');

  const button = find();
  check('the composer offers a way to start a new conversation', Boolean(button));
  if (!button) {
    root.unmount();
    host.remove();
    return;
  }

  check(
    'it says what it does before it is pressed',
    (button.getAttribute('title') || '').toLowerCase().includes('new conversation'),
    button.getAttribute('title') || 'no title',
  );
  check(
    'and it is a button, so the keyboard alone can reach and press it',
    button.tagName === 'BUTTON' && !button.disabled && button.tabIndex >= 0,
    `${button.tagName} disabled=${button.disabled} tabIndex=${button.tabIndex}`,
  );
  check(
    'it is offered while the conversation is healthy, not only once it has failed',
    !host.querySelector('[role="alert"]') && Boolean(find()),
  );

  button.click();
  await wait(150);
  const chatSends = sent.filter((message) => message.type === 'chat_send');
  check(
    'pressing it asks for exactly what typing the command asks for',
    chatSends.length === 1 && chatSends[0].text === '/clear',
    JSON.stringify(chatSends),
  );

  // What the server sends back for a clear: a line under the conversation,
  // then a process starting and going idle. The tab has to come out of that
  // sequence empty and ready — not read-only, and with nothing offering to
  // recover a session that is running.
  for (const event of [
    { t: 'marker', kind: 'cleared', seq: 3, ts: 3 },
    { t: 'state', state: 'starting', seq: 4, ts: 4 },
    { t: 'state', state: 'idle', seq: 5, ts: 5 },
  ]) {
    controller.handle({ type: 'chat_event', sessionId: 'browser-check', event } as never);
  }
  await wait(250);

  const surface = host.textContent ?? '';
  check(
    'after clearing, the window holds none of the conversation it left',
    !surface.includes('that is the parser sorted'),
    surface.slice(0, 200),
  );
  check(
    'and nothing says it ended, is read-only, or offers to recover it',
    !host.querySelector('[role="alert"]') && !/read-only|no longer running|has exited/i.test(surface),
    surface.slice(0, 240),
  );
  const composer = host.querySelector('textarea') as HTMLTextAreaElement | null;
  check(
    'a message can be typed straight away',
    Boolean(composer) && composer?.disabled === false,
    composer ? `disabled=${composer.disabled}` : 'no composer',
  );

  // Mid-answer too: the process the turn is running in is the one being
  // replaced, so there is nothing to wait for.
  controller.handle(snapshot('thinking') as never);
  await wait(200);
  const busyButton = find();
  check(
    'and it stays pressable while the agent is still answering',
    Boolean(busyButton) && busyButton?.disabled === false,
    busyButton ? `disabled=${busyButton.disabled}` : 'gone while busy',
  );

  root.unmount();
  host.remove();
}

/**
 * A turn's badge says how the turn ended, and says the same thing everywhere.
 *
 * Here rather than in a unit test because the claim is about two surfaces
 * agreeing on screen: `groupTurns` is one function, but the rail on the left
 * and the turn's own header are separate components reading it separately, and
 * "the list disagrees with the header" is a defect that only exists rendered.
 *
 * The turn strip only draws its badge while the turn is folded — the open one
 * has its body to speak for it — so the turns under test are past ones, with a
 * fourth left open to fold them (issue #74).
 */
async function checkATurnsBadgeSaysHowItEnded(): Promise<void> {
  const host = document.createElement('div');
  // Wide enough for the turn index to be a rail rather than a sheet.
  host.style.cssText = 'width:1600px;height:900px;position:absolute;top:0;left:0;display:flex;z-index:9999';
  document.body.appendChild(host);

  const at = Date.now();
  const controller = new ChatController('badge-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'badge-check',
    snapshot: {
      sessionId: 'badge-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false,
      },
      messages: [
        // The turn the issue is about: long, several steps went wrong, and it
        // finished and answered.
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: at,
          blocks: [{ kind: 'text', text: 'alpha' }], turnOutcome: 'done',
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: at,
          blocks: [
            { kind: 'tool', toolId: 'x1', name: 'grep', toolKind: 'search', status: 'failed', error: 'no matches' },
            { kind: 'tool', toolId: 'x2', name: 'bash', toolKind: 'execute', status: 'failed', error: 'exit 1' },
            { kind: 'error', text: 'could not read notes.txt' },
            { kind: 'tool', toolId: 'x3', name: 'bash', toolKind: 'execute', status: 'completed' },
            { kind: 'text', text: 'all green now' },
          ],
          turnOutcome: 'done',
        },
        // One that really did fail: the runtime ended it as an error.
        {
          id: 'u2', seq: 3, turnId: 't2', role: 'user', ts: at,
          blocks: [{ kind: 'text', text: 'beta' }], turnOutcome: 'failed',
        },
        {
          id: 'a2', seq: 4, turnId: 't2', role: 'assistant', ts: at,
          blocks: [{ kind: 'error', text: 'rate limited', fatal: true }], turnOutcome: 'failed',
        },
        // An ordinary one, so the check is reading three different answers.
        {
          id: 'u3', seq: 5, turnId: 't3', role: 'user', ts: at,
          blocks: [{ kind: 'text', text: 'gamma' }], turnOutcome: 'done',
        },
        {
          id: 'a3', seq: 6, turnId: 't3', role: 'assistant', ts: at,
          blocks: [{ kind: 'text', text: 'here you are' }], turnOutcome: 'done',
        },
        // Left open, which is what folds the three above it.
        {
          id: 'u4', seq: 7, turnId: 't4', role: 'user', ts: at,
          blocks: [{ kind: 'text', text: 'delta' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 7,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/work',
      view: { ...DEFAULT_CHAT_VIEW, terminalOpen: false },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  // The index runs newest-first, the transcript oldest-first, so the rows are
  // put back into the conversation's order before being read against the
  // strips. Reversed here rather than asserted away: which end the list starts
  // at is a presentation choice, and every claim below is about a turn rather
  // than about a position.
  const rows = (
    Array.from(host.querySelectorAll('nav[aria-label="Turns"] [role="option"]')) as HTMLElement[]
  ).reverse();
  const strips = Array.from(host.querySelectorAll('[data-turn-id]')) as HTMLElement[];

  check(
    'the turn index lists every turn',
    rows.length === 4 && strips.length === 4,
    `rows=${rows.length} strips=${strips.length}`,
  );
  if (rows.length !== 4 || strips.length !== 4) {
    root.unmount();
    host.remove();
    return;
  }

  // The word behind the glyph — the last child of the row, and what anything
  // that cannot see a colour reads.
  const wordOf = (row: HTMLElement): string => (row.lastElementChild?.textContent ?? '').trim();
  // The badge itself, which is a coloured icon and nothing else. Read as a
  // computed colour so the two surfaces are compared on what is drawn rather
  // than on which component drew it.
  const colourOf = (element: HTMLElement): string => {
    // The strip carries a fold/unfold control of its own, and its icon comes
    // first in the DOM — so the badge is the icon that is *not* a control. The
    // rail's whole row is one button, where the badge is the only icon at all.
    const icons = Array.from(element.querySelectorAll('.ricon'));
    const icon = icons.find((node) => !node.closest('button')) ?? icons[0];
    const span = icon?.parentElement as HTMLElement | null;
    return span ? getComputedStyle(span).color : '';
  };

  check(
    'a long turn with failed steps in it still reads as done',
    wordOf(rows[0]) === 'done',
    `${wordOf(rows[0])} for a turn holding 2 failed steps and an error it moved past`,
  );
  check(
    'a turn the runtime ended as an error reads as failed',
    wordOf(rows[1]) === 'failed',
    wordOf(rows[1]),
  );
  check('an ordinary turn reads as done', wordOf(rows[2]) === 'done', wordOf(rows[2]));

  const failedColour = colourOf(rows[1]);
  const doneColour = colourOf(rows[0]);
  check(
    'failed and done are drawn in different colours',
    Boolean(failedColour) && Boolean(doneColour) && failedColour !== doneColour,
    `done=${doneColour} failed=${failedColour}`,
  );

  for (const index of [0, 1, 2]) {
    const rail = colourOf(rows[index]);
    const strip = colourOf(strips[index]);
    check(
      `the list and the turn's own header agree about turn ${index + 1}`,
      Boolean(strip) && strip === rail,
      `rail=${rail} strip=${strip}`,
    );
  }

  // And the steps that failed are still failed where the step is shown: this
  // was never about hiding them, only about not promoting them to a verdict.
  // Opening the turn is what a reader does to find out why, so that is what
  // this does.
  const expand = host.querySelector('[aria-label="Expand turn 1"]') as HTMLElement | null;
  expand?.click();
  await wait(300);
  // Read from the word rather than the colour: the timeline states a step's
  // outcome for anything that cannot see one, which is the same reason the
  // turn's own badge carries a word.
  const activity = host.querySelector('[aria-label="Activity"]');
  const said = Array.from(activity?.querySelectorAll('span') ?? [])
    .map((node) => (node.textContent ?? '').trim())
    .filter(Boolean);
  check(
    'a failed step inside a done turn is still marked failed where it happened',
    said.filter((word) => word === 'Failed').length >= 2,
    `${said.filter((word) => word === 'Failed').length} steps said Failed`,
  );

  root.unmount();
  host.remove();
}

/**
 * A turn's figures stay whole; the prompt beside them is what gets cut.
 *
 * Measured on screen rather than asserted as CSS, because the claim is about
 * what a person can read: a long first line used to push the counts into
 * ellipsis — "16 too…", "9 rea…" — and a truncated measurement is not a
 * measurement. `scrollWidth > clientWidth` is the browser saying "this text did
 * not fit", which no props assertion can stand in for.
 */
async function checkATurnsFiguresAreNeverCutShort(): Promise<void> {
  const host = document.createElement('div');
  // Narrow on purpose: this is the width at which something has to give. A
  // block container, not a flex one — the strip fills the column it sits in,
  // and a flex parent would let it size to its own content and never squeeze.
  host.style.cssText = 'width:820px;height:400px;position:absolute;top:0;left:0;display:block;z-index:9999';
  document.body.appendChild(host);

  const asked =
    'oltre alla spesa complessiva per la chat, inserisci anche la spesa su ogni singolo turno, '
    + 'mi interessa di sapere quanto mi sono costati i turni singolarmente';
  const root = createRoot(host);
  root.render(
    React.createElement(TurnStrip, {
      turn: {
        id: 'm1',
        turnId: 't1',
        index: 11,
        label: asked,
        status: 'done',
        startedAt: Date.now(),
        durationMs: 616000,
        toolCount: 69,
        failedStepCount: 0,
        reasoningCount: 9,
        usage: { costUsd: 10.16 },
        messageIds: ['m1'],
      },
      variant: 'past',
      open: false,
      onToggleOpen: () => {},
      onCopy: () => {},
    } as never),
  );
  await wait(200);

  const strip = host.querySelector('[role="heading"]') as HTMLElement | null;
  const spans = Array.from(strip?.querySelectorAll('span') ?? []) as HTMLElement[];
  const cut = (node: HTMLElement): boolean => node.scrollWidth > node.clientWidth + 1;
  const figures = spans.filter((node) => /^(\d+ (tools?|reasoning)|\$[\d.]+|[\d.]+m? ?[\dms]*)$/.test(
    (node.textContent || '').trim(),
  ));
  const truncatedFigures = figures.filter(cut).map((node) => (node.textContent || '').trim());

  check(
    'the strip draws every figure the turn produced',
    figures.length >= 4,
    figures.map((node) => (node.textContent || '').trim()).join(' | ') || 'no figures on the strip',
  );
  check(
    'no figure on a turn strip is cut short',
    truncatedFigures.length === 0,
    truncatedFigures.join(' | ') || 'none',
  );

  const label = spans.find((node) => (node.textContent || '').trim() === asked);
  check(
    'the prompt is what gives the room up',
    Boolean(label) && cut(label as HTMLElement),
    label ? `${label.clientWidth}px of ${label.scrollWidth}px shown` : 'no label on the strip',
  );
  check(
    'and the whole of it is still there on hover',
    label?.getAttribute('title') === asked,
    (label?.getAttribute('title') || 'no title').slice(0, 60),
  );

  root.unmount();
  host.remove();
}

/**
 * A message waiting in line can be sent now, and the record says why.
 *
 * On screen rather than in a unit test because every claim is about what the
 * two controls on a queued row are to a person using them: that there are two
 * of them and they are told apart by their labels, that a finger can hit both
 * on a phone, that pressing one twice presses it once, and that the control is
 * absent exactly when it would do nothing. A props assertion would pass for a
 * pair of buttons drawn on top of each other with the same name.
 */
async function checkAWaitingMessageCanBeSentNow(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const outbound: Array<Record<string, unknown>> = [];
  const controller = new ChatController('queue-check', {
    send: (message: unknown) => { outbound.push(message as Record<string, unknown>); },
  });
  const snapshot = (state: string, live = true, interrupt = true): void => {
    controller.handle({
      type: 'chat_snapshot',
      sessionId: 'queue-check',
      snapshot: {
        sessionId: 'queue-check',
        runtime: 'claude',
        state,
        capabilities: {
          streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
          interrupt, resume: true, fork: false, attachments: true, usage: true,
          cost: true, plan: false, commands: [],
        },
        messages: [{
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: 1,
          blocks: [{ kind: 'text', text: 'refactor the auth module' }],
        }],
        pendingPermissions: [],
        queued: [
          { id: 'q1', text: 'and then update the docs', ts: 1 },
          { id: 'q2', text: 'stop — you are editing the wrong file', ts: 2 },
        ],
        firstSeq: 1, replayFrom: 1, cursor: 1, live, bypassPermissions: false,
      },
    } as never);
  };

  const root = createRoot(host);
  const paint = async (state: string, phone = false, interrupt = true): Promise<void> => {
    snapshot(state, true, interrupt);
    const view = React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
      onViewChange: () => {},
      ...(phone ? { isMobile: true } : {}),
    } as never);
    root.render(phone ? React.createElement(PhoneContext.Provider, { value: true }, view) : view);
    await wait(250);
  };

  const button = (label: RegExp): HTMLButtonElement | undefined =>
    Array.from(host.querySelectorAll('button')).find((node) =>
      label.test(node.getAttribute('aria-label') ?? '')) as HTMLButtonElement | undefined;

  await paint('thinking');

  // Two waiting messages collapse to the newest one (#79), so opening the list
  // is what puts both of them on screen. Every claim below is about the newest
  // row, which is the one on show either way.
  const disclosure = button(/waiting message/);
  disclosure?.click();
  await wait(200);
  const rows = host.querySelectorAll('[role="list"][aria-label="Messages waiting to be sent"] [role="listitem"]');
  check('both waiting messages are on screen while the agent works', rows.length === 2, `${rows.length} rows`);

  const sendNow = button(/^Send queued message 2 now/);
  const remove = button(/^Remove queued message 2$/);
  check('a waiting message offers a control to send it now', Boolean(sendNow));
  check('alongside the one that removes it', Boolean(remove));
  check(
    'and the two are told apart by their labels, not only by their glyphs',
    Boolean(sendNow && remove) && sendNow!.getAttribute('aria-label') !== remove!.getAttribute('aria-label'),
    `${sendNow?.getAttribute('aria-label')} / ${remove?.getAttribute('aria-label')}`,
  );
  check(
    'the control is a button, so the keyboard alone can reach and press it',
    Boolean(sendNow) && sendNow!.tagName === 'BUTTON' && !sendNow!.disabled
      && sendNow!.tabIndex >= 0,
    `${sendNow?.tagName} tabIndex=${sendNow?.tabIndex}`,
  );

  sendNow?.click();
  await wait(150);
  sendNow?.click();
  await wait(150);
  const promotions = outbound.filter((m) => m.type === 'chat_queue_send_now');
  check(
    'pressing it asks the server for that message, by id',
    promotions.length >= 1 && promotions[0].queuedId === 'q2',
    JSON.stringify(promotions[0] ?? null),
  );
  check(
    'and pressing it twice in quick succession sends it once',
    promotions.length === 1,
    `${promotions.length} requests`,
  );

  // Nothing to cut in front of: the line is already moving.
  await paint('idle');
  check(
    'an idle agent is not offered a control that would change nothing',
    !button(/^Send queued message 1 now/),
  );
  check('while the control that withdraws a message stays', Boolean(button(/^Remove queued message 1$/)));

  // Waiting on a person is still a turn in flight — and the one a correction
  // most often needs to get in front of.
  await paint('awaiting_permission');
  check(
    'a turn waiting on an approval can still be interrupted by a waiting message',
    Boolean(button(/^Send queued message 1 now/)),
  );

  // A runtime that cannot be stopped cannot be cut in front of, and the server
  // refuses — so the row must not offer it.
  await paint('thinking', false, false);
  check(
    'a runtime that cannot be interrupted is not offered the control',
    !button(/^Send queued message 1 now/),
  );
  check(
    'though its queue can still be edited',
    Boolean(button(/^Remove queued message 1$/)),
  );

  // A phone remount starts collapsed again, so the row on show is the newest.
  await paint('thinking', true);
  const phoneSendNow = button(/^Send queued message 2 now/);
  const phoneRemove = button(/^Remove queued message 2$/);
  const size = phoneSendNow ? laidOutSize(phoneSendNow) : { width: 0, height: 0 };
  check(
    'on a phone the new control is big enough to hit',
    size.width >= 44 && size.height >= 44,
    `${size.width}x${size.height}`,
  );
  if (phoneSendNow && phoneRemove) {
    const a = phoneSendNow.getBoundingClientRect();
    const b = phoneRemove.getBoundingClientRect();
    // The clear space between the two, whichever order they are drawn in — not
    // the distance between two arbitrary edges, which is large for any pair and
    // would pass for two buttons directly on top of each other.
    const gap = Math.max(b.left - a.right, a.left - b.right);
    check(
      'and far enough from the one that throws the message away',
      gap >= PHONE_GAP,
      `gap ${Math.round(gap)}px`,
    );
  }

  // The record of what happened, drawn in the conversation.
  await paint('thinking');
  controller.handle({
    type: 'chat_event',
    sessionId: 'queue-check',
    event: { t: 'marker', seq: 2, ts: 2, kind: 'interrupted', detail: '“stop — you are editing the wrong file”' },
  } as never);
  await wait(250);
  const rule = Array.from(host.querySelectorAll('[role="separator"]')).find((node) =>
    (node.getAttribute('aria-label') ?? '').includes('Interrupted'));
  check('the conversation says the turn was cut short', Boolean(rule));
  check(
    'and which message did it',
    (rule?.getAttribute('aria-label') ?? '').includes('editing the wrong file'),
    JSON.stringify(rule?.getAttribute('aria-label') ?? null),
  );

  root.unmount();
  host.remove();
}

/**
 * A long queue takes one row, and opens.
 *
 * Every claim here is a measurement of the laid-out composer, which is the only
 * place they can be made: that twenty collapsed rows are no taller than one,
 * that the opened list scrolls inside its own space instead of pushing the
 * composer off a phone, and that the conversation is still visible behind it. A
 * unit test on the component's props would pass for a list rendered at four
 * thousand pixels tall.
 */
async function checkALongQueueCollapsesToOneRow(): Promise<void> {
  const host = document.createElement('div');
  document.body.appendChild(host);

  const outbound: Array<Record<string, unknown>> = [];
  const controller = new ChatController('queue-size-check', {
    send: (message: unknown) => { outbound.push(message as Record<string, unknown>); },
  });
  const turn = (n: number): Record<string, unknown> => ({
    id: `q${n}`, text: `waiting message number ${n}, long enough to fill the row it is drawn in`, ts: n,
  });
  const snapshot = (count: number): void => {
    controller.handle({
      type: 'chat_snapshot',
      sessionId: 'queue-size-check',
      snapshot: {
        sessionId: 'queue-size-check',
        runtime: 'claude',
        state: 'thinking',
        capabilities: {
          streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
          interrupt: true, resume: true, fork: false, attachments: true, usage: true,
          cost: true, plan: false, commands: [],
        },
        messages: [{
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: 1,
          blocks: [{ kind: 'text', text: 'work through the list' }],
        }],
        pendingPermissions: [],
        queued: Array.from({ length: count }, (_, i) => turn(i + 1)),
        firstSeq: 1, replayFrom: 1, cursor: 1, live: true, bypassPermissions: false,
      },
    } as never);
  };

  const root = createRoot(host);
  const paint = async (count: number, phone: boolean): Promise<void> => {
    snapshot(count);
    const view = React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
      onViewChange: () => {},
      ...(phone ? { isMobile: true } : {}),
    } as never);
    root.render(phone ? React.createElement(PhoneContext.Provider, { value: true }, view) : view);
    await wait(250);
  };
  // A count only: the queue arriving on its own, without a re-render of the
  // whole view, is what must not disturb an open or a closed list.
  const enqueue = async (count: number): Promise<void> => {
    snapshot(count);
    await wait(200);
  };

  const list = (): HTMLElement | null =>
    host.querySelector('[role="list"][aria-label="Messages waiting to be sent"]');
  const rowCount = (): number => list()?.querySelectorAll('[role="listitem"]').length ?? 0;
  const toggle = (): HTMLButtonElement | undefined =>
    Array.from(host.querySelectorAll('button')).find((node) =>
      /waiting message/.test(node.getAttribute('aria-label') ?? '')) as HTMLButtonElement | undefined;
  const status = (): string =>
    Array.from(host.querySelectorAll('[role="status"]'))
      .map((node) => node.textContent ?? '')
      .find((text) => text.includes('waiting to be sent')) ?? '';

  host.style.cssText = 'width:900px;height:700px;position:absolute;top:0;left:0;display:flex';

  // One message is left exactly as it was: no count, no control to press.
  await paint(1, false);
  const oneRow = list()?.getBoundingClientRect().height ?? 0;
  check('a single waiting message is drawn as it always was', rowCount() === 1, `${rowCount()} rows`);
  check('with nothing to open, because there is nothing behind it', !toggle());

  await paint(20, false);
  check('twenty waiting messages collapse to one row', rowCount() === 1, `${rowCount()} rows`);
  const twentyRows = list()?.getBoundingClientRect().height ?? 0;
  check(
    'and take no more room than a single message does',
    twentyRows <= oneRow + 1,
    `${Math.round(twentyRows)}px vs ${Math.round(oneRow)}px`,
  );
  check(
    'the row on show is the one just typed, not the one about to be sent',
    (list()?.textContent ?? '').includes('number 20'),
    JSON.stringify((list()?.textContent ?? '').slice(0, 60)),
  );
  check(
    'the control says how many are behind it',
    (toggle()?.getAttribute('aria-label') ?? '').includes('19'),
    JSON.stringify(toggle()?.getAttribute('aria-label') ?? null),
  );
  check(
    'and a screen reader is told the same, in a region that announces changes',
    status().includes('20') && status().includes('19 hidden'),
    JSON.stringify(status()),
  );
  check(
    'the control is a button the keyboard alone can reach and press',
    Boolean(toggle()) && toggle()!.tagName === 'BUTTON' && toggle()!.tabIndex >= 0
      && toggle()!.getAttribute('aria-expanded') === 'false',
    `${toggle()?.tagName} tabIndex=${toggle()?.tabIndex} expanded=${toggle()?.getAttribute('aria-expanded')}`,
  );

  // Opened: everything, in order.
  toggle()?.click();
  await wait(250);
  check('opening it shows every waiting message', rowCount() === 20, `${rowCount()} rows`);
  check('in the order they will be sent', (() => {
    const texts = Array.from(list()?.querySelectorAll('[role="listitem"]') ?? [])
      .map((node) => node.textContent ?? '');
    return texts[0].includes('number 1,') && texts[19].includes('number 20');
  })());
  check(
    'and says so, rather than leaving the control reading the same either way',
    toggle()?.getAttribute('aria-expanded') === 'true' && status().includes('all shown'),
    `${toggle()?.getAttribute('aria-expanded')} / ${JSON.stringify(status())}`,
  );
  const opened = list()?.getBoundingClientRect().height ?? 0;
  check(
    'the opened list is bounded and scrolls in its own space',
    opened <= 300 && (list()?.scrollHeight ?? 0) > (list()?.clientHeight ?? 0),
    `${Math.round(opened)}px tall, ${list()?.scrollHeight}px of content`,
  );
  // The control that closes it again rides the newest row, which is the last
  // one in a box that scrolls — so opening has to land there rather than at the
  // top of twenty messages with the way back off screen.
  {
    const listNode = list();
    const control = toggle();
    const box = listNode?.getBoundingClientRect();
    const seat = control?.getBoundingClientRect();
    check(
      'and the control that closes it is still where it was left',
      Boolean(box && seat) && seat!.top >= box!.top - 1 && seat!.bottom <= box!.bottom + 1,
      box && seat
        ? `${Math.round(seat.top)}–${Math.round(seat.bottom)} in ${Math.round(box.top)}–${Math.round(box.bottom)}`
        : 'no control',
    );
    check(
      'with the message it belongs to, the list having opened upwards out of it',
      Boolean(listNode && control)
        && (Array.from(listNode!.querySelectorAll('[role="listitem"]'))
          .find((row) => row.contains(control!))?.textContent ?? '').includes('number 20'),
    );
  }

  // #70's control and the one that withdraws a message are still on the rows
  // that are on screen — collapsing must not cost the queue what it could do.
  const removeFirst = Array.from(host.querySelectorAll('button')).find((node) =>
    (node.getAttribute('aria-label') ?? '') === 'Remove queued message 1') as HTMLButtonElement | undefined;
  check('a message can still be withdrawn from the opened list', Boolean(removeFirst));
  check(
    'and sent now from it',
    Boolean(Array.from(host.querySelectorAll('button')).find((node) =>
      /^Send queued message 1 now/.test(node.getAttribute('aria-label') ?? ''))),
  );
  removeFirst?.click();
  await wait(150);
  check(
    'removing one asks the server to drop that message, by id',
    outbound.some((m) => m.type === 'chat_queue_cancel' && m.queuedId === 'q1'),
    JSON.stringify(outbound.filter((m) => m.type === 'chat_queue_cancel')),
  );

  // A list the user opened must survive the queue changing under it, in both
  // directions — this is the criterion a naive `useEffect` on length breaks.
  await enqueue(21);
  check('a message arriving while the list is open leaves it open', rowCount() === 21, `${rowCount()} rows`);
  check('and the count follows it', status().includes('21'), JSON.stringify(status()));

  toggle()?.click();
  await wait(200);
  check('closing it returns to the single row', rowCount() === 1, `${rowCount()} rows`);
  await enqueue(22);
  check('and a message arriving while it is closed does not spring it open', rowCount() === 1, `${rowCount()} rows`);

  // Draining back down: the plain form returns without the user closing
  // anything, and without the count lingering.
  await enqueue(1);
  check('draining to one message returns to the plain form', rowCount() === 1 && !toggle(), `${rowCount()} rows`);
  check('with no count left announcing a queue that is gone', status() === '', JSON.stringify(status()));

  // The phone is where this stops being cosmetic: twenty full-width rows are
  // taller than the screen, so the input, the send control and the
  // conversation all go with them.
  host.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
  const withinScreen = (where: string): void => {
    const frame = host.getBoundingClientRect();
    const field = host.querySelector('textarea') as HTMLElement | null;
    const send = Array.from(host.querySelectorAll('button')).find((node) =>
      /^(Send message|Queue this message)$/.test(node.getAttribute('aria-label') ?? '')) as HTMLElement | undefined;
    const bubble = host.querySelector('[data-message-id]') as HTMLElement | null;
    const box = field?.getBoundingClientRect();
    const sendBox = send?.getBoundingClientRect();
    check(
      `${where}, the box you would type in is still on screen`,
      Boolean(box) && box!.bottom <= frame.bottom + 1 && box!.top >= frame.top - 1 && box!.height > 0,
      box ? `${Math.round(box.top)}–${Math.round(box.bottom)} in ${Math.round(frame.bottom)}` : 'no field',
    );
    check(
      `${where}, so is the control that sends it`,
      Boolean(sendBox) && sendBox!.bottom <= frame.bottom + 1 && sendBox!.height >= PHONE_TARGET,
      sendBox ? `${Math.round(sendBox.bottom)} in ${Math.round(frame.bottom)}, ${Math.round(sendBox.height)}px` : 'none',
    );
    const seen = bubble?.getBoundingClientRect();
    check(
      `${where}, and the conversation is still visible above it`,
      Boolean(seen) && seen!.height > 0 && seen!.bottom > frame.top && seen!.top < frame.bottom,
      seen ? `${Math.round(seen.top)}–${Math.round(seen.bottom)}` : 'nothing rendered',
    );
  };

  await paint(20, true);
  check('a phone collapses the queue to one row too', rowCount() === 1, `${rowCount()} rows`);
  withinScreen('collapsed on a phone');

  const phoneToggle = toggle();
  const size = phoneToggle ? laidOutSize(phoneToggle) : { width: 0, height: 0 };
  check(
    'the control that opens it is big enough for a finger',
    size.width >= PHONE_TARGET && size.height >= PHONE_TARGET,
    `${size.width}x${size.height}`,
  );
  const phoneRemove = Array.from(host.querySelectorAll('button')).find((node) =>
    (node.getAttribute('aria-label') ?? '') === 'Remove queued message 20') as HTMLElement | undefined;
  if (phoneToggle && phoneRemove) {
    const a = phoneToggle.getBoundingClientRect();
    const b = phoneRemove.getBoundingClientRect();
    const gap = Math.max(b.left - a.right, a.left - b.right);
    check(
      'and far enough from the one that throws the message away',
      gap >= PHONE_GAP,
      `gap ${Math.round(gap)}px`,
    );
  }

  phoneToggle?.click();
  await wait(250);
  check('opening it on a phone still shows every message', rowCount() === 20, `${rowCount()} rows`);
  const phoneOpened = list()?.getBoundingClientRect().height ?? 0;
  check(
    'and keeps them inside their own scrolling space rather than the screen',
    phoneOpened > 0 && phoneOpened <= 740 * 0.45 && (list()?.scrollHeight ?? 0) > (list()?.clientHeight ?? 0),
    `${Math.round(phoneOpened)}px of a 740px screen, ${list()?.scrollHeight}px of content`,
  );
  withinScreen('opened on a phone');

  root.unmount();
  host.remove();
}

/* -------------------------------------------------------------------------
 * Folded history is not built until it is opened (issue #81)
 *
 * The whole backlog used to be rendered and then hidden, so entering a
 * conversation paid for every code block, diff and diagram in it — none of
 * which was on screen, because everything but the newest turn is folded by
 * default. The proof has to be at the DOM, not at the policy: `retain` is unit
 * tested on its own, and a list that computes the right retained set and then
 * mounts everything anyway would pass that and fail the user.
 *
 * The bound is asserted the same way — by opening more heavy turns than the
 * budget allows and looking for the earliest one's content to be gone.
 */
async function checkFoldedHistoryIsNotBuiltUntilItIsOpened(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:760px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const capabilities = {
    streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
    interrupt: true, resume: true, fork: false, attachments: true, usage: true,
    cost: true, plan: true, commands: [],
  };

  /**
   * `count` turns, each carrying `chars` of assistant prose and its own marker.
   *
   * Split into 2k blocks rather than one long one, so that a heavier turn is
   * heavier in the document too. A single 60k-character paragraph renders as
   * exactly as many elements as a 2k one, which would make the comparison
   * below pass whether or not anything was fixed.
   */
  const conversation = (count: number, chars: number): unknown[] => {
    const messages: unknown[] = [];
    for (let i = 1; i <= count; i++) {
      const blocks = Array.from({ length: Math.max(1, Math.round(chars / 2000)) }, (_, b) => ({
        kind: 'text',
        text: `${b === 0 ? `MARKER-${i} ` : `part ${b} `}${'filler '.repeat(280)}`,
      }));
      messages.push({
        id: `u${i}`, seq: messages.length + 1, turnId: `t${i}`, role: 'user', ts: 1,
        blocks: [{ kind: 'text', text: `question number ${i}` }],
      });
      messages.push({
        id: `a${i}`, seq: messages.length + 1, turnId: `t${i}`, role: 'assistant', ts: 2,
        blocks,
      });
    }
    return messages;
  };

  const mount = async (id: string, messages: unknown[]) => {
    const controller = new ChatController(id, { send: () => {} });
    controller.handle({
      type: 'chat_snapshot',
      sessionId: id,
      snapshot: {
        sessionId: id, runtime: 'claude', state: 'idle', capabilities,
        messages,
        pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1,
        cursor: messages.length, live: true, bypassPermissions: false,
      },
    } as never);
    const root = createRoot(host);
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/home/dev/project',
        branch: 'main',
        view: { ...DEFAULT_CHAT_VIEW },
        onViewChange: () => {},
      } as never),
    );
    await wait(500);
    return { controller, root };
  };

  const bubbles = (): number => host.querySelectorAll('[data-message-id]').length;
  const nodes = (): number => host.querySelectorAll('*').length;
  const shows = (marker: string): boolean => (host.textContent || '').includes(marker);
  const press = (label: string): void => {
    const button = host.querySelector(`[aria-label="${label}"]`) as HTMLElement | null;
    button?.click();
  };

  // ------------------------------------------- what a folded turn costs
  //
  // Measured as the difference between a 3-turn and a 40-turn conversation of
  // the same content, so the one turn that *is* open cancels out and what is
  // left is the price of 37 folded ones. Run at two very different content
  // weights: if folded turns were still being built, the heavy figure would be
  // a multiple of the light one.
  const overheadPerFoldedTurn = async (label: string, chars: number): Promise<number> => {
    let small = await mount(`${label}-3`, conversation(3, chars));
    const smallNodes = nodes();
    small.root.unmount();
    await wait(80);
    const big = await mount(`${label}-40`, conversation(40, chars));
    const bigNodes = nodes();
    big.root.unmount();
    await wait(80);
    return (bigNodes - smallNodes) / 37;
  };

  const lightPerTurn = await overheadPerFoldedTurn('fold-light', 2000);
  const heavyPerTurn = await overheadPerFoldedTurn('fold-heavy', 60_000);

  let mounted = await mount('fold-long', conversation(40, 2000));
  const longBubbles = bubbles();

  check(
    'with history folded, the browser has not built those turns',
    longBubbles === 2,
    `${longBubbles} message bubbles mounted for a 40-turn conversation`,
  );
  // A folded turn is not free — it still has a strip and an index row, which
  // is what keeps the conversation navigable. What it must not cost is its
  // *contents*.
  check(
    'so entering the tab costs a strip per turn, not that turn’s contents',
    lightPerTurn < 40,
    `${lightPerTurn.toFixed(1)} DOM nodes per folded turn`,
  );
  // Thirty times the content behind the fold, and the same price per turn.
  check(
    'and it does not follow how heavy the folded turns are',
    Math.abs(heavyPerTurn - lightPerTurn) < 5,
    `${heavyPerTurn.toFixed(1)} nodes per folded turn at 60k characters against ${lightPerTurn.toFixed(1)} at 2k`,
  );
  check(
    'and the folded turns’ contents are nowhere in the document',
    !shows('MARKER-1') && !shows('MARKER-20'),
    'looked for turn 1 and turn 20 in a 40-turn conversation',
  );
  check(
    'while the turn on screen is fully built',
    shows('MARKER-40'),
    'the newest turn is open, as it always was',
  );
  // Every turn's strip is still there — the conversation is navigable, and
  // nothing has been made unreachable.
  check(
    'every turn still has its strip, so nothing is out of reach',
    host.querySelectorAll('[data-turn-id]').length === 40,
    `${host.querySelectorAll('[data-turn-id]').length} strips for 40 turns`,
  );

  // ------------------------------------------------- opening one builds it
  press('Expand turn 12');
  await wait(300);
  check(
    'opening a folded turn shows its contents',
    shows('MARKER-12'),
    shows('MARKER-12') ? 'turn 12 is on screen' : 'turn 12 opened empty',
  );

  // Stamped on the node itself: if re-opening rebuilt the turn, React would
  // have mounted a fresh element and the stamp would be gone. This is the
  // behaviour hiding-rather-than-unmounting used to buy, and the one thing
  // this change was most likely to lose.
  const stamp = host.querySelector('#turn-body-u12 [data-message-id]') as (HTMLElement & { seen?: number }) | null;
  if (stamp) stamp.seen = 1;
  press('Collapse turn 12');
  await wait(200);
  press('Expand turn 12');
  await wait(200);
  const again = host.querySelector('#turn-body-u12 [data-message-id]') as (HTMLElement & { seen?: number }) | null;
  check(
    're-folding and re-opening it does not build it a second time',
    Boolean(again) && again?.seen === 1,
    again ? (again.seen === 1 ? 'the same element' : 'a rebuilt element') : 'nothing there at all',
  );

  // ------------------------------- a turn that kept running while folded
  const event = (payload: unknown): void =>
    mounted.controller.handle({ type: 'chat_event', sessionId: 'fold-long', event: payload } as never);
  press('Collapse turn 40');
  await wait(150);
  event({ t: 'msg_start', id: 'late', seq: 999, turnId: 't40', role: 'assistant', ts: 3 });
  event({ t: 'block_start', msgId: 'late', index: 0, block: { kind: 'text', text: 'ARRIVED-WHILE-FOLDED' } });
  event({ t: 'msg_end', msgId: 'late' });
  await wait(200);
  press('Expand turn 40');
  await wait(250);
  check(
    'a turn that kept running while folded opens on its current state',
    shows('ARRIVED-WHILE-FOLDED'),
    shows('ARRIVED-WHILE-FOLDED') ? 'the late message is there' : 'opened on a stale snapshot',
  );

  mounted.root.unmount();
  await wait(80);

  // ------------------------------------------------------ the kept bound
  //
  // Six turns of 60k characters against a 200k budget: the three most recently
  // opened are kept by the floor, one more fits, and the rest are released.
  mounted = await mount('fold-heavy', conversation(8, 60_000));
  for (const turn of [1, 2, 3, 4, 5, 6]) {
    press(`Expand turn ${turn}`);
    await wait(200);
    press(`Collapse turn ${turn}`);
    await wait(120);
  }
  check(
    'a conversation that keeps growing does not keep growing what is kept',
    !shows('MARKER-1') && !shows('MARKER-2'),
    `turn 1 ${shows('MARKER-1') ? 'still built' : 'released'}, turn 2 ${shows('MARKER-2') ? 'still built' : 'released'}`,
  );
  check(
    'while the ones just looked at are still there',
    shows('MARKER-6') && shows('MARKER-5'),
    `turn 6 ${shows('MARKER-6') ? 'kept' : 'gone'}, turn 5 ${shows('MARKER-5') ? 'kept' : 'gone'}`,
  );

  // ------------------------------------------- jumping to a released turn
  // Found by its label rather than by a turn id: the index row's terse title
  // is only used when the index is collapsed, and this is a 1280px window.
  const option = Array.from(host.querySelectorAll('[role="option"]'))
    .find((row) => (row.textContent || '').includes('question number 1')) as HTMLElement | undefined;
  option?.click();
  await wait(350);
  check(
    'jumping to a released turn from the index lands on shown content',
    shows('MARKER-1'),
    option ? (shows('MARKER-1') ? 'turn 1 is built and on screen' : 'landed on an empty turn') : 'no index row for turn 1',
  );

  mounted.root.unmount();
  host.remove();
}

/**
 * That a turn can be branched from its own header, folded or open.
 *
 * Issue #34 asked for copy and branch together on a turn's header, and the
 * changelog said both had shipped. Copy had; branch was a prop nothing ever
 * passed, so the control existed in no state at all — which is why the claim
 * being made here is about the rendered header rather than about a callback.
 *
 * The rest is what makes it a branch rather than a button: the turn the server
 * is asked to cut at is the one whose header was pressed, the conversation that
 * comes back is handed to the shell to open, and a history too large for the
 * model's window is refused *to the user's face* — a refusal that only reached
 * the console would leave someone waiting for a tab that is never coming.
 */
async function checkATurnCanBeBranchedFromItsHeader(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:800px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const capabilities = {
    streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
    interrupt: true, resume: true,
    // Deliberately false, and every adapter in this app says the same: not one
    // of these CLIs can fork a session at a point. Branching is built on top of
    // the transcript instead, so the control must not depend on this.
    fork: false,
    attachments: true, usage: true, cost: true, plan: true, commands: [],
  };

  const messages: unknown[] = [];
  for (let i = 1; i <= 3; i++) {
    messages.push({
      id: `u${i}`, seq: messages.length + 1, turnId: `t${i}`, role: 'user', ts: 1,
      blocks: [{ kind: 'text', text: `question number ${i}` }],
    });
    messages.push({
      id: `a${i}`, seq: messages.length + 1, turnId: `t${i}`, role: 'assistant', ts: 2,
      blocks: [{ kind: 'text', text: `answer number ${i}` }],
    });
  }

  const posted: Array<{ url: string; body: { turnId?: string } }> = [];
  let reply = (): Response =>
    new Response(
      JSON.stringify({
        success: true,
        sessionId: 'branch-1',
        name: 'Refactoring the parser — branch at turn 2',
        workingDir: '/home/dev/project',
        runtime: 'claude',
        turnIndex: 2,
        turns: 2,
        estimatedTokens: 900,
        contextWindow: 200_000,
        sizeChecked: true,
      }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    );
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    // Only the branch request is this check's business. The surface also asks
    // for the working directory's git branch on mount, and counting that as a
    // branch request would have the assertions below reading the wrong call.
    if (!url.endsWith('/branch')) {
      return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
    }
    posted.push({ url, body: JSON.parse(String(init?.body ?? '{}')) });
    return reply();
  }) as typeof window.fetch;

  const controller = new ChatController('branch-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'branch-check',
    snapshot: {
      sessionId: 'branch-check', runtime: 'claude', state: 'idle', capabilities,
      messages, pendingPermissions: [], queued: [],
      firstSeq: 1, replayFrom: 1, cursor: messages.length, live: true, bypassPermissions: false,
    },
  } as never);

  const opened: Array<{ sessionId: string; turnIndex: number }> = [];

  // The toast stack, mounted for real: "the user is told" is a claim about the
  // screen, and reading the store instead would pass for a message nothing
  // paints.
  function ToastHost(): React.ReactElement {
    const state = React.useSyncExternalStore(
      shellStore.subscribe, shellStore.getSnapshot, shellStore.getSnapshot,
    );
    return React.createElement(Toasts, {
      toasts: state.toasts, isMobile: false, onDismiss: () => {},
    } as never);
  }

  const root = createRoot(host);
  root.render(
    React.createElement(
      React.Fragment,
      null,
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude Code',
        workingDir: '/home/dev/project',
        view: { ...DEFAULT_CHAT_VIEW },
        onViewChange: () => {},
        onOpenConversation: (conversation: { sessionId: string; turnIndex: number }) =>
          opened.push(conversation),
      } as never),
      React.createElement(ToastHost, null),
    ),
  );
  await wait(400);

  const BRANCH = '[aria-label="Branch a new session from this turn"]';
  const strip = (anchor: string): HTMLElement | null =>
    host.querySelector(`[data-turn-id="${anchor}"]`) as HTMLElement | null;
  const branchButton = (anchor: string): HTMLElement | null =>
    (strip(anchor)?.querySelector(BRANCH) as HTMLElement | null) ?? null;

  // Turn 3 is the newest and opens itself; 1 and 2 are folded. Both states are
  // the acceptance criterion, and the folded one is the one that was never
  // covered — see the note in ChatView on `openTurnIds`.
  const foldedBody = host.querySelector('#turn-body-u2') as HTMLElement | null;
  check(
    'the fixture really has a folded turn and an open one',
    Boolean(foldedBody?.hidden) && !(host.querySelector('#turn-body-u3') as HTMLElement | null)?.hidden,
    `turn 2 hidden=${foldedBody?.hidden}, turn 3 hidden=${(host.querySelector('#turn-body-u3') as HTMLElement | null)?.hidden}`,
  );
  check(
    'a folded turn offers to branch from its header',
    Boolean(branchButton('u2')),
    branchButton('u2') ? 'the control is there' : 'no branch control on the collapsed strip',
  );
  check(
    'and so does an open one',
    Boolean(branchButton('u3')),
    branchButton('u3') ? 'the control is there' : 'no branch control on the open strip',
  );

  branchButton('u2')?.click();
  await wait(300);

  check(
    'pressing it asks the server to branch this conversation',
    posted.length === 1 && posted[0].url.endsWith('/api/sessions/branch-check/branch'),
    posted.length ? posted[0].url : 'nothing was requested',
  );
  check(
    'at the turn whose header was pressed, by the id the recording uses',
    posted[0]?.body?.turnId === 't2',
    `turnId=${JSON.stringify(posted[0]?.body?.turnId)}`,
  );
  check(
    'and the conversation that comes back is handed over to be opened',
    opened.length === 1 && opened[0].sessionId === 'branch-1' && opened[0].turnIndex === 2,
    JSON.stringify(opened),
  );

  // ------------------------------------------- a branch that will not fit
  reply = (): Response =>
    new Response(
      JSON.stringify({
        error: 'context_too_large',
        message:
          'Branching from turn 3 would carry about 260,000 tokens of history, and this '
          + "model's 200,000-token window leaves 100,000 for it. Branch from an earlier turn.",
      }),
      { status: 413, headers: { 'content-type': 'application/json' } },
    );

  branchButton('u3')?.click();
  await wait(300);

  const toast = (document.body.textContent || '').replace(/\s+/g, ' ');
  check(
    'a history too big for the window is refused in words, on screen',
    /would carry about 260,000 tokens/.test(toast) && /Branch from an earlier turn/.test(toast),
    toast.slice(0, 200) || 'nothing was said',
  );
  check(
    'and nothing is opened for a branch that was refused',
    opened.length === 1,
    `${opened.length} conversations opened`,
  );

  root.unmount();
  host.remove();
  await wait(50);

  // ------------------------------------------------------- on a phone
  const phone = document.createElement('div');
  phone.style.cssText = 'width:390px;height:780px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(phone);

  const phoneRoot = createRoot(phone);
  phoneRoot.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/home/dev/project',
      isMobile: true,
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
      onViewChange: () => {},
      onOpenConversation: () => {},
    } as never),
  );
  await wait(400);

  const phoneBranch = phone.querySelector(`[data-turn-id="u2"] ${BRANCH}`) as HTMLElement | null;
  const box = phoneBranch ? laidOutSize(phoneBranch) : { width: 0, height: 0 };
  check(
    'the branch control is reachable by a finger, not only by a mouse',
    Boolean(phoneBranch) && isPainted(phoneBranch as Element)
      && box.width >= 44 && box.height >= 44,
    phoneBranch ? `${Math.round(box.width)}x${Math.round(box.height)}` : 'no branch control on the phone',
  );
  check(
    'and it stays inside the phone, rather than off the right edge',
    Boolean(phoneBranch)
      && (phoneBranch as HTMLElement).getBoundingClientRect().right
        <= phone.getBoundingClientRect().right + 1,
    phoneBranch
      ? `${Math.round((phoneBranch as HTMLElement).getBoundingClientRect().right)} against ${Math.round(phone.getBoundingClientRect().right)}`
      : 'no branch control on the phone',
  );

  phoneRoot.unmount();
  phone.remove();
  window.fetch = realFetch;
}

/**
 * That a conversation tells one story about how many tokens it has used.
 *
 * Issue #80. Three surfaces answered the same question differently: the
 * composer's session line added the input to the output and stopped there, the
 * header meter added the cache buckets too, and the historical dashboard filed
 * only a total the runtime had volunteered — which Claude never does. The
 * figures below are one real turn out of `claude-oneshot.jsonl`, where the
 * cache is 63,689 of the 63,790 tokens, so a readout that leaves it out is not
 * slightly low, it is the wrong order of magnitude.
 */
async function checkAConversationTellsOneStoryAboutItsTokens(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1000px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('tokens-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'tokens-check',
    snapshot: {
      sessionId: 'tokens-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false,
      },
      messages: [],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const push = (event: Record<string, unknown>, seq: number): void => {
    controller.handle({
      type: 'chat_event',
      sessionId: 'tokens-check',
      event: { seq, ts: 1_700_000_000_000 + seq, ...event },
    } as never);
  };

  push({ t: 'msg_start', id: 'u1', role: 'user', turnId: 'turn-1' }, 1);
  push({ t: 'block_start', msgId: 'u1', index: 0, block: { kind: 'text', text: 'go' } }, 2);
  push({ t: 'msg_end', msgId: 'u1' }, 3);
  push({ t: 'msg_start', id: 'a1', role: 'assistant', turnId: 'turn-1' }, 4);
  push({ t: 'block_start', msgId: 'a1', index: 0, block: { kind: 'text', text: 'done' } }, 5);
  // What Claude reports for this turn: four buckets, and no total at all.
  push({
    t: 'msg_end',
    msgId: 'a1',
    usage: { inputTokens: 4, outputTokens: 97, cacheWriteTokens: 16402, cacheReadTokens: 47287 },
  }, 6);
  push({ t: 'turn_end', turnId: 'turn-1', usage: { costUsd: 0.1901 } }, 7);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(300);

  const meter = host.querySelector('[role="group"][aria-label="Session usage"]');
  const meterText = (meter?.textContent ?? '').replace(/\s+/g, ' ');
  check(
    'the session meter counts a Claude turn’s cache, which is almost all of it',
    /63\.8k tok/.test(meterText),
    meterText || 'no session meter on screen',
  );

  // The composer's own line, which is the figure most often glanced at and was
  // the one leaving the cache out.
  // Anything but the meter above: the two are separate readouts of one number,
  // and a selector that could match either would pass on the meter twice.
  const readout = Array.from(host.querySelectorAll('span')).find(
    (span) =>
      /\d+(\.\d+)?k? tok/.test(span.textContent ?? '')
      && !span.querySelector('span')
      && !meter?.contains(span),
  );
  const readoutText = (readout?.textContent ?? '').replace(/\s+/g, ' ');
  check(
    'and the composer’s session line says the same thing, not input plus output alone',
    /64k tok/.test(readoutText),
    readoutText || 'no session line on screen',
  );
  check(
    'so the two readouts are not two different answers about one conversation',
    !/101 tok/.test(readoutText) && !/101 tok/.test(meterText),
    `${meterText} | ${readoutText}`,
  );

  root.unmount();
  host.remove();
}

/**
 * The model the conversation shows is the one that ran, and its menu is usable.
 *
 * Three things this covers that no unit test can (#75): a grok conversation
 * opens naming no model and is renamed by the turn that finishes, a turn split
 * across models says so on the chip rather than picking one, and a runtime that
 * publishes hundreds of models produces a list somebody can actually find one
 * in.
 */
async function checkTheModelShownIsTheModelThatRan(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const capabilities = {
    streaming: true, thinking: true, toolCalls: false, diffs: false, permissions: false,
    interrupt: true, resume: true, fork: false, attachments: false, usage: true,
    cost: true, plan: false,
    models: [
      { value: 'grok-build', name: 'grok-build', description: 'default' },
      { value: 'grok-4.5', name: 'grok-4.5' },
      { value: 'sxs-claude-opus-4-6', name: 'sxs-claude-opus-4-6' },
    ],
  };

  // Redrawn on `onChange`, because the app redraws on it (#128).
  //
  // A `chat_model_result` lands on the controller and nowhere else — not on the
  // transcript, which is what this surface subscribes to — so the shell's store
  // bumps a revision for exactly this case and re-renders ChatView. A fixture
  // without it holds its first paint for ever, and every assertion below about
  // what the server said would be measured against a screen that never heard
  // it: a removed confirmation and a broken one look identical from there.
  let redraw = (): void => {};
  const controller = new ChatController('model-check', {
    send: () => {},
    onChange: () => redraw(),
  } as never);
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'model-check',
    snapshot: {
      sessionId: 'model-check',
      runtime: 'grok',
      state: 'idle',
      capabilities,
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'what model are you' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'answering' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  const paint = (): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'grok',
        runtimeLabel: 'Grok',
        workingDir: '/tmp/project',
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
  };
  paint();
  redraw = paint;
  await wait(250);

  const chip = (): HTMLElement | null => host.querySelector('[aria-label="Change model"]');
  const chipText = (): string => (chip()?.textContent ?? '').trim();

  // A grok conversation that has run no turn knows no model, and the app does
  // not fill the gap with the one it asked for.
  check(
    'a conversation whose runtime has not named a model does not invent one',
    !/grok-(build|4\.5)/.test(chipText()),
    chipText() || 'empty',
  );

  // The turn that finishes is what names it.
  controller.handle({
    type: 'chat_event',
    sessionId: 'model-check',
    event: {
      t: 'turn_end', seq: 3, ts: Date.now(), turnId: 't1',
      models: [{ model: 'grok-build', calls: 1, usage: { costUsd: 0.0128 } }],
    },
  } as never);
  await wait(200);
  check(
    'the turn that finishes names the model that ran',
    chipText().includes('grok-build'),
    chipText() || 'empty',
  );

  // A turn split across models is not shown as one model.
  controller.handle({
    type: 'chat_event',
    sessionId: 'model-check',
    event: {
      t: 'msg_start', seq: 4, ts: Date.now(), id: 'a2', role: 'assistant', turnId: 't2',
      model: 'grok-build',
    },
  } as never);
  controller.handle({
    type: 'chat_event',
    sessionId: 'model-check',
    event: {
      t: 'turn_end', seq: 5, ts: Date.now(), turnId: 't2',
      models: [
        { model: 'grok-build', calls: 3 },
        { model: 'sxs-claude-opus-4-6', calls: 1 },
      ],
    },
  } as never);
  await wait(200);
  check(
    'a turn that ran on two models says so instead of naming one',
    chipText().includes('grok-build') && chipText().includes('+1'),
    chipText() || 'empty',
  );
  check(
    'and the other model is named where there is room for it',
    (chip()?.getAttribute('title') ?? '').includes('sxs-claude-opus-4-6'),
    chip()?.getAttribute('title') ?? 'no title',
  );

  // The menu: what the runtime published, and findable.
  chip()?.click();
  await wait(200);
  const list = (): HTMLElement | null => host.querySelector('[role="listbox"][aria-label="Models"]');
  const options = (): string[] =>
    Array.from(list()?.querySelectorAll('[role="option"]') ?? []).map(
      (row) => (row.textContent ?? '').trim(),
    );
  check(
    'the picker offers the models the runtime published',
    options().some((row) => row.includes('grok-4.5'))
      && options().some((row) => row.includes('sxs-claude-opus-4-6')),
    options().join(' | ').slice(0, 200) || 'nothing listed',
  );

  const field = list()?.querySelector('input') as HTMLInputElement | null;
  check('and a field to find one in', Boolean(field));
  if (field) {
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set;
    setter?.call(field, 'opus');
    field.dispatchEvent(new Event('input', { bubbles: true }));
    await wait(200);
    check(
      'typing narrows the list rather than only offering to send what was typed',
      options().some((row) => row.includes('sxs-claude-opus-4-6'))
        && !options().some((row) => row.includes('grok-4.5')),
      options().join(' | ').slice(0, 200) || 'nothing listed',
    );
    // And a model the runtime never listed is still reachable, which is the
    // whole reason this is one field and not two.
    setter?.call(field, 'something-unlisted');
    field.dispatchEvent(new Event('input', { bubbles: true }));
    await wait(150);
    const use = Array.from(list()?.querySelectorAll('button') ?? []).find(
      (button) => (button.textContent ?? '').trim() === 'Use',
    ) as HTMLElement | undefined;
    check(
      'a model that matches nothing listed can still be sent',
      Boolean(use) && !(use as HTMLButtonElement).disabled,
      use ? 'enabled' : 'no Use control',
    );
  }

  // What the control does *not* say (issue #128, the question #119 left open).
  //
  // The chip is the announcement: it wears the new model's name the moment one
  // lands, so a box beside it reading "Switched to X for this conversation"
  // spends a glance on news the eye has already had. The three outcomes the
  // chip cannot show for itself still speak, and they are asserted here beside
  // the silence — removing the confirmation and muting a deferral are one edit
  // apart, and only a pair of checks tells them apart.
  //
  // Effects, not markup: the box is state a `useEffect` raises, so a rendered
  // string is not evidence either way and only a real browser settles it.
  document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  await wait(150);

  const noticeIn = (surface: HTMLElement): HTMLElement | null =>
    (surface
      .querySelector('[aria-label="Change model"]')
      ?.parentElement?.querySelector('[role="status"]') ?? null) as HTMLElement | null;
  const noticeText = (surface: HTMLElement): string => (noticeIn(surface)?.textContent ?? '').trim();
  const answer = (
    target: ChatController,
    sessionId: string,
    applied: string,
    message: string,
    model: string | null,
  ): void =>
    target.handle({ type: 'chat_model_result', sessionId, applied, model, message } as never);

  answer(controller, 'model-check', 'live', 'Switched to sxs-claude-opus-4-6 for this conversation.', 'sxs-claude-opus-4-6');
  await wait(200);
  check(
    'a model that took effect pops nothing up beside the composer',
    !noticeIn(host),
    noticeIn(host) ? `a box reading "${noticeText(host)}"` : 'nothing beside the chip',
  );
  check(
    'because the chip is already wearing the new name — the news is dropped, not lost',
    chipText().includes('sxs-claude-opus-4-6'),
    chipText() || 'empty',
  );
  check(
    'and the hover went back to describing the control instead of repeating the change',
    /^(Model:|This turn ran on:)/.test(chip()?.getAttribute('title') ?? ''),
    chip()?.getAttribute('title') ?? 'no title',
  );

  answer(controller, 'model-check', 'sent', 'Sent "/model grok-4.5" to the session — check the transcript to confirm it took.', 'grok-4.5');
  await wait(200);
  check(
    'a runtime that has to be asked mid-session still says the answer is not in yet',
    noticeText(host).includes('check the transcript'),
    noticeText(host) || 'silence',
  );

  answer(controller, 'model-check', 'pending', 'Saved. grok-4.5 will be used the next time a session starts for this conversation.', 'grok-4.5');
  await wait(200);
  check(
    'and so does a choice that will only reach a future session',
    noticeText(host).includes('next time a session starts'),
    noticeText(host) || 'silence',
  );

  answer(controller, 'model-check', 'cleared', 'Cleared the model override. The next session for this conversation will use the runtime default.', null);
  await wait(200);
  check(
    'clearing the override says so too — the chip has already fallen back to a name it will not run at',
    noticeText(host).includes('Cleared the model override'),
    noticeText(host) || 'silence',
  );

  // The box leaves on its own, and a repeat of the same answer brings it back.
  //
  // Both halves were unguarded, and the second one was broken: the effect that
  // raises the box was keyed on the message *text*, so an outcome repeated word
  // for word — the same model picked twice on a runtime that cannot switch
  // mid-session, or "use the default for this runtime" clicked twice — left the
  // dependency unchanged after the timeout had already hidden it, and the second
  // click answered with nothing at all. On a phone, where the chip cannot show a
  // pending model or a clear, that was the whole response to a deliberate action.
  //
  // Virtual milliseconds: this costs budget, not wall-clock.
  await wait(7200);
  check(
    'the answer goes away on its own instead of becoming a fixture beside the composer',
    !noticeIn(host),
    noticeIn(host) ? `still reading "${noticeText(host)}"` : 'gone',
  );

  answer(controller, 'model-check', 'cleared', 'Cleared the model override. The next session for this conversation will use the runtime default.', null);
  await wait(200);
  check(
    'and the very same answer, given again, is announced again rather than swallowed',
    noticeText(host).includes('Cleared the model override'),
    noticeText(host) || 'silence — the repeat was swallowed',
  );

  root.unmount();
  host.remove();

  // The phone, where the confirmation cost the most. The wrapper is `static`
  // there so the menu can have the composer's width, which means this box
  // resolves against the composer rather than against its own chip: it landed
  // on the field the user was about to type into, with the navigation bar
  // directly under it. So the silence is measured as geometry here rather than
  // taken on trust from the desktop mount, and the message that must survive is
  // measured for fit in the place it has the least room.
  //
  // The whole phone shell, not a `PhoneContext` wrapper around ChatView:
  // ChatView publishes that context itself from its own `isMobile` prop, so a
  // provider outside it is overwritten and the surface renders at desktop
  // sizing while agreeing that it is a phone.
  const phone = document.createElement('div');
  phone.style.cssText =
    'width:390px;height:740px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
  document.body.appendChild(phone);

  let redrawPhone = (): void => {};
  const phoneController = new ChatController('model-phone', {
    send: () => {},
    onChange: () => redrawPhone(),
  } as never);
  phoneController.handle({
    type: 'chat_snapshot',
    sessionId: 'model-phone',
    snapshot: {
      sessionId: 'model-phone', runtime: 'grok', state: 'idle', capabilities,
      messages: [], pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 0,
      live: true, bypassPermissions: false,
    },
  } as never);

  const phoneRoot = createRoot(phone);
  const paintPhone = (): void => {
    phoneRoot.render(React.createElement(PhoneSurface, { controller: phoneController }));
  };
  paintPhone();
  redrawPhone = paintPhone;
  await wait(300);

  // The chip lives behind "Show the other controls" on a phone: a fixture that
  // measured the resting row would find no chip, no box, and agree with itself.
  (phone.querySelector('[aria-label="Show the other controls"]') as HTMLElement | null)?.click();
  await wait(300);

  check(
    'the model control is reachable on a phone at all, behind the other controls',
    Boolean(phone.querySelector('[aria-label="Change model"]')),
    phone.querySelector('[aria-label="Change model"]') ? 'on the expanded row' : 'no chip even once the other controls are open',
  );

  answer(phoneController, 'model-phone', 'live', 'Switched to grok-4.5 for this conversation.', 'grok-4.5');
  await wait(300);
  check(
    'a successful change on a phone covers neither the composer nor the bar, because nothing appears',
    !noticeIn(phone),
    noticeIn(phone) ? `a box reading "${noticeText(phone)}"` : 'nothing over the composer',
  );

  answer(
    phoneController, 'model-phone', 'pending',
    'Saved. grok-build will be used the next time a session starts for this conversation.', 'grok-build',
  );
  await wait(300);
  const deferredBox = noticeIn(phone)?.getBoundingClientRect();
  const modelFieldBox = composerField(phone)?.getBoundingClientRect();
  const modelNavBox = (
    phone.querySelector('nav[aria-label="Go to"]') as HTMLElement | null
  )?.getBoundingClientRect();
  const phoneBox = phone.getBoundingClientRect();
  /** True when the two boxes share no pixel — 1px of slack for a shared border. */
  const clearOfBox = (a: DOMRect, b: DOMRect): boolean =>
    a.bottom <= b.top + 1 || a.top >= b.bottom - 1 || a.right <= b.left + 1 || a.left >= b.right - 1;
  check(
    'a deferred model choice on a phone is on screen and clear of both the field and the bar',
    Boolean(deferredBox && modelFieldBox)
      && deferredBox!.height > 0
      && deferredBox!.top >= phoneBox.top - 1
      && deferredBox!.bottom <= phoneBox.bottom + 1
      && clearOfBox(deferredBox!, modelFieldBox!)
      && (!modelNavBox || clearOfBox(deferredBox!, modelNavBox)),
    [
      deferredBox ? `notice ${Math.round(deferredBox.top)}–${Math.round(deferredBox.bottom)}` : 'no deferral shown at all',
      modelFieldBox ? `field ${Math.round(modelFieldBox.top)}–${Math.round(modelFieldBox.bottom)}` : 'no composer',
      modelNavBox ? `bar ${Math.round(modelNavBox.top)}–${Math.round(modelNavBox.bottom)}` : 'no bottom bar',
      `surface ${Math.round(phoneBox.top)}–${Math.round(phoneBox.bottom)}`,
    ].join(', '),
  );

  phoneRoot.unmount();
  phone.remove();
}

/**
 * The picker says which of the three defaults put this model in force.
 *
 * A model reaches a conversation three ways — this chat's own pick, the
 * account's standing choice, and the active runtime profile — and until #135
 * the control said nothing about which. The profile case was the worst of them:
 * the pin was genuinely applied to every launch and the chip read the literal
 * word "model", so a user could neither see it nor tell why their agent was on
 * a model they had not chosen.
 *
 * Here rather than in the unit tests because the sentence lives inside a menu
 * that only exists after a click, and because "rendered" is not the claim — a
 * line at `opacity: 0` drops silently out of every geometry sweep instead of
 * failing one. The box, the paint and the type size are all measured.
 */
async function checkTheModelPickerSaysWhereTheDefaultCameFrom(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const capabilities = {
    streaming: true, thinking: false, toolCalls: false, diffs: false, permissions: false,
    interrupt: true, resume: true, fork: false, attachments: false, usage: true,
    cost: true, plan: false,
    models: [
      { value: 'grok-build', name: 'grok-build' },
      { value: 'grok-4.5', name: 'grok-4.5' },
    ],
  };

  let redraw = (): void => {};
  const controller = new ChatController('model-source', {
    send: () => {},
    onChange: () => redraw(),
  } as never);
  // A conversation that has run no turn, so the runtime has named no model —
  // which is exactly the state in which the pin used to be invisible. Launched
  // on the profile's model, which is what `modelPinned` records: the *default*
  // is not evidence that this conversation is on it, and using it as such was
  // the review's third finding.
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'model-source',
    modelOverride: null,
    modelPinned: 'grok-4.5',
    modelDefault: { model: 'grok-4.5', source: 'profile', profileName: 'House' },
    snapshot: {
      sessionId: 'model-source', runtime: 'grok', state: 'idle', capabilities,
      messages: [], pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 0,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  const paint = (): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'grok',
        runtimeLabel: 'Grok',
        workingDir: '/tmp/project',
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
  };
  paint();
  redraw = paint;
  await wait(300);

  const chip = (): HTMLElement | null => host.querySelector('[aria-label="Change model"]');
  check(
    'a model pinned by a profile is named on the chip instead of the word “model”',
    (chip()?.textContent ?? '').includes('grok-4.5'),
    (chip()?.textContent ?? '').trim() || 'empty',
  );

  // The other half, and the one the chip got wrong: a standing choice that was
  // never applied to this conversation is a fact about the *next* new chat, so
  // naming it here would put a model on the chip that this conversation is not
  // running and never will be. Sent as a rejoin, because that is how it reaches
  // an open tab — the account picked a model somewhere else.
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'model-source',
    modelOverride: null,
    // This conversation launched with no model flag at all.
    modelPinned: null,
    modelDefault: { model: 'grok-4.5', source: 'personal' },
    snapshot: {
      sessionId: 'model-source', runtime: 'grok', state: 'idle', capabilities,
      messages: [], pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 0,
      live: true, bypassPermissions: false,
    },
  } as never);
  await wait(250);
  check(
    'a standing choice this conversation was never launched on stays off the chip',
    (chip()?.textContent ?? '').trim() === 'model',
    (chip()?.textContent ?? '').trim() || 'empty',
  );

  // Back to the profile-launched conversation the rest of this check is about.
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'model-source',
    modelOverride: null,
    modelPinned: 'grok-4.5',
    modelDefault: { model: 'grok-4.5', source: 'profile', profileName: 'House' },
    snapshot: {
      sessionId: 'model-source', runtime: 'grok', state: 'idle', capabilities,
      messages: [], pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 0,
      live: true, bypassPermissions: false,
    },
  } as never);
  await wait(250);

  const sourceLine = (): HTMLElement | null => host.querySelector('[data-model-source]');
  chip()?.click();
  await wait(250);
  settle(host.ownerDocument);

  const line = sourceLine();
  check(
    'and the menu says where it came from',
    (line?.textContent ?? '').includes('House') && (line?.textContent ?? '').includes('grok-4.5'),
    (line?.textContent ?? '').trim() || 'no source line in the open menu',
  );
  // Not `isPainted` alone: it answers false for a line that is not there and
  // false for one that is invisible, and those want different words.
  const lineBox = line?.getBoundingClientRect();
  const hostBox = host.getBoundingClientRect();
  check(
    'the source line is actually on screen, not merely in the markup',
    Boolean(line)
      && isPainted(line!)
      && lineBox!.top >= hostBox.top - 1
      && lineBox!.bottom <= hostBox.bottom + 1,
    line
      ? `${Math.round(lineBox!.width)}x${Math.round(lineBox!.height)} at ${Math.round(lineBox!.top)}–${Math.round(lineBox!.bottom)}, surface ${Math.round(hostBox.top)}–${Math.round(hostBox.bottom)}, opacity ${window.getComputedStyle(line).opacity}, visibility ${window.getComputedStyle(line).visibility}`
      : 'no source line',
  );
  // Measured against the list it explains rather than against a number picked
  // here: the desktop scale in this menu bottoms out at 10px for captions, and
  // a sentence that explains every entry underneath it must not be set smaller
  // than those entries. The phone floor is swept separately, by the type-scale
  // rules that walk the whole composer.
  const optionSize = (): number => {
    const option = host.querySelector('[role="listbox"][aria-label="Models"] [role="option"]');
    return option ? parseFloat(window.getComputedStyle(option).fontSize) || 0 : 0;
  };
  const lineSize = line ? parseFloat(window.getComputedStyle(line).fontSize) || 0 : 0;
  check(
    'and set no smaller than the models it is explaining',
    lineSize > 0 && lineSize >= optionSize() - 0.01,
    `${lineSize}px against the list's ${optionSize()}px`,
  );

  // The way back has to say what it will do, because what it does to a standing
  // choice is forget it rather than fall back to it.
  const clearEntry = Array.from(
    host.querySelectorAll<HTMLElement>('[role="listbox"][aria-label="Models"] [role="option"]'),
  ).find((row) => (row.textContent ?? '').includes('Use the default for this runtime'));
  check(
    'the clear entry says what clearing would land on',
    (clearEntry?.getAttribute('title') ?? '').includes('House'),
    clearEntry?.getAttribute('title') ?? 'no clear entry',
  );

  document.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  await wait(150);

  // Now the account's own choice, arriving the way a pick answers rather than
  // on a rejoin: the line has to follow the click, or it spends the rest of the
  // conversation describing the state before it.
  controller.handle({
    type: 'chat_model_result',
    sessionId: 'model-source',
    model: 'grok-build',
    applied: 'live',
    message: 'Switched to grok-build for this conversation.',
    modelDefault: { model: 'grok-build', source: 'personal' },
  } as never);
  await wait(250);

  chip()?.click();
  await wait(250);
  settle(host.ownerDocument);
  const picked = sourceLine();
  check(
    'after a pick the menu describes the state the click produced, not the launch',
    (picked?.textContent ?? '').includes('Chosen for this conversation only')
      && (picked?.textContent ?? '').includes('forgets grok-build'),
    (picked?.textContent ?? '').trim() || 'no source line after the pick',
  );
  check(
    'and it is still painted, at a readable size, in the state it changed into',
    Boolean(picked)
      && isPainted(picked!)
      && (parseFloat(window.getComputedStyle(picked!).fontSize) || 0) >= optionSize() - 0.01,
    picked
      ? `${Math.round(picked.getBoundingClientRect().width)}x${Math.round(picked.getBoundingClientRect().height)} at ${window.getComputedStyle(picked).fontSize}`
      : 'no source line',
  );

  root.unmount();
  host.remove();
}

/**
 * How hard the agent thinks: shown, changed, and absent when it cannot be.
 *
 * Four things here need a layout engine and get one nowhere else. The colour
 * ramp is `color-mix(in oklab, var(--effort-N) …)` over custom properties, so
 * nothing short of a real cascade can say whether `low` and `max` actually look
 * different — a unit test reads the same two style strings whether the ramp
 * resolves or silently does not. The meter is the carrier of meaning for anyone
 * the colour does not reach, so its fill has to be counted from painted
 * backgrounds rather than from the prop that was passed in. The popup is
 * click-toggled state that opens *upward* out of a bar pinned to the bottom of
 * the screen, which is a geometry question. And the chip removing itself for a
 * runtime with no ladder is only worth anything if what it makes room for —
 * Send — is still there and still hittable.
 *
 * Measured through a canvas round-trip rather than by parsing the computed
 * string: Chrome serialises a computed `color-mix(in oklab, …)` as `oklab(…)`,
 * not as `rgb()`, so hand-parsing rgb() would read every mixed stop as
 * unparseable and quietly agree with itself.
 */
async function checkTheEffortChipSaysAndSetsHowHardTheAgentThinks(): Promise<void> {
  // Cleared first because ChatView seeds a new conversation from the level this
  // runtime was last used at, and a leftover preference would send a
  // `chat_set_effort` nobody in this check asked for — which is exactly what the
  // "exactly one message" assertions below are about.
  window.localStorage.removeItem('cc-web-chat-effort');

  // claude's ladder, spaced the way `rankedEfforts` spaces a five-level list.
  const efforts = [
    { value: 'low', name: 'Low', description: 'the least thinking on offer', rank: 0 },
    { value: 'medium', name: 'Medium', rank: 0.25 },
    { value: 'high', name: 'High', rank: 0.5 },
    { value: 'xhigh', name: 'Extra high', rank: 0.75 },
    { value: 'max', name: 'Max', description: 'the most thinking this runtime will do', rank: 1 },
  ];

  const baseCapabilities = {
    streaming: true, thinking: true, toolCalls: false, diffs: false, permissions: false,
    interrupt: true, resume: true, fork: false, attachments: false, usage: true,
    cost: true, plan: false,
  };

  const snapshotFor = (sessionId: string, capabilities: unknown) => ({
    type: 'chat_snapshot',
    sessionId,
    snapshot: {
      sessionId,
      runtime: 'claude',
      state: 'idle',
      capabilities,
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'think about this' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 1,
      live: true, bypassPermissions: false,
    },
  });

  // Any CSS colour to the three bytes a person's eye receives. A fresh context
  // per call, and `#000` first so an unparseable value leaves black behind
  // rather than the previous measurement.
  const rgbOf = (value: string): [number, number, number] => {
    const canvas = document.createElement('canvas');
    canvas.width = 1;
    canvas.height = 1;
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
    ctx.fillStyle = '#000';
    ctx.fillStyle = value;
    ctx.fillRect(0, 0, 1, 1);
    const pixel = ctx.getImageData(0, 0, 1, 1).data;
    return [pixel[0], pixel[1], pixel[2]];
  };
  /** Distance from grey. Zero for anything on the black-to-white line. */
  const chroma = (rgb: [number, number, number]): number =>
    Math.max(...rgb) - Math.min(...rgb);

  // Measured standing still, and this is a headless limitation stated rather
  // than hidden. Virtual time drives timers, not the compositor's animation
  // clock, so a CSS transition or entry animation here never advances past its
  // first frame: the meter's bars would read as their pre-transition colour for
  // ever, and the menu would be measured 8px down the `relay-rise` it is
  // permanently at the start of. Both settle inside 150ms in a real browser.
  // The resting values are also exactly what a reader who has asked for less
  // motion is served, which is half of who this control is drawn for.
  const still = document.createElement('style');
  still.textContent =
    '.effort-check-surface, .effort-check-surface * { animation: none !important; transition: none !important; }';
  document.head.appendChild(still);

  const host = document.createElement('div');
  host.className = 'effort-check-surface';
  host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  // Redrawn on `onChange`, because the app redraws on it.
  //
  // A `chat_effort_result` lands on the controller and nowhere else — not on
  // the transcript, which is what this surface subscribes to — so the shell's
  // store bumps a revision for exactly this case and re-renders ChatView. A
  // fixture without that holds its first paint for ever, and every assertion
  // below about what the server said would be measured against a screen that
  // never heard it: a removed popup and a broken one look identical from there.
  let redraw = (): void => {};
  const controller = new ChatController('effort-check', {
    send: (message: unknown) => sent.push(message as Record<string, unknown>),
    onChange: () => redraw(),
  } as never);
  controller.handle(snapshotFor('effort-check', { ...baseCapabilities, efforts }) as never);

  const root = createRoot(host);
  const paint = (): void => {
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude',
        workingDir: '/tmp/project',
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
  };
  paint();
  redraw = paint;
  await wait(250);

  const chip = (): HTMLElement | null =>
    host.querySelector('[aria-label="Change how hard the agent thinks"]');
  check('a runtime that publishes a ladder gets a control to move along it', Boolean(chip()));

  // The ramp has to exist before anything measured against it means a thing.
  // This repo has shipped a check that measured an element no stylesheet had
  // ever reached, so the variables are asserted directly as well as by effect.
  const rampDeclared = getComputedStyle(document.documentElement)
    .getPropertyValue('--effort-4')
    .trim();
  check(
    'the effort ramp is really in the cascade, not measured off an unstyled page',
    rampDeclared.length > 0,
    rampDeclared || 'no --effort-4 declared',
  );

  const setLevel = (effort: string, seq: number): void =>
    controller.handle({
      type: 'chat_event',
      sessionId: 'effort-check',
      event: { t: 'effort', seq, ts: Date.now(), effort },
    } as never);

  const borderRgb = rgbOf(
    getComputedStyle(document.documentElement).getPropertyValue('--border').trim(),
  ).join(',');
  const litBars = (): number => {
    const meter = chip()?.querySelector('span[aria-hidden="true"]');
    return Array.from(meter?.children ?? []).filter(
      (bar) => rgbOf(getComputedStyle(bar as HTMLElement).backgroundColor).join(',') !== borderRgb,
    ).length;
  };

  setLevel('low', 2);
  await wait(200);
  const lowRgb = rgbOf(getComputedStyle(chip() as HTMLElement).color);
  const lowBars = litBars();
  check('the chip names the level the runtime reported', (chip()?.textContent ?? '').includes('Low'), chip()?.textContent ?? 'empty');

  setLevel('max', 3);
  await wait(200);
  const maxRgb = rgbOf(getComputedStyle(chip() as HTMLElement).color);
  const maxBars = litBars();
  check('and follows the runtime to the top of its ladder', (chip()?.textContent ?? '').includes('Max'), chip()?.textContent ?? 'empty');

  const mutedRgb = rgbOf(
    getComputedStyle(document.documentElement).getPropertyValue('--muted-foreground').trim(),
  );
  check(
    'the least thinking on offer looks like every other quiet chip on the row',
    chroma(lowRgb) <= 2 && Math.abs(lowRgb[0] - mutedRgb[0]) <= 2,
    `chip=rgb(${lowRgb}) muted=rgb(${mutedRgb})`,
  );
  check(
    'and the most does not — the ramp arrives as colour, not as a nominally different style string',
    chroma(maxRgb) > 60 && lowRgb.join(',') !== maxRgb.join(','),
    `low=rgb(${lowRgb}) chroma=${chroma(lowRgb)} | max=rgb(${maxRgb}) chroma=${chroma(maxRgb)}`,
  );
  check(
    'the meter fills further for more thinking, so the level survives a reader the colour never reaches',
    lowBars >= 1 && maxBars > lowBars,
    `low=${lowBars} bars, max=${maxBars} bars`,
  );

  // The menu.
  chip()?.click();
  await wait(200);
  const list = (): HTMLElement | null =>
    host.querySelector('[role="listbox"][aria-label="Effort levels"]');
  const options = (): HTMLElement[] =>
    Array.from(list()?.querySelectorAll('[role="option"]') ?? []) as HTMLElement[];
  check(
    'the menu offers every level the runtime published, and a way back to its default',
    options().length === efforts.length + 1,
    `${options().length} rows: ${options().map((row) => (row.textContent ?? '').trim().slice(0, 12)).join(' | ')}`,
  );

  // Opened upward, because this bar is pinned to the bottom of the window: a
  // menu that dropped down would be entirely below the fold.
  const listBox = list()?.getBoundingClientRect();
  const chipBox = chip()?.getBoundingClientRect();
  check(
    'the menu opens above the chip and lands inside the window',
    Boolean(listBox && chipBox)
      && listBox!.height > 0
      && listBox!.bottom <= chipBox!.top + 1
      && listBox!.top >= 0
      && listBox!.left >= 0
      && listBox!.right <= window.innerWidth,
    listBox
      ? `menu ${Math.round(listBox.top)}–${Math.round(listBox.bottom)}, chip top ${Math.round(chipBox!.top)}, viewport ${window.innerWidth}x${window.innerHeight}`
      : 'no menu',
  );

  // Picked by position on the ladder rather than by label text, because two of
  // claude's levels differ only in a word ("High" and "Extra high").
  const picks = (): Array<Record<string, unknown>> =>
    sent.filter((message) => message.type === 'chat_set_effort');
  const xhigh = options()[3];
  check('the fourth rung is the one the runtime named fourth', (xhigh?.textContent ?? '').includes('Extra high'), xhigh?.textContent ?? 'missing');
  xhigh?.click();
  await wait(200);
  check(
    'picking a level asks the server for exactly that level, once',
    picks().length === 1 && picks()[0].effort === 'xhigh',
    JSON.stringify(picks()),
  );
  check('and the menu shuts behind the pick', !list(), list() ? 'still open' : 'closed');

  // The way back. Without it a conversation moved off the runtime's own default
  // could never be returned to it.
  chip()?.click();
  await wait(200);
  const rows = options();
  const fallback = rows[rows.length - 1];
  check(
    'the last row offers the runtime’s own default back',
    (fallback?.textContent ?? '').trim() === 'Use the default for this runtime',
    fallback?.textContent ?? 'missing',
  );
  fallback?.click();
  await wait(200);
  check(
    'and choosing it clears the level rather than picking the cheapest one',
    picks().length === 2 && picks()[1].effort === '',
    JSON.stringify(picks()),
  );

  // What the control does *not* say (issue #119).
  //
  // The chip is the announcement. It redraws to the new level — named, metered
  // and coloured — the moment one lands, so a box beside it repeating the word
  // spends a glance on news the eye has already had. The outcomes the chip
  // cannot show for itself are the ones that still have to speak, and they are
  // asserted here beside the silence: removing the confirmation and muting a
  // refusal are one edit apart, and only a pair of checks tells them apart.
  //
  // Effects, not markup — the box is state a `useEffect` raises, so a rendered
  // string is not evidence either way and only a real browser settles it.
  const noticeIn = (surface: HTMLElement): HTMLElement | null =>
    (surface
      .querySelector('[aria-label="Change how hard the agent thinks"]')
      ?.parentElement?.querySelector('[role="status"]') ?? null) as HTMLElement | null;
  const noticeText = (surface: HTMLElement): string => (noticeIn(surface)?.textContent ?? '').trim();
  const answer = (
    target: ChatController,
    sessionId: string,
    applied: string,
    message: string,
    level: string | null,
  ): void =>
    target.handle({ type: 'chat_effort_result', sessionId, applied, effort: level, message } as never);
  const REFUSAL = 'claude does not offer "ludicrous". It accepts: low, medium, high, xhigh, max.';

  answer(controller, 'effort-check', 'live', 'Now thinking at xhigh.', 'xhigh');
  await wait(200);
  check(
    'a level that took effect pops nothing up beside the composer',
    !noticeIn(host),
    noticeIn(host) ? `a box reading "${noticeText(host)}"` : 'nothing beside the chip',
  );
  check(
    'because the chip itself has already moved to it — the news is dropped, not lost',
    (chip()?.textContent ?? '').includes('Extra high'),
    chip()?.textContent ?? 'empty',
  );
  check(
    'and the hover went back to describing the control instead of repeating the change',
    (chip()?.getAttribute('title') ?? '').startsWith('Effort:'),
    chip()?.getAttribute('title') ?? 'no title',
  );

  answer(controller, 'effort-check', 'refused', REFUSAL, null);
  await wait(200);
  check(
    'a refused level still says so — nothing was stored and the old one is still running',
    noticeText(host).includes('does not offer'),
    noticeText(host) || 'silence',
  );

  answer(
    controller,
    'effort-check',
    'pending',
    'Saved. This conversation will run at max from its next session.',
    'max',
  );
  await wait(200);
  check(
    'and so does one that will only reach a future session',
    noticeText(host).includes('next session'),
    noticeText(host) || 'silence',
  );

  root.unmount();
  host.remove();

  // A runtime with no ladder: no control, and the room it gives back is the
  // point of the omission, so Send has to still be there and still be the thing
  // under the pointer.
  const bare = document.createElement('div');
  bare.className = 'effort-check-surface';
  bare.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(bare);
  const bareController = new ChatController('effort-bare', { send: () => {} } as never);
  bareController.handle(snapshotFor('effort-bare', baseCapabilities) as never);
  const bareRoot = createRoot(bare);
  bareRoot.render(
    React.createElement(ChatView, {
      controller: bareController,
      runtime: 'kimi',
      runtimeLabel: 'Kimi',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(250);

  const strayChip = bare.querySelector('[aria-label="Change how hard the agent thinks"]');
  check(
    'a runtime that published no ladder gets no effort control at all',
    !strayChip,
    strayChip ? `a chip reading "${(strayChip.textContent ?? '').trim()}" nothing could accept` : 'no chip on the row',
  );
  const send = bare.querySelector('[aria-label="Send message"]') as HTMLElement | null;
  const sendBox = send?.getBoundingClientRect();
  const underPointer = sendBox
    ? document.elementFromPoint(sendBox.left + sendBox.width / 2, sendBox.top + sendBox.height / 2)
    : null;
  check(
    'and the space it would have taken still belongs to Send, which stays reachable',
    Boolean(send) && Boolean(underPointer) && send!.contains(underPointer as Node),
    sendBox
      ? `send at ${Math.round(sendBox.left)},${Math.round(sendBox.top)} ${Math.round(sendBox.width)}x${Math.round(sendBox.height)}`
      : 'no send control',
  );

  bareRoot.unmount();
  bare.remove();

  // The phone, which is where the confirmation cost the most (issue #119).
  //
  // The wrapper is `static` there so the menu can have the composer's width,
  // which means this box resolves against the composer rather than against its
  // own chip: it landed on the field the user was about to type into, with the
  // navigation bar directly under it. So the silence is measured here as
  // geometry rather than taken on trust from the desktop mount — and the
  // refusal, the one message that must survive, is measured for fit in the
  // place it had the least room.
  //
  // The chip lives behind "Show the other controls" on a phone: a fixture that
  // measured the resting row would find no chip, no box, and agree with itself.
  const phone = document.createElement('div');
  phone.className = 'effort-check-surface';
  phone.style.cssText =
    'width:390px;height:740px;position:absolute;top:0;left:0;display:flex;overflow:hidden';
  document.body.appendChild(phone);
  let redrawPhone = (): void => {};
  const phoneController = new ChatController('effort-phone', {
    send: () => {},
    onChange: () => redrawPhone(),
  } as never);
  phoneController.handle(snapshotFor('effort-phone', { ...baseCapabilities, efforts }) as never);
  const phoneRoot = createRoot(phone);
  const paintPhone = (): void => {
    phoneRoot.render(React.createElement(PhoneSurface, { controller: phoneController }));
  };
  paintPhone();
  redrawPhone = paintPhone;
  await wait(300);
  (phone.querySelector('[aria-label="Show the other controls"]') as HTMLElement | null)?.click();
  await wait(300);

  const phoneChip = phone.querySelector('[aria-label="Change how hard the agent thinks"]');
  check(
    'the effort control is reachable on a phone at all, behind the other controls',
    Boolean(phoneChip),
    phoneChip ? 'on the expanded row' : 'no chip even once the other controls are open',
  );

  answer(phoneController, 'effort-phone', 'live', 'Now thinking at max.', 'max');
  await wait(300);
  check(
    'a successful change on a phone covers neither the composer nor the bar, because nothing appears',
    !noticeIn(phone),
    noticeIn(phone) ? `a box reading "${noticeText(phone)}"` : 'nothing over the composer',
  );

  answer(phoneController, 'effort-phone', 'refused', REFUSAL, null);
  await wait(300);
  const refusalBox = noticeIn(phone)?.getBoundingClientRect();
  const fieldBox = composerField(phone)?.getBoundingClientRect();
  const navBox = (
    phone.querySelector('nav[aria-label="Go to"]') as HTMLElement | null
  )?.getBoundingClientRect();
  const phoneBox = phone.getBoundingClientRect();
  /** True when the two boxes share no pixel — 1px of slack for a shared border. */
  const clearOf = (a: DOMRect, b: DOMRect): boolean =>
    a.bottom <= b.top + 1 || a.top >= b.bottom - 1 || a.right <= b.left + 1 || a.left >= b.right - 1;
  check(
    'a refusal on a phone is on screen and clear of both the field and the bar',
    Boolean(refusalBox && fieldBox && navBox)
      && refusalBox!.height > 0
      && refusalBox!.top >= phoneBox.top - 1
      && refusalBox!.bottom <= phoneBox.bottom + 1
      && clearOf(refusalBox!, fieldBox!)
      && clearOf(refusalBox!, navBox!),
    [
      refusalBox
        ? `notice ${Math.round(refusalBox.top)}–${Math.round(refusalBox.bottom)}`
        : 'no refusal shown at all',
      fieldBox ? `field ${Math.round(fieldBox.top)}–${Math.round(fieldBox.bottom)}` : 'no composer',
      navBox ? `bar ${Math.round(navBox.top)}–${Math.round(navBox.bottom)}` : 'no bottom bar',
      `surface ${Math.round(phoneBox.top)}–${Math.round(phoneBox.bottom)}`,
    ].join(', '),
  );

  phoneRoot.unmount();
  phone.remove();
  still.remove();
}

/**
 * A remembered level opens the next conversation, never reaches into an old one,
 * and a reload still shows what the runtime is actually running at.
 *
 * Three regressions, all from the same review, and all of them need a mounted
 * ChatView because what went wrong lived in an effect and in what the chip drew.
 *
 * **Re-levelling a conversation that had already started** was the worst of
 * them. The seeding effect's other guards all pass for a conversation opened
 * weeks ago and merely clicked back into: the chat surface is keyed on the
 * session id so the effect remounts on every tab switch, `live` and the
 * published ladder both survive on the retained transcript, and a conversation
 * whose chip was never touched carries no `effortOverride`. So visiting a tab
 * silently re-levelled it from a browser preference — wrote the level onto its
 * server record and, on claude, pushed a hidden `/effort` turn into the running
 * process. Nothing about that is visible from a props assertion; the send is the
 * only trace, so the send is what is counted. `transcript.messages.length > 0`
 * is what tells the two cases apart, and both directions are asserted here so
 * that "send nothing, ever" cannot pass for a fix.
 *
 * **The runtime-reported level surviving a reload** is the third. A codex
 * session that launched at `xhigh` and is still running at `xhigh` has never
 * *chosen* a level, so its record holds nothing and the only witness is the
 * `effort` the server replays on the snapshot. `ChatTranscript.hydrate` used to
 * drop that field, and the chip fell back to the grey `effort` placeholder with
 * an empty meter over a session that was demonstrably thinking hard.
 */
async function checkARememberedLevelSeedsOnlyFreshWorkAndSurvivesAReload(): Promise<void> {
  const KEY = 'cc-web-chat-effort';
  // Put back afterwards, and read before anything is written: this key is real
  // user state, and the effort chip check above clears it outright. Neither
  // check may leave the other looking at what it wrote.
  const priorPreference = window.localStorage.getItem(KEY);
  window.localStorage.setItem(KEY, JSON.stringify({ claude: 'xhigh' }));

  const efforts = [
    { value: 'low', name: 'Low', rank: 0 },
    { value: 'medium', name: 'Medium', rank: 0.25 },
    { value: 'high', name: 'High', rank: 0.5 },
    { value: 'xhigh', name: 'Extra high', rank: 0.75 },
    { value: 'max', name: 'Max', rank: 1 },
  ];
  const capabilities = {
    streaming: true, thinking: true, toolCalls: false, diffs: false, permissions: false,
    interrupt: true, resume: true, fork: false, attachments: false, usage: true,
    cost: true, plan: false, efforts,
  };

  /**
   * A snapshot as the server sends it on a rejoin: live, ladder published, and
   * `effortOverride` absent because nobody ever picked a level here.
   */
  const snapshotFor = (
    sessionId: string,
    options: { messages: boolean; effort?: string },
  ): Record<string, unknown> => ({
    type: 'chat_snapshot',
    sessionId,
    effortOverride: null,
    snapshot: {
      sessionId,
      runtime: 'claude',
      state: 'idle',
      capabilities,
      messages: options.messages
        ? [
            {
              id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
              blocks: [{ kind: 'text', text: 'a conversation that already happened' }],
            },
          ]
        : [],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 1,
      live: true, bypassPermissions: false,
      ...(options.effort ? { effort: options.effort } : {}),
    },
  });

  const still = document.createElement('style');
  still.textContent =
    '.effort-seed-surface, .effort-seed-surface * { animation: none !important; transition: none !important; }';
  document.head.appendChild(still);

  /** Mount a ChatView over one snapshot and answer with what it asked the server for. */
  const mount = async (
    sessionId: string,
    options: { messages: boolean; effort?: string },
  ): Promise<{ sent: Array<Record<string, unknown>>; host: HTMLElement; unmount: () => void; controller: ChatController }> => {
    const host = document.createElement('div');
    host.className = 'effort-seed-surface';
    host.style.cssText = 'width:900px;height:600px;position:absolute;top:0;left:0;display:flex';
    document.body.appendChild(host);
    const sent: Array<Record<string, unknown>> = [];
    const controller = new ChatController(sessionId, {
      send: (message: unknown) => sent.push(message as Record<string, unknown>),
    } as never);
    controller.handle(snapshotFor(sessionId, options) as never);
    const root = createRoot(host);
    root.render(
      React.createElement(ChatView, {
        controller,
        runtime: 'claude',
        runtimeLabel: 'Claude',
        workingDir: '/tmp/project',
        view: DEFAULT_CHAT_VIEW,
        onViewChange: () => {},
      } as never),
    );
    await wait(300);
    return {
      sent, host, controller,
      unmount: () => {
        root.unmount();
        host.remove();
      },
    };
  };

  const picksIn = (sent: Array<Record<string, unknown>>): Array<Record<string, unknown>> =>
    sent.filter((message) => message.type === 'chat_set_effort');

  // 1. The conversation that has already started. Merely being looked at.
  const old = await mount('effort-seed-old', { messages: true });
  check(
    'opening a conversation that has already started never re-levels it from a browser preference',
    picksIn(old.sent).length === 0,
    JSON.stringify(picksIn(old.sent)),
  );
  old.unmount();

  // 2. The fresh one, so that "never send" cannot pass for the fix above.
  const fresh = await mount('effort-seed-fresh', { messages: false });
  check(
    'and a conversation that has not begun still opens at the level this runtime was last used at',
    picksIn(fresh.sent).length === 1 && picksIn(fresh.sent)[0].effort === 'xhigh',
    JSON.stringify(picksIn(fresh.sent)),
  );
  fresh.unmount();

  // 3. The reload. Preference cleared first, so the level on the chip can only
  // have come from the snapshot the server replayed and not from this browser.
  window.localStorage.removeItem(KEY);
  const reloaded = await mount('effort-seed-reload', { messages: true, effort: 'xhigh' });
  const chip = reloaded.host.querySelector(
    '[aria-label="Change how hard the agent thinks"]',
  ) as HTMLElement | null;
  check(
    'a reload of a session running at a level nobody chose still names that level',
    (chip?.textContent ?? '').includes('Extra high'),
    chip ? `chip reads "${(chip.textContent ?? '').trim()}"` : 'no chip',
  );

  // Counted off painted backgrounds rather than off the prop, because the grey
  // placeholder the bug produced is a chip that still renders a meter — an empty
  // one. Same canvas round-trip as the check above: Chrome serialises a computed
  // `color-mix(in oklab, …)` as `oklab(…)`, which no rgb() parser reads.
  const rgbOf = (value: string): string => {
    const canvas = document.createElement('canvas');
    canvas.width = 1;
    canvas.height = 1;
    const ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
    ctx.fillStyle = '#000';
    ctx.fillStyle = value;
    ctx.fillRect(0, 0, 1, 1);
    const pixel = ctx.getImageData(0, 0, 1, 1).data;
    return `${pixel[0]},${pixel[1]},${pixel[2]}`;
  };
  const borderRgb = rgbOf(
    getComputedStyle(document.documentElement).getPropertyValue('--border').trim(),
  );
  const meter = chip?.querySelector('span[aria-hidden="true"]');
  const litBars = Array.from(meter?.children ?? []).filter(
    (bar) => rgbOf(getComputedStyle(bar as HTMLElement).backgroundColor) !== borderRgb,
  ).length;
  check(
    'and draws a filled meter for it rather than the empty one a blank level gets',
    litBars >= 2,
    `${litBars} of ${meter?.children.length ?? 0} bars lit`,
  );
  check(
    'the transcript is where that level lives, so anything else can read it too',
    reloaded.controller.transcript.effort === 'xhigh',
    String(reloaded.controller.transcript.effort),
  );
  reloaded.unmount();

  // A snapshot from a runtime that never reported a level: "nobody said", which
  // is the state most conversations spend their life in, and not a throw.
  const silent = await mount('effort-seed-silent', { messages: true });
  check(
    'a session whose runtime never said reads as nobody having said, not as a level or a crash',
    silent.controller.transcript.effort === undefined,
    String(silent.controller.transcript.effort),
  );
  silent.unmount();

  still.remove();
  if (priorPreference === null) window.localStorage.removeItem(KEY);
  else window.localStorage.setItem(KEY, priorPreference);
}
import { UsageMeter } from '../../src/client/shell/chat/UsageMeter';
import { StatusPanel } from '../../src/client/shell/chat/StatusPanel';

/**
 * Issue #82: what a person actually sees about the context window.
 *
 * Three states, because they are three different answers and the product is
 * only useful if they are told apart. Measured against a real ceiling; measured
 * against no ceiling at all; and near enough to the edge that it has to say so
 * while there is still room to act.
 *
 * Rendered through the real stylesheets, because every figure here is a
 * `var(--...)` away from being unreadable.
 */
async function checkTheContextReadingIsHonestAboutItsCeiling(): Promise<void> {
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:520px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="../../dist/public/css/relay/relay.css">'
    + '<link rel="stylesheet" href="../../dist/public/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const capabilities = { usage: true, cost: true } as never;
  const render = (usage: Record<string, unknown>) => {
    const host = doc.createElement('div');
    doc.body.appendChild(host);
    const root = createRoot(host);
    root.render(React.createElement(UsageMeter, { usage: usage as never, capabilities }));
    return { host, root };
  };

  // A window the agent reported, comfortably below the line.
  const calm = render({
    totalTokens: 40000,
    contextWindow: 1000000,
    contextUsed: 40000,
    contextWindowSource: 'agent',
  });
  await wait(150);
  const calmText = (calm.host.textContent || '').replace(/\s+/g, ' ');
  check(
    'a measured context reads as used of total',
    calmText.includes('40.0k') && calmText.includes('1.0M') && calmText.includes('4%'),
    calmText || 'nothing rendered',
  );
  check(
    'and does not shout about a window that is nearly empty',
    !/almost full|filling up/i.test(calmText),
    calmText,
  );

  // The same conversation, near the edge.
  const full = render({
    totalTokens: 190000,
    contextWindow: 200000,
    contextUsed: 190000,
    contextWindowSource: 'agent',
  });
  await wait(150);
  const fullText = (full.host.textContent || '').replace(/\s+/g, ' ');
  check(
    'a context near its limit says so, and says how much is left',
    /almost full/i.test(fullText) && fullText.includes('10.0k'),
    fullText || 'nothing rendered',
  );
  check(
    'and tells the user what to do about it before the limit is reached',
    /compact|new conversation/i.test(fullText),
    fullText,
  );

  // An agent that reports occupancy and no ceiling, and whose provider had no
  // entry either. The reading must say that rather than going quiet.
  const unknown = render({ totalTokens: 8074, contextUsed: 8074 });
  await wait(150);
  const unknownText = (unknown.host.textContent || '').replace(/\s+/g, ' ');
  check(
    'an unestablished capacity is stated, not left blank',
    /size unknown/i.test(unknownText),
    unknownText || 'nothing rendered',
  );
  check(
    'and the figure that is known is still shown',
    unknownText.includes('8.1k'),
    unknownText,
  );
  check(
    'and no bar is drawn against a number nobody stands behind',
    !unknown.host.querySelector('[role="progressbar"]'),
    String(unknown.host.innerHTML).slice(0, 200),
  );

  // The panel, which is where the provenance and the warning are spelled out.
  const panelHost = doc.createElement('div');
  doc.body.appendChild(panelHost);
  const transcript = {
    subscribe: () => () => {},
    getVersion: () => 0,
    usage: {
      totalTokens: 190000,
      contextWindow: 200000,
      contextUsed: 190000,
      contextWindowSource: 'provider',
    },
  };
  const panelRoot = createRoot(panelHost);
  panelRoot.render(
    React.createElement(StatusPanel, { sessionId: '', transcript: transcript as never }),
  );
  await wait(300);
  const panelText = (panelHost.textContent || '').replace(/\s+/g, ' ');
  check(
    'the status panel warns when the context is nearly gone',
    /almost full/i.test(panelText),
    panelText.slice(0, 300) || 'nothing rendered',
  );
  check(
    'and says a looked-up window came from the provider, not the agent',
    /provider/i.test(panelText),
    panelText.slice(0, 300),
  );

  // Legibility: this is the readout someone glances at mid-session, and a
  // 10px warning is one nobody acts on.
  const warning = Array.from(panelHost.querySelectorAll('*')).find((node) =>
    /almost full/i.test(node.textContent || '') && node.children.length === 0,
  ) as HTMLElement | undefined;
  const size = warning ? parseFloat(doc.defaultView!.getComputedStyle(warning).fontSize) : 0;
  check(
    'the warning is set large enough to read',
    size >= 12,
    `${size}px`,
  );

  calm.root.unmount();
  full.root.unmount();
  unknown.root.unmount();
  panelRoot.unmount();
  frame.remove();
}

/**
 * Issue #137: what a person actually reads about their account.
 *
 * The panel used to draw a plan badge reading `max20`, a token meter reading
 * "0 of 220.0k" and a "Left 220.0k" for every user of every agent — all of it
 * from a CLI flag's default and a table written into this repository. So the
 * claim under test is a negative as much as a positive: with nothing reported
 * there must be no badge, no meter and no ceiling anywhere in the section, and
 * with something reported the figure on screen must be the one the provider
 * gave.
 *
 * Through the real stylesheets and asserted for visibility and computed size,
 * because a control at `opacity: 0` drops silently out of every geometry sweep
 * rather than failing one.
 */
async function checkTheAccountReadingIsOnlyEverWhatAProviderSaid(): Promise<void> {
  const realFetch = window.fetch;
  // What the status route answers with. Only the account half matters here; the
  // git half is answered as "not a repository" so that section renders too.
  let account: unknown = null;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    const body = url.includes('/status') ? { git: { repo: false }, account } : {};
    return new Response(JSON.stringify(body), {
      status: 200,
      headers: { 'content-type': 'application/json' },
    });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:520px;height:1000px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="../../dist/public/css/relay/relay.css">'
    + '<link rel="stylesheet" href="../../dist/public/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const view = doc.defaultView as Window;
  const mount = async (limits: unknown, runtimeLabel: string) => {
    const host = doc.createElement('div');
    doc.body.appendChild(host);
    const transcript = {
      subscribe: () => () => {},
      getVersion: () => 0,
      usage: {},
      limits,
    };
    const root = createRoot(host);
    root.render(
      React.createElement(StatusPanel, {
        sessionId: 'acct-check',
        transcript: transcript as never,
        runtimeLabel,
      }),
    );
    await wait(300);
    return { host, root, text: (host.textContent || '').replace(/\s+/g, ' ') };
  };

  // (a) A provider that stated a percentage and a reset.
  account = {
    runtime: 'claude',
    reporting: 'Claude reports which rate-limit window it is in and when that window resets.',
    cached: null,
    measured: null,
  };
  const reported = await mount(
    {
      billing: 'subscription',
      windows: [{
        kind: 'seven_day',
        status: 'allowed_warning',
        utilization: 0.96,
        resetsAt: new Date(Date.now() + 3 * 3600_000).toISOString(),
      }],
    },
    'Claude',
  );
  check(
    'a stated rate-limit window is shown as the percentage the provider gave',
    reported.text.includes('96%') && /seven day/i.test(reported.text),
    reported.text.slice(0, 400) || 'nothing rendered',
  );
  check(
    'and the reset time is shown beside it',
    /Resets/.test(reported.text),
    reported.text.slice(0, 400),
  );
  const bar = reported.host.querySelector('[role="progressbar"]:not([aria-valuenow="0"])') as HTMLElement | null;
  const barBox = bar?.getBoundingClientRect();
  const barStyle = bar ? view.getComputedStyle(bar) : null;
  check(
    'and the meter beside it is really on screen, not a zero-opacity ghost',
    Boolean(bar) && (barBox?.width ?? 0) > 50 && (barBox?.height ?? 0) > 0
      && barStyle?.visibility !== 'hidden' && Number(barStyle?.opacity ?? '0') > 0.5,
    `${barBox?.width ?? 0}x${barBox?.height ?? 0} opacity=${barStyle?.opacity}`,
  );
  check(
    'and no fabricated allowance appears anywhere in the panel',
    !/220\.0k|max20|188026/.test(reported.text),
    reported.text.slice(0, 400),
  );
  check(
    'one reading is a level, not a rate, so no time-to-empty is offered',
    /Not enough readings/i.test(reported.text) && !/At this rate/.test(reported.text),
    reported.text.slice(0, 400),
  );
  reported.root.unmount();

  // (b) An agent that reports nothing about an account.
  account = {
    runtime: 'kimi',
    reporting: 'Kimi Code reports nothing about an account over the protocol this app drives it on.',
    cached: null,
    measured: {
      from: 'a',
      to: 'b',
      hours: 24,
      // A window in which four turns ran and only two of them reported a cost:
      // the totals are real, and the honesty counters are what stop the other
      // two being averaged in as zeroes.
      totals: {
        turns: 4,
        modelTurns: 0,
        toolCalls: 3,
        inputTokens: 1000,
        outputTokens: 2000,
        cacheReadTokens: 0,
        cacheWriteTokens: 0,
        reasoningTokens: 0,
        totalTokens: 3000,
        costUsd: 0,
        tokensReportedTurns: 4,
        costReportedTurns: 0,
        modelTurnsReportedTurns: 0,
      },
    },
  };
  const silent = await mount(undefined, 'Kimi');
  check(
    'an agent that reports no account says so in words',
    /reports nothing about an account/i.test(silent.text),
    silent.text.slice(0, 400) || 'nothing rendered',
  );
  check(
    'and the section it is in draws no meter at all',
    !silent.host.querySelector('[role="progressbar"]'),
    String(silent.host.innerHTML).slice(0, 300),
  );
  check(
    'and the heading names that agent rather than Claude',
    /Kimi account/i.test(silent.text) && !/Claude rate limit/i.test(silent.text),
    silent.text.slice(0, 200),
  );
  check(
    'a cost nobody reported reads as not reported, not as $0.00',
    /Cost\s*not reported/i.test(silent.text) && !/\$0\.00/.test(silent.text),
    silent.text.slice(0, 400),
  );
  check(
    'while the tokens that were reported are still shown, with a rate',
    /3\.0k/.test(silent.text) && /\/h/.test(silent.text),
    silent.text.slice(0, 400),
  );
  const sentence = Array.from(silent.host.querySelectorAll('*')).find(
    (node) => /reports nothing about an account/i.test(node.textContent || '')
      && node.children.length === 0,
  ) as HTMLElement | undefined;
  const sentenceSize = sentence ? parseFloat(view.getComputedStyle(sentence).fontSize) : 0;
  check(
    'and that sentence is set large enough to read',
    sentenceSize >= 10,
    `${sentenceSize}px`,
  );
  silent.root.unmount();

  // (c) A window with a reset and no percentage, which is four captures in five.
  account = {
    runtime: 'claude',
    reporting: 'Claude reports which rate-limit window it is in and when that window resets.',
    cached: null,
    measured: null,
  };
  const noPercent = await mount(
    {
      billing: 'unknown',
      windows: [{
        kind: 'five_hour',
        status: 'allowed',
        resetsAt: new Date(Date.now() + 2 * 3600_000).toISOString(),
      }],
    },
    'Claude',
  );
  check(
    'a window with no percentage says "not reported" instead of 0%',
    /not reported/i.test(noPercent.text) && !/\b0%/.test(noPercent.text),
    noPercent.text.slice(0, 400) || 'nothing rendered',
  );
  check(
    'and draws no bar against a number nobody gave',
    !noPercent.host.querySelector('[role="progressbar"]'),
    String(noPercent.host.innerHTML).slice(0, 300),
  );
  check(
    'and does not claim a billing mode the runtime never stated',
    /did not say whether/i.test(noPercent.text) && !/Billed as/.test(noPercent.text),
    noPercent.text.slice(0, 400),
  );
  noPercent.root.unmount();

  // (d) The state every Claude conversation is in from its first turn onwards:
  // a window it stated itself, and a plan name it has never stated and never
  // will, filled in from the CLI's cache on this server. The caveat has to
  // survive that — it is the whole point of the caveat, and a section that
  // labels itself only when *nothing* was spoken hides it exactly here.
  account = {
    runtime: 'claude',
    reporting: 'Claude reports which rate-limit window it is in and when that window resets.',
    cached: {
      planName: 'claude max 20x',
      windows: [],
      asOf: new Date(Date.now() - 3 * 3600_000).toISOString(),
    },
    measured: null,
  };
  const cachedPlan = await mount(
    {
      billing: 'subscription',
      windows: [{
        kind: 'five_hour',
        status: 'allowed',
        resetsAt: new Date(Date.now() + 2 * 3600_000).toISOString(),
      }],
    },
    'Claude',
  );
  check(
    'a plan name that came from the server\'s CLI cache is labelled as such, even mid-conversation',
    /claude max 20x/i.test(cachedPlan.text) && /as of/i.test(cachedPlan.text)
      && /this server is signed in as/i.test(cachedPlan.text),
    cachedPlan.text.slice(0, 500) || 'nothing rendered',
  );
  check(
    'and the label names the plan alone, not the window this conversation reported itself',
    /The plan above was/.test(cachedPlan.text) && !/figures above/.test(cachedPlan.text),
    cachedPlan.text.slice(0, 500),
  );
  cachedPlan.root.unmount();

  // (e) A conversation that has never been launched. The route cannot scope a
  // measurement without an agent, so it answers `measured: null` — which says
  // nothing at all about whether this server keeps a usage record.
  account = {
    runtime: null,
    reporting: 'Nothing is running here yet, so nobody has been asked.',
    cached: null,
    measured: null,
  };
  const unlaunched = await mount(undefined, 'Agent');
  check(
    'a conversation that has never run says so, rather than blaming the server\'s record-keeping',
    /Nothing has run in this conversation yet/i.test(unlaunched.text)
      && !/not keeping a usage record/i.test(unlaunched.text),
    unlaunched.text.slice(0, 500) || 'nothing rendered',
  );
  unlaunched.root.unmount();

  frame.remove();
  window.fetch = realFetch;
}

/**
 * `/clear` resets the figures over the chat, rather than carrying them into the
 * conversation that replaces the one they were about.
 *
 * Driven through the real controller and the real header, because the claim is
 * about what someone reads after clearing: a bill of $0, no tokens, and an
 * empty context bar. Asserting the folded state alone would pass just as well
 * for a meter that had gone blank — and a readout that disappears when you
 * clear looks like one that broke, not one that reset.
 */
async function checkClearingResetsTheFiguresAboveTheChat(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1000px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('cleared-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'cleared-check',
    snapshot: {
      sessionId: 'cleared-check',
      runtime: 'claude',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: false, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: false,
      },
      messages: [],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: false,
    },
  } as never);

  const push = (event: Record<string, unknown>, seq: number): void => {
    controller.handle({
      type: 'chat_event',
      sessionId: 'cleared-check',
      event: { seq, ts: 1_700_000_000_000 + seq, ...event },
    } as never);
  };

  // A conversation with some hours on it: expensive, and most of a large
  // window used up — which is the state people clear from.
  push({ t: 'msg_start', id: 'u1', role: 'user', turnId: 'turn-1' }, 1);
  push({ t: 'block_start', msgId: 'u1', index: 0, block: { kind: 'text', text: 'go' } }, 2);
  push({ t: 'msg_end', msgId: 'u1' }, 3);
  push({ t: 'msg_start', id: 'a1', role: 'assistant', turnId: 'turn-1' }, 4);
  push({ t: 'block_start', msgId: 'a1', index: 0, block: { kind: 'thinking', text: 'weighing it' } }, 5);
  push({
    t: 'block_start',
    msgId: 'a1',
    index: 1,
    block: { kind: 'tool', toolId: 'x1', name: 'Bash', status: 'done', durationMs: 90000 },
  }, 6);
  push({ t: 'block_start', msgId: 'a1', index: 2, block: { kind: 'text', text: 'done' } }, 7);
  push({ t: 'msg_end', msgId: 'a1', usage: { inputTokens: 120000, outputTokens: 43000 } }, 8);
  push({ t: 'turn_end', turnId: 'turn-1', usage: { costUsd: 12.4 } }, 9);
  push({
    t: 'usage',
    usage: { contextWindow: 200000, contextUsed: 163000, contextWindowSource: 'agent' },
  }, 10);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(300);

  const meterText = (): string =>
    (host.querySelector('[role="group"][aria-label="Session usage"]')?.textContent ?? '')
      .replace(/\s+/g, ' ');

  const before = meterText();
  check(
    'the header reads the conversation’s spend before it is cleared',
    /\$12\.40/.test(before) && /8[12]%/.test(before),
    before || 'no session meter on screen',
  );

  // What the turn itself says, on the rule that opens it: the counts, the
  // clock and the money on one line.
  const stripText = (): string =>
    ((host.querySelector('[data-turn-id]') as HTMLElement | null)?.textContent ?? '')
      .replace(/\s+/g, ' ');
  const beforeSpend = stripText();
  check(
    'a turn shows its steps, its reasoning and its clock',
    /1 tool/.test(beforeSpend) && /1 reasoning/.test(beforeSpend) && /\dm|\ds/.test(beforeSpend),
    beforeSpend || 'no turn strip on screen',
  );

  controller.handle({
    type: 'chat_turn_spend',
    sessionId: 'cleared-check',
    turnId: 'turn-1',
    usage: { costUsd: 12.4 },
  } as never);
  await wait(200);
  const afterSpend = stripText();
  check(
    'and what it cost, on the same line as the rest',
    /\$12\.40/.test(afterSpend) && /1 tool/.test(afterSpend) && /1 reasoning/.test(afterSpend),
    afterSpend || 'no turn strip on screen',
  );

  push({ t: 'marker', kind: 'cleared', detail: 'started a new conversation' }, 11);
  await wait(300);

  const after = meterText();
  check(
    'clearing puts the money back to zero',
    /\$0\.00/.test(after) && !/12\.40/.test(after),
    after || 'no session meter on screen',
  );
  check(
    'and the tokens with it',
    /\b0 tok/.test(after),
    after,
  );
  check(
    'and the context bar reads empty rather than still full',
    // Not `\b0%`: the cost runs straight into the percentage — "$0.000%" — and
    // there is no word boundary between two zeroes.
    /0%/.test(after) && !/8[12]%/.test(after),
    after,
  );
  // The bar itself, not only the number beside it: this is the piece someone
  // reads at a glance to decide whether there is room to keep going.
  const bar = host.querySelector('[role="progressbar"]');
  check(
    'the bar agrees with the figure it sits next to',
    bar?.getAttribute('aria-valuenow') === '0',
    `aria-valuenow=${bar?.getAttribute('aria-valuenow') ?? 'no bar'}`,
  );
  check(
    'and the meter is still there to be read, rather than gone',
    Boolean(host.querySelector('[role="group"][aria-label="Session usage"]')),
    after || 'the header went blank',
  );

  root.unmount();
  host.remove();
}

/**
 * Issue #136: a runtime that reports nothing says so, where a person looks.
 *
 * kimi sends no token counts and no prices — probed, and the same in the
 * capture under `test/fixtures/chat/acp-kimi-tools.jsonl` — and the header used
 * to render nothing at all for it. Nothing is also what a conversation that has
 * simply not spent anything yet looks like, so a user could not tell "this
 * agent will never tell you" from "hold on".
 *
 * Driven through the real controller, the real header and the real composer,
 * because the claim is about what is on screen: the folded state holding
 * `usageSource: 'none'` proves only that the layer that was changed changed.
 * And measured rather than merely found — an opacity-0 span is present in every
 * `querySelector` and readable by nobody.
 *
 * The events are the ones a kimi session produces: an answer, a turn that ends
 * carrying no figures but the spoken silence the session writes onto it, and a
 * window that came from the model's provider rather than from kimi.
 *
 * Two mounts, because the surface is two surfaces: the desktop strip below and
 * the phone's collapsed header after it, which is a different component with a
 * different budget for words.
 */
function silentRuntimeController(
  id: string,
  options: { bypassPermissions?: boolean; state?: string } = {},
): ChatController {
  const controller = new ChatController(id, { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: id,
    snapshot: {
      sessionId: id,
      runtime: 'kimi',
      state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: false, fork: false, attachments: false,
        // Honest, as of #136, and the reason the label must not sit behind them.
        usage: false, cost: false, plan: true,
      },
      messages: [],
      pendingPermissions: [],
      queued: [],
      firstSeq: 1,
      replayFrom: 1,
      cursor: 1,
      live: true,
      bypassPermissions: options.bypassPermissions ?? false,
    },
  } as never);

  const push = (event: Record<string, unknown>, seq: number): void => {
    controller.handle({
      type: 'chat_event',
      sessionId: id,
      event: { seq, ts: 1_700_000_000_000 + seq, ...event },
    } as never);
  };

  push({ t: 'msg_start', id: 'u1', role: 'user', turnId: 'turn-1' }, 1);
  push({ t: 'block_start', msgId: 'u1', index: 0, block: { kind: 'text', text: 'go' } }, 2);
  push({ t: 'msg_end', msgId: 'u1' }, 3);
  push({ t: 'msg_start', id: 'a1', role: 'assistant', turnId: 'turn-1' }, 4);
  push({ t: 'block_start', msgId: 'a1', index: 0, block: { kind: 'text', text: 'DONE' } }, 5);
  push({ t: 'msg_end', msgId: 'a1' }, 6);
  push({ t: 'turn_end', turnId: 'turn-1', usage: { usageSource: 'none', costSource: 'none' } }, 7);
  push({
    t: 'usage',
    usage: { contextWindow: 1048576, contextWindowSource: 'provider' },
  }, 8);
  if (options.state) push({ t: 'state', state: options.state }, 9);

  return controller;
}

/** The desktop strip, at the width the header actually gets on a laptop. */
async function checkASilentRuntimeSaysSoRatherThanGoingBlank(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1000px;height:700px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = silentRuntimeController('silent-check');

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'kimi',
      runtimeLabel: 'Kimi',
      workingDir: '/tmp/project',
      view: DEFAULT_CHAT_VIEW,
      onViewChange: () => {},
    } as never),
  );
  await wait(300);

  const meter = host.querySelector('[role="group"][aria-label="Session usage"]') as HTMLElement | null;
  const meterText = (meter?.textContent ?? '').replace(/\s+/g, ' ');
  check(
    'a runtime that reports nothing says so in the header instead of leaving it blank',
    /not reported/i.test(meterText),
    meterText || 'the header showed nothing at all',
  );
  check(
    'and does not manufacture a zero out of a measurement nobody took',
    !/\$0\.00/.test(meterText) && !/\b0 tok/.test(meterText),
    meterText,
  );
  check(
    'and still shows the window the model’s provider could size',
    /\? of 1\.0M/.test(meterText),
    meterText,
  );

  // Visible, not merely in the DOM. Everything below is measured off the leaf
  // that carries the words.
  const label = Array.from(host.querySelectorAll('*')).find(
    (node) => node.children.length === 0 && /not reported/i.test(node.textContent || ''),
  ) as HTMLElement | undefined;
  const style = label ? getComputedStyle(label) : null;
  const box = label ? label.getBoundingClientRect() : null;
  check(
    'the words are painted rather than present',
    Boolean(
      box && box.width > 0 && box.height > 0
      && style && style.visibility !== 'hidden' && style.display !== 'none'
      && Number(style.opacity) > 0.5,
    ),
    label
      ? `${Math.round(box!.width)}x${Math.round(box!.height)} opacity=${style!.opacity} visibility=${style!.visibility}`
      : 'no element carries the words',
  );
  const fontSize = style ? parseFloat(style.fontSize) : 0;
  check(
    'and set at the size the rest of the header strip is, not shrunk away',
    fontSize >= 10,
    `${fontSize}px`,
  );

  // The composer's status line, the other place the figures live. It used to
  // degrade to a bare turn number for a runtime like this.
  const readout = (host.textContent ?? '').replace(/\s+/g, ' ');
  check(
    'the composer says it too, rather than leaving a bare turn number',
    /turn 1 · usage not reported/.test(readout),
    readout.slice(-200) || 'nothing rendered',
  );

  root.unmount();
  host.remove();
}

/**
 * The same sentence on the surface with the least room for it (#136, AC4).
 *
 * The phone's header is collapsed by default and is one fixed-height row: a
 * status word, then the cost, the bypass shield and the chevron pushed to the
 * right edge. Before this the cost was `$0.12` or nothing at all; it is now up
 * to seventeen characters of "cost not reported" in the same strip, at 15px,
 * against 390px of screen — and the two spans either side of it are
 * `flex: 0 0 auto`, so anything that does not fit does not shrink, it leaves
 * the header. The desktop mount above can never see that: it has 1000px.
 *
 * So this measures the strip rather than reading it. The words have to be on
 * one line, the chevron has to still be inside the header, and the row has to
 * still be one row — with the widest state label the header has ("asked you a
 * question") and the shield showing, which is the tightest this strip ever
 * gets. Text metrics are the reason it is a browser check and not a string
 * match on `renderToStaticMarkup`, which has no layout at all.
 */
async function checkTheSilenceFitsThePhonesCollapsedHeader(): Promise<void> {
  const host = document.createElement('div');
  // No `overflow:hidden`: hiding the overflow is exactly what would stop this
  // check seeing the chevron leave the strip.
  host.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = silentRuntimeController('silent-phone', {
    bypassPermissions: true,
    state: 'awaiting_answer',
  });

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'kimi',
      runtimeLabel: 'Kimi',
      workingDir: '/tmp/project',
      // ChatView publishes `PhoneContext` from this itself, so a provider
      // wrapped around it would be overwritten and the header would render at
      // desktop sizing while agreeing that it is a phone.
      isMobile: true,
      view: { ...DEFAULT_CHAT_VIEW, panelOpen: false },
      onViewChange: () => {},
      onOpenConversations: () => {},
    } as never),
  );
  await wait(300);

  const strip = host.querySelector('[aria-expanded][aria-controls]') as HTMLElement | null;
  const stripText = (strip?.textContent ?? '').replace(/\s+/g, ' ');
  check(
    'the phone’s collapsed header says the cost is not reported, rather than nothing',
    /not reported/i.test(stripText) && !/\$0\.00/.test(stripText),
    stripText || 'no collapsed header strip on screen',
  );

  const label = strip
    ? (Array.from(strip.querySelectorAll('*')).find(
        (node) => node.children.length === 0 && /not reported/i.test(node.textContent || ''),
      ) as HTMLElement | undefined)
    : undefined;
  const style = label ? getComputedStyle(label) : null;
  const box = label ? label.getBoundingClientRect() : null;
  const fontSize = style ? parseFloat(style.fontSize) : 0;
  check(
    'and paints the words at the size the rest of the strip is',
    Boolean(
      box && box.width > 0 && box.height > 0
      && style && style.visibility !== 'hidden' && style.display !== 'none'
      && Number(style.opacity) > 0.5,
    ) && fontSize >= 15,
    label
      ? `${Math.round(box!.width)}x${Math.round(box!.height)} ${fontSize}px opacity=${style!.opacity}`
      : 'no element carries the words',
  );
  // One line: a phrase that wrapped would double the leaf's height, and this
  // row is fixed at 44px with a status word and three icons already on it.
  check(
    'without wrapping onto a second line inside a one-line strip',
    Boolean(box && fontSize && box.height <= fontSize * 1.8),
    box ? `${Math.round(box.height)}px tall at ${fontSize}px` : 'no element carries the words',
  );

  // The two things the strip exists to carry, both of which live to the right
  // of the new words and neither of which may shrink.
  const stripBox = strip?.getBoundingClientRect();
  const chevron = strip?.querySelector('svg:last-of-type') as SVGElement | null;
  const chevronBox = chevron?.getBoundingClientRect();
  check(
    'the chevron that opens the header is still inside it',
    Boolean(stripBox && chevronBox && chevronBox.width > 0 && chevronBox.right <= stripBox.right + 0.5),
    chevronBox && stripBox
      ? `chevron right ${Math.round(chevronBox.right)} vs strip right ${Math.round(stripBox.right)}`
      : 'no chevron in the strip',
  );
  const header = strip?.closest('header') as HTMLElement | null;
  const headerBox = header?.getBoundingClientRect();
  check(
    'and the collapsed header is still one row of the height it was',
    Boolean(headerBox && headerBox.height <= 56),
    headerBox ? `${Math.round(headerBox.height)}px tall` : 'no header',
  );
  check(
    'and nothing on the strip is pushed off the side of the phone',
    Boolean(strip && strip.scrollWidth <= strip.clientWidth + 1),
    strip ? `content ${strip.scrollWidth}px in a ${strip.clientWidth}px strip` : 'no strip',
  );

  // The other surface this change lengthened, and the other one with no room:
  // the composer's status line, which on a phone lives behind the tools row and
  // holds its figures in one unshrinkable nowrap span.
  (host.querySelector('[aria-label="Show the other controls"]') as HTMLElement | null)?.click();
  await wait(200);
  const readout = Array.from(host.querySelectorAll('span')).find(
    (node) => /usage not reported/.test(node.textContent || ''),
  ) as HTMLElement | undefined;
  const readoutBox = readout?.getBoundingClientRect();
  check(
    'the composer’s status line says it on a phone as well',
    Boolean(readoutBox && readoutBox.width > 0),
    readout ? (readout.textContent ?? '').replace(/\s+/g, ' ') : 'no status line on the phone composer',
  );
  check(
    'and says it inside the width of the phone rather than off the edge',
    Boolean(readoutBox && readoutBox.left >= -0.5 && readoutBox.right <= 390.5),
    readoutBox
      ? `${Math.round(readoutBox.left)}–${Math.round(readoutBox.right)} of 0–390`
      : 'no status line on the phone composer',
  );

  root.unmount();
  host.remove();
}

/**
 * The shell inside a conversation can be driven from a phone.
 *
 * Issue #21 stopped every terminal in this app from summoning the on-screen
 * keyboard — it used to pop over half the screen on every tap — and gave the
 * terminal surface a key strip in exchange. The pane inside a conversation is a
 * session of its own with its own socket, so it inherited the suppression and
 * none of the keys: no Escape, no Tab, no Enter, no arrows, no Ctrl. Readable,
 * and impossible to type into.
 *
 * Driven rather than inspected, because a strip that renders and writes to the
 * wrong session is the failure this is about: the keys are asserted by what
 * leaves *this* pane's socket. The server is faked at both ends — the session it
 * would create and the socket it would open — since where a key arrives is the
 * question, and a pty is not part of it.
 */
async function checkTheConversationsTerminalCanBeDrivenFromAPhone(): Promise<void> {
  const frames: string[] = [];
  const opened: string[] = [];

  const realFetch = window.fetch;
  const realWebSocket = window.WebSocket;

  window.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    if (url.includes('/api/sessions/')) {
      return new Response(JSON.stringify({ sessionId: 'shell-in-a-conversation' }), {
        status: 200,
        headers: { 'content-type': 'application/json' },
      });
    }
    return realFetch(input as never, init);
  }) as typeof window.fetch;

  class FakeSocket {
    static readonly OPEN = 1;
    readyState = FakeSocket.OPEN;
    onopen: (() => void) | null = null;
    onmessage: ((event: MessageEvent) => void) | null = null;
    onclose: (() => void) | null = null;
    onerror: (() => void) | null = null;
    constructor(url: string) {
      opened.push(url);
      // Asynchronously, as a real one connects: the pane sends its geometry
      // from `onopen`, and a handler called before it is assigned is a handler
      // that never runs.
      setTimeout(() => this.onopen?.(), 0);
    }
    send(data: string): void {
      frames.push(data);
    }
    close(): void {
      this.readyState = 3;
    }
  }
  window.WebSocket = FakeSocket as never;

  const host = document.createElement('div');
  // Above whatever earlier checks left mounted, because `elementFromPoint` is
  // asked below whether a thumb actually reaches these keys and the first
  // check's terminal is still sitting in the same corner. Bottom-aligned, which
  // is where the split lives: under the transcript, over the composer.
  host.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;z-index:9999;'
    + 'display:flex;flex-direction:column;justify-content:flex-end;background:var(--background)';
  document.body.appendChild(host);

  const props = {
    chatSessionId: 'phone-conversation',
    workingDir: '/home/dev/projects/alpha',
    height: 300,
    onResize: () => {},
    onClose: () => {},
    theme: 'dark' as const,
  };

  const root = createRoot(host);
  root.render(React.createElement(TerminalSplit, { ...props, isMobile: true }));
  for (let i = 0; i < 40 && opened.length === 0; i++) await wait(50);
  await wait(200);

  const strip = host.querySelector('[role="group"][aria-label="Terminal keys"]') as HTMLElement | null;
  check(
    'the shell inside a conversation carries the on-screen keys on a phone',
    Boolean(strip),
    strip ? 'the strip is there' : 'the split renders no strip, so the pane cannot be typed into',
  );

  if (strip) {
    const keys = [
      'Latch Ctrl for the next key', 'Send Escape', 'Send Tab', 'Send Enter',
      'Send Up arrow', 'Send Down arrow', 'Send Left arrow', 'Send Right arrow',
      'Show on-screen keyboard',
    ];
    const missing = keys.filter((label) => !strip.querySelector(`[aria-label="${label}"]`));
    check(
      'and every key a phone keyboard does not have',
      missing.length === 0,
      missing.join(', ') || `all ${keys.length}`,
    );

    // Present is not reachable: the strip lives inside the split's own height,
    // so a key drawn under the terminal body or below the pane's bottom edge
    // would read as fine in the markup and be untappable on glass.
    const unreachable = keys.filter((label) => {
      const button = strip.querySelector(`[aria-label="${label}"]`) as HTMLElement | null;
      if (!button) return true;
      const box = button.getBoundingClientRect();
      const hit = document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2);
      return !hit || !button.contains(hit);
    });
    check(
      'each of them is the thing under the finger',
      unreachable.length === 0,
      unreachable.join(', ') || 'all reachable',
    );

    const terminal = host.querySelector('.xterm') as HTMLElement | null;
    const termBox = terminal?.getBoundingClientRect();
    const stripBox = strip.getBoundingClientRect();
    check(
      'the keys sit under the shell rather than over it',
      Boolean(termBox) && termBox!.bottom <= stripBox.top + 1 && termBox!.height > 60,
      termBox
        ? `terminal ${Math.round(termBox.height)}px tall, ending at ${Math.round(termBox.bottom)}, strip from ${Math.round(stripBox.top)}`
        : 'no terminal in the split',
    );

    const press = (label: string): void => {
      const button = strip.querySelector(`[aria-label="${label}"]`) as HTMLElement | null;
      button?.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, cancelable: true }));
      button?.dispatchEvent(new PointerEvent('pointerup', { bubbles: true, cancelable: true }));
    };

    /** What has reached this pane's socket as terminal input, in order. */
    const typed = (): string[] =>
      frames
        .map((frame) => {
          try {
            return JSON.parse(frame) as { type?: string; data?: string };
          } catch {
            return {};
          }
        })
        .filter((message) => message.type === 'input')
        .map((message) => String(message.data));

    press('Send Escape');
    press('Send Tab');
    press('Send Enter');
    await wait(150);
    check(
      'pressing them types into the conversation’s own shell',
      typed().join('|') === '\x1b|\t|\r',
      JSON.stringify(typed()),
    );
    check(
      'over that shell’s socket rather than the session the app has in focus',
      opened.length === 1 && opened[0].includes('shell-in-a-conversation'),
      opened.join(', ') || 'nothing ever connected',
    );

    const ctrl = strip.querySelector('[aria-label="Latch Ctrl for the next key"]') as HTMLElement | null;
    press('Latch Ctrl for the next key');
    await wait(150);
    check(
      'Ctrl latches here too, and paints itself engaged',
      ctrl?.getAttribute('aria-pressed') === 'true',
      `aria-pressed=${ctrl?.getAttribute('aria-pressed') ?? 'no Ctrl key'}`,
    );

    press('Send Left arrow');
    await wait(150);
    check(
      'so the next key goes out modified',
      typed().slice(-1)[0] === '\x1b[1;5D',
      JSON.stringify(typed().slice(-1)),
    );
    check(
      'and the latch lets go after the one key',
      ctrl?.getAttribute('aria-pressed') === 'false',
      `aria-pressed=${ctrl?.getAttribute('aria-pressed') ?? 'no Ctrl key'}`,
    );

    press('Send Up arrow');
    await wait(150);
    check(
      'an unlatched arrow is the plain one',
      typed().slice(-1)[0] === '\x1b[A',
      JSON.stringify(typed().slice(-1)),
    );

    // The letters, which no strip can carry: since #21 a tap on a terminal no
    // longer summons the keyboard, so this button is the only way to type a
    // word into this pane — and it has to summon it against *this* textarea,
    // not the main terminal's.
    press('Show on-screen keyboard');
    await wait(150);
    const textarea = host.querySelector('.xterm-helper-textarea') as HTMLTextAreaElement | null;
    check(
      'and the keyboard can be summoned over this pane',
      textarea?.inputMode === 'text' && document.activeElement === textarea,
      textarea
        ? `inputMode=${textarea.inputMode} focused=${document.activeElement === textarea}`
        : 'the pane has no input area',
    );
  }

  root.unmount();

  // Nothing of this on a desktop: those keys are on the keyboard already, and
  // the strip would cost the shell three rows to say so.
  const desktop = createRoot(host);
  desktop.render(
    React.createElement(TerminalSplit, {
      ...props,
      chatSessionId: 'desktop-conversation',
      isMobile: false,
    }),
  );
  await wait(400);
  check(
    'and a desktop split is left exactly as it was',
    !host.querySelector('[aria-label="Terminal keys"]'),
    host.querySelector('[aria-label="Terminal keys"]') ? 'the strip followed onto the desktop' : 'no strip',
  );
  desktop.unmount();

  host.remove();
  // The panes outlive the component that mounted them on purpose, so releasing
  // them is this fixture's job — otherwise their xterms and their sockets stay
  // alive for every check after this one.
  forgetTerminals('phone-conversation');
  forgetTerminals('desktop-conversation');
  window.fetch = realFetch;
  window.WebSocket = realWebSocket;
}

/**
 * The two chat destinations the phone scale stopped short of (issue #51).
 *
 * The bar leads to five places and two of them were still drawn for a mouse:
 * the file tree's rows were 26px tall and edge to edge, with the size figure
 * beside each name at 10px, and the shell's tab strip was 28px of 22px tabs
 * with a 14px close button two pixels from its neighbour.
 *
 * Measured against the components directly, not through the shell: reaching
 * the tree needs the workspace API and reaching the shell needs a pty, and the
 * bar-driven pass above already covers the route. What is asserted here is the
 * geometry of the surfaces themselves, including the states the route does not
 * reach — an expanded subdirectory, a changed file's badge.
 *
 * Each half is asserted twice, once inside a phone provider and once outside
 * it. Nothing about this issue may move on a desktop, and a check that only
 * looks at the phone cannot tell a scale that was applied from a scale that
 * replaced the desktop one.
 */
async function checkTheFileTreeAndTheShellAreSizedForAThumb(): Promise<void> {
  const ROOT = '/home/dev/projects/webcli';
  const entries = [
    { name: 'src', path: `${ROOT}/src`, isDirectory: true },
    { name: 'package.json', path: `${ROOT}/package.json`, isDirectory: false, size: 4312 },
    { name: 'README.md', path: `${ROOT}/README.md`, isDirectory: false, size: 918 },
  ];
  const children = [
    { name: 'index.ts', path: `${ROOT}/src/index.ts`, isDirectory: false, size: 2048 },
    { name: 'server.ts', path: `${ROOT}/src/server.ts`, isDirectory: false, size: 15360 },
  ];

  const mount = (
    css: string,
    node: React.ReactElement,
  ): { host: HTMLElement; root: ReturnType<typeof createRoot> } => {
    const host = document.createElement('div');
    host.style.cssText = css;
    document.body.appendChild(host);
    const root = createRoot(host);
    root.render(node);
    return { host, root };
  };

  const tree = (phone: boolean): React.ReactElement =>
    React.createElement(
      PhoneContext.Provider,
      { value: phone },
      React.createElement(FileTreePanel, {
        root: ROOT,
        entries,
        onExpand: () => Promise.resolve(children),
        onOpen: () => {},
        // A row carrying a change badge is the busiest a row gets, and the
        // badge is the smallest type in it — 10px, from a primitive that has
        // no phone size of its own.
        changed: { [`${ROOT}/package.json`]: 'update', [`${ROOT}/src/index.ts`]: 'create' },
        onRefresh: () => {},
      } as never),
    );

  const shell = (phone: boolean, id: string): React.ReactElement =>
    React.createElement(TerminalSplit, {
      chatSessionId: id,
      workingDir: ROOT,
      height: 260,
      onResize: () => {},
      onClose: () => {},
      isMobile: phone,
      theme: 'dark',
    } as never);

  const COLUMN = 'position:absolute;top:0;left:0;display:flex;flex-direction:column;overflow:hidden';

  // The tree, on a phone.
  {
    const { host, root } = mount(`width:390px;height:740px;${COLUMN}`, tree(true));
    await wait(300);
    // Opened, because a nested level is a different code path — the rows under
    // an expanded directory are rendered by a second call with a deeper indent,
    // and an indent is exactly the sort of thing that eats a row's height.
    (host.querySelector('[role="treeitem"]') as HTMLElement | null)?.click();
    await wait(250);
    settle(document);

    const rows = Array.from(host.querySelectorAll<HTMLElement>('[role="treeitem"]')).filter(isPainted);
    check('the file tree draws its rows on a phone', rows.length >= 5, `${rows.length} rows`);

    const short = rows.filter((row) => laidOutSize(row).height < PHONE_TARGET);
    check(
      `every file tree row is at least ${PHONE_TARGET}px tall on a phone`,
      short.length === 0,
      short.length
        ? short.slice(0, 6).map((r) => `${describe(r)}=${laidOutSize(r).height}px`).join(' | ')
        : `${rows.length} rows`,
    );

    // Rows stack, so the gap that matters between them is the vertical one —
    // the rule in assertPhoneSurface only compares controls sitting side by
    // side, which no two rows of a tree ever do.
    const byTop = [...rows].sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
    const touching: string[] = [];
    for (let i = 1; i < byTop.length; i++) {
      const gap = byTop[i].getBoundingClientRect().top - byTop[i - 1].getBoundingClientRect().bottom;
      if (gap < PHONE_GAP - 0.5) {
        touching.push(`${describe(byTop[i - 1])}↔${describe(byTop[i])}=${Math.round(gap)}px`);
      }
    }
    check(
      `file tree rows are at least ${PHONE_GAP}px apart on a phone`,
      touching.length === 0,
      touching.length ? touching.slice(0, 6).join(' | ') : `${rows.length} rows`,
    );

    const tiny = paintedText(host).filter((t) => t.size < PHONE_MIN_TEXT - 0.01);
    check(
      `no text in the file tree is smaller than ${PHONE_MIN_TEXT}px on a phone`,
      tiny.length === 0,
      tiny.length
        ? tiny.slice(0, 8).map((t) => `${describe(t.node, t.text)}@${t.size}px`).join(' | ')
        : 'all legible',
    );

    // The strip at the top of the tree has to be as tall as what is in it:
    // IconButton takes the touch floor on a phone by itself, so a 34px header
    // left the one control that reloads the tree hanging out of both ends of
    // its own border.
    const refresh = host.querySelector('[aria-label="Refresh file tree"]') as HTMLElement | null;
    const strip = refresh?.parentElement ?? null;
    const refreshBox = refresh?.getBoundingClientRect();
    const stripBox = strip?.getBoundingClientRect();
    check(
      'the file tree’s refresh control fits inside its own strip on a phone',
      Boolean(refreshBox && stripBox)
        && refreshBox!.top >= stripBox!.top - 0.5
        && refreshBox!.bottom <= stripBox!.bottom + 0.5,
      refreshBox && stripBox
        ? `control ${Math.round(refreshBox.top)}–${Math.round(refreshBox.bottom)},`
          + ` strip ${Math.round(stripBox.top)}–${Math.round(stripBox.bottom)}`
        : 'no refresh control',
    );

    root.unmount();
    host.remove();
  }

  // And the same tree on a desktop, unchanged.
  {
    const { host, root } = mount(`width:900px;height:600px;${COLUMN}`, tree(false));
    await wait(300);
    settle(document);

    const rows = Array.from(host.querySelectorAll<HTMLElement>('[role="treeitem"]')).filter(isPainted);
    const heights = Array.from(new Set(rows.map((row) => laidOutSize(row).height)));
    check(
      'the file tree keeps its 26px rows off a phone',
      rows.length > 0 && heights.length === 1 && heights[0] === 26,
      heights.join(',') || 'no rows',
    );

    const sizes = paintedText(host).filter((t) => /^\d/.test(t.text) && /[BKMG]$/.test(t.text));
    check(
      'and the size beside a file is still the caption it was off a phone',
      sizes.length > 0 && sizes.every((t) => t.size === 10),
      sizes.map((t) => `${t.text}@${t.size}px`).join(' | ') || 'no size figures',
    );

    root.unmount();
    host.remove();
  }

  // The shell, on a phone.
  {
    const { host, root } = mount(`width:390px;height:420px;${COLUMN}`, shell(true, 'phone-shell-check'));
    // Longer than the rest: the pane creates its session over the network, and
    // this server has no API — the tab strip is drawn either way, but the strip
    // redraws when the attempt fails and measuring it mid-flight is a race.
    await wait(600);
    settle(document);

    const controls = paintedControls(host);
    check('the shell draws its tab strip on a phone', controls.length >= 4, `${controls.length} controls`);

    // A key of the on-screen strip is judged on height alone, for the reason
    // written where assertPhoneSurface does the same: a keyboard row cannot be
    // nine 44px-wide keys on a 390px screen, and is aimed at vertically.
    const inKeyStrip = (node: HTMLElement): boolean =>
      Boolean(node.closest('[aria-label="Terminal keys"]'));
    const small = controls.filter((node) => {
      const box = laidOutSize(node);
      if (inKeyStrip(node)) return box.height < PHONE_TARGET;
      return box.width < PHONE_TARGET || box.height < PHONE_TARGET;
    });
    check(
      `every control in the shell is at least ${PHONE_TARGET}px on a phone`,
      small.length === 0,
      small.length
        ? small.slice(0, 8).map((n) => {
            const b = laidOutSize(n);
            return `${describe(n)}=${b.width}x${b.height}`;
          }).join(' | ')
        : `${controls.length} controls`,
    );

    // Selecting a shell and closing it are neighbours inside one chip, which
    // is the pair a thumb confuses.
    const byLeft = [...controls].sort(
      (a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left,
    );
    const crowded: string[] = [];
    for (let i = 1; i < byLeft.length; i++) {
      if (scrollBoxOf(byLeft[i]) !== scrollBoxOf(byLeft[i - 1])) continue;
      if (inKeyStrip(byLeft[i]) && inKeyStrip(byLeft[i - 1])) continue;
      const gap = byLeft[i].getBoundingClientRect().left - byLeft[i - 1].getBoundingClientRect().right;
      if (gap >= -0.5 && gap < PHONE_GAP - 0.5) {
        crowded.push(`${describe(byLeft[i - 1])}↔${describe(byLeft[i])}=${Math.round(gap)}px`);
      }
    }
    check(
      `neighbouring controls in the shell are at least ${PHONE_GAP}px apart on a phone`,
      crowded.length === 0,
      crowded.length ? crowded.slice(0, 6).join(' | ') : 'no crowded pairs',
    );

    // A second shell, because one tab leaves room the real case does not: the
    // right-hand actions are 44px squares now, and a crowded strip used to take
    // the difference out of them and push "close the terminal" off the screen —
    // clipped, with nothing between it and the viewport that scrolls.
    const another = host.querySelector('[aria-label="Open another terminal here"]') as HTMLElement | null;
    another?.click();
    await wait(400);
    settle(document);

    const hostBox = host.getBoundingClientRect();
    const spilling = paintedControls(host).filter(
      (node) => node.getBoundingClientRect().right > hostBox.right + 0.5,
    );
    check(
      'nothing in the shell is pushed off the side of a phone, however many tabs it has',
      spilling.length === 0,
      spilling.length
        ? spilling.slice(0, 6).map((n) => {
            const b = n.getBoundingClientRect();
            return `${describe(n)}@${Math.round(b.left)}–${Math.round(b.right)} of ${Math.round(hostBox.right)}`;
          }).join(' | ')
        : `${host.querySelectorAll('[role="tab"]').length} tabs, all inside`,
    );

    const tiny = paintedText(host).filter((t) => t.size < PHONE_MIN_TEXT - 0.01);
    check(
      `no text in the shell is smaller than ${PHONE_MIN_TEXT}px on a phone`,
      tiny.length === 0,
      tiny.length
        ? tiny.slice(0, 8).map((t) => `${describe(t.node, t.text)}@${t.size}px`).join(' | ')
        : 'all legible',
    );

    // Bigger chrome comes out of the shell underneath it, and the shell is
    // what the user opened. Asserted because another band — the on-screen key
    // strip — is landing inside this same height: the strip may grow, but it
    // does not get to own the pane.
    const strip = (host.querySelector('[role="tablist"][aria-label="Terminals"]')?.parentElement
      ?? null) as HTMLElement | null;
    const pane = (strip?.parentElement ?? null) as HTMLElement | null;
    const body = (strip?.nextElementSibling ?? null) as HTMLElement | null;
    check(
      'the tab strip takes no more than a touch target out of the pane on a phone',
      Boolean(strip && pane && body) && strip!.offsetHeight <= PHONE_TARGET + PHONE_GAP + 2,
      strip && pane && body
        ? `strip ${strip.offsetHeight}px, shell ${body.offsetHeight}px of ${pane.offsetHeight}px`
        : 'no tab strip',
    );

    root.unmount();
    host.remove();
  }

  // And the same shell on a desktop, unchanged.
  {
    const { host, root } = mount(`width:900px;height:420px;${COLUMN}`, shell(false, 'desktop-shell-check'));
    await wait(600);
    settle(document);

    const strip = (host.querySelector('[role="tablist"][aria-label="Terminals"]')?.parentElement
      ?? null) as HTMLElement | null;
    check(
      'the shell keeps its 28px tab strip off a phone',
      strip?.offsetHeight === 28,
      `${strip?.offsetHeight ?? 'no'}px`,
    );

    const close = host.querySelector('[aria-label^="Close the terminal"]') as HTMLElement | null;
    check(
      'and its actions are the desktop size they were',
      Boolean(close) && laidOutSize(close!).height === 22 && laidOutSize(close!).width === 22,
      close ? `${laidOutSize(close).width}x${laidOutSize(close).height}` : 'no close action',
    );

    root.unmount();
    host.remove();
  }
}

/**
 * The record is queryable from the dashboard for longer than a calendar year.
 *
 * Every window the dialog could ask for was the one containing the moment it
 * asked: four period tabs, no previous or next, no date field, and the only
 * movement available — pressing a bar of the trend — lands inside the period
 * already on screen. So nothing before the first of January was reachable,
 * and from 2027-01-01 the whole of 2026 would leave the figures, the trend,
 * the history and the export while sitting untouched in `usage_jobs` (#56).
 *
 * Driven here rather than asserted on state because the claim is about what
 * goes back to the *server*: a control that moves a label and re-asks nothing
 * has moved nothing, and one that moves the charts while the list underneath
 * goes on answering for today leaves the page contradicting itself.
 */
async function checkTheUsageWindowReachesBeforeThisYear(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });

  // The server's own behaviour, in one line: the window is the day the anchor
  // falls in, and an anchor it was never sent means today. A stub that ignored
  // the anchor would let a broken control pass by answering the same thing
  // whatever it was asked.
  const dayFor = (anchor: string | null): { from: string; to: string } => {
    const at = anchor ? new Date(anchor) : new Date();
    const start = Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate());
    return { from: new Date(start).toISOString(), to: new Date(start + 86_400_000).toISOString() };
  };

  const asked: string[] = [];
  let answered = dayFor(null);
  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    asked.push(url);
    if (!url.includes('/api/usage/dashboard')) {
      return new Response(JSON.stringify({ jobs: [], total: 0, conversations: [] }), {
        status: 200, headers: { 'content-type': 'application/json' },
      });
    }
    const anchor = new URL(url, window.location.origin).searchParams.get('anchor');
    answered = dayFor(anchor);
    // Today has work in it and every earlier day is empty: the case the
    // control has to be honest about, since walking back through a record
    // that starts in July 2026 is mostly walking through nothing.
    const figures = anchor
      ? totals({})
      : totals({ turns: 4, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 4, costReportedTurns: 4 });
    return new Response(
      JSON.stringify({
        scope: 'self', canSeeEveryone: false, period: 'day',
        ...answered,
        bucket: 'hour', filters: {},
        totals: figures,
        series: [{ key: '2026-07-27T09:00', totals: figures }],
        byProject: [], byAgent: [], byModel: [],
        effortByAgent: [], effortByModel: [], topTools: [], topToolsByAgent: [],
      }),
      { status: 200, headers: { 'content-type': 'application/json' } },
    );
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  const byLabel = (prefix: string): HTMLButtonElement | undefined =>
    Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
      (b) => (b.getAttribute('aria-label') || '').startsWith(prefix),
    );
  const windowName = (): string =>
    ((doc.querySelector('[role="group"][aria-label="The period on screen"] [aria-live="polite"]') as HTMLElement | null)
      ?.textContent || '').trim();
  const anchorsAsked = (): string[] =>
    asked
      .filter((u) => u.includes('/api/usage/dashboard'))
      .map((u) => new URL(u, window.location.origin).searchParams.get('anchor'))
      .filter((a): a is string => Boolean(a));

  const back = byLabel('Previous');
  check(
    'the dashboard offers a way off the period that contains now',
    Boolean(back),
    back ? 'found' : Array.from(doc.querySelectorAll('button')).map((b) => describe(b)).join(' | ').slice(0, 240),
  );

  const named = windowName();
  check(
    'and names the window it is showing',
    named.length > 0,
    named || 'no window name on screen',
  );

  check(
    'the walk forward stops at the present',
    Boolean(byLabel('Next')?.disabled),
    byLabel('Next') ? `disabled=${byLabel('Next')?.disabled}` : 'no Next control',
  );

  const dateField = doc.querySelector<HTMLInputElement>('input[type="date"]');
  const today = new Date();
  const pad = (n: number): string => String(n).padStart(2, '0');
  check(
    'and neither does the date field',
    dateField?.max === `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`,
    dateField ? `max=${dateField.max}` : 'no date field',
  );

  back?.click();
  await wait(400);
  check(
    'moving the window back asks the server for that window',
    anchorsAsked().length === 1 && new Date(anchorsAsked()[0]).getTime() < Date.now(),
    anchorsAsked().join(' | ') || 'no anchor ever left the browser',
  );

  check(
    'and the window on screen is the one that was asked for',
    windowName() !== named && windowName().length > 0,
    `${named} -> ${windowName()}`,
  );

  // The list is not a second query with its own idea of when: it takes the
  // range the figures were computed over, so a moved window has to reach it.
  check(
    'the history under the charts follows the window',
    asked.some((u) => u.includes('/api/usage/conversations') && u.includes(encodeURIComponent(answered.from))),
    `${answered.from} vs ${asked.filter((u) => u.includes('/conversations')).slice(-1)[0] || 'nothing asked'}`,
  );

  check(
    'a window with nothing in it says so, rather than drawing an empty chart',
    /Nothing was recorded in this day/i.test((doc.body.textContent || '').replace(/\s+/g, ' ')),
    (doc.body.textContent || '').replace(/\s+/g, ' ').slice(0, 240),
  );

  // Twice back is two days back. Stepping from the range that came back rather
  // than from the anchor makes the second press recompute the first one.
  byLabel('Previous')?.click();
  await wait(400);
  const walked = anchorsAsked();
  check(
    'pressing again moves another period, not over the same one twice',
    walked.length === 2 && new Date(walked[1]).getTime() < new Date(walked[0]).getTime(),
    walked.join(' | '),
  );

  const now = Array.from(doc.querySelectorAll<HTMLButtonElement>('button')).find(
    (b) => (b.textContent || '').trim() === 'Now',
  );
  check('there is one control back to the present', Boolean(now), now ? 'found' : 'no Now control');
  now?.click();
  await wait(400);
  check(
    'and it puts the unmoved question back',
    asked.slice(-4).some((u) => u.includes('/api/usage/dashboard') && !u.includes('anchor=')),
    asked.slice(-4).join(' | ').slice(0, 300),
  );

  frame.style.width = '390px';
  await wait(300);
  const spilling = Array.from(doc.body.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node) || scrollsSideways(node)) return false;
    const box = node.getBoundingClientRect();
    return box.right > 391 || box.left < -1;
  });
  check(
    'the window control stays inside a phone-width window',
    spilling.length === 0,
    spilling.length ? spilling.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * The effort histograms, read without a mouse.
 *
 * #66's criterion is that every chart is operable with the keyboard alone and
 * announces its values — and the trend chart satisfies it while these did not.
 * Each bar was a bare `<div>` inside a tooltip that mounts on mouseenter, so
 * the counts reached no keyboard, no screen reader and no touch screen, and
 * the panel read as an agent name followed by five loose numbers.
 *
 * It survived thirteen checks written for that criterion because every usage
 * fixture in this file sends `effortByAgent: []`, so the component under test
 * was never rendered. This one sends real distributions.
 */
async function checkTheEffortHistogramsAreReadableWithoutAMouse(): Promise<void> {
  const totals = (over: Record<string, number>) => ({
    turns: 0, modelTurns: 0, toolCalls: 0,
    inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0,
    reasoningTokens: 0, totalTokens: 0, costUsd: 0,
    tokensReportedTurns: 0, costReportedTurns: 0, modelTurnsReportedTurns: 0,
    ...over,
  });
  const effort = (key: string) => ({
    key,
    turns: 12,
    modelTurnsReportedTurns: 12,
    modelTurnsAvg: 3.4,
    modelTurnsMax: 11,
    toolCallsAvg: 2.1,
    toolCallsMax: 9,
    modelTurnsHistogram: [4, 3, 3, 1, 1],
    toolCallsHistogram: [2, 4, 3, 2, 1],
  });

  const figures = totals({ turns: 12, modelTurns: 41, toolCalls: 25, totalTokens: 5000, costUsd: 1.25, tokensReportedTurns: 12, costReportedTurns: 12, modelTurnsReportedTurns: 12 });
  const dashboard = {
    scope: 'self', canSeeEveryone: false, period: 'day',
    from: '2026-07-27T00:00:00.000Z', to: '2026-07-28T00:00:00.000Z',
    bucket: 'hour', filters: {},
    totals: figures,
    series: [{ key: '2026-07-27T09:00', totals: figures }],
    byProject: [], byAgent: [], byModel: [],
    effortByAgent: [effort('claude')],
    effortByModel: [effort('claude-opus-5')],
    topTools: [], topToolsByAgent: [],
  };

  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : (input as Request).url ?? input);
    const body = url.includes('/api/usage/dashboard') ? dashboard : { jobs: [], total: 0, conversations: [] };
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof window.fetch;

  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:1100px;height:900px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const root = createRoot(doc.body);
  root.render(React.createElement(UsageDashboardDialog, { open: true, onClose: () => {} } as never));
  await wait(600);

  const histograms = Array.from(doc.querySelectorAll<HTMLElement>('[role="group"][aria-label*="per turn"]'));
  check(
    'an effort histogram announces what it is a distribution of',
    histograms.length >= 2 && histograms.some((h) => /claude/.test(h.getAttribute('aria-label') || '')),
    histograms.map((h) => h.getAttribute('aria-label')).join(' | ').slice(0, 240) || 'no named histogram',
  );

  const bars = histograms.length ? Array.from(histograms[0].querySelectorAll<HTMLButtonElement>('button')) : [];
  check(
    'every bucket of it is a real control, not a decoration',
    bars.length === 5 && bars.every((b) => b.tagName === 'BUTTON'),
    `${bars.length} control(s) in the first histogram`,
  );

  check(
    'and carries its own count into the accessibility tree',
    bars.length === 5 && bars.every((b) => /\d+ of \d+ turn/.test(b.getAttribute('aria-label') || '')),
    bars.map((b) => b.getAttribute('aria-label')).join(' | ').slice(0, 240),
  );

  // The five tokens that used to be loose on the page: each has to belong to
  // something that says what it counts.
  const orphans = histograms.flatMap((h) =>
    Array.from(h.querySelectorAll<HTMLElement>('span')).filter(
      (span) => (span.textContent || '').trim() !== '' && !span.closest('button[aria-label]'),
    ),
  );
  check(
    'no number on the effort panel is left without a quantity attached',
    orphans.length === 0,
    orphans.map((n) => describe(n)).join(' | ').slice(0, 240) || 'every label belongs to a control',
  );

  // No pointer: just reaching the bar, the way a tab stop does.
  bars[1]?.focus();
  await wait(150);
  check(
    'a bucket can be reached with the keyboard alone',
    doc.activeElement === bars[1],
    describe(doc.activeElement as HTMLElement),
  );

  const readout = histograms[0]?.parentElement?.querySelector('[aria-live="polite"]') as HTMLElement | null;
  check(
    'and reaching it reveals its figures without a mouse',
    Boolean(readout && /\d+ of \d+ turn/.test(readout.textContent || '')),
    readout ? (readout.textContent || '').slice(0, 120) || 'readout is empty' : 'no readout region',
  );

  // A touch screen has no hover to reveal a tooltip with, so pressing has to
  // be the same act as reaching.
  bars[1]?.blur();
  await wait(100);
  bars[3]?.click();
  await wait(150);
  check(
    'and pressing it says the same thing, for a screen with no hover',
    Boolean(readout && /\d+ of \d+ turn/.test(readout.textContent || '')),
    readout ? (readout.textContent || '').slice(0, 120) || 'readout is empty' : 'no readout region',
  );

  frame.style.width = '390px';
  await wait(300);
  const spilling = Array.from(doc.body.querySelectorAll<HTMLElement>('*')).filter((node) => {
    if (!isPainted(node) || scrollsSideways(node)) return false;
    const box = node.getBoundingClientRect();
    return box.right > 391 || box.left < -1;
  });
  check(
    'the effort panel stays inside a phone-width window',
    spilling.length === 0,
    spilling.length ? spilling.slice(0, 6).map((n) => describe(n)).join(' | ') : 'nothing overflowing',
  );

  root.unmount();
  frame.remove();
  window.fetch = realFetch;
}

/**
 * Every reasoning row opens onto something, whichever agent filled it.
 *
 * Here rather than in a unit test because the defect *was* a rendered box:
 * `<Markdown text="">` produces a bordered panel with nothing inside it, which
 * every assertion about props and blocks passes straight through. What is
 * checked is what a reader sees — that expanding a reasoning row paints words,
 * that the collapsed row above it says something, and that the two agree (#120).
 *
 * The three rows are the three shapes reasoning arrives in, taken from what the
 * runtimes were watched doing: text (pi, grok, kimi, omp), no text with a
 * reported size (claude), and no text at all (a codex item whose trace is
 * encrypted and which summarised nothing).
 */
async function checkAnExpandedReasoningRowIsNeverEmpty(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:1280px;height:820px;position:absolute;top:0;left:0;display:flex';
  document.body.appendChild(host);

  const controller = new ChatController('reasoning-check', { send: () => {} });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'reasoning-check',
    snapshot: {
      sessionId: 'reasoning-check', runtime: 'claude', state: 'idle',
      capabilities: {
        streaming: true, thinking: true, toolCalls: true, diffs: true, permissions: true,
        interrupt: true, resume: true, fork: false, attachments: true, usage: true,
        cost: true, plan: true, commands: [],
      },
      messages: [
        {
          id: 'u1', seq: 1, turnId: 't1', role: 'user', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'how many sheep are left?' }],
        },
        {
          id: 'a1', seq: 2, turnId: 't1', role: 'assistant', ts: Date.now(),
          blocks: [
            { kind: 'thinking', text: 'ALL-BUT-NINE is the trap in this riddle.' },
            { kind: 'thinking', text: '', tokens: 135 },
            { kind: 'thinking', text: '' },
            { kind: 'text', text: 'nine' },
          ],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: false,
    },
  } as never);

  const root = createRoot(host);
  root.render(
    React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/home/dev/project',
      branch: 'main',
      view: { ...DEFAULT_CHAT_VIEW, activityFilter: 'reasoning' },
      onViewChange: () => {},
    } as never),
  );
  await wait(400);

  const rail = host.querySelector('[aria-label="Activity"]') as HTMLElement;
  const rows = (): HTMLElement[] =>
    Array.from(rail.querySelectorAll<HTMLElement>('button[aria-expanded]'));

  check(
    'all three reasoning rows are on the rail',
    rows().length === 3,
    `${rows().length} rows: ${rows().map((r) => (r.textContent || '').slice(0, 30)).join(' | ')}`,
  );

  // Every collapsed row says something before it is opened — the preview line
  // is the only thing a reader has when deciding whether to expand it.
  const previews = rows().map((row) => (row.textContent || '').replace(/\s+/g, ' ').trim());
  check(
    'the row with reasoning text previews it',
    (previews[0] || '').includes('ALL-BUT-NINE'),
    previews[0] || '(nothing)',
  );
  check(
    'the row with no text says so instead of showing a bare label',
    /text not reported/.test(previews[1] || '') && /135/.test(previews[1] || ''),
    previews[1] || '(nothing)',
  );
  check(
    'and so does the row that reported nothing at all',
    /text not reported/.test(previews[2] || ''),
    previews[2] || '(nothing)',
  );

  for (const [at, name] of [[0, 'with text'], [1, 'with a size only'], [2, 'with nothing']] as Array<[number, string]>) {
    rows()[at].click();
    await wait(120);
  }
  await wait(200);

  const bodies = Array.from(rail.querySelectorAll<HTMLElement>('[data-testid="reasoning-body"]'));
  check(
    'expanding a reasoning row opens a panel for each',
    bodies.length === 3,
    `${bodies.length} panels`,
  );

  bodies.forEach((body, at) => {
    const painted = paintedText(body);
    const words = painted.map((entry) => entry.text).join(' ').trim();
    check(
      `reasoning row ${at + 1} of 3 shows words rather than an empty box`,
      words.length > 0 && body.getBoundingClientRect().height > 0,
      `"${words.slice(0, 90)}" h=${Math.round(body.getBoundingClientRect().height)}`,
    );
  });

  const said = (at: number): string =>
    paintedText(bodies[at]).map((entry) => entry.text).join(' ');
  check(
    'the agent’s own reasoning is what is shown where there is any',
    said(0).includes('ALL-BUT-NINE'),
    said(0).slice(0, 90),
  );
  check(
    'a withheld reasoning block says it was withheld, and how much of it there was',
    /not the text of it/.test(said(1)) && /135/.test(said(1)),
    said(1).slice(0, 120),
  );
  check(
    'a block the agent said nothing about is explained rather than blank',
    /reasoned here, but not the text of it/.test(said(2)),
    said(2).slice(0, 120),
  );

  root.unmount();
  host.remove();
}

/**
 * The list of every conversation, driven the way a person drives it (#127).
 *
 * None of this can be a unit test. The list arrives through an effect, so
 * `renderToStaticMarkup` — which runs no effects — can only ever see the
 * placeholder it starts on; the narrowing, the folding, the reopening and the
 * delete are all things that happen *after* a real React root has mounted and
 * something has been clicked. And the one criterion with a number in it ("with
 * hundreds of conversations across many folders, the list still opens promptly
 * and scrolls smoothly") is a question about a layout engine, which is exactly
 * what this file is for.
 *
 * Three hundred conversations across twelve folders, because that is the size
 * the feature is written for and the size at which a per-row cost that is not
 * bounded stops being invisible.
 */
async function checkEveryConversationCanBeFoundAndReopened(): Promise<void> {
  const FOLDERS = 12;
  const EACH = 25;

  /** A list shaped exactly as `/api/sessions/conversations` answers. */
  const listing = (): {
    projects: Array<{
      dir: string;
      name: string;
      lastActivity: string;
      conversations: Array<Record<string, unknown>>;
    }>;
    total: number;
    truncated: boolean;
  } => {
    const projects = [];
    for (let folder = 0; folder < FOLDERS; folder++) {
      const dir = `/home/dev/projects/service-${folder}`;
      const conversations = [];
      for (let index = 0; index < EACH; index++) {
        conversations.push({
          id: `c-${folder}-${index}`,
          name: `Session ${folder}/${index}`,
          // One folder's conversations are about the release script, so a search
          // has something to find that the others do not have.
          firstMessage:
            folder === 3 && index === 0
              ? 'fix the release script so it tags the right commit'
              : `question ${folder}/${index} about the parser`,
          runtime: 'claude',
          runtimeLabel: 'Claude',
          lastActivity: new Date(Date.UTC(2026, 6, 20, 12, folder, EACH - index)).toISOString(),
          workingDir: dir,
          events: 40,
          // The first of each folder is still running, the second cannot be
          // resumed, the third came back with approvals bypassed.
          canResume: index !== 1,
          running: index === 0,
          bypassPermissions: index === 2,
        });
      }
      projects.push({
        dir,
        name: `service-${folder}`,
        lastActivity: conversations[0].lastActivity as string,
        conversations,
      });
    }
    // Newest project first, which is the order the server sends.
    projects.reverse();
    return { projects, total: FOLDERS * EACH, truncated: false };
  };

  const host = document.createElement('div');
  document.body.appendChild(host);

  const opened: string[] = [];
  const deleted: string[] = [];
  /** What the confirmation answers. Flipped mid-check to cover both outcomes. */
  let allowDelete = false;

  const root = createRoot(host);
  const started = performance.now();
  root.render(
    React.createElement(ConversationsDialog, {
      open: true,
      load: async () => listing(),
      openIds: ['c-11-0'],
      activeId: 'c-11-0',
      onOpen: (conversation: { id: string }) => opened.push(conversation.id),
      onDelete: async (conversation: { id: string }) => {
        deleted.push(conversation.id);
        return allowDelete;
      },
      onClose: () => {},
    } as never),
  );
  await wait(600);
  settle(document);
  const drawn = performance.now() - started;

  const panel = document.querySelector('[role="dialog"]') as HTMLElement | null;
  if (!panel) {
    check('the conversation list opens', false, 'no dialog rendered');
    root.unmount();
    host.remove();
    return;
  }

  /**
   * An element's words, with the whitespace taken out.
   *
   * `textContent` here is not what it looks like: every `Icon` inlines a
   * pretty-printed SVG, and the newlines and indentation inside it are text nodes
   * of the element that holds it. Read raw, the first sixty characters of a
   * heading are the whitespace inside two icons — which is why the failure detail
   * for this check was blank while the check itself was working.
   */
  const words = (node: Element | null): string =>
    (node?.textContent || '').replace(/\s+/g, ' ').trim();

  const headings = (): HTMLElement[] =>
    Array.from(panel.querySelectorAll<HTMLElement>('section > button[aria-expanded]')).filter(isPainted);
  const rowsIn = (section: Element): HTMLElement[] =>
    Array.from(section.querySelectorAll<HTMLElement>('button[aria-label^="Delete"]'))
      .map((button) => button.parentElement as HTMLElement)
      .filter(Boolean);
  const openers = (): HTMLElement[] =>
    Array.from(panel.querySelectorAll<HTMLElement>('section button[aria-label]')).filter(
      (node) => !(node.getAttribute('aria-label') || '').startsWith('Delete'),
    );

  check(
    'the list opens promptly with hundreds of conversations across a dozen folders',
    drawn < 4000,
    `${Math.round(drawn)}ms for ${FOLDERS * EACH} conversations`,
  );

  check(
    'every project the user has conversations in is a group',
    headings().length === FOLDERS,
    `${headings().length} groups, expected ${FOLDERS}`,
  );

  check(
    'the most recently active project comes first',
    words(headings()[0]).startsWith('service-11'),
    words(headings()[0]).slice(0, 70),
  );

  // A row is what was asked, not when it happened. This is the whole reason the
  // launcher's list of timestamps was not worth showing.
  const firstRowLabel = openers()[0]?.getAttribute('aria-label') || '';
  check(
    'a row is identified by what was asked',
    firstRowLabel.startsWith('question 11/0 about the parser'),
    firstRowLabel.slice(0, 90),
  );
  check(
    'and carries the agent, when it was last active, and whether it is running',
    /Claude/.test(firstRowLabel) && /last active/.test(firstRowLabel) && /running now/.test(firstRowLabel),
    firstRowLabel.slice(0, 140),
  );

  const labels = openers().map((node) => node.getAttribute('aria-label') || '');
  check(
    'a conversation whose agent cannot carry on says so before it is picked',
    labels.some((label) => /cannot carry on from where it left off/.test(label)),
    labels.find((label) => /cannot carry on/.test(label))?.slice(0, 120) || 'nothing said',
  );
  check(
    'and one that comes back with approvals bypassed says that too',
    labels.some((label) => /approvals bypassed/.test(label)),
    labels.find((label) => /approvals bypassed/.test(label))?.slice(0, 120) || 'nothing said',
  );
  check(
    'a conversation that already has a tab is marked rather than hidden',
    labels.some((label) => /already open/.test(label)),
    labels.find((label) => /already open/.test(label))?.slice(0, 120) || 'nothing said',
  );

  // The scroller is what makes hundreds of rows usable rather than a page that
  // pushes the dialog past the window.
  const scroller = openers()[0]?.closest('[style*="overflow"]') as HTMLElement | null;
  check(
    'the list scrolls inside the dialog rather than growing past the window',
    Boolean(scroller)
      && scroller!.scrollHeight > scroller!.clientHeight
      && panel.getBoundingClientRect().bottom <= window.innerHeight + 1,
    scroller
      ? `${scroller.scrollHeight}px of rows in ${scroller.clientHeight}px, panel bottom ${Math.round(panel.getBoundingClientRect().bottom)}`
      : 'no scroller',
  );
  if (scroller) {
    scroller.scrollTop = 4000;
    scroller.dispatchEvent(new Event('scroll'));
    await wait(150);
    check(
      'and it actually scrolls',
      scroller.scrollTop > 0,
      `scrollTop=${Math.round(scroller.scrollTop)}`,
    );
    scroller.scrollTop = 0;
  }

  // Folding a group. The rows go; the heading stays, so the map of the list
  // survives being shortened.
  const before = openers().length;
  headings()[0].click();
  await wait(200);
  check(
    'a project group can be folded away',
    openers().length === before - EACH && headings().length === FOLDERS,
    `${openers().length} rows after folding one group of ${EACH} (was ${before})`,
  );
  headings()[0].click();
  await wait(200);

  // Typing narrows it, and a group with no match leaves entirely.
  const field = panel.querySelector('input[aria-label="Search conversations"]') as HTMLInputElement | null;
  if (!field) {
    check('the list can be narrowed by typing', false, 'no search field');
  } else {
    setInputValue(field, 'release script');
    await wait(250);
    const matched = openers().map((node) => node.getAttribute('aria-label') || '');
    check(
      'typing narrows the list to what matches',
      matched.length === 1 && /release script/.test(matched[0]),
      `${matched.length} rows: ${matched.map((l) => l.slice(0, 40)).join(' | ').slice(0, 120)}`,
    );
    check(
      'and every group with no match drops out',
      headings().length === 1,
      `${headings().length} groups left`,
    );
    check(
      'and the count says how much of the list is being shown',
      /1 of 300 in 1 project/.test(words(panel)),
      words(panel).slice(0, 120),
    );

    // The folder is one of the things people remember about a conversation.
    setInputValue(field, 'service-4');
    await wait(250);
    check(
      'searching by folder finds the conversations in it',
      headings().length === 1 && openers().length === EACH,
      `${headings().length} groups, ${openers().length} rows`,
    );

    setInputValue(field, 'nothing like this exists');
    await wait(250);
    check(
      'and a search with no answer says so rather than looking empty',
      /Nothing matches/.test(words(panel)) && headings().length === 0,
      words(panel).slice(0, 140),
    );

    setInputValue(field, '');
    await wait(250);
    check(
      'clearing the search brings the whole list back',
      headings().length === FOLDERS,
      `${headings().length} groups`,
    );
  }

  // Picking one opens it. The row is a control, and this is what it is for.
  openers()[0].click();
  await wait(150);
  check(
    'picking a conversation opens that conversation',
    opened.length === 1 && opened[0] === 'c-11-0',
    opened.join(',') || 'nothing opened',
  );

  // Deleting asks first, and a declined answer changes nothing.
  const deleteButtons = (): HTMLElement[] =>
    Array.from(panel.querySelectorAll<HTMLElement>('button[aria-label^="Delete"]')).filter(isPainted);
  const rowsBefore = openers().length;
  allowDelete = false;
  deleteButtons()[0].click();
  await wait(200);
  check(
    'deleting a conversation asks before anything happens',
    deleted.length === 1,
    `${deleted.length} confirmations requested`,
  );
  check(
    'and a declined confirmation leaves the conversation exactly where it was',
    openers().length === rowsBefore,
    `${openers().length} rows, was ${rowsBefore}`,
  );

  allowDelete = true;
  deleteButtons()[0].click();
  await wait(250);
  check(
    'and a confirmed one takes the row away',
    openers().length === rowsBefore - 1,
    `${openers().length} rows, was ${rowsBefore}`,
  );
  check(
    'and says so in the count',
    /299 conversations in 12 projects/.test(words(panel)),
    words(panel).slice(0, 120),
  );

  root.unmount();
  host.remove();

  // The two states with no list in them, where the honest word matters most: a
  // failed read must not read as "you have no conversations".
  const errorHost = document.createElement('div');
  document.body.appendChild(errorHost);
  let attempts = 0;
  const errorRoot = createRoot(errorHost);
  errorRoot.render(
    React.createElement(ConversationsDialog, {
      open: true,
      load: async () => {
        attempts += 1;
        if (attempts === 1) throw new Error('The list could not be read just now.');
        return { projects: [], total: 0, truncated: false };
      },
      onOpen: () => {},
      onDelete: async () => false,
      onClose: () => {},
    } as never),
  );
  await wait(400);
  const errorPanel = document.querySelector('[role="dialog"]') as HTMLElement | null;
  const errorWords = (): string => (errorPanel?.textContent || '').replace(/\s+/g, ' ').trim();
  check(
    'a list that could not be read says so instead of claiming there are none',
    Boolean(errorPanel)
      && /could not be read just now/.test(errorWords())
      && !/No conversations yet/.test(errorWords()),
    errorWords().slice(0, 140),
  );
  const retry = Array.from(errorPanel?.querySelectorAll<HTMLElement>('button') || []).find((node) =>
    /Try again/.test(node.textContent || ''),
  );
  if (retry) {
    retry.click();
    await wait(400);
    check(
      'and offers a way to try again that actually re-reads it',
      attempts === 2 && /No conversations yet/.test(errorWords()),
      `${attempts} attempts — ${errorWords().slice(0, 110)}`,
    );
  } else {
    check('and offers a way to try again', false, 'no retry control');
  }
  errorRoot.unmount();
  errorHost.remove();
}

/**
 * Set a controlled input the way a keystroke does.
 *
 * Assigning `.value` alone does not notify React: it tracks the previous value
 * on the DOM node and skips the change it cannot see. Every check below that
 * types into a field would silently measure the unfiltered list.
 */
function setInputValue(field: HTMLInputElement, value: string): void {
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set;
  setter?.call(field, value);
  field.dispatchEvent(new Event('input', { bubbles: true }));
}

/**
 * A conversation that has stopped for the user is identifiable from outside it.
 *
 * This is the fallback the whole notification feature rests on: permission can
 * be refused, and on iOS outside an installed app it is not even offered, so
 * the marks inside the product are the only thing some people will ever get.
 *
 * It cannot be a unit test. Every claim here is about paint — that each state
 * icon resolves to its own colour and motion, and that the phone
 * sheet, which is the *only* cross-session surface on a phone because the tab
 * strip is not rendered there at all, actually draws the words at a size an eye
 * can read. Without the app's own stylesheets every `var(--warning)` resolves
 * to the empty string and a test on the inline style would pass on a dot that
 * paints black.
 */
async function checkAWaitingConversationIsVisibleWithoutOpeningIt(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'width:900px;position:absolute;top:0;left:0';
  document.body.appendChild(host);

  const root = createRoot(host);
  root.render(
    React.createElement(TabBar, {
      tabs: [
        // `status: 'running'` on the waiting two is the case that matters and
        // the one that was wrong: a tab's status is the server's "the process
        // is alive", which stays true of an agent that stopped to ask
        // something — so after a reload, or after the tab has been joined, a
        // blocked conversation arrives here as running.
        { id: 'waiting', title: 'infra', status: 'running', unread: true, attention: 'approval' },
        { id: 'asked', title: 'docs', status: 'running', unread: true, attention: 'question' },
        { id: 'unread', title: 'webcli', status: 'idle', unread: true },
        { id: 'quiet', title: 'notes', status: 'running' },
        { id: 'failed', title: 'deploy', status: 'error' },
      ],
      activeId: 'quiet',
      onSelect: () => {},
      onClose: () => {},
      onNew: () => {},
      ariaLabel: 'Sessions',
    } as never),
  );
  await wait(200);

  const strip = host.querySelector('[role="tablist"][aria-label="Sessions"]') as HTMLElement;
  const tabs = Array.from(strip.querySelectorAll<HTMLElement>('[role="tab"]'));
  const stateOf = (tab: HTMLElement): HTMLElement => (
    tab.querySelector('[data-tab-state]') as HTMLElement
  );
  const glyphOf = (tab: HTMLElement): HTMLElement => (
    stateOf(tab).querySelector('.ricon') as HTMLElement
  );
  const colourOf = (tab: HTMLElement): string => getComputedStyle(stateOf(tab)).color;

  const waiting = colourOf(tabs[0]);
  const asked = colourOf(tabs[1]);
  const unread = colourOf(tabs[2]);
  const quiet = colourOf(tabs[3]);
  const failed = colourOf(tabs[4]);

  check(
    'a conversation waiting for approval is not painted as ordinary unread output',
    waiting !== unread && /rgb/.test(waiting),
    `approval=${waiting} unread=${unread}`,
  );
  check(
    'a conversation that asked a question is told apart from one waiting for approval',
    asked !== waiting && asked !== unread,
    `question=${asked} approval=${waiting}`,
  );
  check(
    'a stopped conversation is not painted as one that is working',
    waiting !== quiet && asked !== quiet && /rgb/.test(quiet),
    `approval=${waiting} question=${asked} running=${quiet}`,
  );
  check(
    'success and failure have distinct semantic colours',
    unread !== quiet && failed !== unread && failed !== waiting && /rgb/.test(failed),
    `success=${unread} error=${failed} working=${quiet}`,
  );
  check(
    'only the working icon spins',
    getComputedStyle(glyphOf(tabs[0])).animationName === 'none'
      && getComputedStyle(glyphOf(tabs[3])).animationName === 'relay-spin',
    `waiting=${getComputedStyle(glyphOf(tabs[0])).animationName} working=${getComputedStyle(glyphOf(tabs[3])).animationName}`,
  );
  check(
    'each state uses the corresponding icon rather than a generic dot',
    tabs.every((tab) => Boolean(glyphOf(tab).querySelector('svg')))
      && stateOf(tabs[0]).dataset.tabState === 'waiting-approval'
      && stateOf(tabs[1]).dataset.tabState === 'waiting-input'
      && stateOf(tabs[2]).dataset.tabState === 'success'
      && stateOf(tabs[3]).dataset.tabState === 'working'
      && stateOf(tabs[4]).dataset.tabState === 'error',
    tabs.map((tab) => stateOf(tab).dataset.tabState).join(' / '),
  );
  check(
    'and every state says so in words, not only in colour',
    stateOf(tabs[0]).getAttribute('aria-label') === 'Waiting for approval'
      && stateOf(tabs[1]).getAttribute('aria-label') === 'Waiting for input'
      && stateOf(tabs[2]).getAttribute('aria-label') === 'Completed'
      && stateOf(tabs[3]).getAttribute('aria-label') === 'Working'
      && stateOf(tabs[4]).getAttribute('aria-label') === 'Error',
    tabs.map((tab) => stateOf(tab).getAttribute('aria-label')).join(' / '),
  );

  root.unmount();
  host.remove();

  // The phone, where this is the only place the answer exists: AppShell renders
  // no tab strip below the mobile breakpoint.
  const frame = document.createElement('iframe');
  frame.style.cssText = 'width:390px;height:740px;position:absolute;top:0;left:0;border:0';
  document.body.appendChild(frame);
  const doc = frame.contentDocument as Document;
  doc.open();
  doc.write(
    '<!doctype html><html><head>'
    + '<link rel="stylesheet" href="/css/relay/relay.css">'
    + '<link rel="stylesheet" href="/css/main.css">'
    + '</head><body style="margin:0"></body></html>',
  );
  doc.close();
  await wait(150);

  const sheetRoot = createRoot(doc.body);
  sheetRoot.render(
    React.createElement(
      PhoneContext.Provider,
      { value: true },
      React.createElement(TabSwitcherSheet, {
        open: true,
        tabs: [
          { id: 'waiting', title: 'infra', status: 'running', unread: true, attention: 'approval', workingDir: '/srv/infra' },
          { id: 'quiet', title: 'notes', status: 'running', unread: false, attention: null, workingDir: '/srv/notes' },
          { id: 'complete', title: 'tests', status: 'idle', unread: true, attention: null, workingDir: '/srv/tests' },
          { id: 'failed', title: 'deploy', status: 'error', unread: false, attention: null, workingDir: '/srv/deploy' },
        ],
        activeId: 'quiet',
        onSelect: () => {},
        onCloseTab: () => {},
        onNew: () => {},
        onAllSessions: () => {},
        onClose: () => {},
      } as never),
    ),
  );
  await wait(300);
  settle(doc);

  const said = paintedText(doc.body).find((entry) => entry.text === 'Waiting for approval');
  check(
    'the phone’s session sheet says which conversation is waiting',
    Boolean(said),
    said ? `${said.size}px` : paintedText(doc.body).map((entry) => entry.text).slice(0, 8).join(' | '),
  );
  check(
    'and says it at a size that can be read',
    Boolean(said) && (said as { size: number }).size >= PHONE_MIN_TEXT,
    said ? `${said.size}px, floor ${PHONE_MIN_TEXT}px` : 'not drawn',
  );
  const phoneStates = Array.from(doc.querySelectorAll<HTMLElement>('[data-tab-state]'))
    .map((node) => node.dataset.tabState);
  check(
    'the phone session sheet uses the same state icons as the desktop strip',
    ['waiting-approval', 'working', 'success', 'error']
      .every((state) => phoneStates.includes(state)),
    phoneStates.join(' / '),
  );

  sheetRoot.unmount();
  frame.remove();
}

/**
 * The environment size picker, rendered rather than reasoned about.
 *
 * Three states this dialog has that a screenshot of the happy path would not
 * reach, and all three have been wrong in a settings dialog before: the size a
 * user *chose* differing from the size their environment is *running at* (which
 * is the normal state under automatic sizing), a change that is waiting for
 * them to be idle, and a server where the whole feature is off. A picker that
 * silently shows the wrong current size is the kind of thing people file bugs
 * about.
 */
async function checkTheEnvironmentSizePickerIsUsable(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'position:absolute;top:0;left:0;width:900px;height:700px';
  document.body.appendChild(host);

  const tiers = [
    { id: 'small', label: 'Small', cpus: '1', memory: '1g' },
    { id: 'medium', label: 'Medium', cpus: '2', memory: '2g' },
    { id: 'large', label: 'Large', cpus: '4', memory: '4g' },
  ];

  const applied: string[] = [];
  const root = createRoot(host);

  // 1. Automatic chosen, and the environment currently a size that is not the
  //    default — exactly what automatic sizing produces.
  root.render(
    React.createElement(EnvironmentDialog, {
      open: true,
      info: {
        enabled: true,
        canChoose: true,
        tiers,
        defaultTier: 'medium',
        tier: 'auto',
        appliedTier: 'large',
        intendedTier: 'large',
        pendingTier: null,
        running: true,
      },
      error: null,
      busy: false,
      notice: null,
      onApply: (tier: string) => applied.push(tier),
      onClose: () => {},
    } as never),
  );
  await wait(200);

  const select = document.querySelector('select[aria-label="Environment size"]') as HTMLSelectElement | null;
  check('the size picker renders a select', !!select, select ? 'present' : 'missing');
  if (!select) {
    root.unmount();
    host.remove();
    return;
  }

  check(
    'every configured size is offered, plus automatic',
    select.options.length === tiers.length + 1,
    Array.from(select.options).map((o) => o.value).join(','),
  );
  check(
    'the picker shows what the user chose, not the default',
    select.value === 'auto',
    `value=${select.value}`,
  );

  // The distinction the whole panel exists for: chosen 'auto', running 'Large'.
  // Scoped to the row rather than the dialog: every tier label also appears in
  // the select's own options, so a dialog-wide search would pass on a panel
  // that never showed the running size at all.
  const runningRow = Array.from(document.querySelectorAll<HTMLElement>('[role="dialog"] *'))
    .find((node) => /^Running at/.test(node.innerText || ''));
  const runningText = runningRow?.innerText || '';
  check(
    'it also says what the environment is actually running at',
    /Large/.test(runningText) && /4 cores/.test(runningText),
    runningText.replace(/\s+/g, ' ').slice(0, 160) || 'no "Running at" row',
  );
  check(
    'and does not claim it is running the size that was merely chosen',
    !/\bSmall\b/.test(runningText),
    runningText.replace(/\s+/g, ' ').slice(0, 160),
  );

  // Applying sends the selected id, not the running one.
  select.value = 'small';
  select.dispatchEvent(new Event('change', { bubbles: true }));
  await wait(60);
  const apply = Array.from(document.querySelectorAll('button')).find(
    (button) => button.textContent?.includes('Apply size'),
  ) as HTMLButtonElement | undefined;
  check('there is an apply button', !!apply, apply ? apply.textContent || '' : 'missing');
  apply?.click();
  await wait(60);
  check(
    'applying sends the size the user picked',
    applied.length === 1 && applied[0] === 'small',
    JSON.stringify(applied),
  );

  // 2. A change waiting for the user to be idle has to be visible, or the
  //    picker looks like it silently ignored them.
  root.render(
    React.createElement(EnvironmentDialog, {
      open: true,
      info: {
        enabled: true, canChoose: true, tiers, defaultTier: 'medium',
        tier: 'small', appliedTier: 'large', intendedTier: 'small',
        pendingTier: 'small', running: true,
      },
      error: null, busy: false, notice: 'Saved.',
      onApply: () => {}, onClose: () => {},
    } as never),
  );
  await wait(200);

  const waitingText = (document.querySelector('[role="dialog"]') as HTMLElement | null)?.innerText || '';
  check(
    'a size change that is waiting says so',
    /waiting/i.test(waitingText),
    waitingText.replace(/\s+/g, ' ').slice(0, 200),
  );

  // 3. Nothing offered on a server that has no environments, and no dead
  //    control left enabled.
  root.render(
    React.createElement(EnvironmentDialog, {
      open: true,
      info: { enabled: false },
      error: null, busy: false, notice: null,
      onApply: () => {}, onClose: () => {},
    } as never),
  );
  await wait(200);

  check(
    'a server without environments offers no size control',
    !document.querySelector('select[aria-label="Environment size"]'),
    'select absent',
  );
  const disabledApply = Array.from(document.querySelectorAll('button')).find(
    (button) => button.textContent?.includes('Apply size'),
  ) as HTMLButtonElement | undefined;
  check(
    'and its apply button cannot be pressed',
    !disabledApply || disabledApply.disabled,
    disabledApply ? `disabled=${disabledApply.disabled}` : 'no button',
  );

  // The dialog must still fit the window with every row on screen.
  const panel = document.querySelector('[role="dialog"]') as HTMLElement | null;
  if (panel) {
    const box = panel.getBoundingClientRect();
    check(
      'the environment dialog fits on screen',
      box.top >= 0 && box.bottom <= window.innerHeight,
      `top=${Math.round(box.top)} bottom=${Math.round(box.bottom)} of ${window.innerHeight}`,
    );
  }

  root.unmount();
  host.remove();
}

/** Retrying the recorded prompt must restore its hidden app-owned workflow. */
async function checkARetriedGuidedIssueKeepsItsWorkflow(): Promise<void> {
  const host = document.createElement('div');
  host.style.cssText = 'position:absolute;top:0;left:0;width:960px;height:680px;display:flex';
  document.body.appendChild(host);

  const sent: Array<Record<string, unknown>> = [];
  let controller!: ChatController;
  controller = new ChatController('guided-retry-check', {
    send: (message) => {
      sent.push(message as Record<string, unknown>);
      if (message.type !== 'chat_start_builtin_workflow') return;
      queueMicrotask(() => controller.handle({
        type: 'chat_builtin_workflow_result',
        sessionId: 'guided-retry-check',
        requestId: message.requestId,
        workflow: 'gh-issue',
        accepted: true,
        status: 'accepted',
        message: 'Started.',
      }));
    },
  });
  controller.handle({
    type: 'chat_snapshot',
    sessionId: 'guided-retry-check',
    snapshot: {
      sessionId: 'guided-retry-check', runtime: 'claude', state: 'idle',
      capabilities: {},
      messages: [
        {
          id: 'user-guided-retry', seq: 1, turnId: 'turn-guided-retry', role: 'user', ts: Date.now(),
          workflow: 'gh-issue', blocks: [{ kind: 'text', text: 'The issue prompt to retry.' }],
        },
        {
          id: 'assistant-guided-retry', seq: 2, turnId: 'turn-guided-retry', role: 'assistant', ts: Date.now(),
          blocks: [{ kind: 'text', text: 'Let us specify it.' }],
        },
      ],
      pendingPermissions: [], queued: [], firstSeq: 1, replayFrom: 1, cursor: 2,
      live: true, bypassPermissions: false,
    },
  } as never);
  sent.length = 0;

  const root = createRoot(host);
  try {
    root.render(React.createElement(ChatView, {
      controller,
      runtime: 'claude',
      runtimeLabel: 'Claude Code',
      workingDir: '/home/dev/project',
      branch: 'main',
      view: { ...DEFAULT_CHAT_VIEW },
      onViewChange: () => {},
    } as never));
    await wait(300);
    settle(document);

    const retry = host.querySelector<HTMLButtonElement>('[aria-label="Retry this turn"]');
    retry?.click();
    await wait(40);
    const workflowStart = sent.find((message) => message.type === 'chat_start_builtin_workflow');
    check(
      'retrying a guided issue restores its workflow instead of sending ordinary chat',
      Boolean(
        workflowStart
        && workflowStart.workflow === 'gh-issue'
        && workflowStart.text === 'The issue prompt to retry.'
        && !sent.some((message) => message.type === 'chat_send'),
      ),
      JSON.stringify(sent),
    );
  } finally {
    root.unmount();
    controller.dispose();
    host.remove();
  }
}

/**
 * What the GitHub panel says beyond a title.
 *
 * The panel used to answer "what is open" and nothing else, which is the least
 * of what a person opens it for: whether anyone has picked an issue up, which
 * pull request is going to close it, whether it is one part of something
 * larger. Those facts are now on the row and in the reader, and they are
 * exactly the sort of thing static markup cannot check — the rows are drawn
 * from a fetch, and a 320px rail is where three extra facts per row either fit
 * or push the panel sideways.
 *
 * The reader is driven the way a person drives it: open an issue, follow the
 * pull request that closes it, come back. Following a reference replaces what
 * is on screen, and a reader that cannot get back to where it came from is a
 * worse panel than one that never linked at all.
 */
async function checkTheGitHubPanelSaysWhoIsOnItAndWhatItLinksTo(): Promise<void> {
  const REPO = 'dnviti/code-agents-webcli';
  const link = (kind: 'issue' | 'pr', number: number, extra: Record<string, unknown> = {}) => ({
    kind,
    number,
    url: `https://github.com/${REPO}/${kind === 'pr' ? 'pull' : 'issues'}/${number}`,
    repo: REPO,
    ...extra,
  });

  // The shape the route now serves: normalised, with every empty field absent.
  const ISSUE = {
    number: 134,
    title: 'Approval mode is not applied consistently',
    url: `https://github.com/${REPO}/issues/134`,
    state: 'OPEN',
    author: { login: 'dnviti' },
    assignees: [{ login: 'ada' }],
    labels: [{ name: 'bug' }],
    milestone: '6.0.0',
    parent: link('issue', 100, { title: 'Approvals, end to end', state: 'OPEN', relation: 'parent' }),
    childrenTotal: 2,
    childrenDone: 1,
    blockedBy: [
      link('issue', 77, { title: 'Decide the default', state: 'OPEN', relation: 'blocked-by' }),
      // Closed this morning, and GitHub keeps the dependency. The row must stop
      // saying "blocked" about it, or ready work gets skipped forever.
      link('issue', 78, { title: 'Already settled', state: 'CLOSED', relation: 'blocked-by' }),
    ],
    references: [
      link('pr', 151, { title: 'fix: approval mode', state: 'OPEN', relation: 'closed-by' }),
      // Somewhere else entirely, where the number alone names the wrong thing.
      {
        kind: 'issue' as const,
        number: 5,
        url: 'https://github.com/another-organisation/a-rather-long-repository-name/issues/5',
        repo: 'another-organisation/a-rather-long-repository-name',
        title: 'The upstream bug this waits on',
        state: 'OPEN',
        relation: 'mentions' as const,
      },
    ],
  };
  const PULL = {
    number: 151,
    title: 'fix: approval mode',
    url: `https://github.com/${REPO}/pull/151`,
    state: 'OPEN',
    isDraft: false,
    author: { login: 'dnviti' },
    assignees: [{ login: 'grace' }],
    headRefName: 'fix/approval',
    baseRefName: 'main',
    reviewDecision: 'APPROVED',
    checks: { total: 4, passed: 3, failed: 0, pending: 1, state: 'pending' },
    references: [link('issue', 134, { title: 'Approval mode is not applied consistently', state: 'OPEN', relation: 'closes' })],
  };

  // Flipped for the last pass: what the panel says when `gh` refused to list.
  let listRefused = false;
  let issueStarts = 0;
  let issuePrompt = '';
  const issueRequestIds: string[] = [];
  let refuseIssue = false;
  const startIssue = async (prompt: string, requestId: string): Promise<void> => {
    issueStarts += 1;
    issuePrompt = prompt;
    issueRequestIds.push(requestId);
    if (refuseIssue) throw new Error('The queue is full; try again after a message runs.');
  };
  let setHarnessPlanMode: React.Dispatch<React.SetStateAction<boolean>> = () => undefined;
  function GitHubIssueHarness(): React.JSX.Element {
    const [prompt, setPrompt] = React.useState('');
    const [planMode, setPlanMode] = React.useState(false);
    setHarnessPlanMode = setPlanMode;
    return React.createElement(GitHubPanel, {
      sessionId: 's1', planMode, issuePrompt: prompt, issueRequestId: 'browser-guided-issue',
      onIssuePromptChange: setPrompt, onStartIssue: startIssue,
    });
  }

  const realFetch = window.fetch;
  window.fetch = (async (input: RequestInfo | URL) => {
    const url = String(typeof input === 'string' ? input : input instanceof URL ? input.href : input.url);
    const json = (value: unknown) =>
      new Response(JSON.stringify(value), { status: 200, headers: { 'content-type': 'application/json' } });

    if (url.includes('/github/issue/134')) {
      return json({
        kind: 'issue',
        item: {
          ...ISSUE,
          kind: 'issue',
          body: 'Three start paths disagree about the approval mode.',
          createdAt: '2026-07-28T09:00:00Z',
          children: [
            link('issue', 135, { title: 'Persist the mode', state: 'CLOSED', relation: 'child' }),
            link('issue', 136, { title: 'Say which mode is on', state: 'OPEN', relation: 'child' }),
          ],
          comments: [],
        },
      });
    }
    if (url.includes('/github/pr/151')) {
      return json({ kind: 'pr', item: { ...PULL, kind: 'pr', body: 'Reads the mode from one place.', comments: [] } });
    }
    if (url.includes('/workspace/') && url.includes('/github')) {
      return json(listRefused
        ? {
          available: true,
          repo: { nameWithOwner: REPO },
          prs: [PULL],
          issues: [],
          issuesError: 'Unknown JSON field: "subIssuesSummary"',
        }
        : { available: true, repo: { nameWithOwner: REPO }, prs: [PULL], issues: [ISSUE] });
    }
    return realFetch(input as RequestInfo);
  }) as typeof window.fetch;

  // The rail's own width, because "does it fit" is half of what is being asked.
  const host = document.createElement('div');
  host.style.cssText = 'position:absolute;top:0;left:0;width:320px;height:640px;'
    + 'display:flex;flex-direction:column;overflow:hidden';
  document.body.appendChild(host);
  const root = createRoot(host);

  try {
    root.render(React.createElement(GitHubIssueHarness));
    await wait(300);
    settle(document);

    const rowText = (host.innerText || '').replace(/\s+/g, ' ');
    check(
      'an issue row names who it is assigned to',
      /ada/.test(rowText),
      rowText.slice(0, 240),
    );
    check(
      'an issue row says how many sub-issues are done',
      /1\/2/.test(rowText),
      rowText.slice(0, 240),
    );
    check(
      'an issue row names the pull request that closes it',
      /#151/.test(rowText),
      rowText.slice(0, 240),
    );
    check(
      'an issue row names what it is part of, and what blocks it',
      /#100/.test(rowText) && /#77/.test(rowText),
      rowText.slice(0, 240),
    );
    check(
      'and stops counting a blocker that has been closed',
      !/#78/.test(rowText),
      rowText.slice(0, 240),
    );
    check(
      'a pull request row names its assignee and its checks',
      /grace/.test(rowText) && /3\/4/.test(rowText),
      rowText.slice(0, 240),
    );

    // Three more facts per row is exactly how a 320px rail starts scrolling
    // sideways. They wrap; they do not widen it.
    check(
      'the extra facts stay inside the rail',
      host.scrollWidth <= host.clientWidth + 1,
      `content ${host.scrollWidth}px in ${host.clientWidth}px`,
    );

    const createIssue = host.querySelector<HTMLButtonElement>('[aria-label^="Create GitHub issue"]');
    createIssue?.focus();
    createIssue?.click();
    await wait(40);
    settle(document);
    let issueDialog = document.querySelector('[role="dialog"]') as HTMLElement | null;
    let issueField = issueDialog?.querySelector<HTMLTextAreaElement>('textarea') || null;
    check(
      'the GitHub action opens the labelled guided-issue dialog and autofocuses its field',
      Boolean(issueDialog && /Create GitHub issue/.test(issueDialog.innerText) && issueField && document.activeElement === issueField),
      issueDialog?.innerText || 'no dialog',
    );
    check(
      'the guided issue textarea shows a visible focus ring',
      Boolean(issueField && getComputedStyle(issueField).boxShadow !== 'none'),
      issueField ? getComputedStyle(issueField).boxShadow : 'no field',
    );
    setHarnessPlanMode(true);
    await wait(40);
    let startButton = Array.from(issueDialog?.querySelectorAll<HTMLButtonElement>('button') || []).find(
      (button) => button.textContent?.trim() === 'Start',
    );
    check(
      'an open guided-issue dialog follows a newly active Plan-mode gate',
      Boolean(
        startButton?.disabled
        && issueDialog?.querySelector('[role="status"]')?.textContent?.includes('Turn off Plan mode'),
      ),
      `disabled=${startButton?.disabled} text=${issueDialog?.textContent || 'no dialog'}`,
    );
    setHarnessPlanMode(false);
    await wait(40);
    (Array.from(issueDialog?.querySelectorAll<HTMLButtonElement>('button') || []).find(
      (button) => button.textContent?.trim() === 'Start',
    ))?.click();
    await wait(100);
    settle(document);
    check(
      'an empty guided issue prompt stays open with an inline error',
      issueStarts === 0
        && Boolean(issueDialog?.querySelector('[role="alert"]')?.textContent?.includes('Describe the issue')),
      issueDialog?.querySelector('[role="alert"]')?.textContent
        || `invalid=${issueField?.getAttribute('aria-invalid')} text=${issueDialog?.textContent || 'no dialog'}`,
    );
    const setIssueField = (field: HTMLTextAreaElement | null, value: string): void => {
      if (!field) return;
      const descriptor = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value');
      descriptor?.set?.call(field, value);
      field.dispatchEvent(new Event('input', { bubbles: true }));
    };
    setIssueField(issueField, 'Keep this unfinished issue brief.');
    await wait(0);
    (Array.from(issueDialog?.querySelectorAll<HTMLButtonElement>('button') || []).find(
      (button) => button.textContent?.trim() === 'Cancel',
    ))?.click();
    await wait(40);
    check(
      'cancelling returns focus to the GitHub action',
      document.activeElement === createIssue,
      document.activeElement?.getAttribute('aria-label') || document.activeElement?.tagName || 'nothing focused',
    );
    createIssue?.focus();
    createIssue?.click();
    await wait(40);
    issueDialog = document.querySelector('[role="dialog"]') as HTMLElement | null;
    issueField = issueDialog?.querySelector<HTMLTextAreaElement>('textarea') || null;
    check(
      'a cancelled issue brief survives when the dialog is reopened',
      issueField?.value === 'Keep this unfinished issue brief.',
      JSON.stringify(issueField?.value || ''),
    );
    if (issueField) {
      setIssueField(issueField, 'The settings page loses work\nwhen a request is queued.');
      await wait(0);
      refuseIssue = true;
      (Array.from(issueDialog?.querySelectorAll<HTMLButtonElement>('button') || []).find(
        (button) => button.textContent?.trim() === 'Start',
      ))?.click();
      await wait(100);
      settle(document);
    }
    check(
      'a refused issue start keeps the prompt and shows the correlated error',
      issueStarts === 1
        && issueField?.value.includes('\n')
        && Boolean(issueDialog?.querySelector('[role="alert"]')?.textContent?.includes('queue is full')),
      `${issueStarts} start(s): ${JSON.stringify(issuePrompt)} — invalid=${issueField?.getAttribute('aria-invalid')} text=${issueDialog?.textContent || 'no dialog'}`,
    );
    refuseIssue = false;
    (Array.from(issueDialog?.querySelectorAll<HTMLButtonElement>('button') || []).find(
      (button) => button.textContent?.trim() === 'Start',
    ))?.click();
    await wait(40);
    check(
      'retrying the guided issue prompt submits once and closes only after acceptance',
      issueStarts === 2
        && issuePrompt.includes('\n')
        && issueRequestIds.length === 2
        && issueRequestIds[0] === issueRequestIds[1]
        && !document.querySelector('[role="dialog"]'),
      `${issueStarts} start(s), ids=${JSON.stringify(issueRequestIds)}: ${JSON.stringify(issuePrompt)}`,
    );
    check(
      'the GitHub issue handoff does not widen the narrow rail',
      host.scrollWidth <= host.clientWidth + 1,
      `content ${host.scrollWidth}px in ${host.clientWidth}px`,
    );

    // Open the issue the way a person does. Matched on the number the row
    // opens with, not on one anywhere in it: the pull request's own row now
    // says "#134" too, which is the point of the row and would send this check
    // into the wrong reader.
    const issueRow = Array.from(host.querySelectorAll<HTMLElement>('button')).find(
      (button) => (button.innerText || '').trim().startsWith('#134'),
    );
    issueRow?.click();
    await wait(300);
    settle(document);

    const dialog = document.querySelector('[role="dialog"]') as HTMLElement | null;
    const readerText = (dialog?.innerText || '').replace(/\s+/g, ' ');
    check(
      'the reader says who the issue is assigned to',
      /Assigned to/i.test(readerText) && /ada/.test(readerText),
      readerText.slice(0, 300),
    );
    check(
      'the reader names the pull request that closes it',
      /Closed by/i.test(readerText) && /#151/.test(readerText),
      readerText.slice(0, 300),
    );
    check(
      'the reader names the issue this one is part of',
      /Part of/i.test(readerText) && /#100/.test(readerText),
      readerText.slice(0, 300),
    );
    check(
      'the reader lists the sub-issues and what is blocking it',
      /#135/.test(readerText) && /#136/.test(readerText) && /Blocked by/i.test(readerText),
      readerText.slice(0, 300),
    );

    check(
      'a reference into another repository says which repository',
      /another-organisation\/a-rather-long-repository-name#5/.test(readerText),
      readerText.slice(0, 400),
    );

    // The reader is a phone-width panel too, and a repository name is as long
    // as somebody made it.
    const links = Array.from(dialog?.querySelectorAll<HTMLElement>('button') || []).filter(
      (button) => (button.getAttribute('title') || '').includes('#'),
    );
    const spilling = links.filter(
      (row) => row.getBoundingClientRect().right > (dialog as HTMLElement).getBoundingClientRect().right + 0.5,
    );
    check(
      'no reference runs out of the side of the reader',
      spilling.length === 0,
      spilling.length ? spilling.map((row) => String(row.getAttribute('title'))).join(' | ') : `${links.length} references`,
    );

    const bar = dialog?.querySelector('[role="progressbar"]') as HTMLElement | null;
    check(
      'the sub-issue progress is readable without seeing the bar',
      bar?.getAttribute('aria-label') === '1 of 2 sub-issues done',
      bar ? String(bar.getAttribute('aria-label')) : 'no progress bar',
    );

    // Follow the pull request out of the issue, then come back.
    const follow = Array.from(dialog?.querySelectorAll<HTMLElement>('button') || []).find(
      (button) => (button.getAttribute('title') || '').includes('#151'),
    );
    check('a reference in the reader can be followed', Boolean(follow), follow ? 'link found' : 'no link');
    follow?.click();
    await wait(300);
    settle(document);

    const pullText = ((document.querySelector('[role="dialog"]') as HTMLElement | null)?.innerText || '')
      .replace(/\s+/g, ' ');
    check(
      'following a reference opens that pull request',
      pullText.startsWith('#151') && /grace/.test(pullText),
      pullText.slice(0, 300),
    );
    check(
      'a followed reference can be left again',
      Boolean(document.querySelector('[aria-label="Back"]')),
      'back control',
    );

    (document.querySelector('[aria-label="Back"]') as HTMLElement | null)?.click();
    await wait(300);
    settle(document);
    const backText = ((document.querySelector('[role="dialog"]') as HTMLElement | null)?.innerText || '')
      .replace(/\s+/g, ' ');
    check(
      'and going back returns to the issue it was followed from',
      backText.startsWith('#134') && !document.querySelector('[aria-label="Back"]'),
      backText.slice(0, 200),
    );

    // A `gh` too old for the sub-issue fields refuses the whole command, and an
    // empty section is indistinguishable from a repository with nothing open.
    (document.querySelector('[aria-label="Close"], [aria-label="close"]') as HTMLElement | null)?.click();
    listRefused = true;
    root.render(React.createElement('div'));
    await wait(60);
    root.render(React.createElement(GitHubIssueHarness));
    await wait(400);
    settle(document);

    const refusedText = (host.innerText || '').replace(/\s+/g, ' ');
    check(
      'a list gh refused does not read as a repository with no open issues',
      !/No open issues/.test(refusedText) && /could not be listed/i.test(refusedText),
      refusedText.slice(0, 300),
    );
    check(
      'and the half that answered is still listed',
      /#151/.test(refusedText) && /fix: approval mode/.test(refusedText),
      refusedText.slice(0, 300),
    );
  } finally {
    root.unmount();
    host.remove();
    window.fetch = realFetch;
  }
}
